module.exports = /*#__PURE__*/JSON.parse('{"source_website":"https://allahuakbarofficial.com","source_page":"https://allahuakbarofficial.com/i-am-feeling/","scraped_at":"2026-08-10T22:41:19.588825","total_feelings":28,"total_items":277,"feelings":[{"feeling":"Confident","slug":"confident","url":"https://allahuakbarofficial.com/confident/","items_count":3,"duas":[{"title":"Duʿa of Prophet Sulayman ﷺ for Gratitude to Allah & Doing Good Deeds","arabic":"رَبِّ أَوْزِعْنِيْٓ أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِيْٓ أَنْعَمْتَ عَلَيَّ وَعَلَىٰ وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ ، وَأَدْخِلْنِيْ بِرَحْمَتِكَ فِيْ عِبَادِكَ الصَّالِحِيْنَ.","transliteration":"Rabbi awziʿnī an ashkura niʿmataka-l-latī anʿamta ʿalayya wa ʿalā wālidayya wa an aʿmala ṣāliḥan tarḍāh, wa adhkilnī bi-raḥmatika fī ʿibādika-ṣ-ṣāliḥīn.","translation":"My Lord, enable me to be grateful for Your favour which You have bestowed upon me and upon my parents, and to do good deeds that please You. And admit me by Your mercy amongst Your righteous servants. (27:19)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/confident/"},{"title":"Duʿa for Gratitude, Good Deeds & Pious Children","arabic":"رَبِّ أَوْزِعْنِيْٓ أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِيْٓ أَنْعَمْتَ عَلَيَّ وَعَلَىٰ وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ ، وَأَصْلِحْ لِيْ فِيْ ذُرِّيَّتِيْ ، إِنِّيْ تُبْتُ إِلَيْكَ وَإِنِّيْ مِنَ الْمُسْلِمِيْنَ.","transliteration":"Rabbi awziʿnī an ashkura niʿmataka-l-latī anʿamta ʿalayya wa ʿalā wālidayya wa an aʿmala ṣāliḥan tarḍāh, wa aṣliḥ lī fī dhuriyyatī, innī tubtu ilayka wa innī mina-l-muslimīn.","translation":"My Lord, enable me to be grateful for Your favour which You have bestowed upon me and upon my parents, and to do good deeds that please You. Make my offspring righteous; I truly repent to you, and truly I am of those who submit to You. (46:15)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/confident/"},{"title":"Duʿa of Prophet Yusuf ﷺ for A Good Ending","arabic":"-اَللّٰهُمَّ يَا- فَاطِرَ السَّمٰوَاتِ وَالْأَرْضِ ، أَنْتَ وَلِـيِّيْ فِي الدُّنْيَا وَالْآخِرَةِ ، تَوَفَّنِيْ مُسْلِمًا وَّأَلْحِقْنِيْ بِالصَّالِحِيْنَ.","transliteration":"(Allāhumma yā) Fāṭira-s-samāwāti wa-l-arḍi Anta waliy-yi fi-d-dunyā wal-ākhirah, tawaffanī Muslimaw-wa alḥiqnī bi-ṣ-ṣāliḥīn.","translation":"(O Allah), Originator of the heavens and the earth, You are my Protector in this world and in the Hereafter. Make me die a Muslim and join me with the righteous. (12:101)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/confident/"}]},{"feeling":"Angry","slug":"angry","url":"https://allahuakbarofficial.com/angry/","items_count":4,"duas":[{"title":"Forgiveness, Anger and Trials","arabic":"اَللّٰهُمَّ رَبَّ مُحَمَّدٍ اغْفِرْ لِيْ ذَنْبِيْ ، وَأَذْهِبْ غَيْظَ قَلْبِيْ ، وَأَعِذْنِيْ مِنْ مُضِلَّاتِ الْفِتَنِ.\\nعَنِ الْقَاسِمِ بْنِ مُحَمَّدِ بْنِ أَبِي بَكْرٍ، قَالَ: كَانَتْ عَائِشَةُ رضي الله عنها إِذَا غَضِبَتْ عَرَكَ النَّبِيُّ صلى الله عليه وسلم بِأَنْفِهَا، ثُمَّ يَقُولُ: يَا عُوَيِّشُ، قُولِي: اللَّهُمَّ رَبَّ مُحَمَّدٍ، اغْفِرْ لِي ذَنْبِي، وَأَذْهِبْ غَيْظَ قَلْبِي، وَأَجِرْنِي مِنْ ‌مُضِلَّاتِ الْفِتَنِ.","transliteration":"Allāhumma Rabba Muḥammad, ighfir lī dhambī, wa adh-hib ghayẓa qalbī, wa aʿidhnī min muḍillāti-l-fitan.","translation":"O Allah, Lord of Muḥammad forgive my sins, remove the anger of my heart and protect me from misleading trials.","description":null,"benefit":null,"virtue":null,"hadith":"Muhammad b. Abī Bakr (raḥimahullāh) narrates that when ʿĀ’isha (raḍiy Allāhu ‘anhā) would become angry, the Messenger of Allah ﷺ would stroke her nose and then say (to her): “O ʿUwaysh! Say: [the above].” (Ibn al-Sunnī 455)","reference":"(عمل اليوم والليلة لابن السني ٤٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/angry/"},{"title":"Istiʿadhah #1","arabic":"أَعُوْذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيْمِ.","transliteration":"Aʿūdhu bi-llāhi mina-sh-Shayṭāni-r-rajīm.","translation":"I seek protection in Allah from the rejected Shayṭān.","description":null,"benefit":null,"virtue":null,"hadith":"Allah says: “When you recite the Quran, seek refuge with Allah from rejected Shayṭān.” (16:98)","reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/angry/"},{"title":"Duʿa for Seeking Protection from Shaytan","arabic":"رَبِّ أَعُوْذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِيْنِ ، وَأَعُوذُ بِكَ رَبِّ أَنْ يَّحْضُرُوْنِ.","transliteration":"Rabbi aʿūdhu bika min hamazāti-sh-shayāṭīn. Wa aʿūdhu bika Rabbi ay-yaḥḍurūn.","translation":"My Lord, I seek protection with You from the promptings of the devils; and I seek protection in You, my Lord, from their coming near me. (23:97-98)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/angry/"},{"title":"The Ultimate Duʿa","arabic":"اَللّٰهُمَّ بِعِلْمِكَ الْغَيْبَ ، وَقُدْرَتِكَ عَلَى الْخَلْقِ ، أَحْيِنِيْ مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِّيْ ، وَتَوَفَّنِيْ إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِّيْ ، اَللّٰهُمَّ وَأَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ ، وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ ، وَأَسْأَلُكَ الْقَصْدَ فِي الْفَقْرِ وَالْغِنَىٰ ، وَأَسْأَلُكَ نَعِيْمًا لَّا يَنْفَدُ ، وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لَّا تَنْقَطِعُ ، وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ ، وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَىٰ وَجْهِكَ ، وَالشَّوْقَ إِلَىٰ لِقَائِكَ ، فِيْ غَيْرِ ضَرَّاءَ مُضِرَّةٍ ، وَلَا فِتْنَةٍ مُّضِلَّةٍ ، اَللّٰهُمَّ زَيِّنَّا بِزِيْنَةِ الْإِيْمَانِ ، وَاجْعَلْنَا هُدَاةً مُّهْتَدِيْنَ","transliteration":"Allāhumma bi-ʿilmika-l-ghayb, wa qudratika ʿala-l-khalq, aḥyinī mā ʿalimta-l-ḥayāta khayra-l-lī, wa tawaffanī idhā ʿalimta-l-wafāta khayra-l-lī, Allāhumma wa as’aluka khashyataka fi-l-ghaybi wa-sh-shahādah, wa as’aluka kalimata-l-ḥaqqi fi-r-riḍā wa-l-ghaḍab, wa as’aluka-l-qaṣda fi-l-faqr wa-l-ghinā, wa as’aluka naʿīma-l-lā yanfad, wa as’aluka qurrata ʿayni-l-lā tanqaṭiʿ, wa as’aluka-r-riḍā baʿda-l-qaḍā, wa as’aluka barda-l-ʿayshi baʿda-l-mawt, wa as’aluka ladh-dhata-n-naẓari ilā wajhik, wa-sh-shawqa ilā liqā’ik, fī ghayri ḍarrā’a muḍirrah, wa lā fitnati-m-muḍillah, Allāhumma zayyinnā bi-zīnati-l-īmān, wa-jʿalnā hudāta-m-muhtadīn.","translation":"O Allah, with Your knowledge of the unseen and Your absolute power over the creation, let me live in this world as long as You know my living is good for me; and give me death when You know death is better for me. O Allah, I ask You for Your fear in private and in public, and for the word of truth in times of joy and anger. I ask You for moderation in poverty and in wealth. I ask You for endless blessings and perpetual delights. I ask You to make me pleased with destiny; for a cool and comfortable life after death; for the pleasure of seeing Your Face; and for the longing to meet You, without any painful ordeals and tribulations that misguide. O Allah, adorn us with the beauty of faith, and make us those who guide others and are guided themselves.","description":null,"benefit":null,"virtue":null,"hadith":"ʿAtā b. As-Sā’ib narrated that his father said: “ʿAmmār b. Yāsir (raḍiy Allāhu ‘anhu) led us in prayer and he made it brief. Some of the people said to him: ‘You made the prayer short (or brief).’ He said: ‘Nevertheless I still recited supplications that I heard from the Messenger of Allah ﷺ.’ When he got up and left, a man- he was my father but he did not name himself- followed him and asked him about that supplication, then he came and told the people [the above].” (Nasā’ī 1305)","reference":"أَخْبَرَنَا يَحْيَى بْنُ حَبِيبِ بْنِ عَرَبِيٍّ، قَالَ: حَدَّثَنَا حَمَّادٌ، قَالَ: حَدَّثَنَا عَطَاءُ بْنُ السَّائِبِ ، عَنْ أَبِيهِ قَالَ:صَلَّى بِنَا عَمَّارُ بْنُ يَاسِرٍ صَلَاةً، فَأَوْجَزَ فِيهَا، فَقَالَ لَهُ بَعْضُ الْقَوْمِ: لَقَدْ خَفَّفْتَ، أَوْ أَوْجَزْتَ الصَّلَاةَ، فَقَالَ: أَمَّا عَلَى ذَلِكَ، فَقَدْ دَعَوْتُ فِيهَا بِدَعَوَاتٍ سَمِعْتُهُنَّ مِنْ رَسُولِ اللهِ صلى الله عليه وسلم، فَلَمَّا قَامَ تَبِعَهُ رَجُلٌ مِنَ الْقَوْمِ هُوَ أَبِي غَيْرَ أَنَّهُ كَنَّى عَنْ نَفْسِهِ، فَسَأَلَهُ عَنِ الدُّعَاءِ، ثُمَّ جَاءَ فَأَخْبَرَ بِهِ الْقَوْمَ: اللَّهُمَّ بِعِلْمِكَ الْغَيْبَ، وَقُدْرَتِكَ عَلَى الْخَلْقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِي، وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي، اللَّهُمَّ وَأَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ، وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ، وَأَسْأَلُكَ الْقَصْدَ فِي الْفَقْرِ وَالْغِنَى، وَأَسْأَلُكَ نَعِيمًا لَا يَنْفَدُ، وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لَا تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَاءَ بَعْدَ الْقَضَاءِ، وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ، وَالشَّوْقَ إِلَى لِقَائِكَ فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ، وَلَا فِتْنَةٍ مُضِلَّةٍ، اللَّهُمَّ زَيِّنَّا بِزِينَةِ الْإِيمَانِ، وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ.\\n(سنن النسائي ١٣٠٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Some of the people said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/angry/"}]},{"feeling":"Bored","slug":"bored","url":"https://allahuakbarofficial.com/bored/","items_count":7,"duas":[{"title":"Duʿa of Prophet Musa ﷺ Expressing His Dire Need","arabic":"رَبِّ إِنِّيْ لِمَآ أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيْرٌ.","transliteration":"Rabbi innī limā anzalta illayya min khayrin faqīr.","translation":"My Lord, truly I am in dire need of any good which You may send me. (28:24)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/bored/"},{"title":"Attainment of Every Good","arabic":"اَللّٰهُمَّ إنَّا نَسْأَلُكَ مُوْجِبَاتِ رَحْمَتِكَ ، وَعَزَائِمَ مَغْفِرَتِكَ ، وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ ، وَالْغَنِِيْمَةَ مِنْ كُلِّ بِرٍّ ، وَالْفَوْزَ بِالْجَنَّةِ ، وَالنَّجَاةَ مِنَ النَّارِ.","transliteration":"Allāhumma innā nas’aluka mūjibāti raḥmatik, wa ʿazā’ima maghfiratik, wa-s-salāmata min kulli ithm, wal-ghanīmata min kulli birr, wal-fawza bil-Jannah, wa-n-najāta mina-n-nār.","translation":"O Allah, we beg You for all that which will necessitate Your mercy and the determination to do all that which will necessitate Your forgiveness; for protection from every sin and accomplishment of every good; for attainment of Paradise and for freedom from Hell-fire.","description":null,"benefit":null,"virtue":null,"hadith":"Abdullah b. Mas’ūd (raḍiy Allāhu ‘anhu) says: “From the supplication of the Messenger of Allah ﷺ was:","reference":"[the above]. (Hākim 1925)\\nعَنِ ابْنِ مَسْعُودٍ رضي الله عنه، قَالَ: كَانَ مِنْ دُعَاءِ رَسُولِ اللَّهِ صلى الله عليه وسلم اللَّهُمَّ إِنَّا نَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ، وَالْغَنِيمَةَ مِنْ كُلِّ بِرٍّ، وَالْفَوْزَ بِالْجَنَّةِ، وَالنَّجَاةَ بِعَوْنِكَ مِنَ النَّارِ. (المستدرك على الصحيحين للحاكم ١٩٢٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/bored/"},{"title":"Steadfastness on Obedience","arabic":"اَللّٰهُمَّ مُصَرِّفَ الْقُلُوْبِ صَرِّفْ قُلُوْبَنَا عَلَىٰ طَاعَتِكَ","transliteration":"Allāhumma Muṣarrifa-l-qulūbi ṣarrif qulūbanā ʿalā ṭāʿatik.","translation":"O Allah, Changer of hearts, direct our hearts to Your obedience.","description":null,"benefit":null,"virtue":null,"hadith":"ʿAbdullāh b. ʿAmr (raḍiy Allāhu ‘anhuma) reported that the Messenger of Allah ﷺ said: “Verily, the hearts of the children of Adam, all of them, are between the two fingers of the Merciful as one heart. He directs them wherever He wills.” (Muslim 2654)","reference":"حدثني زهير بن حرب وابن نمير. كلاهما عَنْ الْمُقْرِئِ. قَالَ زُهَيْرٌ: حَدَّثَنَا عَبْدُ الله بن يزيد المقرئ. قال: حدثنا حيوة. أخبرني أَبُو هَانِئٍ؛ أَنَّهُ سَمِعَ أَبَا عَبْدِ الرَّحْمَنِ الحبلي؛ أَنَّهُ سَمِعَ عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ العاص يقول؛\\nأَنَّهُ سَمِعَ رَسُولَ اللَّهِ صلى الله عليه وسلم يقول “إن قلوب بني آدم كلها بين إصبعين من أصابع الرحمن. كقلب واحد. يصرفه حيث يشاء”. ثُمَّ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم اللهم! مصرف القلوب! صرف قلوبنا على طاعتك. (صحيح مسلم ٢٦٥٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/bored/"},{"title":"Seeking Help For Excellence In Worship","arabic":"اَللّٰهُمَّ أَعِنِّيْ عَلَىٰ ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ","transliteration":"Allāhumma aʿinnī ʿalā dhikrika wa shukrika wa ḥusni ʿibādatik.","translation":"O Allah, help me in remembering You, in being grateful to You, and in worshipping You in an excellent manner.","description":null,"benefit":null,"virtue":null,"hadith":"Mu’ādh b. Jabal (raḍiy Allāhu ‘anhu) reported that the Messenger of Allah ﷺ took me by the hand and he said, “O Mu’ādh, I swear by Allah that I love you. I swear by Allah that I love you. O Mu’ādh, I advise you not to forget supplicating after every prayer by saying: [the above]. (Abū Dāwūd 1522)","reference":"عَنْ مُعَاذِ بْنِ جَبَلٍ، أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم أَخَذَ بِيَدِهِ، وَقَالَ: يَا مُعَاذُ، وَاللهِ إِنِّي لَأُحِبُّكَ، فَقَالَ: أُوصِيكَ يَا مُعَاذُ لَا تَدَعَنَّ فِي دُبُرِ كُلِّ صَلَاةٍ تَقُولُ اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ، وَشُكْرِكَ، وَحُسْنِ عِبَادَتِكَ. (سنن ابي داود ١٥٢٢)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/bored/"},{"title":"Duʿa for Allah’s Love & Protection From Trials","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ فِعْلَ الْخَيْرَاتِ ، وَتَرْكَ الْمُنْكَرَاتِ ، وَحُبَّ الْمَسَاكِيْنِ ، وَأَنْ تَغْفِرَ لِيْ وَتَرْحَمَنِيْ ، وَإِذَا أَرَدْتَ فِتْنَةَ قَوْمٍ فَتَوَفَّنِيْ غَيْرَ مَفْتُوْنٍ ، وَأَسْأَلُكَ حُبَّكَ ، وَحُبَّ مَنْ يُّحِبُّكَ ، وَحُبَّ عَمَلٍ يُّقَرِّبُنِيْ إِلَىٰ حُبِّكَ","transliteration":"Allāhumma innī as’aluka fiʿla-l-khayrāt, wa tarka-l-munkarāt, wa ḥubba-l-masākīn, wa an taghfira lī wa tarḥamanī, wa idhā arad-ta fitnata qawmin fa-tawaffanī ghayra maftūn, wa as’aluka ḥubbak, wa ḥubba ma-y-yuḥibbuk, wa ḥubba ʿamali-y-yuqarribunī ilā ḥubbik.","translation":"O Allah, I beg You to enable me to do good deeds, abstain from evil acts, and love the poor; and that You forgive me and have mercy upon me. When You intend to test a people, then grant me death without being tested. I ask You for Your love, the love of those whom You love, and the love of deeds which will bring me closer to Your love.","description":null,"benefit":null,"virtue":null,"hadith":"Mu’ādh b. Jabl (raḍiy Allāhu ‘anhu) narrates: “One morning, the Messenger of Allah ﷺ was prevented from coming to us for the Fajr Salāh, until we were just about to look for the eye of the sun (meaning sunrise). Then he came out quickly and the Salāh was prepared for.","reference":"The Messenger of Allah ﷺ performed the Salah, and he performed his Salah in a relatively quick manner. When he said the salām, he called out to us saying: ‘Stay in your rows as you are.’ Then he turned to us and said: ‘I am going to narrate to you what kept me from you this morning: I got up during the night, I performed wudhu and prayed as much as I was able to, and I dozed off during my Salāh, and fell in a deep asleep. Then I saw my Lord, Blessed and Most High, in the best of appearances. He said: ‘O Muhammad!’ I said: ‘My Lord here I am my Lord!’ He said: ‘What is it that the most exalted group busy themselves with?’ I said: ‘I do not know Lord.’ And He said it three times.” He said: “So I saw Him place His Palm between my shoulders, and I sensed the coolness of His Fingertips between my breast. Then everything was disclosed for me, and I became aware. So He said: ‘O Muhammad!’ I said: ‘Here I am my Lord!’ He said: ‘What is it that the most exalted group busy themselves with?’ I said: ‘In the acts that atone.’ He said: ‘And what are they?’ I said: ‘The footsteps to the congregation, the gatherings in the Masājid after the Salāh, doing wudhu perfectly during difficulties.’ He said: ‘Then what else?’ I said: ‘Feeding others, being lenient in speech, and Salāh during the night while the people are sleeping.’ He said: ‘Ask.’ I said: [the above]’” The Messenger of Allah ﷺ said: “Indeed it is true, so study it and learn it.” (Tirmidhī 3235)\\nعَنْ مُعَاذِ بْنِ جَبَلٍ قَالَ: احْتُبِسَ عَنَّا رَسُولُ اللَّهِ صلى الله عليه وسلم ذَاتَ غَدَاةٍ مِنْ صَلَاةِ الصُّبْحِ حَتَّى كِدْنَا نَتَرَاءَى عَيْنَ الشَّمْسِ، فَخَرَجَ سَرِيعًا فَثُوِّبَ بِالصَّلَاةِ، فَصَلَّى رَسُولُ اللَّهِ صلى الله عليه وسلم وَتَجَوَّزَ فِي صَلَاتِهِ، فَلَمَّا سَلَّمَ دَعَا بِصَوْتِهِ فَقَالَ لَنَا: عَلَى مَصَافِّكُمْ كَمَا أَنْتُمْ ثُمَّ انْفَتَلَ إِلَيْنَا فَقَالَ: ” أَمَا إِنِّي سَأُحَدِّثُكُمْ مَا حَبَسَنِي عَنْكُمُ الغَدَاةَ: أَنِّي قُمْتُ مِنَ اللَّيْلِ فَتَوَضَّأْتُ فَصَلَّيْتُ مَا قُدِّرَ لِي فَنَعَسْتُ فِي صَلَاتِي فَاسْتَثْقَلْتُ، فَإِذَا أَنَا بِرَبِّي تبارك وتعالى فِي أَحْسَنِ صُورَةٍ، فَقَالَ: يَا مُحَمَّدُ قُلْتُ: لَبَّيْكَ رَبِّ، قَالَ: فِيمَ يَخْتَصِمُ المَلَأُ الأَعْلَى؟ قُلْتُ: لَا أَدْرِي رَبِّ، قَالَهَا ثَلَاثًا ” قَالَ: ” فَرَأَيْتُهُ وَضَعَ كَفَّهُ بَيْنَ كَتِفَيَّ حَتَّى وَجَدْتُ بَرْدَ أَنَامِلِهِ بَيْنَ ثَدْيَيَّ، فَتَجَلَّى لِي كُلُّ شَيْءٍ وَعَرَفْتُ، فَقَالَ: يَا مُحَمَّدُ، قُلْتُ: لَبَّيْكَ رَبِّ، قَالَ: فِيمَ يَخْتَصِمُ المَلَأُ الأَعْلَى؟ قُلْتُ: فِي الكَفَّارَاتِ، قَالَ: مَا هُنَّ؟ قُلْتُ: مَشْيُ الأَقْدَامِ إِلَى الجَمَاعَاتِ، وَالجُلُوسُ فِي المَسَاجِدِ بَعْدَ الصَّلَوَاتِ، وَإِسْبَاغُ الوُضُوءِ فِي المَكْرُوهَاتِ، قَالَ: ثُمَّ فِيمَ؟ قُلْتُ: إِطْعَامُ الطَّعَامِ، وَلِينُ الكَلَامِ، وَالصَّلَاةُ بِاللَّيْلِ وَالنَّاسُ نِيَامٌ. قَالَ: سَلْ. قُلْتُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ فِعْلَ الخَيْرَاتِ، وَتَرْكَ المُنْكَرَاتِ، وَحُبَّ المَسَاكِينِ، وَأَنْ تَغْفِرَ لِي وَتَرْحَمَنِي، وَإِذَا أَرَدْتَ فِتْنَةً فِي قَوْمٍ فَتَوَفَّنِي غَيْرَ مَفْتُونٍ، وَأَسْأَلُكَ حُبَّكَ وَحُبَّ مَنْ يُحِبُّكَ، وَحُبَّ عَمَلٍ يُقَرِّبُ إِلَى حُبِّكَ “، قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: إِنَّهَا حَقٌّ فَادْرُسُوهَا ثُمَّ تَعَلَّمُوهَا. (سنن الترمذي ٣٢٣٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"When he said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/bored/"},{"title":"A Comprehensive Duʿa","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ خَيْرَ الْمَسْأَلَةِ ، وَخَيْرَ الدُّعَاءِ ، وَخَيْرَ النَّجَاحِ ، وَخَيْرَ الْعَمَلِ ، وَخَيْرَ الثَّوَابِ ، وَخَيْرَ الْحَيَاةِ ، وَخَيْرَ الْمَمَاتِ ، وَثَبِّتْنِيْ ، وَثَقِّلْ مَوَازِيْنِيْ ، وَحَقِّقْ إِيْمَانِيْ ، وَارْفَعْ دَرَجَاتِيْ ، وَتَقَبَّلْ صَلَاتِيْ ، وَاغْفِرْ خَطِيْئَتِيْ ، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَا مِنَ الْجَنَّةِ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ فَوَاتِحَ الْخَيْرِ ، وَخَوَاتِمَهُ ، وَجَوَامِعَهُ ، وَأَوَّلَهُ ، وَظَاهِرَهُ ، وَبَاطِنَهُ ، وَالدَّرَجَاتِ الْعُلَا مِنَ الْجَنَّةِ آمِيْن ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ خَيْرَ مَا آتِيْ ، وَخَيْرَ مَا أَفْعَلُ ، وَخَيْرَ مَا أَعْمَلُ ، وَخَيْرَ مَا بَطَنَ ، وَخَيْرَ مَا ظَهَرَ ، وَالدَّرَجَاتِ الْعُلَا مِنَ الْجَنَّةِ آمِيْن ، اَللّٰهُمَّ إنِّيْ أَسْأَلُكَ أنْ تَرْفَعَ ذِكْرِيْ ، وَتَضَعَ وِزْرِيْ ، وَتُصْلِحَ أَمْرِيْ ، وَتُطَهِّرَ قَلْبِيْ ، وَتُحَصِّنَ فَرْجِيْ ، وَتُنَوِّرَ لِيْ قَلْبِيْ ، وَتَغْفِرَ لِيْ ذَنْبِيْ ، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَا مِنَ الْجَنَّةِ آمِيْن ، اَللّٰهُمَّ إنِّيْ أَسْأَلُكَ أنْ تُبَارِكَ لِيْ فِيْ نَفْسِيْ ، وَفِيْ سَمْعِيْ ، وَفِيْ بَصَرِيْ ، وَفِيْ رُوْحِيْ ، وَفِيْ خَلْقِيْ ، وَفِيْ خُلُقِيْ ، وَفِيْ أَهْلِيْ ، وَفِيْ مَحْيَايَ ، وَفِيْ مَمَاتِيْ ، وَفِيْ عَمَلِيْ ، فَتَقَبَّلْ حَسَنَاتِيْ ، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَا مِنَ الْجَنَّةِ ، آمِيْن","transliteration":"Allāhumma innī as’aluka khayra-l-mas’alah, wa khayra-d-duʿā’, wa khayra-n-najaḥ, wa khayra-l-ʿamal, wa khayra-th-thawāb, wa khayra-l-ḥayāh, wa khayra-l-mamāt, wa thabbitnī, wa thaqqil mawāzīnī, wa ḥaqqiq īmānī, wa-r-faʿ darajātī, wa taqabbal ṣalātī, wa-ghfir khaṭī’atī, wa as’aluka-d-darajāti-l-ʿulā mina-l-Jannah, Allāhumma innī as’aluka fawātiḥa-l-khayr, wa khawātimah, wa jawāmiʿah, wa awwalah, wa ẓāhirah, wa bāṭinah, wa-d-darajāti-l-ʿulā mina-l-Jannati āmīn, Allāhumma innī as’aluka khayra mā ātī, wa khayra mā afʿal, wa khayra mā aʿmal, wa khayra mā baṭan, wa khayra mā ẓahar, wa-d-darajāti-l-ʿulā mina-l-Jannati, āmīn, Allāhumma innī as’aluka an tarfaʿa dhikrī, wa taḍaʿa wizrī, wa tuṣliḥa amrī, wa tuṭahhira qalbī, wa tuḥaṣṣina farjī, wa tunawwira lī qalbī, wa taghfira lī dhambī, wa as’aluka-d-darajāti-l-ʿulā mina-l-Jannati, āmīn, Allāhumma innī as’aluka an tubārika lī fī nafsī, wa fī samʿī, wa fī baṣarī, wa fī rūḥī, wa fī khalqī, wa fī khuluqī, wa fī ahlī, wa fī maḥyāya, wa fī mamātī, wa fi ʿamalī, fa-taqabbal ḥasanātī, wa as’aluka-d-darajāti-l-ʿulā mina-l-Jannati, āmīn.","translation":"O Allah, I beg You for the best of what can be asked for, the best supplication, the ultimate success, the best deeds, the best reward, the best life, and the best death. Keep me steadfast, make my scales heavy, establish my belief, elevate my ranks, accept my salāh, forgive my sins and I ask You for lofty ranks in Paradise. O Allah, I beg you for good beginnings, good endings, good in its entirety, its first, its apparent and its hidden; and lofty ranks in Paradise. Āmīn. O Allah, I beg you for the best of what I can do, perform and accomplish, the best of what is hidden or apparent; and lofty ranks in Paradise. Āmīn. O Allah, I beg you to elevate my mention, remove my burden, rectify my affairs, purify my heart, protect my chastity, enlighten my heart, forgive my sins and I ask You for lofty ranks in Paradise. Āmīn. O Allah, I beg you to bless for me my inner self, my hearing, my sight, my soul, my appearance, my character, my family, my life, my death and my deeds. Accept my good deeds and I ask You for lofty ranks in Paradise. Āmīn.","description":null,"benefit":null,"virtue":null,"hadith":"Umm Salamah (raḍiy Allāhu ‘anhā) narrates that the Prophet ﷺ said: “This is what Muhammad asks from His Lord: [the above].”(Hākim 1911)","reference":"عَنْ أُمِّ سَلَمَةَ رضي الله عنها، عَنِ النَّبِيِّ صلى الله عليه وسلم هَذَا مَا سَأَلَ مُحَمَّدٌ رَبَّهُ: «اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ الْمَسْأَلَةِ، وَخَيْرَ الدُّعَاءِ، وَخَيْرَ النَّجَاحِ، وَخَيْرَ الْعَمَلِ، وَخَيْرَ الثَّوَابِ، وَخَيْرَ الْحَيَاةِ، وَخَيْرَ الْمَمَاتِ، وَثَبَّتَنِي وَثَقِّلْ مَوَازِينِي، وَحَقِّقْ إِيمَانِي، وَارْفَعْ دَرَجَاتِي، وَتَقَبَّلْ صَلَاتِي، وَاغْفِرْ خَطِيئَتِي، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ ‌فَوَاتِحَ الْخَيْرِ وَخَوَاتِمَهُ، وَجَوَامِعَهُ، وَأَوَّلَهُ، وَظَاهِرَهُ وَبَاطِنَهُ، وَالدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ آمِينَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ مَا آتِي، وَخَيْرَ مَا أَفْعَلُ، وَخَيْرَ مَا أَعْمَلُ، وَخَيْرَ مَا بَطَنَ، وَخَيْرَ مَا ظَهَرَ، وَالدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ آمِينَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ أَنْ تَرْفَعَ ذِكْرِي، وَتَضَعَ وَزِرْي، وَتُصْلِحَ أَمْرِي، وَتُطَهِّرَ قَلْبِي، وَتُحَصِّنَ فَرْجِي، وَتُنَوِّرَ لِي قَلْبِي، وَتَغْفِرَ لِي ذَنْبِي، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ آمِينَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ أَنْ تَبَارَكَ لِي فِي نَفْسِي، وَفِي سَمْعِي، وَفِي بَصَرِي، وَفِي رُوحِي، وَفِي خَلْقِي، وَفِي خُلُقِي، وَفِي أَهْلِي، وَفِي مَحْيَايَ، وَفِي مَمَاتِي، وَفِي عَمَلِي، فَتَقَبَّلْ حَسَنَاتِي، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ آمِينَ.\\n(المستدرك على الصحيحين للحاكم ١٩١١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/bored/"},{"title":"Guidance & Protection from Evil","arabic":"اَللّٰهُمَّ أَلْهِمْنِيْ رُشْدِيْ ، وَأَعِذْنِيْ مِنْ شَرِّ نَفْسِيْ.","transliteration":"Allāhumma alhimnī rushdī, wa aʿidhnī min sharri nafsī.","translation":"O Allah, inspire me with sound guidance and protect me from the evil of my self.","description":null,"benefit":null,"virtue":"ʿImrān b. Husayn (raḍiy Allāhu ‘anhu) narrated: “The Prophet ﷺ said to my father: ‘O Husayn, how many deities do you worship now?‘ He said: ‘Seven. Six in the earth, and one above the heavens.’ He ﷺ said: ‘So which of them do you take for your ardent requests and fears?’ He said: ‘The one above the heavens.’ He ﷺ said: ‘O Husayn, if you accept Islam, I would teach you two phrases that would benefit you.’” He (the narrator) said: “So when Husayn accepted Islam, he said: ‘O Messenger of Allah, teach me the two phrases you promised me.’ So he ﷺ said: [the above].” (Tirmidhī 3483)","hadith":null,"reference":"عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، قَالَ: قَالَ النَّبِيُّ صلى الله عليه وسلم لِأَبِي:يَا حُصَيْنُ كَمْ تَعْبُدُ اليَوْمَ إِلَهًا؟ قَالَ أَبِي: سَبْعَةً سِتَّةً فِي الأَرْضِ وَوَاحِدًا فِي السَّمَاءِ. قَالَ فَأَيُّهُمْ تَعُدُّ لِرَغْبَتِكَ وَرَهْبَتِكَ؟ قَالَ: الَّذِي فِي السَّمَاءِ. قَالَ:يَا حُصَيْنُ أَمَا إِنَّكَ لَوْ أَسْلَمْتَ عَلَّمْتُكَ كَلِمَتَيْنِ تَنْفَعَانِكَ. قَالَ: فَلَمَّا أَسْلَمَ حُصَيْنٌ قَالَ: يَا رَسُولَ اللَّهِ عَلِّمْنِيَ الكَلِمَتَيْنِ اللَّتَيْنِ وَعَدْتَنِي، فَقَالَ:” قُلْ: اللَّهُمَّ أَلْهِمْنِي رُشْدِي، وَأَعِذْنِي مِنْ شَرِّ نَفْسِي.\\n(سنن الترمذي ٣٤٨٣)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"He said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/bored/"}]},{"feeling":"Anxious","slug":"anxious","url":"https://allahuakbarofficial.com/anxious/","items_count":13,"duas":[{"title":"Hawqalah: A Treasure From the Treasures of Paradise","arabic":"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللّٰهِ","transliteration":"Lā ḥawla wa lā quwwata illā bi-llāh","translation":"There is no power (in averting evil) or strength (in attaining good) except through Allah","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “Shall I not teach you a statement which lies beneath the Throne and is from the treasures of Paradise? Say لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِالله upon which Allah says: ‘My slave has submitted and surrendered himself.’” (Hākim 54)","hadith":null,"reference":"He ﷺ also said it is a gate from the gates of Paradise. (Tirmidhī 3581)\\nعَنْ أَبِي هُرَيْرَةَ رضي الله عنه، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم، قَالَ:أَلَا أُعَلِّمُكَ – أَوْ قَالَ: أَلَا أَدُلُّكَ – عَلَى كَلِمَةٍ مِنْ تَحْتِ الْعَرْشِ مِنْ كَنْزِ الْجَنَّةِ؟ تَقُولُ: ‌لَا ‌حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، فَيَقُولُ اللَّهُ عز وجل: أَسْلَمَ عَبْدِي وَاسْتَسْلَمَ.\\n(المستدرك على الصحيحين للحاكم ٥٤)\\nعَنْ قَيْسِ بْنِ سَعْدِ بْنِ عُبَادَةَ، أَنَّ أَبَاهُ دَفَعَهُ إِلَى النَّبِيِّ صلى الله عليه وسلم يَخْدُمُهُ، قَالَ: فَمَرَّ بِيَ النَّبِيُّ صلى الله عليه وسلم وَقَدْ صَلَّيْتُ فَضَرَبَنِي بِرِجْلِهِ وَقَالَ:أَلَا أَدُلُّكَ عَلَى بَابٍ مِنْ أَبْوَابِ الجَنَّةِ؟ قُلْتُ: بَلَى؟ قَالَ: لَا ‌حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ.\\n(سنن الترمذي ٣٥٨١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/anxious/"},{"title":"When One Is in a Difficult Situation","arabic":"اَللّٰهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا ، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا","transliteration":"Allāhumma lā sahla illā mā jaʿaltahū sahlā, wa anta tajʿalu-l-ḥazna idhā shi’ta sahlā.","translation":"O Allah, there is no ease except in that which You have made easy; and You make the difficulty easy when You wish.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Malik (raḍiy Allāhu ʿanhu) ﷺ narrates that the Messenger of Allah said [the above]. (Ibn Ḥibbān 6737, Ibn al-Sunnī 351)","reference":"عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم، قَالَ: اللهُمَّ ‌لَا ‌سَهْلَ إِلَاّ مَا جَعَلْتَهُ سَهْلاً، وَأَنْتَ تَجْعَلُ الْحَزْنَ سَهْلاً إِذَا شِئْتَ. (صحيح ابن حبان ٦٧٣٧)\\nعَنْ أَنَسِ بْنِ مَالِكٍ، رضي الله عنه أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ: اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا، وَأَنْتَ تَجْعَلُ الْحَزَنَ إِذَا شِئْتَ سَهْلًا.\\n(عمل اليوم والليلة لابن السني ٣٥١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Allah said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/anxious/"},{"title":"Protect Yourself From Anxiety, Laziness & Debt","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ ، وَأَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ ، وَأَعُوْذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.","transliteration":"Allāhumma innī aʿūdhu bika min-l-hammi wa-l-ḥazan, wa aʿūdhu bika min-l-ʿajzi wa-l-kasal, wa aʿūdhu bika min-l-jubni wa-l-bukhl, wa aʿūdhu bika min ghalabati-d-dayni wa qahri-r-rijāl.","translation":"O Allah, I seek Your protection from anxiety and grief. I seek Your protection from inability and laziness. I seek Your protection from cowardice and miserliness, and I seek Your protection from being overcome by debt and being overpowered by men.","description":null,"benefit":null,"virtue":"Abū Saʿīd al-Khudrī (raḍiy Allāhu ʿanhu) narrated that one day, the Messenger of Allah ﷺ entered the masjid. He saw a man from the Anṣār called Abū Umāmah (raḍiy Allāhu ʿanhu). He ﷺ asked, “What is the matter? Why are you sitting in the masjid when it is not the time for prayer?” He replied, “Never-ending worries and debts, O Messenger of Allah.” The Messenger of Allah ﷺ then asked, “Shall I not teach you words by which, when you say them, Allah will remove your worries, and settle your debts?” He replied, “Yes of course, O Messenger of Allah.” He ﷺ said, “Say in the morning and evening [the above].” Abū Umāmah (raḍiy Allāhu ʿanhu) said, “Then I did that, and Allah removed my worries and settled my debts.” (Abū Dāwūd 1555)","hadith":null,"reference":"عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: دَخَلَ رَسُولُ صَلَّى عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ مِنَ الْأَنْصَارِ، يُقَالُ لَهُ: أَبُو أُمَامَةَ، فَقَالَ: «يَا أُمَامَةَ، مَا لِي أَرَاكَ جَالِسًا فِي الْمَسْجِدِ فِي غَيْرِ وَقْتِ الصَّلَاةِ؟»، قَالَ: هُمُومٌ لَزِمَتْنِي، وَدُيُونٌ يَا رَسُولَ اللَّهِ، قَالَ: أَفَلَا أُعَلِّمُكَ كَلَامًا إِذَا أَنْتَ قُلْتَهُ أَذْهَبَ عز وجل هَمَّكَ، وَقَضَى عَنْكَ دَيْنَكَ؟، قَالَ: قُلْتُ: بَلَى، يَا رَسُولَ، قَالَ: ” قُلْ إِذَا أَصْبَحْتَ، وَإِذَا أَمْسَيْتَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَقَهْرِ الرِّجَالِ “، قَالَ: فَفَعَلْتُ ذَلِكَ، فَأَذْهَبَ اللَّهُ عز وجل هَمِّي، وَقَضَى عَنِّي دَيْنِي.(سنن أبي داود ١٥٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/anxious/"},{"title":"Attain Well-being in This World and the Hereafter","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِيْ دِيْنِيْ وَدُنْيَايَ وَأَهْلِيْ وَمَالِيْ ، اَللّٰهُمَّ اسْتُرْ عَوْرَاتِيْ وَآمِنْ رَّوْعَاتِيْ ، اَللّٰهُمَّ احْفَظْنِيْ مِنْ بَيْنِ يَدَيَّ ، وَمِنْ خَلْفِيْ ، وَعَنْ يَّمِيْنِيْ ، وَعَنْ شِمَالِيْ ، وَمِنْ فَوْقِيْ ، وَأَعُوْذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِيْ.","transliteration":"Allāhumma innī as’aluka-l-ʿāfiyata fi-d-dunyā wa-l-ākhirah. Allāhumma innī as’aluka-l-ʿafwa wa-l-ʿāfiyata fī dīnī wa dunyāya wa ahlī wa mālī, Allāhumma-stur ʿawrātī wa āmi-r-rawʿātī. Allāhumma-ḥfaẓnī mim bayni yadayya wa min khalfī, wa ʿay-yamīnī wa ʿan shimālī wa min fawqī, wa aʿūdhu bi-ʿaẓamatika an ughtāla min taḥtī.","translation":"O Allah, I ask You for well-being in this world and the next. O Allah, I ask You for forgiveness and well-being in my religion, in my worldly affairs, in my family and in my wealth. O Allah, conceal my faults and calm my fears. O Allah, guard me from in front of me and behind me, from my right, and from my left, and from above me. I seek protection in Your Greatness from being unexpectedly destroyed from beneath me.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “Ask Allah for forgiveness and well-being (‘āfiyah). Indeed, after conviction (yaqīn), no one has been granted anything better than well-being.” (Tirmidhī)","hadith":"ʿAbdullāh b. ʿUmar (raḍiy Allāhu ʿanhumā) narrated: “The Messenger of Allah ﷺ never failed to say these words in the morning and in the evening.” (Abū Dāwūd 5074)","reference":"عَنْ جُبَيْرِ بْنِ أَبِي سُلَيْمَانَ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ، قَالَ: سَمِعْتُ ابْنَ عُمَرَ، يَقُولُ: لَمْ يَكُنْ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَعُ هَؤُلَاءِ الدَّعَوَاتِ، حِينَ يُمْسِي، وَحِينَ يُصْبِحُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَتِي، وَقَالَ عُثْمَانُ: عَوْرَاتِي وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي.(سنن أبي داود ٥٠٧٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/anxious/"},{"title":"Grief & Anxiety #1","arabic":"اَللّٰهُمَّ إِنِّيْ عَبْدُكَ ، وَابْنُ عَبْدِكَ ، وَابْنُ أَمَتِكَ ، نَاصِيَتِيْ بِيَدِكَ ، مَاضٍ فِيَّ حُكْمُكَ ، عَدْلٌ فِيَّ قَضَاؤُكَ ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ ، سَمَّيْتَ بِهِ نَفْسَكَ ، أَوْ عَلَّمْتَهُ أَحَدًا مِّنْ خَلْقِكَ ، أَوْ أَنْزَلْتَهُ فِيْ كِتَابِكَ ، أَوِ اسْتَأْثَرْتَ بِهِ فِيْ عِلْمِ الْغَيْبِ عِنْدَكَ ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيْعَ قَلْبِيْ ، وَنُوْرَ صَدْرِيْ ، وَجَلَاءَ حُزْنِيْ ، وَذَهَابَ هَمِّيْ","transliteration":"Allāhumma innī ʿabduk, wa-bnu ʿabdik, wa-bnu amatik, nāṣiyatī bi-yadik, māḍin fiyya ḥukmuk, ʿadlun fiyya qaḍā’uk, as’aluka bi-kulli-smin huwa lak, sammayta bihī nafsak, aw ʿallamtahū aḥadam-min khalqik, aw anzaltahū fī kitābik, awi-sta’tharta bihī fī ʿilmi-l-ghaybi ʿindak, an tajʿala-l-Qur’āna rabīʿa qalbī, wa nūra ṣadrī, wa jalā’a ḥuznī, wa dha-hāba hammī.","translation":"O Allah, I am Your servant and the son of Your male servant and the son of Your female servant. My forehead is in Your Hand (i.e. you have control over me). I am subject to Your judgement and Your decree concerning me is just. I ask You – by every name that is Yours, by which You have named Yourself, or taught any one of Your creation, or revealed in Your Book, or kept unto Yourself in the knowledge of the unseen that is with You – to make the Qur’ān the spring of my heart, the light of my chest, the banisher of my grief and the reliever of my anxiety.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “There is no one who is stricken with grief and anxiety, and then says [the above] — except that Allah will remove his grief and anxiety, and will give him joy instead.” The Companions asked, ‘O Messenger of Allah, should we not learn these words?’ He ﷺ replied, ‘Certainly! The one who hears them should learn them.’” (Ahmad 3712)","hadith":null,"reference":"عَنْ عَبْدِ اللهِ، قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: مَا أَصَابَ أَحَدًا قَطُّ هَمٌّ وَلَا حَزَنٌ، فَقَالَ: اللهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجِلَاءَ حُزْنِي، وَذَهَابَ هَمِّي، إِلَّا أَذْهَبَ اللهُ هَمَّهُ وَحُزْنَهُ، وَأَبْدَلَهُ مَكَانَهُ فَرَحًا، قَالَ: فَقِيلَ: يَا رَسُولَ اللهِ، أَلَا نَتَعَلَّمُهَا؟ فَقَالَ: بَلَى، يَنْبَغِي لِمَنْ سَمِعَهَا أَنْ يَتَعَلَّمَهَا. (مسند أحمد ٣٧١٢)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/anxious/"},{"title":"Grief & Anxiety #2","arabic":"لَا إِلٰهَ إِلَّا اللّٰهُ الْعَظِيْمُ الْحَلِيْمُ ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ الْعَرْشِ الْعَظِيْمِ ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ السَّمٰـوٰتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيْمِ\\nعَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ:كَانَ النَّبِيُّ صلى الله عليه وسلم يَدْعُو عِنْدَ الْكَرْبِ: لَا إِلَهَ إِلَّا اللهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللهُ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ رَبُّ الْعَرْشِ الْعَظِيمِ.","transliteration":"Lā ilāha illā-llāhu-l-ʿĀẓīmu-l-Ḥalīm, lā ilāha illā-llāhu Rabbu-l-ʿĀrshi-l-ʿAẓīm, lā ilāha illā-llāhu Rabbu-s-samāwāti wa Rabbu-l-arḍi wa Rabbu-l-ʿĀrshi-l-karīm.","translation":"There is no god worthy of worship except Allah — the Supreme, the Forbearing. There is no god worthy of worship except Allah — Lord of the Magnificent Throne. There is no god worthy of worship except Allah — Lord of the heavens, Lord of the earth, and Lord of the Noble Throne.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ used to supplicate with [the above] in times of distress. (Bukhārī 6345, Muslim 2730)","reference":"(صحيح البخاري ٦٣٤٥)\\nعَنِ ابْنِ عَبَّاسٍ؛ أَنَّ نبي الله صلى الله عليه وسلم كان يقول عند الكرب “لا إله إلا الله العظيم الحليم. لا إله إلا الله رب العرش العظيم. لا إله إلا الله رب السماوات ورب الأرض ورب العرش الكريم. (صحيح مسلم ٢٧٣٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/anxious/"},{"title":"When One Is Afraid of People #2","arabic":"حَسْبُنَا اللّٰهُ وَنِعْمَ الْوَكِيْلُ","transliteration":"Ḥasbunallāhu wa niʿmal Wakīl.","translation":"Allah is enough for us and He is the Best Protector.","description":null,"benefit":null,"virtue":null,"hadith":"Ibn ʿAbbās (radiy Allāhū ʿanhumā) narrated: “[The above] was said by Ibrāhīm (ʿalayhis-salām) when he was thrown into the fire; and it was said by Muḥammad ﷺ when (the hypocrites) said, ‘Your enemies have mobilised their forces against you, so fear them,’ — but this only increased them in faith and they replied: ‘Allah is enough for us and He is the Best Protector (3:173).’” (Bukhārī 4563)","reference":"عَنِ ابْنِ عَبَّاسٍ : حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ} قَالَهَا إِبْرَاهِيمُ عليه السلام حِينَ أُلْقِيَ فِي النَّارِ، وَقَالَهَا مُحَمَّدٌ صلى الله عليه وسلم حِينَ قَالُوا: إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ. (صحيح البخاري ٤٥٦٣)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/anxious/"},{"title":"When One Feels Frightened","arabic":"لَا إِلٰهَ إِلَّا اللّٰهُ","transliteration":"Lā ilāha illā-llāh.","translation":"There is no god worthy of worship except Allah.","description":null,"benefit":null,"virtue":null,"hadith":"Zaynab b. Jaḥsh (raḍiy Allāhu ʿanhā) said that the Messenger of Allah ﷺ once entered her house in a state of fear and said, “[The above]. Woe to the Arabs from a danger that is imminent. An opening has been made today in the wall of Ya‘jūj and Ma‘jūj like this” and he made a circle with his thumb and index finger. Zaynab b. Jaḥsh said, “O Messenger of Allah ﷺ! Will we be destroyed even though there are pious people amongst us?” He ﷺ said, “Yes, when evil becomes widespread.” (Bukhārī 3346)","reference":"عَنْ أُمِّ حَبِيبَةَ بِنْتِ أَبِي سُفْيَانَ عَنْ زَيْنَبَ ابْنَةِ جَحْشٍ رضي الله عنهن أَنَّ النَّبِيَّ صلى الله عليه وسلم دَخَلَ عَلَيْهَا فَزِعًا يَقُولُ لَا إِلَهَ إِلَّا اللهُ وَيْلٌ لِلْعَرَبِ مِنْ شَرٍّ قَدِ اقْتَرَبَ فُتِحَ الْيَوْمَ مِنْ رَدْمِ يَاجُوجُ وَمَاجُوجُ مِثْلُ هَذِهِ وَحَلَّقَ بِإِصْبَعِهِ الْإِبْهَامِ وَالَّتِي تَلِيهَا قَالَتْ زَيْنَبُ ابْنَةُ جَحْشٍ: فَقُلْتُ: يَا رَسُولَ اللهِ أَنَهْلِكُ وَفِينَا الصَّالِحُونَ قَالَ نَعَمْ إِذَا كَثُرَ الْخَبَثُ. (صحيح البخاري ٣٣٤٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Jaḥsh said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/anxious/"},{"title":"Allah Will Suffice You in Everything","arabic":"حَسْبِيَ اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ ، عَلَيْهِ تَوَكَّلْتُ ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ.","transliteration":"Ḥasbiya-Allāhu lā ilāha illā Huwa, ʿalayhi tawakkalt, wa Huwa Rabbu-l-ʿArshi-l-ʿaẓīm.","translation":"Repeat. x7","description":null,"benefit":null,"virtue":"Abū al-Dardā’ (raḍiy Allāhu ʿanhu) narrates from the Messenger of Allah ﷺ that he said: “Whoever recites [the above] seven times in the morning and in the evening, Allah will suffice him in everything that concerns him in matters of this world and the next.” (Ibn al-Sunnī 71)","hadith":null,"reference":"عَنْ أَبِي الدَّرْدَاءِ، رضي الله عنه، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ: مَنْ قَالَ فِي كُلِّ يَوْمٍ حِينَ يُصْبِحُ وَحِينَ يُمْسِي: حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ، سَبْعَ مَرَّاتٍ، كَفَاهُ اللَّهُ عز وجل هَمَّهُ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ. (عمل اليوم والليلة لابن السني ٧١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":7,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/anxious/"},{"title":"Duʿa of Prophet Musa ﷺ Expressing His Dire Need","arabic":"رَبِّ إِنِّيْ لِمَآ أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيْرٌ.","transliteration":"Rabbi innī limā anzalta illayya min khayrin faqīr.","translation":"My Lord, truly I am in dire need of any good which You may send me. (28:24)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/anxious/"},{"title":"When One Is Distressed","arabic":"اَللّٰهُمَّ رَحْمَتَكَ أَرْجُوْ فَلَا تَكِلْنِيْ إِلٰى نَفْسِيْ طَرْفَةَ عَيْنٍ ، وَأَصْلِحْ لِي شَأْنِيْ كُلَّهُ ، لَا إِلٰهَ إِلَّا أَنْتَ","transliteration":"Allāhumma raḥmataka arjū fa-lā takilnī ilā nafsī ṭarfata ʿayn, wa aṣliḥ lī sha’nī kullah, lā ilāha illā Ant.","translation":"O Allah! It is certainly Your Mercy what I hope for, so do not entrust me to myself for the blink of an eye; and rectify all of my affairs. There is no god worthy of worship except You.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ said: “The supplications of the distressed person are [the above].”","reference":"(Abū Dāwūd 5090)\\nعَنْ جَعْفَرِ بْنِ مَيْمُونٍ قَالَ: حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ «أَنَّهُ قَالَ لِأَبِيهِ : يَا أَبَتِ إِنِّي أَسْمَعُكَ تَدْعُو كُلَّ غَدَاةٍ: اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَدْعُو بِهِنَّ، فَأَنَا أُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ قَالَ عَبَّاسٌ فِيهِ: وَتَقُولُ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَتَدْعُو بِهِنَّ، فَأُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ. قَالَ: وَقَالَ رَسُولُ اللهِ صلى الله عليه وسلم: دَعَوَاتُ الْمَكْرُوبِ اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا ‌تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ.\\n(سنن ابي داود ٥٠٩٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/anxious/"},{"title":"Duʿa for Seeking Protection from Shaytan","arabic":"رَبِّ أَعُوْذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِيْنِ ، وَأَعُوذُ بِكَ رَبِّ أَنْ يَّحْضُرُوْنِ.","transliteration":"Rabbi aʿūdhu bika min hamazāti-sh-shayāṭīn. Wa aʿūdhu bika Rabbi ay-yaḥḍurūn.","translation":"My Lord, I seek protection with You from the promptings of the devils; and I seek protection in You, my Lord, from their coming near me. (23:97-98)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/anxious/"},{"title":"Duʿa of Prophet Ayyub ﷺ for Times of Distress","arabic":"-رَبِّ- أَنِّيْ مَسَّنِيَ الضُّرُّ وَأَنْتَ أَرْحَمُ الرّٰحِمِيْن.","transliteration":"(Rabbi) Annī massaniya-ḍ-ḍurru wa Anta Arḥamu-r-raḥimīn.","translation":"(My Lord), indeed adversity has touched me, and you are the Most Merciful of the merciful. (21:83)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/anxious/"}]},{"feeling":"Content","slug":"content","url":"https://allahuakbarofficial.com/content/","items_count":7,"duas":[{"title":"Fulfil Your Obligation to Thank Allah","arabic":"اَللّٰهُمَّ مَا أَصْبَحَ بِيْ مِنْ نِّعْمَةٍ أَوْ بِأَحَدٍ مِّنْ خَلْقِكَ ، فَمِنْكَ وَحْدَكَ لَا شَرِيْكَ لَكَ ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ.","transliteration":"Allāhumma mā aṣbaḥa bī min niʿmatin aw bi-aḥadim-min khalqik, fa-minka waḥdaka lā sharīka lak, fa laka-l-ḥamdu wa laka-sh-shukr.","translation":"O Allah, all the favours that I or anyone from Your creation has received in the morning, are from You Alone. You have no partner. To You Alone belong all praise and all thanks.","description":null,"benefit":null,"virtue":"ʿAbdullāh b. Ghannām (raḍiy Allāhu ʿanhu) narrates that the Messenger of Allah ﷺ said: “Whoever says [the above] in the morning has fulfilled his obligation to thank Allah for that day. And whoever says it in the evening has fulfilled his obligation for that night.”","hadith":null,"reference":"(Abū Dāwūd 5073)\\nعن عبدِ الله بن غنَّام البَياضيِّ، أن رسولَ الله صلى الله عليه وسلم قال: “من قال حينَ يُصبِح: اللَّهُمَّ ما أصبَحَ بي من نعمَةٍ فمِنكَ وحدَكَ لا شريكَ لك، فلكَ الحمدُ ولكَ الشُّكرُ، فقد أدَّى شُكرَ يومه، ومَن قال مِثلَ ذلك حينَ يُمسِي فقد أدَّى شُكرَ ليلَتِهِ. (سنن أبي داود ٥٠٧٣)\\nعَن عبد الله بن عَنْبَسَة عَن ابْن غنّام عَن رَسُول الله صلى الله عليه وسلم أَنه قَالَ من قَالَ حِين يصبح اللَّهُمَّ مَا أصبح بِي من نعْمَة أَو بأحدٍ من خلقك فمنك وَحدك لَا شريك لَك فلك الْحَمد وَلَك الشُّكْر إِلَّا أدّى شكر ذَلِك الْيَوْم.\\n(عمل اليوم والليلة للنسائي ٧)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/content/"},{"title":"Fulfil Your Obligation to Thank Allah","arabic":"اَللّٰهُمَّ مَا أَمْسَىٰ بِيْ مِنْ نِّعْمَةٍ أَوْ بِأَحَدٍ مِّنْ خَلْقِكَ ، فَمِنْكَ وَحْدَكَ لَا شَرِيْكَ لَكَ ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ.","transliteration":"Allāhumma mā amsā bī min niʿmatin aw bi-aḥadin min khalqik, fa-minka waḥdaka lā sharīka lak, fa laka-l-ḥamdu wa laka-sh-shukr.","translation":"O Allah, all the favours that I or anyone from Your creation has received in the evening, are from You Alone. You have no partner. To You Alone belong all praise and all thanks.","description":null,"benefit":null,"virtue":"ʿAbdullāh b. Ghannām (raḍiy Allāhu ʿanhu) narrates that the Messenger of Allah ﷺ said: “Whoever says [the above] in the morning has fulfilled his obligation to thank Allah for that day. And whoever says it in the evening has fulfilled his obligation for that night.”","hadith":null,"reference":"(Abū Dāwūd 5073)\\nعَن عبد الله بن عَنْبَسَة عَن ابْن غنّام عَن رَسُول الله صلى الله عليه وسلم أَنه قَالَ من قَالَ حِين يصبح اللَّهُمَّ مَا أصبح بِي من نعْمَة أَو بأحدٍ من خلقك فمنك وَحدك لَا شريك لَك فلك الْحَمد وَلَك الشُّكْر إِلَّا أدّى شكر ذَلِك الْيَوْم. (عمل اليوم والليلة للنسائي ٧)\\nعن عبدِ الله بن غنَّام البَياضيِّ، أن رسولَ الله صلى الله عليه وسلم قال: من قال حينَ يُصبِح: اللَّهُمَّ ما أصبَحَ بي من نعمَةٍ فمِنكَ وحدَكَ لا شريكَ لك، فلكَ الحمدُ ولكَ الشُّكرُ، فقد أدَّى شُكرَ يومه، ومَن قال مِثلَ ذلك حينَ يُمسِي فقد أدَّى شُكرَ ليلَتِهِ.(سنن ابي داود ٥٠٧٣)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/content/"},{"title":"Thank Allah for Blessing You","arabic":"اَلْحَمْدُ لِلّٰهِ الَّذِيْ أَطْعَمَنَا وَسَقَانَا ، وَكَفَانَا وَآوَانَا ، فَكَمْ مِّمَّنْ لَّا كَافِيَ لَهُ وَلَا مُؤْوِيَ.","transliteration":"Al-ḥamdu li-llāhi-l-ladhī aṭʿamanā wa saqānā, wa kafānā wa āwānā, fakam-mim-mal-lā kāfīya lahū walā mu’wiy.","translation":"All praise is for Allah, who provided us food and drink, and who sufficed us and has sheltered us; for how many have none to suffice them or shelter them.","description":null,"benefit":null,"virtue":null,"hadith":"Anas (raḍiy Allāhu ʿanhu) narrates that when the Messenger of Allah ﷺ would retire to bed, he would say [the above]. (Muslim 2715)","reference":"عَنْ أَنَسٍ أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم كَانَ إِذَا أَوَى إِلَى فِرَاشِهِ قَالَ: الْحَمْدُ لِلهِ الَّذِي أَطْعَمَنَا، وَسَقَانَا، وَكَفَانَا، وَآوَانَا فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ، وَلَا مُؤْوِيَ.\\n(صحيح مسلم ٢٧١٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/content/"},{"title":"Praise Allah with the Praises of the Entire Creation","arabic":"اَلْحَمْدُ لِلّٰهِ الَّذِيْ كَفَانِيْ وَآوَانِيْ ، اَلْحَمْدُ لِلّٰهِ الَّذِيْ أَطْعَمَنِيْ وَسَقَانِيْ ، اَلْحَمْدُ لِلّٰهِ الَّذِيْ مَنَّ عَلَيَّ فَأَفْضَلَ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ بِعِزَّتِكَ أَنْ تُنَجِّيَنِيْ مِنَ النَّارِ.","transliteration":"Al-ḥamdu lillāhi-lladhī kafānī wa āwānī, al-ḥamdu lillāhi-lladhī aṭʿamanī wa saqānī, al-ḥamdu lillāhi-lladhī manna ʿalayya fa-afḍal, Allāhumma innī as’aluka biʿizzatika an tunajjiyanī mina-n-nār.","translation":"All praise is for Allah who has sufficed me and given me refuge. All praise is for Allah who has fed me and given me drink. All praise is for Allah who has been gracious to me and showered favours on me. O Allah, I ask You by Your glory to save me from the Hell-Fire.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “Whoever says [the above] when retiring to bed has praised Allah with all the praises of His entire creation.” (Hākim 2001)","hadith":null,"reference":"عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: ” مَنْ قَالَ إِذَا أَوَى إِلَى فِرَاشِهِ: الْحَمْدُ لِلَّهِ الَّذِي كَفَانِي وَآوَانِي، الْحَمْدُ لِلَّهِ الَّذِي أَطْعِمْنِي وَسَقَانِي، الْحَمْدُ لِلَّهِ الَّذِي مَنَّ عَلَيَّ فَأَفْضَلَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ بِعِزَّتِكَ أَنْ تُنَجِّيَنِي مِنَ النَّارِ، فَقَدْ حَمِدَ اللَّهَ بِجَمِيعِ مَحَامِدِ الْخَلْقِ كُلِّهِمْ. (المستدرك على الصحيحين للحاكم ٢٠٠١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/content/"},{"title":"Praise Allah for All His Favours","arabic":"اَلْحَمْدُ لِلَّهِ الَّذِيْ يُطْعِمُ وَلَا يُطْعَمُ ، مَنَّ عَلَيْنَا فَهَدَانَا وَأَطْعَمَنَا وَسَقَانَا ، وَكُلَّ بَلَاءٍ حَسَنٍ أَبْلَانَا ، اَلْحَمْدُ لِلَّهِ غَيْرَ مُوَدَّعٍ وَّلَا مُكَافَأٍ وَّلَا مَكْفُوْرٍ وَّلَا مُسْتَغْنًى عَنْهُ ، اَلْحَمْدُ لِلَّهِ الَّذِيْ أَطْعَمَ مِنَ الطَّعَامِ ، وَسَقَىٰ مِنَ الشَّرَابِ ، وَكَسَا مِنَ الْعُرْيِ ، وَهَدَىٰ مِنَ الضَّلَالَةِ ، وَبَصَّرَ مِنَ الْعَمَىٰ ، وَفَضَّلَ عَلَىٰ كَثِيْرٍ مِّنْ خَلْقِهِ تَفْضِيْلًا ، اَلْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِيْنَ","transliteration":"Al-ḥamdu lillāhi-lladhī yuṭʿiumu wa lā yuṭʿam, manna ʿalaynā fa-hadānā wa aṭʿamanā wa saqānā, wa kulla balā’in ḥasanin ablānā, al-ḥamdu lillāhi ghayra muwaddaʿin wa lā mukāfa’iw-wa lā makfūrin wa lā mustaghnan ʿanh, al-ḥamdu lillāhi-lladhī aṭʿama mina-ṭ-ṭaʿām, wa saqā mina-sh-sharāb, wa kasā minal-ʿurā, wa hadā mina-ḍ-ḍalālah, wa baṣṣara mina-l-ʿamā, wa faḍḍala ʿalā kathīrim-min-khalqihī tafḍīlā, alḥamdu-lillāhi Rabbi-l-ʿālamīn.","translation":"All praise is for Allah who feeds and is not fed. He favoured us, and thus guided us, blessed us with food and drink, and bestowed upon us every favour. All praise is for Allah, a praise which we will never bid farewell to, a never-ending praise, an accepted praise and an indispensable praise. All praise is for Allah who provided food and drink; who clothed us, guided us from error, removed our blindness and favoured us greatly over many of His creation. All praise is for Allah, Lord of the worlds.","description":null,"benefit":null,"virtue":null,"hadith":"Abū Hurayrah (raḍiy Allāhu ‘anhu) narrates: “A man from the Anṣār from the people of Qubā invited the Prophet ﷺ for a meal. When he ﷺ had finished eating and had washed his hands, he said [the above].” (Nasā’ī in Sunan al-Kubrā 10060, Ibn Ḥibbān 2024)","reference":"عَنْ أَبِي هُرَيْرَةَ قَالَ: دَعَا رَجُلٌ مِنَ الْأَنْصَارِ مِنْ أَهْلِ قُبَاءٍ النَّبِيَّ صلى الله عليه وسلم، فَانْطَلَقْنَا مَعَهُ، فَلَمَّا طَعِمَ وَغَسَلَ يَدَهُ، أَوْ يَدَيْهِ عَلَيْنَا قَالَ: «الْحَمْدُ لِلَّهِ الَّذِي يُطْعِمُ وَلَا يُطْعَمُ، مَنَّ عَلَيْنَا فَهَدَانَا وَأَطْعَمَنَا وَسَقَانَا، وَكُلَّ بَلَاءٍ حَسَنٍ أَبْلَانَا، الْحَمْدُ لِلَّهِ غَيْرَ مُوَدَّعٍ، وَلَا مُكَافَئٍ وَلَا مَكْفُورٍ، وَلَا مُسْتَغْنًى عَنْهُ، الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَ مِنَ الطَّعَامِ، وَسَقَى مِنَ الشَّرَابِ، وَكَسَا مِنَ الْعُرْيِ، وَهَدَى مِنَ الضَّلَالَةِ، وَبَصَّرَ مِنَ الْعَمَى، وَفَضَّلَ عَلَى كَثِيرٍ مِنْ خَلْقِهِ تَفْضِيلًا، الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ.\\n(السنن الكبرى للنسائي ١٠٠٦٠)\\nعَنْ أَبِي هُرَيْرَةَ، قَالَ: دَعَا رَجُلٌ مِنَ الأَنْصَارِ النَّبِيَّ صلى الله عليه وسلم، قَالَ: فَانْطَلَقْنَا مَعَهُ، فَلَمَّا طَعِمَ وَغَسَلَ يَدَهُ، قَالَ: “الْحَمْدُ للهِ الَّذِي يُطْعِمُ وَلَا يُطْعَمُ، مَنَّ عَلَيْنَا فَهَدَانَا، وَأَطْعَمَنَا وَسَقَانَا، وَكُلَّ بَلَاءٍ حَسَنٍ أَبْلَانَا، الْحَمْدُ للهِ الَّذِي أَطْعَمَ مِنَ الطَّعَامِ، وَسَقَى مِنَ الشَّرَابِ، وَكَسَا مِنَ الْعُرْيِ، وَهَدَى مِنَ الضَّلَالَةِ، وَبَصَّرَ مِنَ الْعَمَى، وَفَضَّلَ عَلَى كَثِيرٍ مِمَّنْ خَلَقَ ‌تَفْضِيلاً، الْحَمْدُ للهِ رَبِّ الْعَالَمِينَ.\\n(صحيح ابن حبان  ٢٠٢٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/content/"},{"title":"Duʿa of Prophet Yusuf ﷺ for A Good Ending","arabic":"-اَللّٰهُمَّ يَا- فَاطِرَ السَّمٰوَاتِ وَالْأَرْضِ ، أَنْتَ وَلِـيِّيْ فِي الدُّنْيَا وَالْآخِرَةِ ، تَوَفَّنِيْ مُسْلِمًا وَّأَلْحِقْنِيْ بِالصَّالِحِيْنَ.","transliteration":"(Allāhumma yā) Fāṭira-s-samāwāti wa-l-arḍi Anta waliy-yi fi-d-dunyā wal-ākhirah, tawaffanī Muslimaw-wa alḥiqnī bi-ṣ-ṣāliḥīn.","translation":"(O Allah), Originator of the heavens and the earth, You are my Protector in this world and in the Hereafter. Make me die a Muslim and join me with the righteous. (12:101)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/content/"},{"title":"Protection from Allah’s Anger & Removal of Blessings","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ ، وَتَحَوُّلِ عَافِيَتِكَ ، وَفُجَاءَةِ نِقْمَتِكَ ، وَجَمِيْعِ سَخَطِكَ.\\nعَنِ ابْنِ عُمَرَ قَالَ:كَانَ مِنْ دُعَاءِ رَسُولِ اللهِ صلى الله عليه وسلم: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ، وَتَحْوِيلِ عَافِيَتِكَ، وَفُجَاءَةِ نِقْمَتِكَ، وَجَمِيعِ سَخَطِكَ.","transliteration":"Allāhumma innī aʿūdhu bika min zawāli niʿmatik, wa taḥawwuli ʿāfiyatik, wa fujā’ati niqmatik, wa jamīʿi sakhaṭik.","translation":"O Allah, I seek Your protection from the loss of Your favours, the removal of Your complete protection, Your sudden punishment and all that which may incur Your displeasure.","description":null,"benefit":null,"virtue":null,"hadith":"ʿAbdullah b. ʿUmar (radiy Allāhū ‘anhumā) reported that from the supplication of the Messenger of Allah ﷺ was [the above]. (Muslim 2739, Abū Dāwūd 1545)","reference":"عَنْ عَبْدِ الله بن عمر، قال كان من دعاء رَسُولُ اللَّهِ صلى الله عليه وسلم “اللَّهُمَّ! إني أعوذ بك من زوال نعمتك، وتحول عافيتك، وفجاءة نقمتك، وجميع سخطك.\\n(صحيح مسلم ٢٧٣٩)\\n(سنن ابي داود ١٥٤٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/content/"}]},{"feeling":"Confused","slug":"confused","url":"https://allahuakbarofficial.com/confused/","items_count":8,"duas":[{"title":"Surah al-Fatihah: The Greatest Duʿa","arabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيْمِ ،\\nاَلْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِيْنَ ، الرَّحْمٰنِ الرَّحِيْمِ ، مٰلِكِ يَوْمِ الدِّيْنِ ، إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِيْنُ ، اِهْدِنَا الصِّرَاطَ الْمُسْتَقِيْمَ ، صِرَاطَ الَّذِيْنَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوْبِ عَلَيْهِمْ وَلَا الضَّآلِّيْنَ","transliteration":"Bismi-llāhi-r-Raḥmāni-r-Raḥīm. Alḥamdu-lillāhi Rabbi-l-ʿālamīn, ar-Raḥmāni-r-Raḥīm, Māliki yawmi-d-dīn, iyyāka naʿbudu wa iyyāka nastaʿīn, ihdina-ṣ-Ṣirāṭa-l-Mustaqīm, ṣirāṭa-lladhīna anʿamta ʿalayhim ghayri-l-maghḍūbi ʿālayhim wa la-ḍ-ḍāllīn.","translation":"In the name of Allah, the All-Merciful, the Very Merciful. All praises and thanks are for Allah, the Lord of all the worlds, The All-Merciful, The Very Merciful, Master of the Day of Judgement. You Alone we worship, You Alone we ask for help. Guide us on the Straight Path, the path of those whom You have favoured, not of those who incur (Your) anger nor of those who have gone astray. (1:1-7)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/confused/"},{"title":"Istikharah (Seeking Allah‘s Help in Making a Decision)","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْتَخِيْرُكَ بِعِلْمِكَ ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيْمِ ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ ، وَتَعْلَمُ وَلَا أَعْلَمُ ، وَأَنْتَ عَلَّامُ الْغُيُوْبِ . اَللّٰهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هٰذَا الْأَمْرَ (ويسمّي حاجته) خَيْرٌ لِّيْ فِيْ دِيْنِيْ وَمَعَاشِيْ وَعَاقِبَةِ أَمْرِيْ ، فَاقْدُرْهُ لِيْ وَيَسِّرْهُ لِيْ ثُمَّ بَارِكْ لِيْ فِيْهِ ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هٰذَا الْأَمْرَ (ويسمّي حاجته) شَرٌّ لِّيْ فِيْ دِيْنِيْ وَمَعَاشِيْ وَعَاقِبَةِ أَمْرِيْ ، فَاصْرِفْهُ عَنِّيْ وَاصْرِفْنِيْ عَنْهُ ، وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ ثُمَّ أَرْضِنِيْ بِهِ\\nوقال بن أبي جمرة الحكمة في تقديم الصلاة على الدعاء أن المراد بالاستخارة حصول الجمع بين خيري الدنيا والآخرة فيحتاج إلى قرع ‌باب ‌الملك ولا شيء لذلك أنجع ولا أنجح من الصلاة لما فيها من تعظيم الله والثناء عليه والافتقار إليه مآلا وحالا.","transliteration":"Allāhumma innī astakhīruka bi ʿilmik, wa astaqdiruka bi qudratik, wa as’aluka min faḍlika-l-ʿaẓīm, fa innaka taqdiru wa lā aqdir, wa taʿlamu wa lā aʿlam, wa Anta ʿAllāmu-l-ghuyūb. Allāhumma in kunta taʿlamu an-na hādha-l-amr (specify the matter) khayrul-lī fī dīnī wa maʿāshī wa ʿāqibati amrī, faqdurhu lī wa yassirhu lī thumma bārik lī fīh, wa in kunta taʿlamu anna hādha-l-amr (specify the matter) sharrul-lī fī dīnī wa maʿāshī wa ʿāqibati amrī, faṣrifhu ʿannī waṣrifnī ʿanh, waqdur liya-l-khayra ḥaythu kān, thumma arḍinī bih.","translation":"O Allah, I ask You for the best through Your knowledge, I seek strength through Your power, and I ask You from Your immense favour. For You are fully able whilst I am not, You know everything whilst I do not know anything, and You are the Knower of the unseen. O Allah, if in Your knowledge, this matter (specify the matter) is good for me in my religion, my livelihood and my ultimate destiny, then decree it for me and make it easy it for me, then bless it for me. But if in Your knowledge, this matter (specify the matter) is bad for me in my religion, my livelihood and my ultimate destiny, then turn it away from me, and turn me away from it. Decree good for me wherever it may be, then make me pleased with it.","description":null,"benefit":null,"virtue":null,"hadith":"Jābir (raḍiy Allāhu ʿanhu) narrated: “The Messenger of Allah ﷺ used to teach us *istikhārah* (when one seeks Allah’s help in making a decision) for all matters, the same way he taught us Sūrahs from the Qur’ān. He ﷺ said: “When one of you intends to do something, he should offer two rak‘ahs of voluntary ṣalāh, and then say [the above].” (Bukhārī 6382)","reference":"Ibn Abī Jamrah (raḥimahullāh) said: “The wisdom of preceding ṣalāh before the duʿā’ is that the purpose of *istikhārah* is to combine the good of this world and the hereafter. A person needs to knock at the door of the King (Allah), and there is nothing more effective for this than ṣalāh, because it combines the glorification and praise of Allah, and expresses one’s need for Him at all times.” (Fatḥ al-Bārī 11/186)\\nعَنْ جَابِرٍ رضي الله عنه قَالَ: كَانَ النَّبِيُّ صلى الله عليه وسلم يُعَلِّمُنَا الِاسْتِخَارَةَ فِي الْأُمُورِ كُلِّهَا، كَالسُّورَةِ مِنَ الْقُرْآنِ: إِذَا هَمَّ بِالْأَمْرِ فَلْيَرْكَعْ رَكْعَتَيْنِ، ثُمَّ يَقُولُ: اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي، أَوْ قَالَ فِي عَاجِلِ أَمْرِي وَآجِلِهِ، فَاقْدُرْهُ لِي، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي، أَوْ قَالَ فِي عَاجِلِ أَمْرِي وَآجِلِهِ، فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِي الْخَيْرَ حَيْثُ كَانَ ثُمَّ رَضِّنِي بِهِ، وَيُسَمِّي حَاجَتَهُ. (صحيح البخاري ٦٣٨٢)\\n(فتح الباري بشرح البخاري ١١\\\\١٨٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/confused/"},{"title":"Duʿa of Prophet Musa ﷺ Expressing His Dire Need","arabic":"رَبِّ إِنِّيْ لِمَآ أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيْرٌ.","transliteration":"Rabbi innī limā anzalta illayya min khayrin faqīr.","translation":"My Lord, truly I am in dire need of any good which You may send me. (28:24)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/confused/"},{"title":"Best Outcomes & Protection from Humiliation","arabic":"اَللّٰهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي الْأُمُوْرِ كُلِّهَا ، وَأَجِرْنَا مِنْ خِزْيِ الدُّنْيَا وَعَذَابِ الْآخِرَةِ","transliteration":"Allāhumma aḥsin ʿāqibatanā fi-l-umūri kullihā, wa ajirnā min khizyi-d-dunyā wa ʿadhābi-l-ākhirah.","translation":"O Allah, grant us the best outcome in all of our affairs, and protect us from the humiliation of this world and the punishment of the hereafter.","description":null,"benefit":null,"virtue":null,"hadith":"Busr b. Abī Artāt (raḍiy Allāhu ‘anhu) narrates that I heard the Messenger of Allah ﷺ supplicate with [the above]. (Aḥmad 17628)","reference":"عَنْ بُسْرِ بْنِ أَرْطَاةَ الْقُرَشِيِّ، قَالَ: سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَدْعُو: ” اللهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي الْأُمُورِ كُلِّهَا، وَأَجِرْنَا مِنْ خِزْيِ الدُّنْيَا وَعَذَابِ الْآخِرَةِ. (مسند احمد ١٧٦٢٨)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/confused/"},{"title":"A Priceless Treasure","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ ، وَالْعَزِيْمَةَ عَلَى الرُّشْدِ ، وَأَسْأَلُكَ مُوْجِبَاتِ رَحْمَتِكَ ، وَعَزَائِمَ مَغْفِرَتِكَ ، وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ ، وَحُسْنَ عِبَادَتِكَ ، وَأَسْأَلُكَ قَلْبًا سَلِيْمًا ، وَلِسَانًا صَادِقًا ، وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ ، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ ، وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ ، إِنَّكَ أَنْتَ عَلَّامُ الْغُيُوْبِ","transliteration":"Allāhumma innī as’aluka-th-thabāta fil-amr, wa-l-ʿazīmata ʿala-r-rushd, wa as’aluka mūjibāti raḥmatik, wa ʿazā’ima maghfiratik, wa as’aluka shukra niʿmatik, wa ḥusna ʿibādatik, wa as’aluka qalban salīmā, wa lisānan ṣādiqā, wa as’aluka min khayri mā taʿlam, wa aʿūdhu bika min sharri mā taʿlam, wa astaghfiruka limā taʿlam, innaka Anta ʿAllāmul-ghuyūb.","translation":"O Allah, I beg you for steadfastness in all matters and the determination to take the right course. I ask You for all that which will necessitate Your mercy and the determination to do all that which will necessitate Your forgiveness. I ask You to make me grateful for Your blessings and to worship You in an excellent manner. I ask You for a sound heart and a truthful tongue. I ask You for the good of what You know, I seek Your protection from the evil of what You know, and I seek Your forgiveness for what You know. Indeed, You are the All-Knowing of the unseen.","description":null,"benefit":null,"virtue":"Shaddād b. Aws (raḍiy Allāhu ‘anhu) narrates that the Messenger of Allah ﷺ was teaching this duā to me. he said: “O Shaddād, when you see people collecting gold & silver as their treasures, then consider [the above] as your treasure.” (Ahmad 17114)","hadith":null,"reference":"حَدَّثَنَا رَوْحٌ، قَالَ: حَدَّثَنَا الْأَوْزَاعِيُّ، عَنْ حَسَّانَ بْنِ عَطِيَّةَ قَالَ: كَانَ شَدَّادُ بْنُ أَوْسٍ، فِي سَفَرٍ، فَنَزَلَ مَنْزِلًا، فَقَالَ لِغُلَامِهِ: ائْتِنَا بِالسُّفْرَةِ نَعْبَثْ بِهَا. فَأَنْكَرْتُ عَلَيْهِ، فَقَالَ: مَا تَكَلَّمْتُ بِكَلِمَةٍ مُنْذُ أَسْلَمْتُ إِلَّا وَأَنَا أَخْطِمُهَا وَأَزُمُّهَا غَيْرَ كَلِمَتِي هَذِهِ، فَلَا تَحْفَظُوهَا عَلَيَّ، وَاحْفَظُوا مِنِّي مَا أَقُولُ لَكُمْ: سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَقُولُ: ” إِذَا كَنَزَ النَّاسُ الذَّهَبَ وَالْفِضَّةَ، فَاكْنِزُوا هَؤُلَاءِ الْكَلِمَاتِ: اللهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ، وَالْعَزِيمَةَ عَلَى الرُّشْدِ، وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ، وَأَسْأَلُكَ حُسْنَ عِبَادَتِكَ، وَأَسْأَلُكَ قَلْبًا سَلِيمًا، وَأَسْأَلُكَ لِسَانًا صَادِقًا، وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ، إِنَّكَ أَنْتَ عَلَّامُ الْغُيُوبِ.\\n(مسند احمد ١٧١١٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/confused/"},{"title":"Asking for Good & Protection From Evil","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ ، وَأَعُوْذُ بِكَ مِنَ الشَّرِّ كُلِّهِ عَاجِلِهِ وَآجِلِهِ ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ عَبْدُكَ وَنَبِيُّكَ ، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا عَاذَ مِنْهُ عَبْدُكَ وَنَبِيُّكَ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْجَنَّةَ ، وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ ، وَأَعُوْذُ بِكَ مِنَ النَّارِ ، وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ ، وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ قَضَيْتَهُ لِيْ خَيْرًا","transliteration":"Allāhumma innī as’aluka mina-l-khayri kullihī ʿājilihī wa ājilih, mā ʿalimtu minhu wa mā lam aʿlam, wa aʿūdhu bika mina-sh-sharri kullih ʿājilihī wa ājilih, mā ʿalimtu minhu wa mā lam aʿlam, Allāhumma innī as’aluka min khayri mā sa’alaka ʿabduka wa Nabiyyuk, wa aʿūdhu bika min sharri mā ʿādha minhu ʿabduka wa Nabiyyuk, Allāhumma innī as’aluka-l-Jannah, wa mā qarraba ilayhā min qawlin aw ʿamal, wa aʿūdhu bika mina-n-nār, wa mā qarraba ilayhā min qawlin aw ʿamal, wa as’aluka an tajʿala kulla qaḍā’in qaḍaytahū lī khayrā.","translation":"O Allah, I beg You for all good: the immediate and the delayed, what I know of and what I do not know. I seek Your protection from all evil: the immediate and the delayed, what I know of and what I do not know. O Allah, I beg You for the good which Your slave and Prophet ﷺ asked from You, and I seek Your protection from the evil which Your slave and Prophet ﷺ sought protection for from You. O Allah, I beg You for Paradise, and whatever words or actions lead to it. I seek Your protection from Hell-fire, and whatever words or actions lead to it. I ask You to decree good for me in everything You foreordain for me.","description":null,"benefit":null,"virtue":null,"hadith":"‘Āishah narrates that the Messenger of Allah ﷺ taught her [the above]. (Ahmad 25019)","reference":"عَنْ عَائِشَةَ أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم عَلَّمَهَا هَذَا الدُّعَاءَ: اللهُمَّ إِنِّي أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، وَأَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ، وَمَا لَمْ أَعْلَمْ، اللهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ عَبْدُكَ وَنَبِيُّكَ مُحَمَّدٌ صلى الله عليه وسلم، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا عَاذَ مِنْهُ عَبْدُكَ وَنَبِيُّكَ، اللهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَعُوذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ تَقْضِيهِ لِي خَيْرًا.\\n(مسند احمد ٢٥٠١٩)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/confused/"},{"title":"Guidance to the Truth","arabic":"اَللّٰهُمَّ رَبَّ جَبْرَائِيْلَ ، وَمِيْكَائِيْلَ ، وإِسْرَافِيْلَ ، فَاطِرَ السَّمٰوَاتِ وَالْأَرْضِ ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ ، أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيْمَا كَانُوْا فِيْهِ يَخْتَلِفُوْنَ ، اِهْدِنِيْ لِمَا اخْتُلِفَ فِيْهِ مِنَ الْحَقِّ بِإِذْنِكَ ، إِنَّكَ تَهْدِيْ مَنْ تَشَاءُ إِلَىٰ صِرَاطٍ مُّسْتَقِيْمٍ.","transliteration":"Allāhumma Rabba Jabrā’īla, wa Mīkā’īla, wa Isrāfīl, fāṭira-s-samāwāti wa-l-arḍ, ʿālima-l-ghaybi wa-sh-shahādah, Anta taḥkumu bayna ʿibādika fīmā kānū fīhi yakhtalifūn, ihdinī lima-khtulifa fīhi mina-l-ḥaqqi bi-idhnik, innaka tahdī man tashā’u ilā Ṣirāṭi-m-Mustaqīm.","translation":"O Allah, Lord of Jabrā’īl, Mīkā’īl and Isrāfīl, Creator of the heavens and the earth, Knower of the unseen and seen; You will judge between Your servants in what they used to differ. Guide me in what is contentious to the truth, by Your will. Indeed, You guide whomsoever You wish to a straight path.","description":null,"benefit":null,"virtue":null,"hadith":"ʿAbdur Rahmān b. Awf (raḍiy Allāhu ‘anhu) narrated: I asked ‘Ā’isha (raḍiy Allāhu ‘anhā), the mother of the believers, (to tell me) the words with which the Messenger of Allah ﷺ commenced the Salāh when he got up at night. She said: “When he got up at night he would commence his Salāh with [the above] words. (Muslim 770)","reference":"حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، وَمُحَمَّدُ بْنُ حَاتِمٍ، وَعَبْدُ بْنُ حُمَيْدٍ، وَأَبُو مَعْنٍ الرَّقَاشِيُّ قَالُوا: حَدَّثَنَا عُمَرُ بْنُ يُونُسَ ، حَدَّثَنَا عِكْرِمَةُ بْنُ عَمَّارٍ ، حَدَّثَنَا يَحْيَى بْنُ أَبِي كَثِيرٍ ، حَدَّثَنِي أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ قَالَ: « سَأَلْتُ عَائِشَةَ أُمَّ الْمُؤْمِنِينَ بِأَيِّ شَيْءٍ كَانَ نَبِيُّ اللهِ صلى الله عليه وسلم يَفْتَتِحُ صَلَاتَهُ إِذَا قَامَ مِنَ اللَّيْلِ؟ قَالَتْ: كَانَ إِذَا قَامَ مِنَ اللَّيْلِ افْتَتَحَ صَلَاتَهُ: اللَّهُمَّ رَبَّ جَبْرَائِيلَ وَمِيكَائِيلَ وَإِسْرَافِيلَ، فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ. اهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ، إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ. (صحيح مسلم ٧٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"She said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/confused/"},{"title":"Guidance & Steadfastness","arabic":"اَللّٰهُمَّ اهْدِنِيْ وَسَدِّدْنِيْ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْهُدَىٰ وَالسَّدَادَ.","transliteration":"Allāhumma-hdinī wa saddidnī, Allāhumma innī as’aluka-l-hudā wa-s-sadād.","translation":"O Allah, guide me and grant me firmness. O Allah, I beg You for guidance and firmness (on the straight path).","description":null,"benefit":null,"virtue":null,"hadith":"Ali (raḍiy Allāhu ‘anhu) reported that the Messenger of Allah ﷺ said to him: “Say: [the above] and when you make a mention of guidance, keep in mind the (Straight) Path and when you consider the Straight (Path), keep in mind the straightness of the arrow.” (Muslim 2725)","reference":"عَنْ عَلِيٍّ قَالَ:قَالَ لِي رَسُولُ اللهِ صلى الله عليه وسلم: قُلِ: اللَّهُمَّ اهْدِنِي، وَسَدِّدْنِي، وَاذْكُرْ بِالْهُدَى هِدَايَتَكَ الطَّرِيقَ وَالسَّدَادِ سَدَادَ السَّهْمِ. (صحيح مسلم ٢٧٢٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/confused/"}]},{"feeling":"Depressed","slug":"depressed","url":"https://allahuakbarofficial.com/depressed/","items_count":19,"duas":[{"title":"Surah al-Fatihah: The Greatest Duʿa","arabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيْمِ ،\\nاَلْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِيْنَ ، الرَّحْمٰنِ الرَّحِيْمِ ، مٰلِكِ يَوْمِ الدِّيْنِ ، إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِيْنُ ، اِهْدِنَا الصِّرَاطَ الْمُسْتَقِيْمَ ، صِرَاطَ الَّذِيْنَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوْبِ عَلَيْهِمْ وَلَا الضَّآلِّيْنَ","transliteration":"Bismi-llāhi-r-Raḥmāni-r-Raḥīm. Alḥamdu-lillāhi Rabbi-l-ʿālamīn, ar-Raḥmāni-r-Raḥīm, Māliki yawmi-d-dīn, iyyāka naʿbudu wa iyyāka nastaʿīn, ihdina-ṣ-Ṣirāṭa-l-Mustaqīm, ṣirāṭa-lladhīna anʿamta ʿalayhim ghayri-l-maghḍūbi ʿālayhim wa la-ḍ-ḍāllīn.","translation":"In the name of Allah, the All-Merciful, the Very Merciful. All praises and thanks are for Allah, the Lord of all the worlds, The All-Merciful, The Very Merciful, Master of the Day of Judgement. You Alone we worship, You Alone we ask for help. Guide us on the Straight Path, the path of those whom You have favoured, not of those who incur (Your) anger nor of those who have gone astray. (1:1-7)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"When Difficulties Make You Yearn for Death","arabic":"اَللّٰهُمَّ أَحْيِنِيْ مَا كَانَتِ الْحَيَاةُ خَيْرًا لِّيْ ، وَتَوَفَّنِيْ إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِّيْ","transliteration":"Allāhumma aḥyinī mā kānati-l-ḥayātu khayral-lī, wa tawaffanī idhā kānati-l-wafātu khayral-lī.","translation":"O Allah, let me live as long as life is better for me; and give me death when death is better for me.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ said: “None of you should wish for death because of a difficulty that befalls him. Rather he should say [the above].” (Bukhārī 5671, Muslim 2680)","reference":"عَنْ أَنَسِ بْنِ مَالِكٍ رضي الله عنه، قَالَ النَّبِيُّ صلى الله عليه وسلم: «لَا يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ مِنْ ضُرٍّ أَصَابَهُ، فَإِنْ كَانَ لَا بُدَّ فَاعِلًا فَلْيَقُلِ: اللَّهُمَّ أَحْيِنِي مَا كَانَتِ الْحَيَاةُ خَيْرًا لِي، وَتَوَفَّنِي إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِي. (صحيح البخاري ٥٦٧١)\\nعَنْ أَنَسٍ، قَالَ قَالَ رسول الله صلى الله عليه وسلم لا يتمنين أحدكم الموت لضر نزل به. فإن كان لابد متمنيا فليقل: اللهم! أحيني ما كانت الحياة خيرا لي، وتوفني إذا كانت الوفاة خيرا لي.\\n(صحيح مسلم ٢٦٨٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"When One Is in a Difficult Situation","arabic":"اَللّٰهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا ، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا","transliteration":"Allāhumma lā sahla illā mā jaʿaltahū sahlā, wa anta tajʿalu-l-ḥazna idhā shi’ta sahlā.","translation":"O Allah, there is no ease except in that which You have made easy; and You make the difficulty easy when You wish.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Malik (raḍiy Allāhu ʿanhu) ﷺ narrates that the Messenger of Allah said [the above].","reference":"(Ibn Ḥibbān 6737, Ibn al-Sunnī 351)\\nعَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم، قَالَ: اللهُمَّ ‌لَا ‌سَهْلَ إِلَاّ مَا جَعَلْتَهُ سَهْلاً، وَأَنْتَ تَجْعَلُ الْحَزْنَ سَهْلاً إِذَا شِئْتَ. (صحيح ابن حبان ٦٧٣٧)\\nعَنْ أَنَسِ بْنِ مَالِكٍ، رضي الله عنه أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ: اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا، وَأَنْتَ تَجْعَلُ الْحَزَنَ إِذَا شِئْتَ سَهْلًا.\\n(عمل اليوم والليلة لابن السني ٣٥١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Allah said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"Protect Yourself From Anxiety, Laziness & Debt","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ ، وَأَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ ، وَأَعُوْذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.","transliteration":"Allāhumma innī aʿūdhu bika min-l-hammi wa-l-ḥazan, wa aʿūdhu bika min-l-ʿajzi wa-l-kasal, wa aʿūdhu bika min-l-jubni wa-l-bukhl, wa aʿūdhu bika min ghalabati-d-dayni wa qahri-r-rijāl.","translation":"O Allah, I seek Your protection from anxiety and grief. I seek Your protection from inability and laziness. I seek Your protection from cowardice and miserliness, and I seek Your protection from being overcome by debt and being overpowered by men.","description":null,"benefit":null,"virtue":"Abū Saʿīd al-Khudrī (raḍiy Allāhu ʿanhu) narrated that one day, the Messenger of Allah ﷺ entered the masjid. He saw a man from the Anṣār called Abū Umāmah (raḍiy Allāhu ʿanhu). He ﷺ asked, “What is the matter? Why are you sitting in the masjid when it is not the time for prayer?” He replied, “Never-ending worries and debts, O Messenger of Allah.” The Messenger of Allah ﷺ then asked, “Shall I not teach you words by which, when you say them, Allah will remove your worries, and settle your debts?” He replied, “Yes of course, O Messenger of Allah.” He ﷺ said, “Say in the morning and evening [the above].” Abū Umāmah (raḍiy Allāhu ʿanhu) said, “Then I did that, and Allah removed my worries and settled my debts.” (Abū Dāwūd 1555)","hadith":null,"reference":"عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: دَخَلَ رَسُولُ صَلَّى عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ مِنَ الْأَنْصَارِ، يُقَالُ لَهُ: أَبُو أُمَامَةَ، فَقَالَ: «يَا أُمَامَةَ، مَا لِي أَرَاكَ جَالِسًا فِي الْمَسْجِدِ فِي غَيْرِ وَقْتِ الصَّلَاةِ؟»، قَالَ: هُمُومٌ لَزِمَتْنِي، وَدُيُونٌ يَا رَسُولَ اللَّهِ، قَالَ: أَفَلَا أُعَلِّمُكَ كَلَامًا إِذَا أَنْتَ قُلْتَهُ أَذْهَبَ عز وجل هَمَّكَ، وَقَضَى عَنْكَ دَيْنَكَ؟، قَالَ: قُلْتُ: بَلَى، يَا رَسُولَ، قَالَ: ” قُلْ إِذَا أَصْبَحْتَ، وَإِذَا أَمْسَيْتَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَقَهْرِ الرِّجَالِ “، قَالَ: فَفَعَلْتُ ذَلِكَ، فَأَذْهَبَ اللَّهُ عز وجل هَمِّي، وَقَضَى عَنِّي دَيْنِي.\\n(سنن أبي داود ١٥٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"When Struck by a Calamity","arabic":"إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ رَاجِعُوْنَ ، اَللّٰهُمَّ اْجُرْنِيْ فِيْ مُصِيْبَتِيْ ، وَأَخْلِفْ لِيْ خَيْرًا مِّنْهَا","transliteration":"Innā lillāhi wa innā ilayhi rājiʿūn, Allāhumma-‘jurnī fī muṣībatī, wa akhlif lī khayram-minhā.","translation":"Indeed, to Allah we belong and to Him we will return. O Allah, recompense me for my affliction and replace it for me with something better.","description":null,"benefit":null,"virtue":"Umm Salamah (raḍiy Allāhu ʿanhā) said: I heard the Messenger of Allah ﷺ say, “There is no Muslim who is afflicted with a calamity, and then says what Allah has commanded him [the above duʿā’], except that Allah will recompense him with something better than it.” She says: “When Abū Salamah (her first husband) passed away, I said, ‘Which Muslim is better than Abū Salamah – the first household to migrate to the Messenger of Allah?’ I then said [the above], and Allah recompensed me (by marrying me to) the Messenger of Allah ﷺ.” (Muslim 918)","hadith":null,"reference":"وحدثنا أبو بكر بن أبي شيبة. حدثنا أَبُو أُسَامَةَ عَنْ سَعْدِ بْنِ سَعِيدٍ. قَالَ: أَخْبَرَنِي عُمَرُ بْنُ كَثِيرِ بْنِ أَفْلَحَ. قَالَ: سَمِعْتُ ابْنَ سَفِينَةَ يُحَدِّثُ؛ أَنَّهُ سَمِعَ أُمِّ سَلَمَةَ ، أَنَّهَا قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَقُولُ: مَا مِنْ مُسْلِمٍ تُصِيبُهُ مُصِيبَةٌ فَيَقُولُ مَا أَمَرَهُ اللهُ: إِنَّا لِلهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرًا مِنْهَا، إِلَّا أَخْلَفَ اللهُ لَهُ خَيْرًا مِنْهَا، قَالَتْ: فَلَمَّا مَاتَ أَبُو سَلَمَةَ قُلْتُ: أَيُّ الْمُسْلِمِينَ خَيْرٌ مِنْ أَبِي سَلَمَةَ؟ أَوَّلُ بَيْتٍ هَاجَرَ إِلَى رَسُولِ اللهِ صلى الله عليه وسلم، ثُمَّ إِنِّي قُلْتُهَا، فَأَخْلَفَ اللهُ لِي رَسُولَ اللهِ صلى الله عليه وسلم، قَالَتْ: أَرْسَلَ إِلَيَّ رَسُولُ اللهِ صلى الله عليه وسلم حَاطِبَ بْنَ أَبِي بَلْتَعَةَ يَخْطُبُنِي لَهُ، فَقُلْتُ: إِنَّ لِي بِنْتًا وَأَنَا غَيُورٌ، فَقَالَ: أَمَّا ابْنَتُهَا فَنَدْعُو اللهَ أَنْ يُغْنِيَهَا عَنْهَا، وَأَدْعُو اللهَ أَنْ يُذْهِبَ بِالْغَيْرَةِ. (صحيح مسلم ٩١٨)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"I said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"Attain Well-being in This World and the Hereafter","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِيْ دِيْنِيْ وَدُنْيَايَ وَأَهْلِيْ وَمَالِيْ ، اَللّٰهُمَّ اسْتُرْ عَوْرَاتِيْ وَآمِنْ رَّوْعَاتِيْ ، اَللّٰهُمَّ احْفَظْنِيْ مِنْ بَيْنِ يَدَيَّ ، وَمِنْ خَلْفِيْ ، وَعَنْ يَّمِيْنِيْ ، وَعَنْ شِمَالِيْ ، وَمِنْ فَوْقِيْ ، وَأَعُوْذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِيْ.","transliteration":"Allāhumma innī as’aluka-l-ʿāfiyata fi-d-dunyā wa-l-ākhirah. Allāhumma innī as’aluka-l-ʿafwa wa-l-ʿāfiyata fī dīnī wa dunyāya wa ahlī wa mālī, Allāhumma-stur ʿawrātī wa āmi-r-rawʿātī. Allāhumma-ḥfaẓnī mim bayni yadayya wa min khalfī, wa ʿay-yamīnī wa ʿan shimālī wa min fawqī, wa aʿūdhu bi-ʿaẓamatika an ughtāla min taḥtī.","translation":"O Allah, I ask You for well-being in this world and the next. O Allah, I ask You for forgiveness and well-being in my religion, in my worldly affairs, in my family and in my wealth. O Allah, conceal my faults and calm my fears. O Allah, guard me from in front of me and behind me, from my right, and from my left, and from above me. I seek protection in Your Greatness from being unexpectedly destroyed from beneath me.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “Ask Allah for forgiveness and well-being (‘āfiyah). Indeed, after conviction (yaqīn), no one has been granted anything better than well-being.” (Tirmidhī)","hadith":"ʿAbdullāh b. ʿUmar (raḍiy Allāhu ʿanhumā) narrated: “The Messenger of Allah ﷺ never failed to say these words in the morning and in the evening.” (Abū Dāwūd 5074)","reference":"عَنْ جُبَيْرِ بْنِ أَبِي سُلَيْمَانَ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ، قَالَ: سَمِعْتُ ابْنَ عُمَرَ، يَقُولُ: لَمْ يَكُنْ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَعُ هَؤُلَاءِ الدَّعَوَاتِ، حِينَ يُمْسِي، وَحِينَ يُصْبِحُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَتِي، وَقَالَ عُثْمَانُ: عَوْرَاتِي وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي.(سنن أبي داود ٥٠٧٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"Grief & Anxiety #1","arabic":"اَللّٰهُمَّ إِنِّيْ عَبْدُكَ ، وَابْنُ عَبْدِكَ ، وَابْنُ أَمَتِكَ ، نَاصِيَتِيْ بِيَدِكَ ، مَاضٍ فِيَّ حُكْمُكَ ، عَدْلٌ فِيَّ قَضَاؤُكَ ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ ، سَمَّيْتَ بِهِ نَفْسَكَ ، أَوْ عَلَّمْتَهُ أَحَدًا مِّنْ خَلْقِكَ ، أَوْ أَنْزَلْتَهُ فِيْ كِتَابِكَ ، أَوِ اسْتَأْثَرْتَ بِهِ فِيْ عِلْمِ الْغَيْبِ عِنْدَكَ ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيْعَ قَلْبِيْ ، وَنُوْرَ صَدْرِيْ ، وَجَلَاءَ حُزْنِيْ ، وَذَهَابَ هَمِّيْ","transliteration":"Allāhumma innī ʿabduk, wa-bnu ʿabdik, wa-bnu amatik, nāṣiyatī bi-yadik, māḍin fiyya ḥukmuk, ʿadlun fiyya qaḍā’uk, as’aluka bi-kulli-smin huwa lak, sammayta bihī nafsak, aw ʿallamtahū aḥadam-min khalqik, aw anzaltahū fī kitābik, awi-sta’tharta bihī fī ʿilmi-l-ghaybi ʿindak, an tajʿala-l-Qur’āna rabīʿa qalbī, wa nūra ṣadrī, wa jalā’a ḥuznī, wa dha-hāba hammī.","translation":"O Allah, I am Your servant and the son of Your male servant and the son of Your female servant. My forehead is in Your Hand (i.e. you have control over me). I am subject to Your judgement and Your decree concerning me is just. I ask You – by every name that is Yours, by which You have named Yourself, or taught any one of Your creation, or revealed in Your Book, or kept unto Yourself in the knowledge of the unseen that is with You – to make the Qur’ān the spring of my heart, the light of my chest, the banisher of my grief and the reliever of my anxiety.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “There is no one who is stricken with grief and anxiety, and then says [the above] — except that Allah will remove his grief and anxiety, and will give him joy instead.” The Companions asked, ‘O Messenger of Allah, should we not learn these words?’ He ﷺ replied, ‘Certainly! The one who hears them should learn them.’” (Ahmad 3712)","hadith":null,"reference":"عَنْ عَبْدِ اللهِ، قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: مَا أَصَابَ أَحَدًا قَطُّ هَمٌّ وَلَا حَزَنٌ، فَقَالَ: اللهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجِلَاءَ حُزْنِي، وَذَهَابَ هَمِّي، إِلَّا أَذْهَبَ اللهُ هَمَّهُ وَحُزْنَهُ، وَأَبْدَلَهُ مَكَانَهُ فَرَحًا، قَالَ: فَقِيلَ: يَا رَسُولَ اللهِ، أَلَا نَتَعَلَّمُهَا؟ فَقَالَ: بَلَى، يَنْبَغِي لِمَنْ سَمِعَهَا أَنْ يَتَعَلَّمَهَا. (مسند أحمد ٣٧١٢)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"Grief & Anxiety #2","arabic":"لَا إِلٰهَ إِلَّا اللّٰهُ الْعَظِيْمُ الْحَلِيْمُ ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ الْعَرْشِ الْعَظِيْمِ ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ السَّمٰـوٰتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيْمِ\\nعَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ:كَانَ النَّبِيُّ صلى الله عليه وسلم يَدْعُو عِنْدَ الْكَرْبِ: لَا إِلَهَ إِلَّا اللهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللهُ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ رَبُّ الْعَرْشِ الْعَظِيمِ.","transliteration":"Lā ilāha illā-llāhu-l-ʿĀẓīmu-l-Ḥalīm, lā ilāha illā-llāhu Rabbu-l-ʿĀrshi-l-ʿAẓīm, lā ilāha illā-llāhu Rabbu-s-samāwāti wa Rabbu-l-arḍi wa Rabbu-l-ʿĀrshi-l-karīm.","translation":"There is no god worthy of worship except Allah — the Supreme, the Forbearing. There is no god worthy of worship except Allah — Lord of the Magnificent Throne. There is no god worthy of worship except Allah — Lord of the heavens, Lord of the earth, and Lord of the Noble Throne.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ used to supplicate with [the above] in times of distress. (Bukhārī 6345, Muslim 2730)","reference":"(صحيح البخاري ٦٣٤٥)\\nعَنِ ابْنِ عَبَّاسٍ؛ أَنَّ نبي الله صلى الله عليه وسلم كان يقول عند الكرب “لا إله إلا الله العظيم الحليم. لا إله إلا الله رب العرش العظيم. لا إله إلا الله رب السماوات ورب الأرض ورب العرش الكريم. (صحيح مسلم ٢٧٣٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"When One Is Afraid of People #2","arabic":"حَسْبُنَا اللّٰهُ وَنِعْمَ الْوَكِيْلُ","transliteration":"Ḥasbunallāhu wa niʿmal Wakīl.","translation":"Allah is enough for us and He is the Best Protector.","description":null,"benefit":null,"virtue":null,"hadith":"Ibn ʿAbbās (radiy Allāhū ʿanhumā) narrated: “[The above] was said by Ibrāhīm (ʿalayhis-salām) when he was thrown into the fire; and it was said by Muḥammad ﷺ when (the hypocrites) said, ‘Your enemies have mobilised their forces against you, so fear them,’ — but this only increased them in faith and they replied: ‘Allah is enough for us and He is the Best Protector (3:173).’” (Bukhārī 4563)","reference":"عَنِ ابْنِ عَبَّاسٍ : حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ} قَالَهَا إِبْرَاهِيمُ عليه السلام حِينَ أُلْقِيَ فِي النَّارِ، وَقَالَهَا مُحَمَّدٌ صلى الله عليه وسلم حِينَ قَالُوا: إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ. (صحيح البخاري ٤٥٦٣)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"When One Feels Frightened","arabic":"لَا إِلٰهَ إِلَّا اللّٰهُ","transliteration":"Lā ilāha illā-llāh.","translation":"There is no god worthy of worship except Allah.","description":null,"benefit":null,"virtue":null,"hadith":"Zaynab b. Jaḥsh (raḍiy Allāhu ʿanhā) said that the Messenger of Allah ﷺ once entered her house in a state of fear and said, “[The above]. Woe to the Arabs from a danger that is imminent. An opening has been made today in the wall of Ya‘jūj and Ma‘jūj like this” and he made a circle with his thumb and index finger. Zaynab b. Jaḥsh said, “O Messenger of Allah ﷺ! Will we be destroyed even though there are pious people amongst us?” He ﷺ said, “Yes, when evil becomes widespread.” (Bukhārī 3346)","reference":"عَنْ أُمِّ حَبِيبَةَ بِنْتِ أَبِي سُفْيَانَ عَنْ زَيْنَبَ ابْنَةِ جَحْشٍ رضي الله عنهن أَنَّ النَّبِيَّ صلى الله عليه وسلم دَخَلَ عَلَيْهَا فَزِعًا يَقُولُ لَا إِلَهَ إِلَّا اللهُ وَيْلٌ لِلْعَرَبِ مِنْ شَرٍّ قَدِ اقْتَرَبَ فُتِحَ الْيَوْمَ مِنْ رَدْمِ يَاجُوجُ وَمَاجُوجُ مِثْلُ هَذِهِ وَحَلَّقَ بِإِصْبَعِهِ الْإِبْهَامِ وَالَّتِي تَلِيهَا قَالَتْ زَيْنَبُ ابْنَةُ جَحْشٍ: فَقُلْتُ: يَا رَسُولَ اللهِ أَنَهْلِكُ وَفِينَا الصَّالِحُونَ قَالَ نَعَمْ إِذَا كَثُرَ الْخَبَثُ. (صحيح البخاري ٣٣٤٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Jaḥsh said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"Protection From The Anguish of the World & Hereafter","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنْ ضِيْقِ الدُّنْيَا وَضِيْقِ يَوْمِ الْقِيَامَةِ.","transliteration":"Allāhumma innī aʿūdhu bika min ḍīqi-d-dunyā wa ḍīqi yawmi-l-qiyāmah.","translation":"O Allah, I seek Your protection from the anguish of the world and the anguish of the Day of Judgement.","description":null,"benefit":null,"virtue":null,"hadith":"Sharīq al-Hawzānī (raḥimahullāh) narrates that I entered upon Aisha (raḍiy Allāhu ‘anhā) and I asked her: “With which supplication did the Messenger of Allah ﷺ begin his Salāh when he woke up at night?” She replied: “You have asked me regarding something which no one has asked me before.” When he woke up at night, he uttered: Allāhu Akbar (Allah is the Greatest) ten times, and uttered Alḥamdullillāh (All praise be to Allah) ten times, and said Subḥāna-llāhi wa bi ḥamdih. (Allah is free from imperfection, and all praise is due to Him.) ten times, and said: Subḥānal Malik al-Quddūs (How perfect is the Sovereign, the Most Holy) ten times, and asked Allah’s forgiveness ten times, and said: “There is no god but Allah” ten times, and then said: [the above] ten times. He then began the Salāh. (Abū Dāwūd 5085)","reference":"عَنْ عُمَرَ بْنِ جُعْثُمٍ قَالَ: نَا الْأَزْهَرُ بْنُ عَبْدِ اللهِ الْحَرَازِيُّ قَالَ: حَدَّثَنِي شَرِيقٌ الْهَوْزَنِيُّ قَالَ: «دَخَلْتُ عَلَى عَائِشَةَ فَسَأَلْتُهَا بِمَ كَانَ رَسُولُ اللهِ صلى الله عليه وسلم يَفْتَتِحُ إِذَا هَبَّ مِنَ اللَّيْلِ، فَقَالَتْ: لَقَدْ سَأَلْتَنِي عَنْ شَيْءٍ مَا سَأَلَنِي عَنْهُ أَحَدٌ قَبْلَكَ، كَانَ إِذَا هَبَّ مِنَ اللَّيْلِ كَبَّرَ عَشْرًا وَحَمِدَ عَشْرًا وَقَالَ: سُبْحَانَ اللهِ وَبِحَمْدِهِ عَشْرًا وَقَالَ: سُبْحَانَ الْمَلِكِ الْقُدُّوسِ عَشْرًا وَاسْتَغْفَرَ عَشْرًا، وَهَلَّلَ عَشْرًا، ثُمَّ قَالَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ضِيقِ الدُّنْيَا، وَضِيقِ يَوْمِ الْقِيَامَةِ عَشْرًا ثُمَّ يَفْتَتِحُ الصَّلَاةَ.\\n(سنن ابي دادد ٥٠٨٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"Allah Will Suffice You in Everything","arabic":"حَسْبِيَ اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ ، عَلَيْهِ تَوَكَّلْتُ ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ.","transliteration":"Ḥasbiya-Allāhu lā ilāha illā Huwa, ʿalayhi tawakkalt, wa Huwa Rabbu-l-ʿArshi-l-ʿaẓīm.","translation":"Repeat.  x7","description":null,"benefit":null,"virtue":"Abū al-Dardā’ (raḍiy Allāhu ʿanhu) narrates from the Messenger of Allah ﷺ that he said: “Whoever recites [the above] seven times in the morning and in the evening, Allah will suffice him in everything that concerns him in matters of this world and the next.”","hadith":null,"reference":"(Ibn al-Sunnī 71)\\nعَنْ أَبِي الدَّرْدَاءِ، رضي الله عنه، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ: مَنْ قَالَ فِي كُلِّ يَوْمٍ حِينَ يُصْبِحُ وَحِينَ يُمْسِي: حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ، سَبْعَ مَرَّاتٍ، كَفَاهُ اللَّهُ عز وجل هَمَّهُ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ. (عمل اليوم والليلة لابن السني ٧١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":7,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"Duʿa of Prophet Musa ﷺ Expressing His Dire Need","arabic":"رَبِّ إِنِّيْ لِمَآ أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيْرٌ.","transliteration":"Rabbi innī limā anzalta illayya min khayrin faqīr.","translation":"My Lord, truly I am in dire need of any good which You may send me. (28:24)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"For Difficult Times: All Your Prayers Answered","arabic":"لَآ إِلٰهَ إِلَّآ أَنْتَ سُبْحَانَكَ إِنِّيْ كُنْتُ مِنَ الظَّالِمِيْنَ","transliteration":"Lā ilāha illā Anta subḥānaka innī kuntu mina-ẓ-ẓālimīn.","translation":"There is no god worthy of worship except You; You are free from all imperfection. Indeed, I have been of the wrongdoers. (21:87)","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “The supplication of Dhun-Nūn (Prophet Yūnus) when he supplicated in the belly of the whale was: [the above]. No Muslim man ever supplicates with [the above] except that Allah answers his supplications.” (Tirmidhī 3505)","hadith":null,"reference":"Saʿd b. Abī Waqqāṣ said: We were sat in the company of the Messenger of Allah ﷺ. He ﷺ said, “Shall I not inform you of a supplication which will remove the calamity or a worldy trial which befalls a person from amongst you?” It was said, “Of course.” He said, “The supplication of Dhun-Nūn: [the above].”  (See Nasā‘ī in ʿAmal al-Yawm wa al-Laylah 655)\\nعَنْ سَعْدٍ قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: دَعْوَةُ ذِي النُّونِ إِذْ دَعَا وَهُوَ فِي بَطْنِ الْحُوتِ: لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ؛ فَإِنَّهُ لَمْ يَدْعُ بِهَا رَجُلٌ مُسْلِمٌ فِي شَيْءٍ قَطُّ إِلَّا اسْتَجَابَ اللهُ لَهُ. (سنن الترمذي ٣٥٠٥)\\nأخبرنَا الْقَاسِم بن زَكَرِيَّا قَالَ حَدثنَا عبيد بن مُحَمَّد قَالَ حَدثنَا مُحَمَّد بن مهَاجر قَالَ حَدثنِي إِبْرَاهِيم بن مُحَمَّد بن سعد عَن أَبِيه عَن جده قَالَ كُنَّا جُلُوسًا عِنْد رَسُول الله صلى الله عليه وسلم قَالَ أَلا أخْبركُم أَو أحدثكُم بِشَيْء إِذا نزل بِرَجُل مِنْكُم كرب أَو بلَاء من بلَاء الدُّنْيَا دَعَا بِهِ فرج عَنهُ فَقيل لَهُ بلَى قَالَ دُعَاء ذِي النُّون لَا إِلَه إِلَّا أَنْت سُبْحَانَكَ إِنِّي كنت من الظَّالِمين. (عمل اليوم والليلة للنسائي ٦٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Waqqāṣ said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"When One Is Distressed","arabic":"اَللّٰهُمَّ رَحْمَتَكَ أَرْجُوْ فَلَا تَكِلْنِيْ إِلٰى نَفْسِيْ طَرْفَةَ عَيْنٍ ، وَأَصْلِحْ لِي شَأْنِيْ كُلَّهُ ، لَا إِلٰهَ إِلَّا أَنْتَ","transliteration":"Allāhumma raḥmataka arjū fa-lā takilnī ilā nafsī ṭarfata ʿayn, wa aṣliḥ lī sha’nī kullah, lā ilāha illā Ant.","translation":"O Allah! It is certainly Your Mercy what I hope for, so do not entrust me to myself for the blink of an eye; and rectify all of my affairs. There is no god worthy of worship except You.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ said: “The supplications of the distressed person are [the above].”","reference":"(Abū Dāwūd 5090)\\nعَنْ جَعْفَرِ بْنِ مَيْمُونٍ قَالَ: حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ «أَنَّهُ قَالَ لِأَبِيهِ : يَا أَبَتِ إِنِّي أَسْمَعُكَ تَدْعُو كُلَّ غَدَاةٍ: اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَدْعُو بِهِنَّ، فَأَنَا أُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ قَالَ عَبَّاسٌ فِيهِ: وَتَقُولُ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَتَدْعُو بِهِنَّ، فَأُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ. قَالَ: وَقَالَ رَسُولُ اللهِ صلى الله عليه وسلم: دَعَوَاتُ الْمَكْرُوبِ اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا ‌تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ.\\n(سنن ابي داود ٥٠٩٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"Entrust All Your Matters to Allah","arabic":"يَا حَيُّ يَا قَيُّوْمُ ، بِرَحْمَتِكَ أَسْتَغِيْثُ ، أَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ ، وَلَا تَكِلْنِيْ إِلَىٰ نَفْسِيْ طَرْفَةَ عَيْنٍ.\\nأخبرنَا عبد الرَّحْمَن بن مُحَمَّد بن سَلام حَدثنَا زيد بن الْحباب أَخْبرنِي عُثْمَان بن موهب الْهَاشِمِي سَمِعت أنس بن مَالك يَقُول قَالَ النَّبِي صلى الله عليه وسلم لفاطمة مَا يمنعك أَن سَمْعِي مَا أوصيك بِهِ أَو تقولي إِذا أَصبَحت وَإِذا أمسيت يَا حَيّ يَا قيوم بِرَحْمَتك أستغيث أصلح لي شأني كلَّه وَلَا تَكِلنِي إِلَى نَفسِي طرفَة عين.","transliteration":"Yā Ḥayyu yā Qayyūm, bi-raḥmatika astaghīth, aṣliḥ lī sha’nī kullah, wa lā takilnī ilā nafsī ṭarfata ʿayn.","translation":"O The Ever Living, The Sustainer of all. ; I seek assistance through Your mercy. Rectify all of my affairs and do not entrust me to myself for the blink of an eye.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ʿanhu) narrates that the Prophet ﷺ said to Fāṭimah (raḍiy Allāhu ʿanhā), “What is preventing you from (doing) what I am advising you; that you say [the above] in the morning and evening?” (Nasā’ī in ʿAmal al-Yawm wa-l-Laylah 570)","reference":"(عمل اليوم والليلة للنسائي ٥٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"Duʿa for Seeking Protection from Shaytan","arabic":"رَبِّ أَعُوْذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِيْنِ ، وَأَعُوذُ بِكَ رَبِّ أَنْ يَّحْضُرُوْنِ.","transliteration":"Rabbi aʿūdhu bika min hamazāti-sh-shayāṭīn. Wa aʿūdhu bika Rabbi ay-yaḥḍurūn.","translation":"My Lord, I seek protection with You from the promptings of the devils; and I seek protection in You, my Lord, from their coming near me. (23:97-98)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"Duʿa of Prophet Ayyub ﷺ for Times of Distress","arabic":"-رَبِّ- أَنِّيْ مَسَّنِيَ الضُّرُّ وَأَنْتَ أَرْحَمُ الرّٰحِمِيْن.","transliteration":"(Rabbi) Annī massaniya-ḍ-ḍurru wa Anta Arḥamu-r-raḥimīn.","translation":"(My Lord), indeed adversity has touched me, and you are the Most Merciful of the merciful. (21:83)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"},{"title":"Protection from Trials, Wretchedness, Bad Fate & the Gloating of Enemies","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنْ جَهْدِ الْبَلَاءِ ، وَدَرَكِ الشَّقَاءِ ، وَسُوْءِ الْقَضَاءِ ، وَشَمَاتَةِ الْأَعْدَاءِ.","transliteration":"Allāhumma innī aʿūdhu bika min jahdi-l-balā’, wa daraki-sh-shaqā’, wa sūi’-l-qaḍā’, wa shamātati-l-aʿdā’.","translation":"O Allah, I seek Your protection from severe trials, wretchedness, bad fate and that my enemies rejoice in my misery.","description":null,"benefit":null,"virtue":null,"hadith":"Abū Hurayrah (raḍiy Allāhu ‘anhu) narrates that the Messenger of Allah ﷺ used to seek refuge with Allah from [the above]. (Bukhārī 6347)","reference":"عَنْ أَبِي هُرَيْرَةَ كَانَ رَسُولُ اللهِ صلى الله عليه وسلم يَتَعَوَّذُ مِنْ جَهْدِ الْبَلَاءِ وَدَرَكِ الشَّقَاءِ وَسُوءِ الْقَضَاءِ وَشَمَاتَةِ الْأَعْدَاءِ. (صحيح البخاري ٦٣٤٧)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/depressed/"}]},{"feeling":"Doubtful","slug":"doubtful","url":"https://allahuakbarofficial.com/doubtful/","items_count":15,"duas":[{"title":"Surah al-Fatihah: The Greatest Duʿa","arabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيْمِ ،\\nاَلْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِيْنَ ، الرَّحْمٰنِ الرَّحِيْمِ ، مٰلِكِ يَوْمِ الدِّيْنِ ، إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِيْنُ ، اِهْدِنَا الصِّرَاطَ الْمُسْتَقِيْمَ ، صِرَاطَ الَّذِيْنَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوْبِ عَلَيْهِمْ وَلَا الضَّآلِّيْنَ","transliteration":"Bismi-llāhi-r-Raḥmāni-r-Raḥīm. Alḥamdu-lillāhi Rabbi-l-ʿālamīn, ar-Raḥmāni-r-Raḥīm, Māliki yawmi-d-dīn, iyyāka naʿbudu wa iyyāka nastaʿīn, ihdina-ṣ-Ṣirāṭa-l-Mustaqīm, ṣirāṭa-lladhīna anʿamta ʿalayhim ghayri-l-maghḍūbi ʿālayhim wa la-ḍ-ḍāllīn.","translation":"In the name of Allah, the All-Merciful, the Very Merciful. All praises and thanks are for Allah, the Lord of all the worlds, The All-Merciful, The Very Merciful, Master of the Day of Judgement. You Alone we worship, You Alone we ask for help. Guide us on the Straight Path, the path of those whom You have favoured, not of those who incur (Your) anger nor of those who have gone astray. (1:1-7)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/doubtful/"},{"title":"For Firmness of the Heart","arabic":"يَا مُقَلِّبَ الْقُلُوْبِ ثَبِّتْ قَلْبِيْ عَلَىٰ دِيْنِكَ","transliteration":"Yā Muqalliba-l-qulūbi thabbit qalbī ʿalā dīnik.","translation":"O Changer of the hearts, make my heart firm upon Your religion.","description":null,"benefit":null,"virtue":null,"hadith":"Anas (raḍiy Allāhu ʿanhu) said: “The Messenger of Allah ﷺ would often say [the above]. So I asked: ‘O Messenger of Allah, we believe in you and what you have come with, but do you fear for us?’ He replied: ‘Yes. Indeed the hearts are in between the two Fingers of Allah’s Fingers. He changes them as He wills.’”","reference":"(Tirmidhī 3522)\\nعَنْ أَبِي كَعْبٍ صَاحِبِ الحَرِيرِ قَالَ: حَدَّثَنِي شَهْرُ بْنُ حَوْشَبٍ، قَالَ: قُلْتُ لِأُمِّ سَلَمَةَ: يَا أُمَّ المُؤْمِنِينَ مَا كَانَ أَكْثَرُ دُعَاءِ رَسُولِ اللَّهِ صلى الله عليه وسلم إِذَا كَانَ عِنْدَكِ؟ قَالَتْ: كَانَ أَكْثَرُ دُعَائِهِ: يَا مُقَلِّبَ القُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِك قَالَتْ: فَقُلْتُ: يَا رَسُولَ اللَّهِ مَا لِأَكْثَرِ دُعَائِكَ يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ؟ قَالَ: يَا أُمَّ سَلَمَةَ إِنَّهُ لَيْسَ آدَمِيٌّ إِلَّا وَقَلْبُهُ بَيْنَ أُصْبُعَيْنِ مِنْ أَصَابِعِ اللَّهِ، فَمَنْ شَاءَ أَقَامَ، وَمَنْ شَاءَ أَزَاغَ. فَتَلَا مُعَاذٌ رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا.\\n(سنن الترمذي ٣٥٢٢)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/doubtful/"},{"title":"When One Experiences Doubt in Faith #1","arabic":"آمَنْتُ بِاللهِ وَرُسُلِهِ","transliteration":"Āmantu bi-llāhi wa rusulih.","translation":"I believe in Allah and His Messengers.","description":null,"benefit":null,"virtue":"The Messenger of Allāh ﷺ said: “Men will continue to question one another till this is propounded: ‘Allāh created all things but who created Allāh?’  He who found himself confronted with such a situation should say: [the above].” (Muslim 134)","hadith":null,"reference":"عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: « لَا يَزَالُ النَّاسُ ‌يَتَسَاءَلُونَ حَتَّى يُقَالَ هَذَا: خَلَقَ اللهُ الْخَلْقَ، فَمَنْ خَلَقَ اللهَ؟ فَمَنْ وَجَدَ مِنْ ذَلِكَ شَيْئًا، فَلْيَقُلْ: آمَنْتُ بِاللهِ.\\n(صحيح مسلم ١٣٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/doubtful/"},{"title":"When One Experiences Doubt in Faith #2","arabic":"هُوَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ ، وَهُوَ بِكُلِّ شَيْءٍ عَلِيْمٌ","transliteration":"Huwa-l-Awwalu wa-l-Ākhiru wa-ẓ-Ẓāhiru wa-l-Bāṭin, wa Huwa bi-kulli shay’in ‘Alīm.","translation":"He is the First and the Last, the Most High and the Most Near. And He is All-Knowing about everything.","description":null,"benefit":null,"virtue":null,"hadith":"Abū Zumayl reported: “I asked Ibn ʿAbbās (raḍiy Allāhū ʿanhumā): ‘What is this that I am experiencing in my heart?’ He answered: ‘What is it?’ I said: ‘By Allah, I cannot talk about it.’ He asked me: ‘Is it something to do with doubt?’ [When answered it was], he smiled and said: ‘No-one was safe from it until Allah revealed:","reference":"*If you are in doubt concerning what We revealed unto you [O Prophet], ask those who read the Scripture from before your time. The truth has indeed come to you from your Lord, so do not be of those in doubt (10:94).*’ | So he (Ibn ʿAbbās) told me: ‘If you experience any [doubt] within yourself, say: [the above].’” | (Abū Dāwūd 5110)\\nحَدَّثَنَا عَبَّاسُ بْنُ عَبْدِ الْعَظِيمِ، نَا النَّضْرُ بْنُ مُحَمَّدٍ ، نَا عِكْرِمَةُ يَعْنِي ابْنَ عَمَّارٍ قَالَ: وَنَا أَبُو زُمَيْلٍ قَالَ: سَأَلْتُ ابْنَ عَبَّاسٍ فَقُلْتُ: مَا شَيْءٌ أَجِدُهُ فِي صَدْرِي قَالَ: مَا هُوَ؟ قُلْتُ: وَاللهِ مَا أَتَكَلَّمُ بِهِ. قَالَ: فَقَالَ لِي: أَشَيْءٌ مِنْ شَكٍّ؟ قَالَ وَضَحِكَ قَالَ: مَا نَجَا أَحَدٌ مِنْ ذَلِكَ، حَتَّى أَنْزَلَ اللهُ تَعَالَى {فَإِنْ كُنْتَ فِي شَكٍّ مِمَّا أَنْزَلْنَا إِلَيْكَ فَاسْأَلِ الَّذِينَ يَقْرَءُونَ الْكِتَابَ} الْآيَةَ، قَالَ: فَقَالَ لِي: إِذَا وَجَدْتَ فِي نَفْسِكَ شَيْئًا فَقُلْ {هُوَ الأَوَّلُ وَالآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ. (سنن ابي داود ٥١١٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"I said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/doubtful/"},{"title":"When One Fears Shirk & Showing off","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ","transliteration":"Allāhumma innī aʿūdhu bika an ushrika bika wa-ana aʿlam, wa astaghfiruka limā lā aʿlam.","translation":"O Allah, I seek Your protection from knowingly committing shirk, and I seek Your forgiveness for unknowingly (committing it).","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “O people, beware of this shirk, for it is more subtle than the footsteps of an ant.” The one whom Allah willed should speak asked him: “How can we beware of it when it is more subtle than the footsteps of an ant, O Messenger of Allah?” He replied: “Say [the above].” (Ahmad 19606)","hadith":null,"reference":"حَدَّثَنَا عَبَّاسٌ النَّرْسِيُّ قَالَ: حَدَّثَنَا عَبْدُ الْوَاحِدِ قَالَ: حَدَّثَنَا لَيْثٌ قَالَ: أَخْبَرَنِي رَجُلٌ مِنْ أَهْلِ الْبَصْرَةِ قَالَ: سَمِعْتُ مَعْقِلَ بْنَ يَسَارٍ يَقُولُ: انْطَلَقْتُ مَعَ أَبِي بَكْرٍ الصِّدِّيقِ رضي الله عنه إِلَى النَّبِيِّ صلى الله عليه وسلم، فَقَالَ:يَا أَبَا بَكْرٍ، لَلشِّرْكُ فِيكُمْ أَخْفَى مِنْ دَبِيبِ النَّمْلِ، فَقَالَ أَبُو بَكْرٍ: وَهَلِ الشِّرْكُ إِلَّا مَنْ جَعَلَ مَعَ اللَّهِ إِلَهًا آخَرَ؟ فَقَالَ النَّبِيُّ صلى الله عليه وسلم:وَالَّذِي نَفْسِي بِيَدِهِ، لَلشِّرْكُ أَخْفَى مِنْ دَبِيبِ النَّمْلِ، أَلَا أَدُلُّكَ عَلَى شَيْءٍ إِذَا قُلْتَهُ ذَهَبَ عَنْكَ قَلِيلُهُ وَكَثِيرُهُ؟  قَالَ:قُلِ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ. (الأدب المفرد ٧١٦)\\nعَنْ أَبِي عَلِيٍّ رَجُلٍ مِنْ بَنِي كَاهِلٍ، قَالَ: خَطَبَنَا أَبُو مُوسَى الْأَشْعَرِيُّ، فَقَالَ: يَا أَيُّهَا النَّاسُ، اتَّقُوا هَذَا الشِّرْكَ، فَإِنَّهُ أَخْفَى مِنْ دَبِيبِ النَّمْلِ، فَقَامَ إِلَيْهِ عَبْدُ اللهِ بْنُ حَزْنٍ وَقَيْسُ بْنُ المُضَارِبِ، فَقَالَا: وَاللهِ لَتَخْرُجَنَّ مِمَّا قُلْتَ، أَوْ لَنَأْتِيَنَّ عُمَرَ، مَأْذُونٌ لَنَا أَوْ غَيْرُ مَأْذُونٍ. قَالَ: بَلْ أَخْرُجُ مِمَّا قُلْتُ: خَطَبَنَا رَسُولُ اللهِ صلى الله عليه وسلم ذَاتَ يَوْمٍ، فَقَالَ: ” أَيُّهَا النَّاسُ، اتَّقُوا هَذَا الشِّرْكَ، فَإِنَّهُ أَخْفَى مِنْ دَبِيبِ النَّمْلِ  فَقَالَ لَهُ مَنْ شَاءَ اللهُ أَنْ يَقُولَ: وَكَيْفَ نَتَّقِيهِ وَهُوَ أَخْفَى مِنْ دَبِيبِ النَّمْلِ يَا رَسُولَ اللهِ؟ قَالَ:  قُولُوا: اللهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ أَنْ نُشْرِكَ بِكَ شَيْئًا نَعْلَمُهُ، وَنَسْتَغْفِرُكَ لِمَا لَا نَعْلَمُ. (احمد ١٩٦٠٦)\\nعَنْ حُذَيْفَةَ، عَنْ أَبِي رضي الله عنهما، أَمَا أَخْبَرَ ذَلِكَ حُذَيْفَةُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ، وَأَمَا أَخْبَرَهُ أَبُو بَكْرٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ قَالَ: الشِّرْكُ أَخْفَى فِيكُمْ مِنْ دَبِيبِ ‌النَّمْلِ، قَالَ: قُلْنَا: يَا رَسُولَ اللَّهِ، وَهَلِ الشِّرْكُ إِلَّا مَا عُبِدَ مِنْ دُونِ اللَّهِ عز وجل، أَوْ مَا دُعِيَ مَعَ اللَّهِ، شَكَّ عَبْدُ الْمَلِكِ بْنُ جُرَيْجٍ، فَقَالَ:ثَكِلَتْكَ أُمُّكَ يَا صِدِّيقُ، الشِّرْكُ أَخْفَى فِيكُمْ مِنْ دَبِيبِ ‌النَّمْلِ، أَلَا أُخْبِرُكَ بِقَوْلٍ يُذْهِبُ صِغَارَهُ وَكِبَارَهُ، أَوْ صَغِيرَهُ وَكَبِيرَهُ؟قَالَ: قُلْتُ: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: ” تَقُولُ كُلَّ يَوْمٍ ثَلَاثَ مَرَّاتٍ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ، وَالشِّرْكُ أَنْ يَقُولَ أَعْطَانِي اللَّهُ وَفُلَانٌ، وَالنِّدُّ أَنْ يَقُولَ الْإِنْسَانُ: لَوْلَا فُلَانٌ لَقَتَلَنِي فُلَانٌ.\\n(عمل اليوم والليلة لابن السني ٢٨٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/doubtful/"},{"title":"Forgiveness, Anger and Trials","arabic":"اَللّٰهُمَّ رَبَّ مُحَمَّدٍ اغْفِرْ لِيْ ذَنْبِيْ ، وَأَذْهِبْ غَيْظَ قَلْبِيْ ، وَأَعِذْنِيْ مِنْ مُضِلَّاتِ الْفِتَنِ.\\nعَنِ الْقَاسِمِ بْنِ مُحَمَّدِ بْنِ أَبِي بَكْرٍ، قَالَ: كَانَتْ عَائِشَةُ رضي الله عنها إِذَا غَضِبَتْ عَرَكَ النَّبِيُّ صلى الله عليه وسلم بِأَنْفِهَا، ثُمَّ يَقُولُ: يَا عُوَيِّشُ، قُولِي: اللَّهُمَّ رَبَّ مُحَمَّدٍ، اغْفِرْ لِي ذَنْبِي، وَأَذْهِبْ غَيْظَ قَلْبِي، وَأَجِرْنِي مِنْ ‌مُضِلَّاتِ الْفِتَنِ.","transliteration":"Allāhumma Rabba Muḥammad, ighfir lī dhambī, wa adh-hib ghayẓa qalbī, wa aʿidhnī min muḍillāti-l-fitan.","translation":"O Allah, Lord of Muḥammad forgive my sins, remove the anger of my heart and protect me from misleading trials.","description":null,"benefit":null,"virtue":null,"hadith":"Muhammad b. Abī Bakr (raḥimahullāh) narrates that when ʿĀ’isha (raḍiy Allāhu ‘anhā) would become angry, the Messenger of Allah ﷺ would stroke her nose and then say (to her): “O ʿUwaysh! Say: [the above].”","reference":"(Ibn al-Sunnī 455)\\n(عمل اليوم والليلة لابن السني ٤٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/doubtful/"},{"title":"Unwavering Iman, Blessings & The Prophet’s Company in Paradise","arabic":"اَللّٰهُمَّ إنِّيْ أَسْأَلُكَ إِيْمَانًا لَّا يَرْتَدُّ ، وَنَعِيْمًا لَّا يَنْفَدُ ، وَمُرَافَقَةَ نَبِيِّنَا مُحَمَّدٍ فِيْ أَعْلَىٰ جَنَّةِ الْخُلْدِ.","transliteration":"Allāhumma innī as’aluka īmāna-l-lā yartad, wa naʿīma-l-lā yanfad, wa murāfaqata Nabiyyanā Muḥammadin fī aʿlā Jannati-l-khuld.","translation":"O Allah, I beg you for faith which does not waver, blessings which do not cease, and the company of our Prophet Muhammad ﷺ in the loftiest abode of the Eternal Garden.","description":null,"benefit":null,"virtue":null,"hadith":"Abdullāh b. Mas’ūd (raḍiy Allāhu ‘anhu) narrates: ‘’The Messenger of Allāh ﷺ entered the Masjid – He was with Abu Bakr and ‘Umar (raḍiy Allāhu ‘anhumā) . They saw Ibn Mas’ūd (raḍiy Allāhu ‘anhu) performing Salah whilst reciting Surah Nisā. He continued reciting until he reached 100 verses. Ibn Mas’ūd (raḍiy Allāhu ‘anhu) then began supplicating whilst he was standing in prayer. The Prophet ﷺ then said: ‘’Ask (of Allah), you will be granted, ask, you will be granted.’’ Then He ﷺ said: ‘’Whoever wishes to recite The Qurān, fresh, as it was revealed, then he should recite in the manner of Ibn Umm ‘Abd.’’ The following morning Abu Bakr (raḍiy Allāhu ‘anhu) visited him to give him glad tidings and asked: ‘’What did you ask Allāh for last night?’’ He replied: ‘’I said: [the above].’’ (Ahmad 4340)","reference":"عَنْ ابْنِ مَسْعُودٍ، قَالَ: دَخَلَ رَسُولُ اللهِ صلى الله عليه وسلم الْمَسْجِدَ، وَهُوَ بَيْنَ أَبِي بَكْرٍ وَعُمَرَ، وَإِذَا ابْنُ مَسْعُودٍ يُصَلِّي، وَإِذَا هُوَ يَقْرَأُ النِّسَاءَ، فَانْتَهَى إِلَى رَأْسِ الْمِئَةِ، فَجَعَلَ ابْنُ مَسْعُودٍ يَدْعُو، وَهُوَ قَائِمٌ يُصَلِّي، فَقَالَ النَّبِيُّ صلى الله عليه وسلم: ” اسْأَلْ تُعْطَهْ، اسْأَلْ تُعْطَهْ “، ثُمَّ قَالَ: ” مَنْ سَرَّهُ أَنْ يَقْرَأَ الْقُرْآنَ غَضًّا كَمَا أُنْزِلَ، فَلْيَقْرَأْهُ بِقِرَاءَةِ ابْنِ أُمِّ عَبْدٍ”، فَلَمَّا أَصْبَحَ غَدَا إِلَيْهِ أَبُو بَكْرٍ رضي الله عنه، لِيُبَشِّرَهُ، وَقَالَ لَهُ: مَا سَأَلْتَ اللهَ الْبَارِحَةَ؟ قَالَ: قُلْتُ: اللهُمَّ إِنِّي أَسْأَلُكَ إِيمَانًا لَا يَرْتَدُّ، وَنَعِيمًا لَا يَنْفَدُ، وَمُرَافَقَةَ مُحَمَّدٍ فِي أَعْلَى جَنَّةِ الْخُلْدِ. (مسند احمد ٤٣٤٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"I said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/doubtful/"},{"title":"The Prophet’s Comprehensive Duʿa After the Battle of Uhud","arabic":"اَللّٰهُمَّ ابْسُطْ عَلَيْنَا مِنْ بَرَكَاتِكَ وَرَحْمَتِكَ وَفَضْلِكَ وَرِزْقِكَ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ النَّعِيْمَ الْمُقِيْمَ الَّذِيْ لَا يَحُوْلُ وَلَا يَزُوْلُ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ النَّعِيْمَ يَوْمَ الْعَيْلَةِ ، وَالْأَمْنَ يَوْمَ الْخَوْفِ ، اَللّٰهُمَّ إِنِّيْ عَائِذٌ بِكَ مِنْ شَرِّ مَا أَعْطَيْتَنَا وَشَرِّ مَا مَنَعْتَنَا ، اَللّٰهُمَّ حَبِّبْ إِلَيْنَا الْإِيْمَانَ وَزَيِّنْهُ فِيْ قُلُوْبِنَا ، وَكَرِّهْ إِلَيْنَا الْكُفْرَ وَالْفُسُوْقَ وَالْعِصْيَانَ ، وَاجْعَلْنَا مِنَ الرَّاشِدِيْنَ ، اَللّٰهُمَّ تَوَفَّنَا مُسْلِمِيْنَ ، وَأَحْيِنَا مُسْلِمِيْنَ ، وَأَلْحِقْنَا بِالصَّالِحِيْنَ ، غَيْرَ خَزَايَا وَلَا مَفْتُوْنِيْنَ ، اَللّٰهُمَّ قَاتِلِ الْكَفَرَةَ الَّذِيْنَ يُكَذِّبُوْنَ رُسُلَكَ ، وَيَصُدُّوْنَ عَنْ سَبِيْلِكَ ، وَاجْعَلْ عَلَيْهِمْ رِجْزَكَ وَعَذَابَكَ ، اَللّٰهُمَّ قَاتِلِ الْكَفَرَةَ الَّذِيْنَ أُوْتُوا الْكِتَابَ ، إِلٰهَ الْحَقِّ.","transliteration":"Allāhumma-b-suṭ ʿalaynā min barakātika wa raḥmatika wa faḍlika wa rizqik, Allāhumma innī as’aluka-n-naʿīmal-muqīma-l-ladhī lā yaḥūlu wa lā yazūl, Allāhumma innī as’aluka-n-naʿīma yawmal-ʿaylah, wa-l-amna yawma-l-khawf, Allāhumma innī ʿā’idhu-m-bika min sharri mā aʿṭaytanā wa sharri mā manaʿtanā, Allāhumma ḥab-bib ilaynal-īmāna wa zay-yinhu fī qulūbinā, wa kar-rih ilayna-l-kufra wal-fusūqa wa-l-ʿiṣyān, waj-ʿalnā mina-r-rāshidīn, Allāhumma tawaf-fanā Muslimīn, wa aḥyinā Muslimīn, wa alḥiqnā bi-ṣ-ṣāliḥīn, ghayra khazāyā wa lā maftūnīn, Allāhumma qātili-l-kafarata-l-ladhīna yukadh-dhibūna rusulak, wa yaṣuddūna ʿan sabīlik, waj-ʿal ʿalayhim rijzaka wa ʿadhābak, Allāhumma qātilil-kafarata-l-ladhīna ūtu-l-kitāb, ilāha-l-ḥaqq.","translation":"O Allah, grant us Your blessings, Your mercy, Your grace and Your sustenance in abundance. O Allah, I beg you for eternal blessings which do not change nor disappear. O Allah, I beg you for blessings on the day of intense need and safety on the day of fear (i.e. Day of Judgement). O Allah, I seek Your protection from the evil of what You have granted us and the evil of what You have withheld from us. O Allah, endear faith to us and beautify it in our hearts. Make disbelief, sins and disobedience hateful to us, and make us of the rightly guided ones. O Allah, grant us death as Muslims, make us live as Muslims and join us with the righteous without being humiliated or tested. O Allah, fight the disbelievers who reject Your Messengers and avert from Your path. Inflict upon them Your punishment and vengeance. O Allah, fight the disbelievers who were given the Book, O the True God.","description":null,"benefit":null,"virtue":null,"hadith":"Rifā’ah az-Zuraqī (raḍiy Allāhu ‘anhu) narrates: “When it was the day of (the battle of) Uhud and the polytheists retreated, the Messenger of Allah ﷺ said: ‘Arrange yourselves (in rows) so I can praise my Lord.’ So the Companions (radiy Allāhū ‘anhum) stood behind him in rows. Then the Messenger of Allah ﷺ said: “O Allah, for You Alone is all praise. O Allah, none can restrict what You expand and none can expand what You have restricted. None can guide whom You have left astray, and none can mislead whom You have guided. None can give what You withhold, and none can withhold what You bestow. None can bring near what You have distanced and none can distance what You have brought near.” Then he said: [the above].”","reference":"(Aḥmad 15492)\\nعَنِ ابْنِ رِفَاعَةَ الزُّرَقِيِّ، عَنْ أَبِيهِ. وَقَالَ غَيْرُ الْفَزَارِيِّ: عُبَيْدِ بْنِ رِفَاعَةَ الزُّرَقِيِّ قَالَ: لَمَّا كَانَ يَوْمُ أُحُدٍ، وَانْكَفَأَ الْمُشْرِكُونَ، قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: ” اسْتَوُوا حَتَّى أُثْنِيَ عَلَى رَبِّي ” فَصَارُوا خَلْفَهُ صُفُوفًا، فَقَالَ: ” اللهُمَّ لَكَ الْحَمْدُ كُلُّهُ، اللهُمَّ لَا قَابِضَ لِمَا بَسَطْتَ، وَلَا بَاسِطَ لِمَا قَبَضْتَ، وَلَا هَادِيَ لِمَا أَضْلَلْتَ، وَلَا مُضِلَّ لِمَنْ هَدَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُقَرِّبَ لِمَا بَاعَدْتَ، وَلَا مُبَاعِدَ لِمَا قَرَّبْتَ، اللهُمَّ ابْسُطْ عَلَيْنَا مِنْ بَرَكَاتِكَ وَرَحْمَتِكَ وَفَضْلِكَ وَرِزْقِكَ، اللهُمَّ إِنِّي أَسْأَلُكَ النَّعِيمَ الْمُقِيمَ الَّذِي لَا يَحُولُ وَلَا يَزُولُ، اللهُمَّ إِنِّي أَسْأَلُكَ النَّعِيمَ يَوْمَ الْعَيْلَةِ، وَالْأَمْنَ يَوْمَ الْخَوْفِ، اللهُمَّ إِنِّي عَائِذٌ بِكَ مِنْ شَرِّ مَا أَعْطَيْتَنَا وَشَرِّ مَا مَنَعْتَ، اللهُمَّ حَبِّبْ إِلَيْنَا الْإِيمَانَ، وَزَيِّنْهُ فِي قُلُوبِنَا، وَكَرِّهْ إِلَيْنَا الْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَ، وَاجْعَلْنَا مِنَ الرَّاشِدِينَ، اللهُمَّ تَوَفَّنَا مُسْلِمِينَ، وَأَحْيِنَا مُسْلِمِينَ، وَأَلْحِقْنَا بِالصَّالِحِينَ غَيْرَ خَزَايَا وَلَا مَفْتُونِينَ، اللهُمَّ قَاتِلِ الْكَفَرَةَ الَّذِينَ يُكَذِّبُونَ رُسُلَكَ، وَيَصُدُّونَ عَنْ سَبِيلِكَ، وَاجْعَلْ عَلَيْهِمْ رِجْزَكَ وَعَذَابَكَ، اللهُمَّ قَاتِلِ الْكَفَرَةَ، الَّذِينَ أُوتُوا الْكِتَابَ، إِلَهَ الْحَقِّ. (مسند احمد ١٥٤٩٢)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Then he said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/doubtful/"},{"title":"Entrust All Your Matters to Allah","arabic":"يَا حَيُّ يَا قَيُّوْمُ ، بِرَحْمَتِكَ أَسْتَغِيْثُ ، أَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ ، وَلَا تَكِلْنِيْ إِلَىٰ نَفْسِيْ طَرْفَةَ عَيْنٍ.\\nأخبرنَا عبد الرَّحْمَن بن مُحَمَّد بن سَلام حَدثنَا زيد بن الْحباب أَخْبرنِي عُثْمَان بن موهب الْهَاشِمِي سَمِعت أنس بن مَالك يَقُول قَالَ النَّبِي صلى الله عليه وسلم لفاطمة مَا يمنعك أَن سَمْعِي مَا أوصيك بِهِ أَو تقولي إِذا أَصبَحت وَإِذا أمسيت يَا حَيّ يَا قيوم بِرَحْمَتك أستغيث أصلح لي شأني كلَّه وَلَا تَكِلنِي إِلَى نَفسِي طرفَة عين.","transliteration":"Yā Ḥayyu yā Qayyūm, bi-raḥmatika astaghīth, aṣliḥ lī sha’nī kullah, wa lā takilnī ilā nafsī ṭarfata ʿayn.","translation":"O The Ever Living, The Sustainer of all. ; I seek assistance through Your mercy. Rectify all of my affairs and do not entrust me to myself for the blink of an eye.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ʿanhu) narrates that the Prophet ﷺ said to Fāṭimah (raḍiy Allāhu ʿanhā), “What is preventing you from (doing) what I am advising you; that you say [the above] in the morning and evening?” (Nasā’ī in ʿAmal al-Yawm wa-l-Laylah 570)","reference":"(عمل اليوم والليلة للنسائي ٥٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/doubtful/"},{"title":"Renewal of Iman","arabic":"اَللّٰهُمَّ جَدِّدِ الْإِيْمَانَ فِيْ قَلْبِيْ\\nعن عبد اللهِ بن عمرٍو، قال: قال رسولُ اللهِ صلى الله عليه وسلم:إِنَّ الإِيمَانَ لَيَخْلَقُ فِي جَوْفِ أَحَدِكُمْ كَمَا يَخْلَقُ الثَّوْبُ الخَلَقُ؛ فَسَلُوا اللهَ أَنْ يُجَدِّدَ الإِيمَانَ فِي قُلُوبِكُمْ.","transliteration":"Allāhumma jaddidi-l-īmāna fī qalbī.","translation":"O Allah, keep faith rejuvenated in my heart.","description":null,"benefit":null,"virtue":null,"hadith":"ʿAbdullāh b. ʿAmr (radiy Allāhū ‘anhumā) narrates that the Messenger of Allah ﷺ said: “Indeed, īmān (faith) wears out in your hearts the way a piece of cloth wears out. So ask Allah to rejuvenate īmān (faith) in your hearts.” (Tabrāni, Al-Mu’jam Al-Kabir)","reference":"(المعجم الكبير للطبراني ١٤٦٦٨)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/doubtful/"},{"title":"Steadfastness on Din","arabic":"يَا مُقَلِّبَ الْقُلُوْبِ ثَبِّتْ قَلْبِيْ عَلَىٰ دِيْنِكَ","transliteration":"Yā Muqalliba-l-qulūbi thabbit qalbī ʿalā dīnik.","translation":"O Allah, Turner of hearts, make my heart firm upon Your religion.","description":null,"benefit":null,"virtue":null,"hadith":"Shahr bin Hawshab (raḥimahullāh) said: “I said to Umm Salamah (raḍiy Allāhu ‘anhā): ‘O Mother of the Believers! What was the supplication that the Messenger of Allah ﷺ said most frequently when he was with you?” She said: ‘The supplication he said most frequently was: ’[the above]’” She said: ‘So I said: “O Messenger of Allah, why do you supplicate [the above] so frequently [the above]? He said: ‘O Umm Salamah! Verily, there is no human being except that his heart is between Two Fingers of the Fingers of Allah, so whomsoever He wills He makes steadfast, and whomever He wills He causes to deviate.’” (Tirmidhī 3522)","reference":"عَنْ أَبِي كَعْبٍ صَاحِبِ الْحَرِيرِ، قَالَ: حَدَّثَنِي شَهْرُ بْنُ حَوْشَبٍ قَالَ قُلْتُ: لِأُمِّ سَلَمَةَ يَا أُمَّ الْمُؤْمِنِينَ مَا كَانَ أَكْثَرُ دُعَاءِ رَسُولِ اللهِ صلى الله عليه وسلم إِذَا كَانَ عِنْدَكِ؟ قَالَتْ: كَانَ أَكْثَرُ دُعَائِهِ يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ. قَالَتْ: فَقُلْتُ: يَا رَسُولَ اللهِ، مَا لِأَكْثَرِ دُعَائِكَ يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ؟ قَالَ: يَا أُمَّ سَلَمَةَ، إِنَّهُ لَيْسَ آدَمِيٌّ إِلَّا وَقَلْبُهُ بَيْنَ أُصْبُعَيْنِ مِنْ أَصَابِعِ اللهِ، فَمَنْ شَاءَ أَقَامَ، وَمَنْ أَشَاءَ أَزَاغَ.\\n(سنن الترمذي ٣٥٢٢)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"I said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/doubtful/"},{"title":"Steadfastness on Islam","arabic":"يَا وَلِيَّ الْإسْلَامِ وَأَهْلِهِ ، ثَبِّتْنِيْ بِهِ حَتَّىٰ أَلْقَاكَ","transliteration":"Yā Waliyyal-Islāmi wa ahlih, thab-bitnī bihī ḥattā alqāk.","translation":"O Guardian of Islam and its followers, keep me firm on it (Islam) until I meet You.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ‘anhu) narrates that the Messenger of Allah ﷺ would say [the above]. (Tabarānī in Mu’jam al-Awsat 661)","reference":"عَنْ أَنَسِ بْنِ مَالِكٍ رضي الله عنه، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ يَقُولُ: يَا وَلِيَّ الْإِسْلَامِ وَأَهْلِهِ، ثَبِّتْنِي بِهِ حَتَّى أَلْقَاكَ.\\n(المعجم الأوسط للطبراني ٦٦١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/doubtful/"},{"title":"Guidance & Steadfastness","arabic":"اَللّٰهُمَّ اهْدِنِيْ وَسَدِّدْنِيْ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْهُدَىٰ وَالسَّدَادَ.","transliteration":"Allāhumma-hdinī wa saddidnī, Allāhumma innī as’aluka-l-hudā wa-s-sadād.","translation":"O Allah, guide me and grant me firmness. O Allah, I beg You for guidance and firmness (on the straight path).","description":null,"benefit":null,"virtue":null,"hadith":"Ali (raḍiy Allāhu ‘anhu) reported that the Messenger of Allah ﷺ said to him: “Say: [the above] and when you make a mention of guidance, keep in mind the (Straight) Path and when you consider the Straight (Path), keep in mind the straightness of the arrow.” (Muslim 2725)","reference":"عَنْ عَلِيٍّ قَالَ:قَالَ لِي رَسُولُ اللهِ صلى الله عليه وسلم: قُلِ: اللَّهُمَّ اهْدِنِي، وَسَدِّدْنِي، وَاذْكُرْ بِالْهُدَى هِدَايَتَكَ الطَّرِيقَ وَالسَّدَادِ سَدَادَ السَّهْمِ.\\n(صحيح مسلم ٢٧٢٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/doubtful/"},{"title":"Protection from Shirk & Riya","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ.","transliteration":"Allāhumma innī aʿūdhu bika an ushrika bika wa ana aʿlam, wa astaghfiruka limā lā aʿlam.","translation":"O Allah, I seek Your protection from knowingly associating partners with You and seek Your forgiveness for unknowingly (doing so).","description":null,"benefit":null,"virtue":"Ma’qil b. Yasār (raḍiy Allāhu ‘anhu) narrated: “I walked with Abū Bakr Siddīq (raḍiy Allāhu ‘anhu) to the Messenger of Allah ﷺ. He ﷺ said: “O Abū Bakr! This shirk is more subtle than the footsteps of an ant.” Abū Bakr asked, “Is shirk not only when a person ascribes a partner with Allah?” The Messenger of Allah ﷺ replied: By the One in whose hands my life is, shirk is more subtle than the footsteps of an ant. Shall I not guide you towards something which if you say, it will remove it’s minor and major? He ﷺ said: “Say [the above].”","hadith":null,"reference":"(Al-Adab al-Mufrad 716, Ibn al-Sunnī 286)\\nحَدَّثَنَا عَبَّاسٌ النَّرْسِيُّ قَالَ: حَدَّثَنَا عَبْدُ الْوَاحِدِ قَالَ: حَدَّثَنَا لَيْثٌ قَالَ: أَخْبَرَنِي رَجُلٌ مِنْ أَهْلِ الْبَصْرَةِ قَالَ: سَمِعْتُ مَعْقِلَ بْنَ يَسَارٍ يَقُولُ: انْطَلَقْتُ مَعَ أَبِي بَكْرٍ الصِّدِّيقِ رضي الله عنه إِلَى النَّبِيِّ صلى الله عليه وسلم، فَقَالَ:يَا أَبَا بَكْرٍ، لَلشِّرْكُ فِيكُمْ أَخْفَى مِنْ دَبِيبِ النَّمْلِ، فَقَالَ أَبُو بَكْرٍ: وَهَلِ الشِّرْكُ إِلَّا مَنْ جَعَلَ مَعَ اللَّهِ إِلَهًا آخَرَ؟ فَقَالَ النَّبِيُّ صلى الله عليه وسلم:وَالَّذِي نَفْسِي بِيَدِهِ، لَلشِّرْكُ أَخْفَى مِنْ دَبِيبِ النَّمْلِ، أَلَا أَدُلُّكَ عَلَى شَيْءٍ إِذَا قُلْتَهُ ذَهَبَ عَنْكَ قَلِيلُهُ وَكَثِيرُهُ؟  قَالَ:قُلِ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ. (الأدب المفرد ٧١٦)\\nعَنْ حُذَيْفَةَ، عَنْ أَبِي رضي الله عنهما، أَمَا أَخْبَرَ ذَلِكَ حُذَيْفَةُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ، وَأَمَا أَخْبَرَهُ أَبُو بَكْرٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ قَالَ: الشِّرْكُ أَخْفَى فِيكُمْ مِنْ دَبِيبِ ‌النَّمْلِ، قَالَ: قُلْنَا: يَا رَسُولَ اللَّهِ، وَهَلِ الشِّرْكُ إِلَّا مَا عُبِدَ مِنْ دُونِ اللَّهِ عز وجل، أَوْ مَا دُعِيَ مَعَ اللَّهِ، شَكَّ عَبْدُ الْمَلِكِ بْنُ جُرَيْجٍ، فَقَالَ:ثَكِلَتْكَ أُمُّكَ يَا صِدِّيقُ، الشِّرْكُ أَخْفَى فِيكُمْ مِنْ دَبِيبِ ‌النَّمْلِ، أَلَا أُخْبِرُكَ بِقَوْلٍ يُذْهِبُ صِغَارَهُ وَكِبَارَهُ، أَوْ صَغِيرَهُ وَكَبِيرَهُ؟قَالَ: قُلْتُ: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: ” تَقُولُ كُلَّ يَوْمٍ ثَلَاثَ مَرَّاتٍ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ، وَالشِّرْكُ أَنْ يَقُولَ أَعْطَانِي اللَّهُ وَفُلَانٌ، وَالنِّدُّ أَنْ يَقُولَ الْإِنْسَانُ: لَوْلَا فُلَانٌ لَقَتَلَنِي فُلَانٌ. (عمل اليوم والليلة لابن السني ٢٨٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/doubtful/"},{"title":"Protection from Evil Traits & Endings","arabic":"اَللّٰهُمَّ إِنّيْ أَعُوْذُ بِكَ مِنَ الْبُخْلِ ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ ، وَأَعُوْذُ بِكَ أَنْ أُرَدَّ إِلَىٰ أَرْذَلِ الْعُمُرِ ، وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا ، وَأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ.","transliteration":"Allāhumma innī aʿūdhu bika mina-l-bukhl, wa aʿūdhu bika mina-l-jubn, wa aʿūdhu bika an uradda ilā ardhali-l-ʿumur, wa aʿūdhu bika min fitnati-d-dunyā, wa aʿūdhu bika min ʿadhābi-l-qabr.","translation":"O Allah, I seek Your protection from miserliness and I seek Your protection from cowardice. I seek Your protection from being returned to the worst part of life (old age), I seek Your protection from the trials of the world, and I seek Your protection from the punishment of the grave.","description":null,"benefit":null,"virtue":null,"hadith":"Saʿd b. Abī Waqqās (radiy Allāhū ‘anhu) would instruct (to seek refuge) about five things [the above] and he would narrate it from the Messenger of Allah ﷺ . (Bukhārī 6370)","reference":"عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رضي الله عنه كَانَ يَأْمُرُ بِهَؤُلَاءِ الْخَمْسِ وَيُحَدِّثُهُنَّ عَنِ النَّبِيِّ صلى الله عليه وسلم: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبُخْلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ.\\n(صحيح البخاري ٦٣٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/doubtful/"}]},{"feeling":"Greedy","slug":"greedy","url":"https://allahuakbarofficial.com/greedy/","items_count":2,"duas":[{"title":"Protect Yourself From Anxiety, Laziness & Debt","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ ، وَأَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ ، وَأَعُوْذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.","transliteration":"Allāhumma innī aʿūdhu bika min-l-hammi wa-l-ḥazan, wa aʿūdhu bika min-l-ʿajzi wa-l-kasal, wa aʿūdhu bika min-l-jubni wa-l-bukhl, wa aʿūdhu bika min ghalabati-d-dayni wa qahri-r-rijāl.","translation":"O Allah, I seek Your protection from anxiety and grief. I seek Your protection from inability and laziness. I seek Your protection from cowardice and miserliness, and I seek Your protection from being overcome by debt and being overpowered by men.","description":null,"benefit":null,"virtue":"Abū Saʿīd al-Khudrī (raḍiy Allāhu ʿanhu) narrated that one day, the Messenger of Allah ﷺ entered the masjid. He saw a man from the Anṣār called Abū Umāmah (raḍiy Allāhu ʿanhu). He ﷺ asked, “What is the matter? Why are you sitting in the masjid when it is not the time for prayer?” He replied, “Never-ending worries and debts, O Messenger of Allah.” The Messenger of Allah ﷺ then asked, “Shall I not teach you words by which, when you say them, Allah will remove your worries, and settle your debts?” He replied, “Yes of course, O Messenger of Allah.” He ﷺ said, “Say in the morning and evening [the above].” Abū Umāmah (raḍiy Allāhu ʿanhu) said, “Then I did that, and Allah removed my worries and settled my debts.” (Abū Dāwūd 1555)","hadith":null,"reference":"عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: دَخَلَ رَسُولُ صَلَّى عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ مِنَ الْأَنْصَارِ، يُقَالُ لَهُ: أَبُو أُمَامَةَ، فَقَالَ: «يَا أُمَامَةَ، مَا لِي أَرَاكَ جَالِسًا فِي الْمَسْجِدِ فِي غَيْرِ وَقْتِ الصَّلَاةِ؟»، قَالَ: هُمُومٌ لَزِمَتْنِي، وَدُيُونٌ يَا رَسُولَ اللَّهِ، قَالَ: أَفَلَا أُعَلِّمُكَ كَلَامًا إِذَا أَنْتَ قُلْتَهُ أَذْهَبَ عز وجل هَمَّكَ، وَقَضَى عَنْكَ دَيْنَكَ؟، قَالَ: قُلْتُ: بَلَى، يَا رَسُولَ، قَالَ: ” قُلْ إِذَا أَصْبَحْتَ، وَإِذَا أَمْسَيْتَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَقَهْرِ الرِّجَالِ “، قَالَ: فَفَعَلْتُ ذَلِكَ، فَأَذْهَبَ اللَّهُ عز وجل هَمِّي، وَقَضَى عَنِّي دَيْنِي.\\n(سنن أبي داود ١٥٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/greedy/"},{"title":"Contentment & Allah’s Protection","arabic":"اَللّٰهُمَّ قَنِّعْنِيْ بِمَا رَزَقْتَنِيْ ، وَبَارِكْ لِيْ فِيْهِ ، وَاخْلُفْ عَلَيٰ كُلِّ غَائِبَةٍ لِّيْ بِخَيْرٍ\\nعَنِ ابْنِ عَبَّاسٍ، رضي الله عنهما، قَالَ: كَانَ النَّبِيُّ صلى الله عليه وسلم يَدْعُو يَقُولُ: اللَّهُمَّ ‌قَنِّعْنِي بِمَا رَزَقْتَنِي، وَبَارِكْ لِي فِيهِ، وَاخْلُفْ عَلَى كُلِّ غَائِبَةٍ لِي بِخَيْرٍ.","transliteration":"Allāhumma qanniʿnī bimā razaqtanī, wa bārik lī fīhī, wa-khluf ʿalā kulli ghā’ibati-l-lī bi-khayr.","translation":"O Allah, make me content with what You have granted me, bless me in it and be a protector for me in that which is absent from me (i.e. family and wealth).","description":null,"benefit":null,"virtue":null,"hadith":"Ibn ʿAbbās (radiy Allāhū ‘anhumā) narrates that the Prophet ﷺ would supplicate with [the above].","reference":"(Hākim 1878)\\n(المستدرك على الصحيحين للحاكم ١٨٧٨)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/greedy/"}]},{"feeling":"Grateful","slug":"grateful","url":"https://allahuakbarofficial.com/grateful/","items_count":11,"duas":[{"title":"Surah al-Fatihah: The Greatest Duʿa","arabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيْمِ ،\\nاَلْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِيْنَ ، الرَّحْمٰنِ الرَّحِيْمِ ، مٰلِكِ يَوْمِ الدِّيْنِ ، إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِيْنُ ، اِهْدِنَا الصِّرَاطَ الْمُسْتَقِيْمَ ، صِرَاطَ الَّذِيْنَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوْبِ عَلَيْهِمْ وَلَا الضَّآلِّيْنَ","transliteration":"Bismi-llāhi-r-Raḥmāni-r-Raḥīm. Alḥamdu-lillāhi Rabbi-l-ʿālamīn, ar-Raḥmāni-r-Raḥīm, Māliki yawmi-d-dīn, iyyāka naʿbudu wa iyyāka nastaʿīn, ihdina-ṣ-Ṣirāṭa-l-Mustaqīm, ṣirāṭa-lladhīna anʿamta ʿalayhim ghayri-l-maghḍūbi ʿālayhim wa la-ḍ-ḍāllīn.","translation":"In the name of Allah, the All-Merciful, the Very Merciful. All praises and thanks are for Allah, the Lord of all the worlds, The All-Merciful, The Very Merciful, Master of the Day of Judgement. You Alone we worship, You Alone we ask for help. Guide us on the Straight Path, the path of those whom You have favoured, not of those who incur (Your) anger nor of those who have gone astray. (1:1-7)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/grateful/"},{"title":"When Thanking Another Person","arabic":"جَزَاكَ اللَّهُ خَيْرًا","transliteration":"Jazāk-Allāhu khayrā.","translation":"May Allah reward you with goodness.","description":null,"benefit":null,"virtue":null,"hadith":"Usāmah b. Zayd (raḍiy Allāhu ʿanhu) narrated that the Messenger of Allah ﷺ said: “Whoever receives a favour and then says [the above] to the doer, has excelled in his appreciation.” (Tirmidhī 2035)","reference":"عَنْ أُسَامَةَ بْنِ زَيْدٍ قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: مَنْ صُنِعَ إِلَيْهِ مَعْرُوفٌ فَقَالَ لِفَاعِلِهِ: جَزَاكَ اللَّهُ خَيْرًا فَقَدْ أَبْلَغَ فِي الثَّنَاءِ.\\n(سنن الترمذي ٢٠٣٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/grateful/"},{"title":"Fulfil Your Obligation to Thank Allah","arabic":"اَللّٰهُمَّ مَا أَصْبَحَ بِيْ مِنْ نِّعْمَةٍ أَوْ بِأَحَدٍ مِّنْ خَلْقِكَ ، فَمِنْكَ وَحْدَكَ لَا شَرِيْكَ لَكَ ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ.","transliteration":"Allāhumma mā aṣbaḥa bī min niʿmatin aw bi-aḥadim-min khalqik, fa-minka waḥdaka lā sharīka lak, fa laka-l-ḥamdu wa laka-sh-shukr.","translation":"O Allah, all the favours that I or anyone from Your creation has received in the morning, are from You Alone. You have no partner. To You Alone belong all praise and all thanks.","description":null,"benefit":null,"virtue":"ʿAbdullāh b. Ghannām (raḍiy Allāhu ʿanhu) narrates that the Messenger of Allah ﷺ said: “Whoever says [the above] in the morning has fulfilled his obligation to thank Allah for that day. And whoever says it in the evening has fulfilled his obligation for that night.”","hadith":null,"reference":"(Abū Dāwūd 5073)\\nعن عبدِ الله بن غنَّام البَياضيِّ، أن رسولَ الله صلى الله عليه وسلم قال: “من قال حينَ يُصبِح: اللَّهُمَّ ما أصبَحَ بي من نعمَةٍ فمِنكَ وحدَكَ لا شريكَ لك، فلكَ الحمدُ ولكَ الشُّكرُ، فقد أدَّى شُكرَ يومه، ومَن قال مِثلَ ذلك حينَ يُمسِي فقد أدَّى شُكرَ ليلَتِهِ. (سنن أبي داود ٥٠٧٣)\\nعَن عبد الله بن عَنْبَسَة عَن ابْن غنّام عَن رَسُول الله صلى الله عليه وسلم أَنه قَالَ من قَالَ حِين يصبح اللَّهُمَّ مَا أصبح بِي من نعْمَة أَو بأحدٍ من خلقك فمنك وَحدك لَا شريك لَك فلك الْحَمد وَلَك الشُّكْر إِلَّا أدّى شكر ذَلِك الْيَوْم.\\n(عمل اليوم والليلة للنسائي ٧)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/grateful/"},{"title":"Thank Allah for Blessing You","arabic":"اَلْحَمْدُ لِلّٰهِ الَّذِيْ أَطْعَمَنَا وَسَقَانَا ، وَكَفَانَا وَآوَانَا ، فَكَمْ مِّمَّنْ لَّا كَافِيَ لَهُ وَلَا مُؤْوِيَ.","transliteration":"Al-ḥamdu li-llāhi-l-ladhī aṭʿamanā wa saqānā, wa kafānā wa āwānā, fakam-mim-mal-lā kāfīya lahū walā mu’wiy.","translation":"All praise is for Allah, who provided us food and drink, and who sufficed us and has sheltered us; for how many have none to suffice them or shelter them.","description":null,"benefit":null,"virtue":null,"hadith":"Anas (raḍiy Allāhu ʿanhu) narrates that when the Messenger of Allah ﷺ would retire to bed, he would say [the above]. (Muslim 2715)","reference":"عَنْ أَنَسٍ أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم كَانَ إِذَا أَوَى إِلَى فِرَاشِهِ قَالَ: الْحَمْدُ لِلهِ الَّذِي أَطْعَمَنَا، وَسَقَانَا، وَكَفَانَا، وَآوَانَا فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ، وَلَا مُؤْوِيَ.\\n(صحيح مسلم ٢٧١٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/grateful/"},{"title":"Praise Allah with the Praises of the Entire Creation","arabic":"اَلْحَمْدُ لِلّٰهِ الَّذِيْ كَفَانِيْ وَآوَانِيْ ، اَلْحَمْدُ لِلّٰهِ الَّذِيْ أَطْعَمَنِيْ وَسَقَانِيْ ، اَلْحَمْدُ لِلّٰهِ الَّذِيْ مَنَّ عَلَيَّ فَأَفْضَلَ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ بِعِزَّتِكَ أَنْ تُنَجِّيَنِيْ مِنَ النَّارِ.","transliteration":"Al-ḥamdu lillāhi-lladhī kafānī wa āwānī, al-ḥamdu lillāhi-lladhī aṭʿamanī wa saqānī, al-ḥamdu lillāhi-lladhī manna ʿalayya fa-afḍal, Allāhumma innī as’aluka biʿizzatika an tunajjiyanī mina-n-nār.","translation":"All praise is for Allah who has sufficed me and given me refuge. All praise is for Allah who has fed me and given me drink. All praise is for Allah who has been gracious to me and showered favours on me. O Allah, I ask You by Your glory to save me from the Hell-Fire.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “Whoever says [the above] when retiring to bed has praised Allah with all the praises of His entire creation.” (Hākim 2001)","hadith":null,"reference":"عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: ” مَنْ قَالَ إِذَا أَوَى إِلَى فِرَاشِهِ: الْحَمْدُ لِلَّهِ الَّذِي كَفَانِي وَآوَانِي، الْحَمْدُ لِلَّهِ الَّذِي أَطْعِمْنِي وَسَقَانِي، الْحَمْدُ لِلَّهِ الَّذِي مَنَّ عَلَيَّ فَأَفْضَلَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ بِعِزَّتِكَ أَنْ تُنَجِّيَنِي مِنَ النَّارِ، فَقَدْ حَمِدَ اللَّهَ بِجَمِيعِ مَحَامِدِ الْخَلْقِ كُلِّهِمْ.\\n(المستدرك على الصحيحين للحاكم ٢٠٠١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/grateful/"},{"title":"Praise Allah for All His Favours","arabic":"اَلْحَمْدُ لِلَّهِ الَّذِيْ يُطْعِمُ وَلَا يُطْعَمُ ، مَنَّ عَلَيْنَا فَهَدَانَا وَأَطْعَمَنَا وَسَقَانَا ، وَكُلَّ بَلَاءٍ حَسَنٍ أَبْلَانَا ، اَلْحَمْدُ لِلَّهِ غَيْرَ مُوَدَّعٍ وَّلَا مُكَافَأٍ وَّلَا مَكْفُوْرٍ وَّلَا مُسْتَغْنًى عَنْهُ ، اَلْحَمْدُ لِلَّهِ الَّذِيْ أَطْعَمَ مِنَ الطَّعَامِ ، وَسَقَىٰ مِنَ الشَّرَابِ ، وَكَسَا مِنَ الْعُرْيِ ، وَهَدَىٰ مِنَ الضَّلَالَةِ ، وَبَصَّرَ مِنَ الْعَمَىٰ ، وَفَضَّلَ عَلَىٰ كَثِيْرٍ مِّنْ خَلْقِهِ تَفْضِيْلًا ، اَلْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِيْنَ","transliteration":"Al-ḥamdu lillāhi-lladhī yuṭʿiumu wa lā yuṭʿam, manna ʿalaynā fa-hadānā wa aṭʿamanā wa saqānā, wa kulla balā’in ḥasanin ablānā, al-ḥamdu lillāhi ghayra muwaddaʿin wa lā mukāfa’iw-wa lā makfūrin wa lā mustaghnan ʿanh, al-ḥamdu lillāhi-lladhī aṭʿama mina-ṭ-ṭaʿām, wa saqā mina-sh-sharāb, wa kasā minal-ʿurā, wa hadā mina-ḍ-ḍalālah, wa baṣṣara mina-l-ʿamā, wa faḍḍala ʿalā kathīrim-min-khalqihī tafḍīlā, alḥamdu-lillāhi Rabbi-l-ʿālamīn.","translation":"All praise is for Allah who feeds and is not fed. He favoured us, and thus guided us, blessed us with food and drink, and bestowed upon us every favour. All praise is for Allah, a praise which we will never bid farewell to, a never-ending praise, an accepted praise and an indispensable praise. All praise is for Allah who provided food and drink; who clothed us, guided us from error, removed our blindness and favoured us greatly over many of His creation. All praise is for Allah, Lord of the worlds.","description":null,"benefit":null,"virtue":null,"hadith":"Abū Hurayrah (raḍiy Allāhu ‘anhu) narrates: “A man from the Anṣār from the people of Qubā invited the Prophet ﷺ for a meal. When he ﷺ had finished eating and had washed his hands, he said [the above].” (Nasā’ī in Sunan al-Kubrā 10060, Ibn Ḥibbān 2024)","reference":"عَنْ أَبِي هُرَيْرَةَ قَالَ: دَعَا رَجُلٌ مِنَ الْأَنْصَارِ مِنْ أَهْلِ قُبَاءٍ النَّبِيَّ صلى الله عليه وسلم، فَانْطَلَقْنَا مَعَهُ، فَلَمَّا طَعِمَ وَغَسَلَ يَدَهُ، أَوْ يَدَيْهِ عَلَيْنَا قَالَ: «الْحَمْدُ لِلَّهِ الَّذِي يُطْعِمُ وَلَا يُطْعَمُ، مَنَّ عَلَيْنَا فَهَدَانَا وَأَطْعَمَنَا وَسَقَانَا، وَكُلَّ بَلَاءٍ حَسَنٍ أَبْلَانَا، الْحَمْدُ لِلَّهِ غَيْرَ مُوَدَّعٍ، وَلَا مُكَافَئٍ وَلَا مَكْفُورٍ، وَلَا مُسْتَغْنًى عَنْهُ، الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَ مِنَ الطَّعَامِ، وَسَقَى مِنَ الشَّرَابِ، وَكَسَا مِنَ الْعُرْيِ، وَهَدَى مِنَ الضَّلَالَةِ، وَبَصَّرَ مِنَ الْعَمَى، وَفَضَّلَ عَلَى كَثِيرٍ مِنْ خَلْقِهِ تَفْضِيلًا، الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ.\\n(السنن الكبرى للنسائي ١٠٠٦٠)\\nعَنْ أَبِي هُرَيْرَةَ، قَالَ: دَعَا رَجُلٌ مِنَ الأَنْصَارِ النَّبِيَّ صلى الله عليه وسلم، قَالَ: فَانْطَلَقْنَا مَعَهُ، فَلَمَّا طَعِمَ وَغَسَلَ يَدَهُ، قَالَ: “الْحَمْدُ للهِ الَّذِي يُطْعِمُ وَلَا يُطْعَمُ، مَنَّ عَلَيْنَا فَهَدَانَا، وَأَطْعَمَنَا وَسَقَانَا، وَكُلَّ بَلَاءٍ حَسَنٍ أَبْلَانَا، الْحَمْدُ للهِ الَّذِي أَطْعَمَ مِنَ الطَّعَامِ، وَسَقَى مِنَ الشَّرَابِ، وَكَسَا مِنَ الْعُرْيِ، وَهَدَى مِنَ الضَّلَالَةِ، وَبَصَّرَ مِنَ الْعَمَى، وَفَضَّلَ عَلَى كَثِيرٍ مِمَّنْ خَلَقَ ‌تَفْضِيلاً، الْحَمْدُ للهِ رَبِّ الْعَالَمِينَ.\\n(صحيح ابن حبان  ٢٠٢٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/grateful/"},{"title":"Duʿa of Prophet Sulayman ﷺ for Gratitude to Allah & Doing Good Deeds","arabic":"رَبِّ أَوْزِعْنِيْٓ أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِيْٓ أَنْعَمْتَ عَلَيَّ وَعَلَىٰ وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ ، وَأَدْخِلْنِيْ بِرَحْمَتِكَ فِيْ عِبَادِكَ الصَّالِحِيْنَ.","transliteration":"Rabbi awziʿnī an ashkura niʿmataka-l-latī anʿamta ʿalayya wa ʿalā wālidayya wa an aʿmala ṣāliḥan tarḍāh, wa adhkilnī bi-raḥmatika fī ʿibādika-ṣ-ṣāliḥīn.","translation":"My Lord, enable me to be grateful for Your favour which You have bestowed upon me and upon my parents, and to do good deeds that please You. And admit me by Your mercy amongst Your righteous servants. (27:19)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/grateful/"},{"title":"A Priceless Treasure","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ ، وَالْعَزِيْمَةَ عَلَى الرُّشْدِ ، وَأَسْأَلُكَ مُوْجِبَاتِ رَحْمَتِكَ ، وَعَزَائِمَ مَغْفِرَتِكَ ، وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ ، وَحُسْنَ عِبَادَتِكَ ، وَأَسْأَلُكَ قَلْبًا سَلِيْمًا ، وَلِسَانًا صَادِقًا ، وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ ، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ ، وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ ، إِنَّكَ أَنْتَ عَلَّامُ الْغُيُوْبِ","transliteration":"Allāhumma innī as’aluka-th-thabāta fil-amr, wa-l-ʿazīmata ʿala-r-rushd, wa as’aluka mūjibāti raḥmatik, wa ʿazā’ima maghfiratik, wa as’aluka shukra niʿmatik, wa ḥusna ʿibādatik, wa as’aluka qalban salīmā, wa lisānan ṣādiqā, wa as’aluka min khayri mā taʿlam, wa aʿūdhu bika min sharri mā taʿlam, wa astaghfiruka limā taʿlam, innaka Anta ʿAllāmul-ghuyūb.","translation":"O Allah, I beg you for steadfastness in all matters and the determination to take the right course. I ask You for all that which will necessitate Your mercy and the determination to do all that which will necessitate Your forgiveness. I ask You to make me grateful for Your blessings and to worship You in an excellent manner. I ask You for a sound heart and a truthful tongue. I ask You for the good of what You know, I seek Your protection from the evil of what You know, and I seek Your forgiveness for what You know. Indeed, You are the All-Knowing of the unseen.","description":null,"benefit":null,"virtue":"Shaddād b. Aws (raḍiy Allāhu ‘anhu) narrates that the Messenger of Allah ﷺ was teaching this duā to me. he said: “O Shaddād, when you see people collecting gold & silver as their treasures, then consider [the above] as your treasure.” (Ahmad 17114)","hadith":null,"reference":"حَدَّثَنَا رَوْحٌ، قَالَ: حَدَّثَنَا الْأَوْزَاعِيُّ، عَنْ حَسَّانَ بْنِ عَطِيَّةَ قَالَ: كَانَ شَدَّادُ بْنُ أَوْسٍ، فِي سَفَرٍ، فَنَزَلَ مَنْزِلًا، فَقَالَ لِغُلَامِهِ: ائْتِنَا بِالسُّفْرَةِ نَعْبَثْ بِهَا. فَأَنْكَرْتُ عَلَيْهِ، فَقَالَ: مَا تَكَلَّمْتُ بِكَلِمَةٍ مُنْذُ أَسْلَمْتُ إِلَّا وَأَنَا أَخْطِمُهَا وَأَزُمُّهَا غَيْرَ كَلِمَتِي هَذِهِ، فَلَا تَحْفَظُوهَا عَلَيَّ، وَاحْفَظُوا مِنِّي مَا أَقُولُ لَكُمْ: سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَقُولُ: ” إِذَا كَنَزَ النَّاسُ الذَّهَبَ وَالْفِضَّةَ، فَاكْنِزُوا هَؤُلَاءِ الْكَلِمَاتِ: اللهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ، وَالْعَزِيمَةَ عَلَى الرُّشْدِ، وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ، وَأَسْأَلُكَ حُسْنَ عِبَادَتِكَ، وَأَسْأَلُكَ قَلْبًا سَلِيمًا، وَأَسْأَلُكَ لِسَانًا صَادِقًا، وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ، إِنَّكَ أَنْتَ عَلَّامُ الْغُيُوبِ.\\n(مسند احمد ١٧١١٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/grateful/"},{"title":"Duʿa for Gratitude, Good Deeds & Pious Children","arabic":"رَبِّ أَوْزِعْنِيْٓ أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِيْٓ أَنْعَمْتَ عَلَيَّ وَعَلَىٰ وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ ، وَأَصْلِحْ لِيْ فِيْ ذُرِّيَّتِيْ ، إِنِّيْ تُبْتُ إِلَيْكَ وَإِنِّيْ مِنَ الْمُسْلِمِيْنَ.","transliteration":"Rabbi awziʿnī an ashkura niʿmataka-l-latī anʿamta ʿalayya wa ʿalā wālidayya wa an aʿmala ṣāliḥan tarḍāh, wa aṣliḥ lī fī dhuriyyatī, innī tubtu ilayka wa innī mina-l-muslimīn.","translation":"My Lord, enable me to be grateful for Your favour which You have bestowed upon me and upon my parents, and to do good deeds that please You. Make my offspring righteous; I truly repent to you, and truly I am of those who submit to You. (46:15)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/grateful/"},{"title":"Becoming A Godly Person","arabic":"رَبِّ أَعِنِّيْ وَلَا تُعِنْ عَلَيَّ ، وَانْصُرْنِيْ وَلَا تَنْصُرْ عَلَيَّ ، وَامْكُرْ لِيْ وَلَا تَمْكُرْ عَلَيَّ ، وَاهْدِنِيْ وَيَسِّرِ الْهُدَىٰ لِيْ ، وَانْصُرْنِيْ عَلَىٰ مَنْ بَغَىٰ عَلَيَّ ، رَبِّ اجْعَلْنِيْ لَكَ شَكَّارًا ، لَكَ ذَكَّارًا ، لَكَ رَهَّابًا ، لَكَ مِطْوَاعًا ، لَكَ مُخْبِتًا ، إِلَيْكَ أَوَّاهًا مُّنِيْبًا ، رَبِّ تَقَبَّلْ تَوْبَتِيْ ، وَاغْسِلْ حَوْبَتِيْ ، وَأَجِبْ دَعْوَتِيْ ، وَثَبِّتْ حُجَّتِيْ ، وَسَدِّدْ لِسَانِيْ ، وَاهْدِ قَلْبِيْ ، وَاسْلُلْ سَخِيْمَةَ صَدْرِيْ","transliteration":"Rabbi aʿinnī wa lā tuʿin ʿalayya, wan-ṣurnī wa lā tanṣur ʿalayya, wa-mkur lī wa lā tamkur ʿalayya, wa-hdinī wa yas-siri-l-hudā lī, wan-ṣurnī ʿalā ma-m-baghā ʿalayya, Rabbi-j-ʿalnī laka shakkārā, laka dhak- kārā, laka rahhābā, laka miṭwāʿā, laka mukhbitā, ilayka aw-wāha-m-munībā, Rabbi taqabbal tawbatī, wa-ghsil ḥawbatī, wa ajib daʿwatī, wa thab-bit ḥujjatī, wa saddid lisānī, wahdi qalbī, waslul sakhīmata ṣadrī.","translation":"My Lord, help me and do not help others against me. Grant me victory and do not grant victory to others over me. Plan in my favour and do not plan for others against me. Guide me and ease guidance for me. Help me against those who oppress me. My Lord, make me one who is extremely grateful to You, who remembers you always, who perpetually fears You, who is fully obedient to You, who is humble before You, who constantly cries and pleads with You, and who repeatedly turns to You in repentance. My Lord, accept my repentance, wash away my sins, accept my supplications, strengthen my case, rectify my speech, guide my heart, and remove the malice from my heart.","description":null,"benefit":null,"virtue":null,"hadith":"Ibn ʿAbbās (raḍiy Allāhu ‘anhu) narrates that the Messenger of Allah ﷺ would supplicate with [the above]. (Tirmidhī 3551)","reference":"عَنْ ابْنِ عَبَّاسٍ، قَالَ: كَانَ النَّبِيُّ صلى الله عليه وسلم يَدْعُو يَقُولُ: رَبِّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ، وَانْصُرْنِي وَلَا تَنْصُرْ عَلَيَّ، وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ، وَاهْدِنِي وَيَسِّرِ الهُدَى لِي، وَانْصُرْنِي عَلَى مَنْ بَغَى عَلَيَّ، رَبِّ اجْعَلْنِي لَكَ شَكَّارًا، لَكَ ذَكَّارًا، لَكَ رَهَّابًا، لَكَ مِطْوَاعًا، لَكَ مُخْبِتًا، إِلَيْكَ أَوَّاهًا مُنِيبًا، رَبِّ تَقَبَّلْ تَوْبَتِي، وَاغْسِلْ حَوْبَتِي، وَأَجِبْ دَعْوَتِي، وَثَبِّتْ حُجَّتِي، وَسَدِّدْ لِسَانِي، وَاهْدِ قَلْبِي، وَاسْلُلْ سَخِيمَةَ صَدْرِي. (سنن الترمذي ٣٥٥١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/grateful/"},{"title":"Protection from Allah’s Anger & Removal of Blessings","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ ، وَتَحَوُّلِ عَافِيَتِكَ ، وَفُجَاءَةِ نِقْمَتِكَ ، وَجَمِيْعِ سَخَطِكَ.\\nعَنِ ابْنِ عُمَرَ قَالَ:كَانَ مِنْ دُعَاءِ رَسُولِ اللهِ صلى الله عليه وسلم: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ، وَتَحْوِيلِ عَافِيَتِكَ، وَفُجَاءَةِ نِقْمَتِكَ، وَجَمِيعِ سَخَطِكَ.","transliteration":"Allāhumma innī aʿūdhu bika min zawāli niʿmatik, wa taḥawwuli ʿāfiyatik, wa fujā’ati niqmatik, wa jamīʿi sakhaṭik.","translation":"O Allah, I seek Your protection from the loss of Your favours, the removal of Your complete protection, Your sudden punishment and all that which may incur Your displeasure.","description":null,"benefit":null,"virtue":null,"hadith":"ʿAbdullah b. ʿUmar (radiy Allāhū ‘anhumā) reported that from the supplication of the Messenger of Allah ﷺ was [the above]. (Muslim 2739, Abū Dāwūd 1545)","reference":"عَنْ عَبْدِ الله بن عمر، قال كان من دعاء رَسُولُ اللَّهِ صلى الله عليه وسلم “اللَّهُمَّ! إني أعوذ بك من زوال نعمتك، وتحول عافيتك، وفجاءة نقمتك، وجميع سخطك.\\n(صحيح مسلم ٢٧٣٩)\\n(سنن ابي داود ١٥٤٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/grateful/"}]},{"feeling":"Guilty","slug":"guilty","url":"https://allahuakbarofficial.com/guilty/","items_count":20,"duas":[{"title":"Sayyid al-Istighfar: The Best Way of Seeking Forgiveness","arabic":"(سيد الاستغفار) اَللّٰهُمَّ أَنْتَ رَبِّيْ لَا إِلٰهَ إِلَّا أَنْتَ ، خَلَقْتَنِيْ وَأَنَا عَبْدُكَ ، وَأَنَا عَلَىٰ عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ ، أَعُوْذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ ، أَبُوْءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوْءُ لَكَ بِذَنْبِيْ ، فَاغْفِرْ لِيْ فَإِنَّهُ لَا يَغْفِرُ الذُّنُوْبَ إِلَّا أَنْتَ.","transliteration":"Allāhumma Anta Rabbī, lā ilāha illā Ant, khalaqtanī wa ana ʿabduk, wa ana ʿalā ʿahdika wa waʿdika mā’staṭaʿt, aʿūdhu bika min sharri mā ṣanaʿt, abū’u laka bi niʿmatika ʿalayya wa abū’u bidhambī fa-ghfir lī fa-innahū lā yaghfiru-dh-dhunūba illā Ant.","translation":"(Sayyid al-Istighfār) O Allah, You are my Lord. There is no god worthy of worship except You. You have created me, and I am Your slave, and I am under Your covenant and pledge (to fulfil it) to the best of my ability. I seek Your protection from the evil that I have done. I acknowledge the favours that You have bestowed upon me, and I admit my sins. Forgive me, for none forgives sins but You.","description":null,"benefit":null,"virtue":"Shaddād b. Aws (raḍiy Allāhu ʿanhu) narrates that the Messenger of Allah ﷺ said: “The most superior manner of seeking forgiveness is that you say [the above]. Whoever says it during the day with firm belief in it and dies on the same day before the evening, he will be from the people of Paradise. And whoever says it during the night with firm belief in it and dies before the morning, he will be from the people of Paradise.” (Bukhārī 6306)","hadith":null,"reference":"عَنْ بُشَيْرُ بْنُ كَعْبٍ الْعَدَوِيُّ قَالَ: حَدَّثَنِي شَدَّادُ بْنُ أَوْسٍ رضي الله عنه عَنِ النَّبِيِّ صلى الله عليه وسلم:سَيِّدُ الِاسْتِغْفَارِ أَنْ تَقُولَ: اللَّهُمَّ أَنْتَ رَبِّي، لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي، فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ. قَالَ: وَمَنْ قَالَهَا مِنَ النَّهَارِ مُوقِنًا بِهَا فَمَاتَ مِنْ يَوْمِهِ قَبْلَ أَنْ يُمْسِيَ فَهُوَ مِنْ أَهْلِ الْجَنَّةِ، وَمَنْ قَالَهَا مِنَ اللَّيْلِ وَهُوَ مُوقِنٌ بِهَا فَمَاتَ قَبْلَ أَنْ يُصْبِحَ فَهُوَ مِنْ أَهْلِ الْجَنَّةِ.(صحيح البخاري ٦٣٠٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"Duʿa of the Grief-stricken Prophet Yunus ﷺ","arabic":"لَآ إِلٰهَ إِلَّآ أَنْتَ سُبْحَانَكَ إِنِّيْ كُنْتُ مِنَ الظَّالِمِيْنَ.","transliteration":"Lā ilāha illā Anta subḥānaka innī kuntu mina-ẓ-ẓālimīn.","translation":"There is no god worthy of worship except You. You are free from imperfection. Indeed, I have been of the wrongdoers. (21:87)","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “The supplication of Dhun-Nūn (Prophet Yūnus) when he supplicated, while in the belly of the whale was: [the above]. ”No Muslim man ever supplicates with [the above] except that Allah answers his supplication.” (Tirmidhī 3505)","hadith":null,"reference":"He ﷺ also said that [the above] removes difficulties and calamities. (Nasā’i 10416)\\nعَنْ إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ سَعْدٍ، عَنْ أَبِيهِ ، عَنْ سَعْدٍ قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: دَعْوَةُ ذِي النُّونِ إِذْ دَعَا وَهُوَ فِي بَطْنِ الْحُوتِ: لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ؛ فَإِنَّهُ لَمْ يَدْعُ بِهَا رَجُلٌ مُسْلِمٌ فِي شَيْءٍ قَطُّ إِلَّا اسْتَجَابَ اللهُ لَهُ. (سنن الترمذي ٣٥٠٥)\\nأَخْبَرَنَا الْقَاسِمُ بْنُ زَكَرِيَّا، قَالَ: حَدَّثَنَا عُبَيْدُ بْنُ مُحَمَّدٍ، قَالَ: حَدَّثَنَا مُحَمَّدُ بْنُ مُهَاجِرٍ، قَالَ: حَدَّثَنِي إِبْرَاهِيمُ بْنُ مُحَمَّدِ بْنِ سَعْدٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ: كُنَّا جُلُوسًا عِنْدَ رَسُولِ اللهِ صلى الله عليه وسلم قَالَ: أَلَا أُخْبِرُكُمْ، أَوْ أُحَدِّثُكُمْ، بِشَيْءٍ إِذَا نَزَلَ بِرَجُلٍ مِنْكُمْ كَرْبٌ أَوْ بَلَاءٌ مِنَ بَلَاءِ الدُّنْيَا دَعَا بِهِ فُرِّجَ عَنْهُ؟ فَقِيلَ لَهُ: بَلَى، قَالَ: ” دُعَاءُ ذِي النُّونِ: ‌لَا ‌إِلَهَ ‌إِلَّا ‌أَنْتَ ‌سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ.\\n(السنن الكبرى للنسائي ١٠٤١٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"Praising Allah, Forgiveness and Good Character","arabic":"اَللّٰهُمَّ أَنْتَ الْمَلِكُ لَا إِلٰهَ إِلَّا أَنْتَ ، أَنْتَ رَبِّيْ وَأَنَا عَبْدُكَ ، ظَلَمْتُ نَفْسِيْ وَاعْتَرَفْتُ بِذَنْبِيْ ، فَاغْفِرْ لِيْ ذُنُوْبِيْ جَمِيْعًا ، إِنَّهُ لَا يَغْفِرُ الذُّنُوْبَ إِلَّا أَنْتَ ، وَاهْدِنِيْ لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِيْ لِأَحْسَنِهَا إِلَّا أَنْتَ ، وَاصْرِفْ عَنِّيْ سَيِّئَهَا لَا يَصْرِفُ عَنِّيْ سَيِّئَهَا إِلَّا أَنْتَ ، لَبَّيْكَ وَسَعْدَيْكَ ، وَالْخَيْرُ كُلُّهُ فِيْ يَدَيْكَ ، وَالشَّرُّ لَيْسَ إِلَيْكَ ، أَنَا بِكَ وَإِلَيْكَ ، تَبَارَكْتَ وَتَعَالَيْتَ ، أَسْتَغْفِرُكَ وَأَتُوْبُ إِلَيْكَ.\\nوَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَوَاتِ وَالأَرْضَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ إِنَّ صَلاَتِي وَنُسُكِي وَمَحْيَاىَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ لاَ شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ\\nاللَّهُمَّ لَكَ رَكَعْتُ وَبِكَ آمَنْتُ وَلَكَ أَسْلَمْتُ خَشَعَ لَكَ سَمْعِي وَبَصَرِي وَمُخِّي وَعَظْمِي وَعَصَبِي\\nاللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الأَرْضِ وَمِلْءَ مَا بَيْنَهُمَا وَمِلْءَ مَا شِئْتَ مِنْ شَىْءٍ بَعْدُ\\nاللَّهُمَّ لَكَ سَجَدْتُ وَبِكَ آمَنْتُ وَلَكَ أَسْلَمْتُ سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ وَصَوَّرَهُ وَشَقَّ سَمْعَهُ وَبَصَرَهُ تَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ\\nاللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَمَا أَسْرَفْتُ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ لاَ إِلَهَ إِلاَّ أَنْتَ","transliteration":"Allāhumma Antal-Maliku lā ilāha illā Ant, Anta Rabbī wa ana ʿabduk, ẓalamtu nafsī waʿtaraftu bi-dhambī, fa-ghfir lī dhunūbī jamīʿā, innahū lā yaghfiru-dh-dhunūba illā Ant, wa-hdinī li-aḥsani-l-akhlāqi lā yahdī li-aḥsanihā illā Ant, wa-ṣrif ʿannī sayyi’ahā lā yaṣrifu ʿannī sayyi’ahā illā Ant, labbayka wa saʿdayk, wal-khayru kulluhū fī yadayk, wa-sh-sharru laysa ilayk, ana bika wa ilayk, tabārakta wa taʿālayt, astaghfiruka wa atūbu ilayk.","translation":"O Allah, You are the King, there is no god worthy of worship except You. You are my Lord and I am Your slave. I have wronged myself and I confess my sins. Forgive all of my sins; indeed no one forgives sins except You. Guide me to the best of character, for no one guides to the best of it except You; and turn the evil of it away from me, for no one turns it away except You. Here I am at Your service, seeking Your pleasure; all good is in Your hands and no evil is attributed to You. I am from You and I am returning to You. You are Most Blessed and You are Most Exalted. I seek Your forgiveness and repent to You.","description":null,"benefit":null,"virtue":null,"hadith":"ʿAlī b. Abī Ṭālib (raḍiy Allāhu ‘anhu) narrates: “When the Messenger of Allah ﷺ would stand for prayer, he would say:","reference":"(I have turned my face towards the One who created the heavens and the earth, turned away from all that is false having surrendered to Allah, and I am not of the polytheists. My ṣalāh, my sacrifice, my life and my death are all for Allah, Lord of the worlds, who has no partners. I have been commanded of this, and I am of those who submit.) | (O Allah, for You Alone I have bowed in prayer, in You Alone I have believed, and to You Alone I have submitted. My hearing, sight, mind, bones and nerves are humble to You.) | (O Allah, Our Lord, for You Alone is all praise; praise which fills the heavens, which fills the earth, which fills whatever is in between them, and which fills whatever You wish after that.) | (O Allah, for You Alone I have prostrated, in You Alone I have believed, and to You Alone I have submitted. My face has prostrated to the One who created and fashioned it, and who formed its hearing and sight. Blessed is Allah, the Best of Creators.) | (O Allah, forgive me for what I have done in the past and for what I am yet to do, for what I have done privately and for what I have done publicly, for my excesses and for that which You know more than me. You are the One who brings forward and the One who puts behind, and there is no god worthy of worship except You.) (Muslim 771)\\nعَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، عن رسول الله صلى الله عليه وسلم؛ أَنَّهُ كَانَ إِذَا قَامَ إِلَى الصَّلَاةِ قَالَ: وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالأَرْضَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ. إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ لَا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ. اللَّهُمَّ! أنت الملك لا إله إِلَّا أَنْتَ. وَاهْدِنِي لِأَحْسَنِ الأَخْلَاقِ. لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ. وَاصْرِفْ عَنِّي سَيِّئَهَا. لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ. لَبَّيْكَ! وَسَعْدَيْكَ! وَالْخَيْرُ كُلُّهُ فِي يَدَيْكَ. وَالشَّرُّ لَيْسَ إِلَيْكَ. أَنَا بِكَ وَإِلَيْكَ. تَبَارَكْتَ وَتَعَالَيْتَ. أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ. وَإِذَا رَكَعَ قَالَ اللَّهُمَّ! لَكَ رَكَعْتُ. وَبِكَ آمَنْتُ. وَلَكَ أَسْلَمْتُ. خَشَعَ لَكَ سَمْعِي وَبَصَرِي. وَمُخِّي وَعَظْمِي وَعَصَبِي. وَإِذَا رَفَعَ قَالَ اللَّهُمَّ! رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَاوَاتِ وَمِلْءَ الأَرْضِ وَمِلْءَ مَا بَيْنَهُمَا وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ. وَإِذَا سَجَدَ قَالَ اللَّهُمَّ! لَكَ سَجَدْتُ. وَبِكَ آمَنْتُ. وَلَكَ أَسْلَمْتُ. سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ وَصَوَّرَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ. تبارك الله أحسن الخالقين” ثم يكون منت آخِرِ مَا يَقُولُ بَيْنَ التَّشَهُّدِ وَالتَّسْلِيمِ اللَّهُمَّ! اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ. وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ. وَمَا أَسْرَفْتُ. وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي. أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ. لا إله إلا أنت. (صحيح مسلم ٧٧١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"Duʿa of Prophet Musa ﷺ for Forgiveness","arabic":"رَبِّ إِنِّيْ ظَلَمْتُ نَفْسِيْ فَاغْفِرْ لِيْ.","transliteration":"Rabbi innī ẓalamtu nafsī fa-ghfirlī.","translation":"My Lord, I have certainly wronged myself, so forgive me. (28:16)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"Comprehensive Forgiveness","arabic":"اَللّٰهُمَّ اغْفِرْ لِيْ خَطِيْئَتِيْ وَجَهْلِيْ وَإِسْرَافِيْ فِيْ أَمْرِيْ ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّيْ ، اَللّٰهُمَّ اغْفِرْ لِيْ جِدِّيْ وَهَزْلِيْ وَخَطَئِيْ وَعَمْدِيْ وَكُلُّ ذٰلِكَ عِنْدِيْ ، اَللّٰهُمَّ اغْفِرْ لِيْ مَا قَدَّمْتُ وَمَا أَخَّرْتُ ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّـيْ ، أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ ، وَأَنْتَ عَلَىٰ كُلِّ شَيْءٍ قَدِيْرٌ.","transliteration":"Allāhumma-ghfirlī khaṭī’atī wa jahlī wa isrāfī fī amrī, wa mā Anta aʿlamu bihī minnī, Allāhumma-ghfir lī jiddī wa hazlī wa khaṭa’ī wa ʿamdī wa kullu dhālika ʿindī, Allāhumma-ghfirlī mā qaddamtu wa mā akh-khart, wa mā asrartu wa mā aʿlant, wa mā Anta aʿlamu bihī minnī, Anta-l-Muqaddimu wa Anta-l-Muakh-khir, wa Anta ʿalā kulli shay’in Qadīr.","translation":"O Allah, forgive my mistakes, ignorance, transgression in my matters, and what You are more Knowledgeable of than me. O Allah, forgive me for what I did in earnestness and in jest; unintentionally or intentionally; as I have committed all of these (types of sins). O Allah, forgive me for what I have already done, what I am yet to do, what I did publicly, what I did privately, and what You are more Knowledgeable of than me. You are the One who brings forward and You are the One who defers. You are All-Powerful over everything.","description":null,"benefit":null,"virtue":null,"hadith":"Abū Mūsā al-‘Ashʿarī (raḍiy Allāhu ‘anhu) reported from his father that the Messenger of Allah ﷺ would supplicate with [the above]. (Muslim 2719)","reference":"عَنْ أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى الْأَشْعَرِيِّ، عَنْ أَبِيهِ عَنِ النَّبِيِّ صلى الله عليه وسلم؛ أنه كان يدعو بهذا الدعاء “اللهم! اغفر لي خطيئتي وجهلي. وإسرافي في أمري. وما أنت أعلم به مني. اللهم! اغفر لي جدي وهزلي. وخطئي وعمدي. وكل ذلك عندي. اللَّهُمَّ! اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ. وما أسررت وما أعلنت. وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي. أَنْتَ الْمُقَدِّمُ وأنت المؤخر. وأنت على كل شيء قدير.\\n(صحيح مسلم ٢٧١٩)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"Protect Yourself From Anxiety, Laziness & Debt","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ ، وَأَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ ، وَأَعُوْذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.","transliteration":"Allāhumma innī aʿūdhu bika min-l-hammi wa-l-ḥazan, wa aʿūdhu bika min-l-ʿajzi wa-l-kasal, wa aʿūdhu bika min-l-jubni wa-l-bukhl, wa aʿūdhu bika min ghalabati-d-dayni wa qahri-r-rijāl.","translation":"O Allah, I seek Your protection from anxiety and grief. I seek Your protection from inability and laziness. I seek Your protection from cowardice and miserliness, and I seek Your protection from being overcome by debt and being overpowered by men.","description":null,"benefit":null,"virtue":"Abū Saʿīd al-Khudrī (raḍiy Allāhu ʿanhu) narrated that one day, the Messenger of Allah ﷺ entered the masjid. He saw a man from the Anṣār called Abū Umāmah (raḍiy Allāhu ʿanhu). He ﷺ asked, “What is the matter? Why are you sitting in the masjid when it is not the time for prayer?” He replied, “Never-ending worries and debts, O Messenger of Allah.” The Messenger of Allah ﷺ then asked, “Shall I not teach you words by which, when you say them, Allah will remove your worries, and settle your debts?” He replied, “Yes of course, O Messenger of Allah.” He ﷺ said, “Say in the morning and evening [the above].” Abū Umāmah (raḍiy Allāhu ʿanhu) said, “Then I did that, and Allah removed my worries and settled my debts.” (Abū Dāwūd 1555)","hadith":null,"reference":"عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: دَخَلَ رَسُولُ صَلَّى عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ مِنَ الْأَنْصَارِ، يُقَالُ لَهُ: أَبُو أُمَامَةَ، فَقَالَ: «يَا أُمَامَةَ، مَا لِي أَرَاكَ جَالِسًا فِي الْمَسْجِدِ فِي غَيْرِ وَقْتِ الصَّلَاةِ؟»، قَالَ: هُمُومٌ لَزِمَتْنِي، وَدُيُونٌ يَا رَسُولَ اللَّهِ، قَالَ: أَفَلَا أُعَلِّمُكَ كَلَامًا إِذَا أَنْتَ قُلْتَهُ أَذْهَبَ عز وجل هَمَّكَ، وَقَضَى عَنْكَ دَيْنَكَ؟، قَالَ: قُلْتُ: بَلَى، يَا رَسُولَ، قَالَ: ” قُلْ إِذَا أَصْبَحْتَ، وَإِذَا أَمْسَيْتَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَقَهْرِ الرِّجَالِ “، قَالَ: فَفَعَلْتُ ذَلِكَ، فَأَذْهَبَ اللَّهُ عز وجل هَمِّي، وَقَضَى عَنِّي دَيْنِي.\\n(سنن أبي داود ١٥٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"Duʿa of Prophet Adam ﷺ and Hawwa for Forgiveness","arabic":"رَبَّنَا ظَلَمْنَآ أَنْفُسَنَا وَإِنْ لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُوْنَنَّ مِنَ الْخٰسِرِيْنَ.","transliteration":"Rabbanā ẓalamnā anfusanā wa il-lam taghfir lanā wa tarḥamnā la-nakūnanna minal-khāsīrīn.","translation":"Our Lord, we have wronged ourselves. If You do not forgive us and have mercy upon us, we will surely be amongst the losers. (7:23)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"Forgiveness","arabic":"اَللّٰهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّيْ.","transliteration":"Allāhumma innaka ʿAffuwwun tuḥibb-ul-ʿafwa faʿfu ʿannī.","translation":"O Allah, You are the Ever-Pardoning, You love to pardon so pardon me.","description":null,"benefit":null,"virtue":null,"hadith":"ʿĀ’isha (raḍiy Allāhu ‘anhā) narrated: “I said: ‘O Messenger of Allah ﷺ, if I know when the Night of al-Qadr is, then what should I say in it?” He said: ‘Say: [the above].’” (Tirmidhī 3513)","reference":"عَنْ عَائِشَةَ قَالَتْ: قُلْتُ: يَا رَسُولَ اللهِ، أَرَأَيْتَ إِنْ عَلِمْتُ أَيَّ لَيْلَةٍ لَيْلَةَ الْقَدْرِ مَا أَقُولُ فِيهَا؟ قَالَ: قُولِي: اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي.\\n(سنن الترمذي ٣٥١٣)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"I said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"Duʿa of Prophet Musa ﷺ for Forgiveness","arabic":"أَنْتَ وَلِيُّنَا فَاغْفِرْ لَنَا وَارْحَمْنَا ۖ وَأَنْتَ خَيْرُ الْغَافِرِيْنَ.","transliteration":"Anta Walliyyunā fa-ghfir lanā war-ḥamnā wa Anta khayrul-ghāfirīn.","translation":"You are our Protector, so forgive us and have mercy upon us. You are the best of those who forgive. (7:155)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"Forgiveness, Anger and Trials","arabic":"اَللّٰهُمَّ رَبَّ مُحَمَّدٍ اغْفِرْ لِيْ ذَنْبِيْ ، وَأَذْهِبْ غَيْظَ قَلْبِيْ ، وَأَعِذْنِيْ مِنْ مُضِلَّاتِ الْفِتَنِ.\\nعَنِ الْقَاسِمِ بْنِ مُحَمَّدِ بْنِ أَبِي بَكْرٍ، قَالَ: كَانَتْ عَائِشَةُ رضي الله عنها إِذَا غَضِبَتْ عَرَكَ النَّبِيُّ صلى الله عليه وسلم بِأَنْفِهَا، ثُمَّ يَقُولُ: يَا عُوَيِّشُ، قُولِي: اللَّهُمَّ رَبَّ مُحَمَّدٍ، اغْفِرْ لِي ذَنْبِي، وَأَذْهِبْ غَيْظَ قَلْبِي، وَأَجِرْنِي مِنْ ‌مُضِلَّاتِ الْفِتَنِ.","transliteration":"Allāhumma Rabba Muḥammad, ighfir lī dhambī, wa adh-hib ghayẓa qalbī, wa aʿidhnī min muḍillāti-l-fitan.","translation":"O Allah, Lord of Muḥammad forgive my sins, remove the anger of my heart and protect me from misleading trials.","description":null,"benefit":null,"virtue":null,"hadith":"Muhammad b. Abī Bakr (raḥimahullāh) narrates that when ʿĀ’isha (raḍiy Allāhu ‘anhā) would become angry, the Messenger of Allah ﷺ would stroke her nose and then say (to her): “O ʿUwaysh! Say: [the above].”","reference":"(Ibn al-Sunnī 455)\\n(عمل اليوم والليلة لابن السني ٤٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"Duʿa of the Pious for Forgiveness & Protection From the Hell-fire","arabic":"رَبَّنَآ إِنَّنَآ اٰمَنَّا فَاغْفِرْ لَنَا ذُنُوْبَنَا وَقِنَا عَذَابَ النَّارِ.","transliteration":"Rabbanā in-nanā āmannā fa-ghfir lanā dhunūbanā wa qinā ʿadhāba-n-nār.","translation":"Our Lord, indeed we have believed, so forgive us our sins and protect us from the punishment of the Fire. (3:16)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"Forgiveness For All Types of Sins","arabic":"اَللّٰهُمَّ اغْفِرْ لِيْ ذَنْبِيْ كُلَّهُ ، دِقَّهُ وَجِلَّهُ ، وَأَوَّلَهُ وَآخِرَهُ ، وَعَلَانِيَتَهُ وَسِرَّهُ.","transliteration":"Allāhumma-ghfir lī dhambī kullah, diqqahū wa jillah, wa awwalahū wa ākhirah, wa ʿalāniyatahū wa sirrah.","translation":"O Allah, forgive for me all of my sins: the minor and major, the first and the last, the public and the private.","description":null,"benefit":null,"virtue":null,"hadith":"Abū Hurayrah (raḍiy Allāhu ‘anhu) narrates that the Messenger of Allah ﷺ would say [the above] in sujūd.” (Muslim 483)","reference":"عَنْ أَبِي هُرَيْرَةَ؛ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كان يقول في سجوده : الهم اغْفِرْ لِي ذَنْبِي كُلَّهُ. دِقَّهُ وَجِلَّهُ. وَأَوَّلَهُ وآخره. وعلانيته وسره.\\n(صحيح مسلم ٤٨٣)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"Duʿa of the Slaves of Allah for Forgiveness & Mercy","arabic":"رَبَّنَآ اٰمَنَّا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنْتَ خَيْرُ الرّٰحِمِيْنَ.","transliteration":"Rabbanā āmannā fa-ghfir lanā war-ḥamnā wa Anta khayru-r-rāḥimīn.","translation":"Our Lord, we have believed, so forgive us and have mercy upon us: You are the Best of those who are merciful. (23:109)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"Acknowledgement of Your Sins, Forgiveness & Mercy","arabic":"اَللّٰهُمَّ إِنّيْ ظَلَمْتُ نَفْسِيْ ظُلْمًا كَثِيْرًا ، وَلَا يَغْفِرُ الذُّنُوْبَ إِلَّا أَنْتَ ، فَاغْفِرْ لِيْ مَغْفِرَةً مِّنْ عِنْدِكَ ، وَارْحَمْنِيْ ، إِنَّكَ أَنْتَ الْغَفُوْرُ الرَّحِيْمُ.","transliteration":"Allāhumma innī ẓalamtu nafsī ẓulman kathīrā, wa lā yaghfiru-dh-dhunūba illā Ant, fa-ghfir lī maghfirata-m-min ʿindik, war-ḥamnī, innaka Anta-l-Ghafūru-r-Raḥīm.","translation":"O Allah, I have wronged myself greatly and no one forgives sins except You; so grant me forgiveness from You and have mercy upon me. You are the Most Forgiving, the Most Merciful.","description":null,"benefit":null,"virtue":null,"hadith":"Abū Bakr al-Ṣiddīq (raḍiy Allāhu ‘anhu) narrates: “I asked the Messenger of Allah ﷺ to teach me a du’ā so that I may invoke Allah with it in my salāh. He told me to say: [the above].” (Bukhārī 834)","reference":"عَنْ أَبِي بَكْرٍ الصِّدِّيقِ رضي الله عنه: أَنَّهُ قَالَ لِرَسُولِ اللهِ صلى الله عليه وسلم:عَلِّمْنِي دُعَاءً أَدْعُو بِهِ فِي صَلَاتِي. قَالَ: قُلِ: اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ.\\n(صحيح البخاري ٨٣٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"Duʿa for Forgiveness & Mercy","arabic":"رَبِّ اغْفِرْ وَارْحَمْ وَأَنْتَ خَيْرُ الرّٰحِمِيْنَ.","transliteration":"Rabbi-ghfir wa-rḥam wa Anta khayru-r-rāḥimīn.","translation":"My Lord, forgive and have mercy. You are the Best of those who are merciful. (23:118)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"Forgiveness, Mercy & Guidance","arabic":"اَللّٰهُمَّ اغْفِرْ لِيْ ، وَارْحَمْنِيْ ، وَعَافِنيْ ، وَاهْدِنِيْ وَارْزُقْنِيْ.","transliteration":"Allāhumma-ghfir lī, war-ḥamnī, wa ʿāfinī, wah-dinī war-zuqnī.","translation":"O Allah, forgive me, have mercy on me, grant me wellbeing, guide me and grant me sustenance.","description":null,"benefit":null,"virtue":null,"hadith":"ʿAbdullāh b. ʿAbbās (radiy Allāhū ‘anhumā): “The Prophet ﷺ used to say [the above] between the two prostrations.” (Abū Dāwūd 850)","reference":"عَنِ ابْنِ عَبَّاسٍ، قَالَ:كَانَ النَّبِيَّ صلى الله عليه وسلم يَقُولُ بَيْنَ السَّجْدَتَيْنِ: اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَعَافِنِي، وَاهْدِنِي، وَارْزُقْنِي. (سنن ابي داود ٨٥٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"A Deep Cleansing of Sins","arabic":"اَللّٰهُمَّ بَاعِدْ بَيْنِيْ وَبَيْنَ خَطَايَاىَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ ، اللَّهُمَّ نَقِّنِيْ مِنَ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الأَبْيَضُ مِنَ الدَّنَسِ ، اللَّهُمَّ اغْسِلْنِيْ مِنْ خَطَايَاىَ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ.","transliteration":"Allāhumma bāʿid baynī wa bayna khaṭāyāya kamā bāʿadta bayna-l-mashriqi wa-l-maghrib, Allāhumma naq-qinī min khaṭāyāya kamā yunaq-qa-th-thawbul-abyaḍu mina-d-danas, Allāhumma-ghsilnī min khaṭāyāya bil-māi’ wa-th-thalji wal-barad.","translation":"O Allah, distance me from my sins as You have distanced the East from the West. O Allah, purify me from my sins as white cloth is purified from dirt. O Allah, wash away my sins with water, snow and hail.","description":null,"benefit":null,"virtue":null,"hadith":"Abū Hurayrah (raḍiy Allāhu ‘anhu) narrates: “The Messenger of Allah ﷺ would pause between the opening takbīr and the recitation. said: ‘May my father and mother be sacrificed for you, the pause between the opening takbir and the recitation, what do you say?’ He replied: ‘I say [the above].’ (Bukhārī 744, Muslim 598)","reference":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ قَالَ: حَدَّثَنَا عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ قَالَ: حَدَّثَنَا عُمَارَةُ بْنُ الْقَعْقَاعِ قَالَ: حَدَّثَنَا أَبُو زُرْعَةَ قَالَ: حَدَّثَنَا أبو هريرة قال كان الرسول صلى الله عليه وسلم يَسْكُتُ بَيْنَ التَّكْبِيرِ وَبَيْنَ الْقِرَاءَةِ إِسْكَاتَةً – قَالَ أَحْسِبُهُ قَالَ هُنَيَّةً – فقلت: بأبي وأمي يارسول الله، إسكاتك بين التكبير والقراءة، ماتقول؟ قَالَ: أَقُولُ: اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ، كَمَا ‌بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنَ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْ خَطَايَايَ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ. (صحيح البخاري ٧٤٤)\\nعَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ رَسُولُ اللهِ صلى الله عليه وسلم إِذَا كَبَّرَ فِي الصَّلَاةِ سَكَتَ هُنَيَّةً قَبْلَ أَنْ يَقْرَأَ فَقُلْتُ: يَا رَسُولَ اللهِ، بِأَبِي أَنْتَ وَأُمِّي، أَرَأَيْتَ سُكُوتَكَ بَيْنَ التَّكْبِيرِ وَالْقِرَاءَةِ؟ مَا تَقُولُ؟ قَالَ: أَقُولُ: اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنْ خَطَايَايَ كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْنِي مِنْ خَطَايَايَ بِالثَّلْجِ وَالْمَاءِ وَالْبَرَدِ.\\n(صحيح مسلم ٥٩٨)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"When One Is Afraid of People #6","arabic":"اَللّٰهُمَّ اسْتُرْ عَوْرَاتِنَا وَاٰمِنْ رَوْعَاتِنَا","transliteration":"Allāhumma-stur ‘awrātinā wa āmin raw‘ātinā.","translation":"O Allah, conceal our faults and calm our fears.","description":null,"benefit":null,"virtue":null,"hadith":"Abū Sa‘īd al-Khuḍrī (raḍiy Allāhu ‘anhu) narrates: “We (the Companions) said on the Day of Khandaq (Trenches): ‘O Messenger of Allah, is there anything we can say? For the hearts have reached the throats (out of fear).’ He ﷺ replied: ‘Yes! (Say) [the above].’ Abū Sa‘īd al-Khuḍrī says: ‘Allah, Mighty and Majestic destroyed the faces of the enemy with wind and Allah made them face defeat through wind.’” (Ahmad 10996)","reference":"حَدَّثَنَا أَبُو عَامِرٍ، حَدَّثَنَا الزُّبَيْرُ بْنُ عَبْدِ اللهِ، حَدَّثَنِي رُبَيْحُ بْنُ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنْ أَبِيهِ قَالَ: قُلْنَا يَوْمَ الْخَنْدَقِ: يَا رَسُولَ اللهِ، هَلْ مِنْ شَيْءٍ نَقُولُهُ فَقَدْ بَلَغَتِ الْقُلُوبُ الْحَنَاجِرَ؟ قَالَ نَعَمْ، اللهُمَّ اسْتُرْ ‌عَوْرَاتِنَا، وَآمِنْ رَوْعَاتِنَا قَالَ: فَضَرَبَ اللهُ عز وجل وُجُوهَ أَعْدَائِهِ بِالرِّيحِ، فَهَزَمَهُمُ اللهُ عز وجل بِالرِّيحِ. (مسند احمد ١٠٩٩٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"Entrust All Your Matters to Allah","arabic":"يَا حَيُّ يَا قَيُّوْمُ ، بِرَحْمَتِكَ أَسْتَغِيْثُ ، أَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ ، وَلَا تَكِلْنِيْ إِلَىٰ نَفْسِيْ طَرْفَةَ عَيْنٍ.\\nأخبرنَا عبد الرَّحْمَن بن مُحَمَّد بن سَلام حَدثنَا زيد بن الْحباب أَخْبرنِي عُثْمَان بن موهب الْهَاشِمِي سَمِعت أنس بن مَالك يَقُول قَالَ النَّبِي صلى الله عليه وسلم لفاطمة مَا يمنعك أَن سَمْعِي مَا أوصيك بِهِ أَو تقولي إِذا أَصبَحت وَإِذا أمسيت يَا حَيّ يَا قيوم بِرَحْمَتك أستغيث أصلح لي شأني كلَّه وَلَا تَكِلنِي إِلَى نَفسِي طرفَة عين.","transliteration":"Yā Ḥayyu yā Qayyūm, bi-raḥmatika astaghīth, aṣliḥ lī sha’nī kullah, wa lā takilnī ilā nafsī ṭarfata ʿayn.","translation":"O The Ever Living, The Sustainer of all. ; I seek assistance through Your mercy. Rectify all of my affairs and do not entrust me to myself for the blink of an eye.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ʿanhu) narrates that the Prophet ﷺ said to Fāṭimah (raḍiy Allāhu ʿanhā), “What is preventing you from (doing) what I am advising you; that you say [the above] in the morning and evening?” (Nasā’ī in ʿAmal al-Yawm wa-l-Laylah 570)","reference":"(عمل اليوم والليلة للنسائي ٥٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"},{"title":"Atonement for Hurting Another Muslim","arabic":"اَللّٰهُمَّ فَأَيُّمَا عَبْدٍ مُّؤْمِنٍ سَبَبْتُهُ فَاجْعَلْ ذٰلِكَ لَهُ قُرْبَةً إِلَيْكَ يَوْمَ الْقِيَامَةِ.","transliteration":"Allāhumma fa-ayyumā ʿabdi-m-mu’minin sababtuhū fa-jʿal dhālika lahū qurbatan ilayka yawma-l-qiyāmah.","translation":"O Allah, any believing servant whom I have cursed, make that a source of nearness to You on the Day of Judgement.","description":null,"benefit":null,"virtue":null,"hadith":"Abū Hurayrah (raḍiy Allāhu ‘anhu) narrates that he heard the Messenger of Allah ﷺ say [the above].(Bukhārī 6000)","reference":"In another narration Abū Hurayrah (raḍiy Allāhu ‘anhu) narrates that the Messenger of Allah ﷺ said, “O Allah, I am only a human being. Whenever I scold, curse, or punish a Muslim man, then turn it into purification and mercy for him.” (Muslim 2601)\\nعَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم:اللَّهُمَّ إِنَّمَا أَنَا بَشَرٌ، فَأَيُّمَا رَجُلٍ مِنَ الْمُسْلِمِينَ سَبَبْتُهُ، أَوْ لَعَنْتُهُ، أَوْ جَلَدْتُهُ فَاجْعَلْهَا لَهُ زَكَاةً وَرَحْمَةً.\\n(صحيح مسلم ٢٦٠١)\\nعَنِ ابْنِ شِهَابٍ قَالَ: أَخْبَرَنِي سَعِيدُ بْنُ المسيَّب، عَنْ أَبِي هُرَيْرَةَ رضي الله عنه أَنَّهُ سَمِعَ النَّبِيَّ صلى الله عليه وسلم يَقُولُ: اللَّهُمَّ فَأَيُّمَا مُؤْمِنٍ سَبَبْتُهُ، فَاجْعَلْ ذَلِكَ لَهُ قُرْبَةً إِلَيْكَ يَوْمَ القيامة. (صحيح البخاري ٦٠٠٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/guilty/"}]},{"feeling":"Happy","slug":"happy","url":"https://allahuakbarofficial.com/happy/","items_count":3,"duas":[{"title":"When Something Pleases You #1","arabic":"اَلْحَمْدُ لِلّٰهِ الَّذِيْ بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ","transliteration":"Al-ḥamdu li-llāh-ladhī bi-niʿmatihī tattimmu-ṣ-ṣāliḥāt.","translation":"All praise is for Allah — through whose blessing righteous actions are accomplished.","description":null,"benefit":null,"virtue":null,"hadith":"When the Messenger of Allah ﷺ saw something pleasing, he used to say [the above]. (Ibn Mājah 3803, Ibn al-Sunnī 378)","reference":"عَنْ عَائِشَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِذَا رَأَى مَا يُحِبُّ قَالَ: الْحَمْدُ لِلَّهِ الَّذِي بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ، وَإِذَا رَأَى مَا يَكْرَهُ قَالَ: الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ. (سنن ابن ماجه ٣٨٠٣)\\nعَنْ عَائِشَةَ، رضي الله عنها قَالَتْ: كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِذَا رَأَى مَا يُحِبُّ قَالَ:الْحَمْدُ لِلَّهِ الَّذِي بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ، وَإِذَا رَأَى مَا يَكْرَهُ قَالَ: الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ.\\n(عمل اليوم والليلة لابن السني ٣٧٨)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/happy/"},{"title":"Duʿa of Prophet Yusuf ﷺ for A Good Ending","arabic":"-اَللّٰهُمَّ يَا- فَاطِرَ السَّمٰوَاتِ وَالْأَرْضِ ، أَنْتَ وَلِـيِّيْ فِي الدُّنْيَا وَالْآخِرَةِ ، تَوَفَّنِيْ مُسْلِمًا وَّأَلْحِقْنِيْ بِالصَّالِحِيْنَ.","transliteration":"(Allāhumma yā) Fāṭira-s-samāwāti wa-l-arḍi Anta waliy-yi fi-d-dunyā wal-ākhirah, tawaffanī Muslimaw-wa alḥiqnī bi-ṣ-ṣāliḥīn.","translation":"(O Allah), Originator of the heavens and the earth, You are my Protector in this world and in the Hereafter. Make me die a Muslim and join me with the righteous. (12:101)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/happy/"},{"title":"Protection from Allah’s Anger & Removal of Blessings","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ ، وَتَحَوُّلِ عَافِيَتِكَ ، وَفُجَاءَةِ نِقْمَتِكَ ، وَجَمِيْعِ سَخَطِكَ.\\nعَنِ ابْنِ عُمَرَ قَالَ:كَانَ مِنْ دُعَاءِ رَسُولِ اللهِ صلى الله عليه وسلم: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ، وَتَحْوِيلِ عَافِيَتِكَ، وَفُجَاءَةِ نِقْمَتِكَ، وَجَمِيعِ سَخَطِكَ.","transliteration":"Allāhumma innī aʿūdhu bika min zawāli niʿmatik, wa taḥawwuli ʿāfiyatik, wa fujā’ati niqmatik, wa jamīʿi sakhaṭik.","translation":"O Allah, I seek Your protection from the loss of Your favours, the removal of Your complete protection, Your sudden punishment and all that which may incur Your displeasure.","description":null,"benefit":null,"virtue":null,"hadith":"ʿAbdullah b. ʿUmar (radiy Allāhū ‘anhumā) reported that from the supplication of the Messenger of Allah ﷺ was [the above]. (Muslim 2739, Abū Dāwūd 1545)","reference":"عَنْ عَبْدِ الله بن عمر، قال كان من دعاء رَسُولُ اللَّهِ صلى الله عليه وسلم “اللَّهُمَّ! إني أعوذ بك من زوال نعمتك، وتحول عافيتك، وفجاءة نقمتك، وجميع سخطك.\\n(صحيح مسلم ٢٧٣٩)\\n(سنن ابي داود ١٥٤٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/happy/"}]},{"feeling":"Hurt","slug":"hurt","url":"https://allahuakbarofficial.com/hurt/","items_count":15,"duas":[{"title":"When Difficulties Make You Yearn for Death","arabic":"اَللّٰهُمَّ أَحْيِنِيْ مَا كَانَتِ الْحَيَاةُ خَيْرًا لِّيْ ، وَتَوَفَّنِيْ إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِّيْ","transliteration":"Allāhumma aḥyinī mā kānati-l-ḥayātu khayral-lī, wa tawaffanī idhā kānati-l-wafātu khayral-lī.","translation":"O Allah, let me live as long as life is better for me; and give me death when death is better for me.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ said: “None of you should wish for death because of a difficulty that befalls him. Rather he should say [the above].” (Bukhārī 5671, Muslim 2680)","reference":"عَنْ أَنَسِ بْنِ مَالِكٍ رضي الله عنه، قَالَ النَّبِيُّ صلى الله عليه وسلم: «لَا يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ مِنْ ضُرٍّ أَصَابَهُ، فَإِنْ كَانَ لَا بُدَّ فَاعِلًا فَلْيَقُلِ: اللَّهُمَّ أَحْيِنِي مَا كَانَتِ الْحَيَاةُ خَيْرًا لِي، وَتَوَفَّنِي إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِي. (صحيح البخاري ٥٦٧١)\\nعَنْ أَنَسٍ، قَالَ قَالَ رسول الله صلى الله عليه وسلم لا يتمنين أحدكم الموت لضر نزل به. فإن كان لابد متمنيا فليقل: اللهم! أحيني ما كانت الحياة خيرا لي، وتوفني إذا كانت الوفاة خيرا لي.\\n(صحيح مسلم ٢٦٨٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hurt/"},{"title":"Protect Yourself From Anxiety, Laziness & Debt","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ ، وَأَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ ، وَأَعُوْذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.","transliteration":"Allāhumma innī aʿūdhu bika min-l-hammi wa-l-ḥazan, wa aʿūdhu bika min-l-ʿajzi wa-l-kasal, wa aʿūdhu bika min-l-jubni wa-l-bukhl, wa aʿūdhu bika min ghalabati-d-dayni wa qahri-r-rijāl.","translation":"O Allah, I seek Your protection from anxiety and grief. I seek Your protection from inability and laziness. I seek Your protection from cowardice and miserliness, and I seek Your protection from being overcome by debt and being overpowered by men.","description":null,"benefit":null,"virtue":"Abū Saʿīd al-Khudrī (raḍiy Allāhu ʿanhu) narrated that one day, the Messenger of Allah ﷺ entered the masjid. He saw a man from the Anṣār called Abū Umāmah (raḍiy Allāhu ʿanhu). He ﷺ asked, “What is the matter? Why are you sitting in the masjid when it is not the time for prayer?” He replied, “Never-ending worries and debts, O Messenger of Allah.” The Messenger of Allah ﷺ then asked, “Shall I not teach you words by which, when you say them, Allah will remove your worries, and settle your debts?” He replied, “Yes of course, O Messenger of Allah.” He ﷺ said, “Say in the morning and evening [the above].” Abū Umāmah (raḍiy Allāhu ʿanhu) said, “Then I did that, and Allah removed my worries and settled my debts.” (Abū Dāwūd 1555)","hadith":null,"reference":"عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: دَخَلَ رَسُولُ صَلَّى عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ مِنَ الْأَنْصَارِ، يُقَالُ لَهُ: أَبُو أُمَامَةَ، فَقَالَ: «يَا أُمَامَةَ، مَا لِي أَرَاكَ جَالِسًا فِي الْمَسْجِدِ فِي غَيْرِ وَقْتِ الصَّلَاةِ؟»، قَالَ: هُمُومٌ لَزِمَتْنِي، وَدُيُونٌ يَا رَسُولَ اللَّهِ، قَالَ: أَفَلَا أُعَلِّمُكَ كَلَامًا إِذَا أَنْتَ قُلْتَهُ أَذْهَبَ عز وجل هَمَّكَ، وَقَضَى عَنْكَ دَيْنَكَ؟، قَالَ: قُلْتُ: بَلَى، يَا رَسُولَ، قَالَ: ” قُلْ إِذَا أَصْبَحْتَ، وَإِذَا أَمْسَيْتَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَقَهْرِ الرِّجَالِ “، قَالَ: فَفَعَلْتُ ذَلِكَ، فَأَذْهَبَ اللَّهُ عز وجل هَمِّي، وَقَضَى عَنِّي دَيْنِي.\\n(سنن أبي داود ١٥٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hurt/"},{"title":"When Struck by a Calamity","arabic":"إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ رَاجِعُوْنَ ، اَللّٰهُمَّ اْجُرْنِيْ فِيْ مُصِيْبَتِيْ ، وَأَخْلِفْ لِيْ خَيْرًا مِّنْهَا","transliteration":"Innā lillāhi wa innā ilayhi rājiʿūn, Allāhumma-‘jurnī fī muṣībatī, wa akhlif lī khayram-minhā.","translation":"Indeed, to Allah we belong and to Him we will return. O Allah, recompense me for my affliction and replace it for me with something better.","description":null,"benefit":null,"virtue":"Umm Salamah (raḍiy Allāhu ʿanhā) said: I heard the Messenger of Allah ﷺ say, “There is no Muslim who is afflicted with a calamity, and then says what Allah has commanded him [the above duʿā’], except that Allah will recompense him with something better than it.” She says: “When Abū Salamah (her first husband) passed away, I said, ‘Which Muslim is better than Abū Salamah – the first household to migrate to the Messenger of Allah?’ I then said [the above], and Allah recompensed me (by marrying me to) the Messenger of Allah ﷺ.” (Muslim 918)","hadith":null,"reference":"وحدثنا أبو بكر بن أبي شيبة. حدثنا أَبُو أُسَامَةَ عَنْ سَعْدِ بْنِ سَعِيدٍ. قَالَ: أَخْبَرَنِي عُمَرُ بْنُ كَثِيرِ بْنِ أَفْلَحَ. قَالَ: سَمِعْتُ ابْنَ سَفِينَةَ يُحَدِّثُ؛ أَنَّهُ سَمِعَ أُمِّ سَلَمَةَ ، أَنَّهَا قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَقُولُ: مَا مِنْ مُسْلِمٍ تُصِيبُهُ مُصِيبَةٌ فَيَقُولُ مَا أَمَرَهُ اللهُ: إِنَّا لِلهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرًا مِنْهَا، إِلَّا أَخْلَفَ اللهُ لَهُ خَيْرًا مِنْهَا، قَالَتْ: فَلَمَّا مَاتَ أَبُو سَلَمَةَ قُلْتُ: أَيُّ الْمُسْلِمِينَ خَيْرٌ مِنْ أَبِي سَلَمَةَ؟ أَوَّلُ بَيْتٍ هَاجَرَ إِلَى رَسُولِ اللهِ صلى الله عليه وسلم، ثُمَّ إِنِّي قُلْتُهَا، فَأَخْلَفَ اللهُ لِي رَسُولَ اللهِ صلى الله عليه وسلم، قَالَتْ: أَرْسَلَ إِلَيَّ رَسُولُ اللهِ صلى الله عليه وسلم حَاطِبَ بْنَ أَبِي بَلْتَعَةَ يَخْطُبُنِي لَهُ، فَقُلْتُ: إِنَّ لِي بِنْتًا وَأَنَا غَيُورٌ، فَقَالَ: أَمَّا ابْنَتُهَا فَنَدْعُو اللهَ أَنْ يُغْنِيَهَا عَنْهَا، وَأَدْعُو اللهَ أَنْ يُذْهِبَ بِالْغَيْرَةِ. (صحيح مسلم ٩١٨)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"I said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hurt/"},{"title":"Attain Well-being in This World and the Hereafter","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِيْ دِيْنِيْ وَدُنْيَايَ وَأَهْلِيْ وَمَالِيْ ، اَللّٰهُمَّ اسْتُرْ عَوْرَاتِيْ وَآمِنْ رَّوْعَاتِيْ ، اَللّٰهُمَّ احْفَظْنِيْ مِنْ بَيْنِ يَدَيَّ ، وَمِنْ خَلْفِيْ ، وَعَنْ يَّمِيْنِيْ ، وَعَنْ شِمَالِيْ ، وَمِنْ فَوْقِيْ ، وَأَعُوْذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِيْ.","transliteration":"Allāhumma innī as’aluka-l-ʿāfiyata fi-d-dunyā wa-l-ākhirah. Allāhumma innī as’aluka-l-ʿafwa wa-l-ʿāfiyata fī dīnī wa dunyāya wa ahlī wa mālī, Allāhumma-stur ʿawrātī wa āmi-r-rawʿātī. Allāhumma-ḥfaẓnī mim bayni yadayya wa min khalfī, wa ʿay-yamīnī wa ʿan shimālī wa min fawqī, wa aʿūdhu bi-ʿaẓamatika an ughtāla min taḥtī.","translation":"O Allah, I ask You for well-being in this world and the next. O Allah, I ask You for forgiveness and well-being in my religion, in my worldly affairs, in my family and in my wealth. O Allah, conceal my faults and calm my fears. O Allah, guard me from in front of me and behind me, from my right, and from my left, and from above me. I seek protection in Your Greatness from being unexpectedly destroyed from beneath me.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “Ask Allah for forgiveness and well-being (‘āfiyah). Indeed, after conviction (yaqīn), no one has been granted anything better than well-being.” (Tirmidhī)","hadith":"ʿAbdullāh b. ʿUmar (raḍiy Allāhu ʿanhumā) narrated: “The Messenger of Allah ﷺ never failed to say these words in the morning and in the evening.” (Abū Dāwūd 5074)","reference":"عَنْ جُبَيْرِ بْنِ أَبِي سُلَيْمَانَ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ، قَالَ: سَمِعْتُ ابْنَ عُمَرَ، يَقُولُ: لَمْ يَكُنْ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَعُ هَؤُلَاءِ الدَّعَوَاتِ، حِينَ يُمْسِي، وَحِينَ يُصْبِحُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَتِي، وَقَالَ عُثْمَانُ: عَوْرَاتِي وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي.(سنن أبي داود ٥٠٧٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hurt/"},{"title":"Grief & Anxiety #1","arabic":"اَللّٰهُمَّ إِنِّيْ عَبْدُكَ ، وَابْنُ عَبْدِكَ ، وَابْنُ أَمَتِكَ ، نَاصِيَتِيْ بِيَدِكَ ، مَاضٍ فِيَّ حُكْمُكَ ، عَدْلٌ فِيَّ قَضَاؤُكَ ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ ، سَمَّيْتَ بِهِ نَفْسَكَ ، أَوْ عَلَّمْتَهُ أَحَدًا مِّنْ خَلْقِكَ ، أَوْ أَنْزَلْتَهُ فِيْ كِتَابِكَ ، أَوِ اسْتَأْثَرْتَ بِهِ فِيْ عِلْمِ الْغَيْبِ عِنْدَكَ ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيْعَ قَلْبِيْ ، وَنُوْرَ صَدْرِيْ ، وَجَلَاءَ حُزْنِيْ ، وَذَهَابَ هَمِّيْ","transliteration":"Allāhumma innī ʿabduk, wa-bnu ʿabdik, wa-bnu amatik, nāṣiyatī bi-yadik, māḍin fiyya ḥukmuk, ʿadlun fiyya qaḍā’uk, as’aluka bi-kulli-smin huwa lak, sammayta bihī nafsak, aw ʿallamtahū aḥadam-min khalqik, aw anzaltahū fī kitābik, awi-sta’tharta bihī fī ʿilmi-l-ghaybi ʿindak, an tajʿala-l-Qur’āna rabīʿa qalbī, wa nūra ṣadrī, wa jalā’a ḥuznī, wa dha-hāba hammī.","translation":"O Allah, I am Your servant and the son of Your male servant and the son of Your female servant. My forehead is in Your Hand (i.e. you have control over me). I am subject to Your judgement and Your decree concerning me is just. I ask You – by every name that is Yours, by which You have named Yourself, or taught any one of Your creation, or revealed in Your Book, or kept unto Yourself in the knowledge of the unseen that is with You – to make the Qur’ān the spring of my heart, the light of my chest, the banisher of my grief and the reliever of my anxiety.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “There is no one who is stricken with grief and anxiety, and then says [the above] — except that Allah will remove his grief and anxiety, and will give him joy instead.” The Companions asked, ‘O Messenger of Allah, should we not learn these words?’ He ﷺ replied, ‘Certainly! The one who hears them should learn them.’” (Ahmad 3712)","hadith":null,"reference":"عَنْ عَبْدِ اللهِ، قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: مَا أَصَابَ أَحَدًا قَطُّ هَمٌّ وَلَا حَزَنٌ، فَقَالَ: اللهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجِلَاءَ حُزْنِي، وَذَهَابَ هَمِّي، إِلَّا أَذْهَبَ اللهُ هَمَّهُ وَحُزْنَهُ، وَأَبْدَلَهُ مَكَانَهُ فَرَحًا، قَالَ: فَقِيلَ: يَا رَسُولَ اللهِ، أَلَا نَتَعَلَّمُهَا؟ فَقَالَ: بَلَى، يَنْبَغِي لِمَنْ سَمِعَهَا أَنْ يَتَعَلَّمَهَا. (مسند أحمد ٣٧١٢)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hurt/"},{"title":"Grief & Anxiety #2","arabic":"لَا إِلٰهَ إِلَّا اللّٰهُ الْعَظِيْمُ الْحَلِيْمُ ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ الْعَرْشِ الْعَظِيْمِ ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ السَّمٰـوٰتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيْمِ\\nعَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ:كَانَ النَّبِيُّ صلى الله عليه وسلم يَدْعُو عِنْدَ الْكَرْبِ: لَا إِلَهَ إِلَّا اللهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللهُ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ رَبُّ الْعَرْشِ الْعَظِيمِ.","transliteration":"Lā ilāha illā-llāhu-l-ʿĀẓīmu-l-Ḥalīm, lā ilāha illā-llāhu Rabbu-l-ʿĀrshi-l-ʿAẓīm, lā ilāha illā-llāhu Rabbu-s-samāwāti wa Rabbu-l-arḍi wa Rabbu-l-ʿĀrshi-l-karīm.","translation":"There is no god worthy of worship except Allah — the Supreme, the Forbearing. There is no god worthy of worship except Allah — Lord of the Magnificent Throne. There is no god worthy of worship except Allah — Lord of the heavens, Lord of the earth, and Lord of the Noble Throne.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ used to supplicate with [the above] in times of distress. (Bukhārī 6345, Muslim 2730)","reference":"(صحيح البخاري ٦٣٤٥)\\nعَنِ ابْنِ عَبَّاسٍ؛ أَنَّ نبي الله صلى الله عليه وسلم كان يقول عند الكرب “لا إله إلا الله العظيم الحليم. لا إله إلا الله رب العرش العظيم. لا إله إلا الله رب السماوات ورب الأرض ورب العرش الكريم. (صحيح مسلم ٢٧٣٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hurt/"},{"title":"Allah Will Suffice You in Everything","arabic":"حَسْبِيَ اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ ، عَلَيْهِ تَوَكَّلْتُ ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ.","transliteration":"Ḥasbiya-Allāhu lā ilāha illā Huwa, ʿalayhi tawakkalt, wa Huwa Rabbu-l-ʿArshi-l-ʿaẓīm.","translation":"Repeat. x7","description":null,"benefit":null,"virtue":"Abū al-Dardā’ (raḍiy Allāhu ʿanhu) narrates from the Messenger of Allah ﷺ that he said: “Whoever recites [the above] seven times in the morning and in the evening, Allah will suffice him in everything that concerns him in matters of this world and the next.”","hadith":null,"reference":"(Ibn al-Sunnī 71)\\nعَنْ أَبِي الدَّرْدَاءِ، رضي الله عنه، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ: مَنْ قَالَ فِي كُلِّ يَوْمٍ حِينَ يُصْبِحُ وَحِينَ يُمْسِي: حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ، سَبْعَ مَرَّاتٍ، كَفَاهُ اللَّهُ عز وجل هَمَّهُ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ. (عمل اليوم والليلة لابن السني ٧١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":7,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hurt/"},{"title":"For Difficult Times: All Your Prayers Answered","arabic":"لَآ إِلٰهَ إِلَّآ أَنْتَ سُبْحَانَكَ إِنِّيْ كُنْتُ مِنَ الظَّالِمِيْنَ","transliteration":"Lā ilāha illā Anta subḥānaka innī kuntu mina-ẓ-ẓālimīn.","translation":"There is no god worthy of worship except You; You are free from all imperfection. Indeed, I have been of the wrongdoers. (21:87)","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “The supplication of Dhun-Nūn (Prophet Yūnus) when he supplicated in the belly of the whale was: [the above]. No Muslim man ever supplicates with [the above] except that Allah answers his supplications.” (Tirmidhī 3505)","hadith":null,"reference":"Saʿd b. Abī Waqqāṣ said: We were sat in the company of the Messenger of Allah ﷺ. He ﷺ said, “Shall I not inform you of a supplication which will remove the calamity or a worldy trial which befalls a person from amongst you?” It was said, “Of course.” He said, “The supplication of Dhun-Nūn: [the above].”  (See Nasā‘ī in ʿAmal al-Yawm wa al-Laylah 655)\\nعَنْ أَبِي الدَّرْدَاءِ، رضي الله عنه، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ: مَنْ قَالَ فِي كُلِّ يَوْمٍ حِينَ يُصْبِحُ وَحِينَ يُمْسِي: حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ، سَبْعَ مَرَّاتٍ، كَفَاهُ اللَّهُ عز وجل هَمَّهُ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ. (عمل اليوم والليلة لابن السني ٧١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Waqqāṣ said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hurt/"},{"title":"When One Is Distressed","arabic":"اَللّٰهُمَّ رَحْمَتَكَ أَرْجُوْ فَلَا تَكِلْنِيْ إِلٰى نَفْسِيْ طَرْفَةَ عَيْنٍ ، وَأَصْلِحْ لِي شَأْنِيْ كُلَّهُ ، لَا إِلٰهَ إِلَّا أَنْتَ","transliteration":"Allāhumma raḥmataka arjū fa-lā takilnī ilā nafsī ṭarfata ʿayn, wa aṣliḥ lī sha’nī kullah, lā ilāha illā Ant.","translation":"O Allah! It is certainly Your Mercy what I hope for, so do not entrust me to myself for the blink of an eye; and rectify all of my affairs. There is no god worthy of worship except You.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ said: “The supplications of the distressed person are [the above].” (Abū Dāwūd 5090)","reference":"عَنْ جَعْفَرِ بْنِ مَيْمُونٍ قَالَ: حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ «أَنَّهُ قَالَ لِأَبِيهِ : يَا أَبَتِ إِنِّي أَسْمَعُكَ تَدْعُو كُلَّ غَدَاةٍ: اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَدْعُو بِهِنَّ، فَأَنَا أُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ قَالَ عَبَّاسٌ فِيهِ: وَتَقُولُ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَتَدْعُو بِهِنَّ، فَأُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ. قَالَ: وَقَالَ رَسُولُ اللهِ صلى الله عليه وسلم: دَعَوَاتُ الْمَكْرُوبِ اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا ‌تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ.\\n(سنن ابي داود ٥٠٩٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hurt/"},{"title":"Entrust All Your Matters to Allah","arabic":"يَا حَيُّ يَا قَيُّوْمُ ، بِرَحْمَتِكَ أَسْتَغِيْثُ ، أَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ ، وَلَا تَكِلْنِيْ إِلَىٰ نَفْسِيْ طَرْفَةَ عَيْنٍ.\\nأخبرنَا عبد الرَّحْمَن بن مُحَمَّد بن سَلام حَدثنَا زيد بن الْحباب أَخْبرنِي عُثْمَان بن موهب الْهَاشِمِي سَمِعت أنس بن مَالك يَقُول قَالَ النَّبِي صلى الله عليه وسلم لفاطمة مَا يمنعك أَن سَمْعِي مَا أوصيك بِهِ أَو تقولي إِذا أَصبَحت وَإِذا أمسيت يَا حَيّ يَا قيوم بِرَحْمَتك أستغيث أصلح لي شأني كلَّه وَلَا تَكِلنِي إِلَى نَفسِي طرفَة عين.","transliteration":"Yā Ḥayyu yā Qayyūm, bi-raḥmatika astaghīth, aṣliḥ lī sha’nī kullah, wa lā takilnī ilā nafsī ṭarfata ʿayn.","translation":"O The Ever Living, The Sustainer of all. ; I seek assistance through Your mercy. Rectify all of my affairs and do not entrust me to myself for the blink of an eye.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ʿanhu) narrates that the Prophet ﷺ said to Fāṭimah (raḍiy Allāhu ʿanhā), “What is preventing you from (doing) what I am advising you; that you say [the above] in the morning and evening?” (Nasā’ī in ʿAmal al-Yawm wa-l-Laylah 570)","reference":"(عمل اليوم والليلة للنسائي ٥٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hurt/"},{"title":"A Comprehensive Duʿa","arabic":"اَللّٰهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا يَحُوْلُ بِهِ بَيْنَنَا وَبَيْنَ مَعَاصِيْكَ ، وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ ، وَمِنَ الْيَقِيْنِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مَصَائِبَ الدُّنْيَا ، اَللّٰهُمَّ مَتِّعْنَا بِأَسْمَاعِنَا ، وَأَبْصَارِنَا ، وَقُوَّتِنَا مَا أَحْيَيْتَنَا ، وَاجْعَلْهُ الْوَارِثَ مِنَّا ، وَاجْعَلْ ثَأْرَنَا عَلَىٰ مَنْ ظَلَمَنَا ، وَانْصُرْنَا عَلَىٰ مَنْ عَادَانَا ، وَلَا تَجْعَلْ مُصِيْبَتَنَا فِيْ دِيْنِنَا ، وَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا ، وَلَا مَبْلَغَ عِلْمِنَا ، وَلَا تُسَلِّطْ عَلَيْنَا مَنْ لَّا يَرْحَمُنَا.","transliteration":"Allāhumma-q-sim lanā min khashyatika mā yaḥūlu bihī baynanā wa bayna maʿāṣīk, wa min ṭāʿatika mā tuballighunā bihī jannatak, wa mina-l-yaqīni mā tuhawwinu bihī ʿalaynā maṣā’iba-d-dunyā, allāhumma mattiʿnā bi asmāʿinā, wa abṣārinā, wa quwwātinā mā aḥyaytanā, wa-j-ʿalhu-l-wāritha minnā, wa-j-ʿal tha’ranā ʿalā man ẓalamanā, wa-n-ṣurnā ʿalā man ʿādānā, wa lā tajʿal muṣībatanā fī dīninā, wa lā tajʿali-d-dunyā akbara hamminā, wa lā mablagha ʿilminā, wa lā tusalliṭ ʿalaynā mal-lā yarḥamunā.","translation":"O Allah, apportion for us enough fear and awe of You to prevent us from sinning against You, and enough obedience to You to make us reach Your Paradise, and enough certainty to make the difficulties of this world easy for us. O Allah, let us enjoy our hearing and sight and strength as long as You allow us to live, and make it an inheritance for us. Let our retaliation be upon those who have wronged us, and help us against those who harbour enmity towards us. Let not our afflictions be in our religion. Do not make the world our biggest concern or the full extent of our knowledge, and do not give power over us to anyone who will not have mercy on us.","description":null,"benefit":null,"virtue":null,"hadith":"‘Abdullāh b. ‘Umar (radiy Allāhū ‘anhumā) said: “Rarely would the Messenger of Allah ﷺ rise from a gathering without supplicating for his companions with [the above].” (Tirmidhī 3502)","reference":"عَنْ خَالِدِ بْنِ أَبِي عِمْرَانَ، أَنَّ ابْنَ عُمَرَ، قَالَ: قَلَّمَا كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَقُومُ مِنْ مَجْلِسٍ حَتَّى يَدْعُوَ بِهَؤُلَاءِ الدَّعَوَاتِ لِأَصْحَابِهِ: «اللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا يَحُولُ بَيْنَنَا وَبَيْنَ مَعَاصِيكَ، وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ، وَمِنَ اليَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مُصِيبَاتِ الدُّنْيَا، وَمَتِّعْنَا بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّتِنَا مَا أَحْيَيْتَنَا، وَاجْعَلْهُ الوَارِثَ مِنَّا، وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا، وَانْصُرْنَا عَلَى مَنْ عَادَانَا، وَلَا تَجْعَلْ مُصِيبَتَنَا فِي دِينِنَا، وَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا وَلَا مَبْلَغَ عِلْمِنَا، وَلَا تُسَلِّطْ عَلَيْنَا مَنْ لَا يَرْحَمُنَا. (سنن الترمذي ٣٥٠٢)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hurt/"},{"title":"Protection from Evil Traits & Endings","arabic":"اَللّٰهُمَّ إِنّيْ أَعُوْذُ بِكَ مِنَ الْبُخْلِ ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ ، وَأَعُوْذُ بِكَ أَنْ أُرَدَّ إِلَىٰ أَرْذَلِ الْعُمُرِ ، وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا ، وَأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ.","transliteration":"Allāhumma innī aʿūdhu bika mina-l-bukhl, wa aʿūdhu bika mina-l-jubn, wa aʿūdhu bika an uradda ilā ardhali-l-ʿumur, wa aʿūdhu bika min fitnati-d-dunyā, wa aʿūdhu bika min ʿadhābi-l-qabr.","translation":"O Allah, I seek Your protection from miserliness and I seek Your protection from cowardice. I seek Your protection from being returned to the worst part of life (old age), I seek Your protection from the trials of the world, and I seek Your protection from the punishment of the grave.","description":null,"benefit":null,"virtue":null,"hadith":"Saʿd b. Abī Waqqās (radiy Allāhū ‘anhu) would instruct (to seek refuge) about five things [the above] and he would narrate it from the Messenger of Allah ﷺ . (Bukhārī 6370)","reference":"عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رضي الله عنه كَانَ يَأْمُرُ بِهَؤُلَاءِ الْخَمْسِ وَيُحَدِّثُهُنَّ عَنِ النَّبِيِّ صلى الله عليه وسلم: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبُخْلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ.\\n(صحيح البخاري ٦٣٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hurt/"},{"title":"Protection from Hunger & Treachery","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْجُوْعِ ، فَإِنَّهُ بِئْسَ الضَّجِيْعُ ، وَأَعُوْذُ بِكَ مِنَ الْخِيَانَةِ ، فَإِنَّهَا بِئْسَتِ الْبِطَانَةُ.","transliteration":"Allāhumma innī aʿūdhu bika mina-l-jūʿ, fa-innahū bi’sa-ḍ-ḍajīʿ, wa aʿūdhu bika mina-l-khiyānah, fa-innahā bi’sati-l-biṭānah.","translation":"O Allah, I seek Your protection from hunger, as it is indeed an evil companion and I seek Your protection from treachery, as it is an evil confidante.","description":null,"benefit":null,"virtue":null,"hadith":"‘Urwah b. Maymūn said: “I heard ‘Umar b. Al-Khaṭṭab (raḍiy Allāhu ‘anhu) say: ‘The Messenger of Allah ﷺ used to seek refuge with Allah from five things and say: [the above].’” (Nasā’ī 5468)","reference":"عَنْ أَبِي هُرَيْرَةَ قَالَ:كَانَ رَسُولُ اللهِ صلى الله عليه وسلم يَقُولُ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ ‌الْجُوعِ؛ فَإِنَّهُ بِئْسَ الضَّجِيعُ، وَأَعُوذُ بِكَ مِنَ الْخِيَانَةِ؛ فَإِنَّهَا بِئْسَتِ الْبِطَانَةُ.\\n(سنن النسائي ٥٤٦٨)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Maymūn said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hurt/"},{"title":"Protection from Bad Neighbours & Family Members","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنْ جَارِ السُّوْءِ ، وَمِنْ زَوْجٍ تُشَيِّبُنِيْ قَبْلَ المَشِيْبِ ، وَمِنْ وَّلَدٍ يَّكُوْنُ عَليَّ رَبًّا ، وَمِنْ مَّالٍ يَّكُوْنُ عَلَيَّ عَذَابًا ، وَمِنْ خَلِيْلٍ مَّاكِرٍ عَيْنُهُ تَرَانِيْ ، وَقَلْبُهُ يَرْعَانِيْ ، إِنْ رَأَىٰ حَسَنَةً دَفَنَهَا ، وَإِذَا رَأَىٰ سَيِّئَةً أَذَاعَهَا.","transliteration":"Allāhumma innī aʿūdhu bika min jāri-s-sū’, wa min zawjin tushayyibunī qabla-l-mashīb, wa min waladi-y-yakūnu ʿalayya rabbā, wa mi-m-māli-y-yakūnu ʿalayya ʿadhābā, wa min khalīli-m-mākir, ʿaynuhu tarānī, wa qalbuhū yarʿānī, ir-ra’ā ḥasanatan dafanahā wa idhā ra’ā sayyi’atan adhāʿahā.","translation":"O Allah, I seek Your protection from an evil neighbour; from a spouse who will age me ahead of time; from a child who will rule over me; from wealth that will become a punishment for me; from a cunning friend whose eyes see me yet his heart keeps guard over me: if he sees any good, he conceals it and if he sees any bad, he announces it.","description":null,"benefit":null,"virtue":null,"hadith":"Abū Hurayrah (raḍiy Allāhu ‘anhu) narrates that [the above] was from the supplication of the Messenger of Allah ﷺ. (Tabarānī in al-Du’ā 1339)","reference":"عَنْ أَبِي هُرَيْرَةَ، رضي الله عنه قَالَ: كَانَ مِنْ دُعَاءِ رَسُولِ اللَّهِ صلى الله عليه وسلم: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ جَارِ السُّوءِ، وَمِنْ زَوْجٍ تُشَيِّبُنِي قَبْلَ الْمَشِيبِ، وَمِنْ وَلَدٍ يَكُونُ عَلَيَّ رِبًا، وَمِنْ مَالٍ يَكُونُ عَلَيَّ عَذَابًا، وَمِنْ خَلِيلٍ مَاكِرٍ عَيْنَهُ تَرَانِي وَقَلْبُهُ تَرْعَانِي إِنْ رَأَى حَسَنَةً دَفَنَهَا، وَإِذَا رَأَى سَيِّئَةً أَذَاعَهَا.\\n(الدعاء-للطبراني ١٣٣٩)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hurt/"},{"title":"Unity, Guidance & Repentance","arabic":"اَللّٰهُمَّ أَلِّفْ بَيْنَ قُلُوْبِنَا ، وَأَصْلِحْ ذَاتَ بَيْنِنَا ، وَاهْدِنَا سُبُلَ السَّلَامِ ، وَنَجِّنَا مِنَ الظُّلُمَاتِ إِلَى النُّوْرِ ، وَجَنِّبْنَا الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ ، وَبَارِكْ لَنَا فِيْ أَسْمَاعِنَا ، وَأَبْصَارِنَا ، وَقُلُوْبِنَا ، وَأَزْوَاجِنَا ، وَذُرِّيَّاتِنَا ، وَتُبْ عَلَيْنَا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيْمُ ، وَاجْعَلْنَا شَاكِرِيْنَ لِنِعَمِكَ مُثْنِيْنَ بِهَا عَلَيْكَ ، قَابِلِيْنَ لَهَا ، وَأَتْمِمْهَا عَلَيْنَا.","transliteration":"Allāhumma allif bayna qulūbinā, wa aṣliḥ dhāta bayninā, wa-hdinā subula-s-sālām, wa najjinā mina-ẓ-ẓulumāti ila-n-nūr, wa jannibna-l-fawāḥisha mā ẓahara minhā wa mā baṭan, wa bārik lanā fī asmāʿinā, wa abṣārinā, wa qulūbinā, wa azwājinā, wa dhurriyyātinā, wa tub ʿalaynā innaka Anta-t-Tawwābu-r-Raḥīm, wa-jʿalnā shākirīna li-niʿamik muthnīna bihā ʿalayk, qābilīna lahā, wa atmimhā ʿalaynā.","translation":"O Allah, unite our hearts, set aright our relationships, and guide us to the paths of peace. Bring us out of darknesses into light and protect us from evident and hidden obscenities. Bless us in our hearing, our sight, our hearts, our spouses and our children. Accept our repentance. Indeed, You truly are the Acceptor of repentance, the Ever-Merciful. Make us of those who are grateful for Your blessings, who praise You for them and acknowledge them. Perfect (the blessings) and make them last forever for us.","description":null,"benefit":null,"virtue":null,"hadith":"Ibn Mas’ūd (raḍiy Allāhu ‘anhu) narrates that the Messenger of Allah ﷺ said [the above]. (Hākim 977)","reference":"عَنْ عَبْدِ اللَّهِ، قَالَ: كُنَّا لَا نَدْرِي مَا نَقُولُ إِذَا جَلَسْنَا فِي الصَّلَاةِ، وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم قَدْ عَلِمَ جَوَامِعَ الْكَلِمِ، وَخَوَاتِمَهُ، قَالَ: فَذَكَرَ التَّشَهُّدَ وَقَالَ: كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُعَلِّمُنَا كَلِمَاتٍ، كَمَا يُعَلِّمُنَا التَّشَهُّدَ:اللَّهُمَّ أَلَّفْ بَيْنَ قُلُوبِنَا، وَأَصْلِحْ ذَاتَ بَيْنِنَا، وَاهْدِنَا سُبُلَ السَّلَامِ، وَنَجِّنَا مِنَ الظُّلُمَاتِ إِلَى النُّورِ، وَجَنِّبْنَا الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا، وَمَا بَطَنَ، وَبَارِكْ لَنَا فِي أَسْمَاعِنَا، وَأَبْصَارِنَا، وَقُلُوبِنَا، وَأَزْوَاجِنَا، وَذُرِّيَّاتِنَا، وَتُبْ عَلَيْنَا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ، وَاجْعَلْنَا شَاكِرِينَ لِنِعَمِكَ، مُثْنِينَ بِهَا عَلَيْكَ، قَابِلِينَ لَهَا وَأَتِمَّهَا عَلَيْنَا.\\n(المستدرك على الصحيحين للحاكم ٩٧٧)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hurt/"}]},{"feeling":"Indecisive","slug":"indecisive","url":"https://allahuakbarofficial.com/indecisive/","items_count":10,"duas":[{"title":"Istikharah (Seeking Allah‘s Help in Making a Decision)","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْتَخِيْرُكَ بِعِلْمِكَ ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيْمِ ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ ، وَتَعْلَمُ وَلَا أَعْلَمُ ، وَأَنْتَ عَلَّامُ الْغُيُوْبِ . اَللّٰهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هٰذَا الْأَمْرَ (ويسمّي حاجته) خَيْرٌ لِّيْ فِيْ دِيْنِيْ وَمَعَاشِيْ وَعَاقِبَةِ أَمْرِيْ ، فَاقْدُرْهُ لِيْ وَيَسِّرْهُ لِيْ ثُمَّ بَارِكْ لِيْ فِيْهِ ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هٰذَا الْأَمْرَ (ويسمّي حاجته) شَرٌّ لِّيْ فِيْ دِيْنِيْ وَمَعَاشِيْ وَعَاقِبَةِ أَمْرِيْ ، فَاصْرِفْهُ عَنِّيْ وَاصْرِفْنِيْ عَنْهُ ، وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ ثُمَّ أَرْضِنِيْ بِهِ","transliteration":"Allāhumma innī astakhīruka bi ʿilmik, wa astaqdiruka bi qudratik, wa as’aluka min faḍlika-l-ʿaẓīm, fa innaka taqdiru wa lā aqdir, wa taʿlamu wa lā aʿlam, wa Anta ʿAllāmu-l-ghuyūb. Allāhumma in kunta taʿlamu an-na hādha-l-amr (specify the matter) khayrul-lī fī dīnī wa maʿāshī wa ʿāqibati amrī, faqdurhu lī wa yassirhu lī thumma bārik lī fīh, wa in kunta taʿlamu anna hādha-l-amr (specify the matter) sharrul-lī fī dīnī wa maʿāshī wa ʿāqibati amrī, faṣrifhu ʿannī waṣrifnī ʿanh, waqdur liya-l-khayra ḥaythu kān, thumma arḍinī bih.","translation":"O Allah, I ask You for the best through Your knowledge, I seek strength through Your power, and I ask You from Your immense favour. For You are fully able whilst I am not, You know everything whilst I do not know anything, and You are the Knower of the unseen. O Allah, if in Your knowledge, this matter (specify the matter) is good for me in my religion, my livelihood and my ultimate destiny, then decree it for me and make it easy it for me, then bless it for me. But if in Your knowledge, this matter (specify the matter) is bad for me in my religion, my livelihood and my ultimate destiny, then turn it away from me, and turn me away from it. Decree good for me wherever it may be, then make me pleased with it.","description":null,"benefit":null,"virtue":null,"hadith":"Jābir (raḍiy Allāhu ʿanhu) narrated: “The Messenger of Allah ﷺ used to teach us *istikhārah* (when one seeks Allah’s help in making a decision) for all matters, the same way he taught us Sūrahs from the Qur’ān. He ﷺ said: “When one of you intends to do something, he should offer two rak‘ahs of voluntary ṣalāh, and then say [the above].” (Bukhārī 6382)","reference":"Ibn Abī Jamrah (raḥimahullāh) said: “The wisdom of preceding ṣalāh before the duʿā’ is that the purpose of *istikhārah* is to combine the good of this world and the hereafter. A person needs to knock at the door of the King (Allah), and there is nothing more effective for this than ṣalāh, because it combines the glorification and praise of Allah, and expresses one’s need for Him at all times.” (Fatḥ al-Bārī 11/186)\\nعَنْ جَابِرٍ رضي الله عنه قَالَ: كَانَ النَّبِيُّ صلى الله عليه وسلم يُعَلِّمُنَا الِاسْتِخَارَةَ فِي الْأُمُورِ كُلِّهَا، كَالسُّورَةِ مِنَ الْقُرْآنِ: إِذَا هَمَّ بِالْأَمْرِ فَلْيَرْكَعْ رَكْعَتَيْنِ، ثُمَّ يَقُولُ: اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي، أَوْ قَالَ فِي عَاجِلِ أَمْرِي وَآجِلِهِ، فَاقْدُرْهُ لِي، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي، أَوْ قَالَ فِي عَاجِلِ أَمْرِي وَآجِلِهِ، فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِي الْخَيْرَ حَيْثُ كَانَ ثُمَّ رَضِّنِي بِهِ، وَيُسَمِّي حَاجَتَهُ. (صحيح البخاري ٦٣٨٢)\\nوقال بن أبي جمرة الحكمة في تقديم الصلاة على الدعاء أن المراد بالاستخارة حصول الجمع بين خيري الدنيا والآخرة فيحتاج إلى قرع ‌باب ‌الملك ولا شيء لذلك أنجع ولا أنجح من الصلاة لما فيها من تعظيم الله والثناء عليه والافتقار إليه مآلا وحالا. (فتح الباري بشرح البخاري ١١\\\\١٨٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/indecisive/"},{"title":"When One Feels Frightened","arabic":"لَا إِلٰهَ إِلَّا اللّٰهُ","transliteration":"Lā ilāha illā-llāh.","translation":"There is no god worthy of worship except Allah.","description":null,"benefit":null,"virtue":null,"hadith":"Zaynab b. Jaḥsh (raḍiy Allāhu ʿanhā) said that the Messenger of Allah ﷺ once entered her house in a state of fear and said, “[The above]. Woe to the Arabs from a danger that is imminent. An opening has been made today in the wall of Ya‘jūj and Ma‘jūj like this” and he made a circle with his thumb and index finger. Zaynab b. Jaḥsh said, “O Messenger of Allah ﷺ! Will we be destroyed even though there are pious people amongst us?” He ﷺ said, “Yes, when evil becomes widespread.” (Bukhārī 3346)","reference":"عَنْ أُمِّ حَبِيبَةَ بِنْتِ أَبِي سُفْيَانَ عَنْ زَيْنَبَ ابْنَةِ جَحْشٍ رضي الله عنهن أَنَّ النَّبِيَّ صلى الله عليه وسلم دَخَلَ عَلَيْهَا فَزِعًا يَقُولُ لَا إِلَهَ إِلَّا اللهُ وَيْلٌ لِلْعَرَبِ مِنْ شَرٍّ قَدِ اقْتَرَبَ فُتِحَ الْيَوْمَ مِنْ رَدْمِ يَاجُوجُ وَمَاجُوجُ مِثْلُ هَذِهِ وَحَلَّقَ بِإِصْبَعِهِ الْإِبْهَامِ وَالَّتِي تَلِيهَا قَالَتْ زَيْنَبُ ابْنَةُ جَحْشٍ: فَقُلْتُ: يَا رَسُولَ اللهِ أَنَهْلِكُ وَفِينَا الصَّالِحُونَ قَالَ نَعَمْ إِذَا كَثُرَ الْخَبَثُ. (صحيح البخاري ٣٣٤٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Jaḥsh said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/indecisive/"},{"title":"Entrust All Your Matters to Allah","arabic":"يَا حَيُّ يَا قَيُّوْمُ ، بِرَحْمَتِكَ أَسْتَغِيْثُ ، أَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ ، وَلَا تَكِلْنِيْ إِلَىٰ نَفْسِيْ طَرْفَةَ عَيْنٍ.\\nأخبرنَا عبد الرَّحْمَن بن مُحَمَّد بن سَلام حَدثنَا زيد بن الْحباب أَخْبرنِي عُثْمَان بن موهب الْهَاشِمِي سَمِعت أنس بن مَالك يَقُول قَالَ النَّبِي صلى الله عليه وسلم لفاطمة مَا يمنعك أَن سَمْعِي مَا أوصيك بِهِ أَو تقولي إِذا أَصبَحت وَإِذا أمسيت يَا حَيّ يَا قيوم بِرَحْمَتك أستغيث أصلح لي شأني كلَّه وَلَا تَكِلنِي إِلَى نَفسِي طرفَة عين.","transliteration":"Yā Ḥayyu yā Qayyūm, bi-raḥmatika astaghīth, aṣliḥ lī sha’nī kullah, wa lā takilnī ilā nafsī ṭarfata ʿayn.","translation":"O The Ever Living, The Sustainer of all. ; I seek assistance through Your mercy. Rectify all of my affairs and do not entrust me to myself for the blink of an eye.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ʿanhu) narrates that the Prophet ﷺ said to Fāṭimah (raḍiy Allāhu ʿanhā), “What is preventing you from (doing) what I am advising you; that you say [the above] in the morning and evening?” (Nasā’ī in ʿAmal al-Yawm wa-l-Laylah 570)","reference":"(عمل اليوم والليلة للنسائي ٥٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/indecisive/"},{"title":"Steadfastness on Din","arabic":"يَا مُقَلِّبَ الْقُلُوْبِ ثَبِّتْ قَلْبِيْ عَلَىٰ دِيْنِكَ","transliteration":"Yā Muqalliba-l-qulūbi thabbit qalbī ʿalā dīnik.","translation":"O Allah, Turner of hearts, make my heart firm upon Your religion.","description":null,"benefit":null,"virtue":null,"hadith":"Shahr bin Hawshab (raḥimahullāh) said: “I said to Umm Salamah (raḍiy Allāhu ‘anhā): ‘O Mother of the Believers! What was the supplication that the Messenger of Allah ﷺ said most frequently when he was with you?” She said: ‘The supplication he said most frequently was: ’[the above]’” She said: ‘So I said: “O Messenger of Allah, why do you supplicate [the above] so frequently [the above]? He said: ‘O Umm Salamah! Verily, there is no human being except that his heart is between Two Fingers of the Fingers of Allah, so whomsoever He wills He makes steadfast, and whomever He wills He causes to deviate.’” (Tirmidhī 3522)","reference":"عَنْ أَبِي كَعْبٍ صَاحِبِ الْحَرِيرِ، قَالَ: حَدَّثَنِي شَهْرُ بْنُ حَوْشَبٍ قَالَ قُلْتُ: لِأُمِّ سَلَمَةَ يَا أُمَّ الْمُؤْمِنِينَ مَا كَانَ أَكْثَرُ دُعَاءِ رَسُولِ اللهِ صلى الله عليه وسلم إِذَا كَانَ عِنْدَكِ؟ قَالَتْ: كَانَ أَكْثَرُ دُعَائِهِ يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ. قَالَتْ: فَقُلْتُ: يَا رَسُولَ اللهِ، مَا لِأَكْثَرِ دُعَائِكَ يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ؟ قَالَ: يَا أُمَّ سَلَمَةَ، إِنَّهُ لَيْسَ آدَمِيٌّ إِلَّا وَقَلْبُهُ بَيْنَ أُصْبُعَيْنِ مِنْ أَصَابِعِ اللهِ، فَمَنْ شَاءَ أَقَامَ، وَمَنْ أَشَاءَ أَزَاغَ.\\n(سنن الترمذي ٣٥٢٢)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"I said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/indecisive/"},{"title":"Steadfastness on Islam","arabic":"يَا وَلِيَّ الْإسْلَامِ وَأَهْلِهِ ، ثَبِّتْنِيْ بِهِ حَتَّىٰ أَلْقَاكَ","transliteration":"Yā Waliyyal-Islāmi wa ahlih, thab-bitnī bihī ḥattā alqāk.","translation":"O Guardian of Islam and its followers, keep me firm on it (Islam) until I meet You.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ‘anhu) narrates that the Messenger of Allah ﷺ would say [the above]. (Tabarānī in Mu’jam al-Awsat 661)","reference":"عَنْ أَنَسِ بْنِ مَالِكٍ رضي الله عنه، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ يَقُولُ: يَا وَلِيَّ الْإِسْلَامِ وَأَهْلِهِ، ثَبِّتْنِي بِهِ حَتَّى أَلْقَاكَ. (المعجم الأوسط للطبراني ٦٦١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/indecisive/"},{"title":"Best Outcomes & Protection from Humiliation","arabic":"اَللّٰهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي الْأُمُوْرِ كُلِّهَا ، وَأَجِرْنَا مِنْ خِزْيِ الدُّنْيَا وَعَذَابِ الْآخِرَةِ","transliteration":"Allāhumma aḥsin ʿāqibatanā fi-l-umūri kullihā, wa ajirnā min khizyi-d-dunyā wa ʿadhābi-l-ākhirah.","translation":"O Allah, grant us the best outcome in all of our affairs, and protect us from the humiliation of this world and the punishment of the hereafter.","description":null,"benefit":null,"virtue":null,"hadith":"Busr b. Abī Artāt (raḍiy Allāhu ‘anhu) narrates that I heard the Messenger of Allah ﷺ supplicate with [the above]. (Aḥmad 17628)","reference":"عَنْ بُسْرِ بْنِ أَرْطَاةَ الْقُرَشِيِّ، قَالَ: سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَدْعُو: ” اللهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي الْأُمُورِ كُلِّهَا، وَأَجِرْنَا مِنْ خِزْيِ الدُّنْيَا وَعَذَابِ الْآخِرَةِ. (مسند احمد ١٧٦٢٨)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/indecisive/"},{"title":"A Priceless Treasure","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ ، وَالْعَزِيْمَةَ عَلَى الرُّشْدِ ، وَأَسْأَلُكَ مُوْجِبَاتِ رَحْمَتِكَ ، وَعَزَائِمَ مَغْفِرَتِكَ ، وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ ، وَحُسْنَ عِبَادَتِكَ ، وَأَسْأَلُكَ قَلْبًا سَلِيْمًا ، وَلِسَانًا صَادِقًا ، وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ ، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ ، وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ ، إِنَّكَ أَنْتَ عَلَّامُ الْغُيُوْبِ","transliteration":"Allāhumma innī as’aluka-th-thabāta fil-amr, wa-l-ʿazīmata ʿala-r-rushd, wa as’aluka mūjibāti raḥmatik, wa ʿazā’ima maghfiratik, wa as’aluka shukra niʿmatik, wa ḥusna ʿibādatik, wa as’aluka qalban salīmā, wa lisānan ṣādiqā, wa as’aluka min khayri mā taʿlam, wa aʿūdhu bika min sharri mā taʿlam, wa astaghfiruka limā taʿlam, innaka Anta ʿAllāmul-ghuyūb.","translation":"O Allah, I beg you for steadfastness in all matters and the determination to take the right course. I ask You for all that which will necessitate Your mercy and the determination to do all that which will necessitate Your forgiveness. I ask You to make me grateful for Your blessings and to worship You in an excellent manner. I ask You for a sound heart and a truthful tongue. I ask You for the good of what You know, I seek Your protection from the evil of what You know, and I seek Your forgiveness for what You know. Indeed, You are the All-Knowing of the unseen.","description":null,"benefit":null,"virtue":"Shaddād b. Aws (raḍiy Allāhu ‘anhu) narrates that the Messenger of Allah ﷺ was teaching this duā to me. he said: “O Shaddād, when you see people collecting gold & silver as their treasures, then consider [the above] as your treasure.” (Ahmad 17114)","hadith":null,"reference":"حَدَّثَنَا رَوْحٌ، قَالَ: حَدَّثَنَا الْأَوْزَاعِيُّ، عَنْ حَسَّانَ بْنِ عَطِيَّةَ قَالَ: كَانَ شَدَّادُ بْنُ أَوْسٍ، فِي سَفَرٍ، فَنَزَلَ مَنْزِلًا، فَقَالَ لِغُلَامِهِ: ائْتِنَا بِالسُّفْرَةِ نَعْبَثْ بِهَا. فَأَنْكَرْتُ عَلَيْهِ، فَقَالَ: مَا تَكَلَّمْتُ بِكَلِمَةٍ مُنْذُ أَسْلَمْتُ إِلَّا وَأَنَا أَخْطِمُهَا وَأَزُمُّهَا غَيْرَ كَلِمَتِي هَذِهِ، فَلَا تَحْفَظُوهَا عَلَيَّ، وَاحْفَظُوا مِنِّي مَا أَقُولُ لَكُمْ: سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَقُولُ: ” إِذَا كَنَزَ النَّاسُ الذَّهَبَ وَالْفِضَّةَ، فَاكْنِزُوا هَؤُلَاءِ الْكَلِمَاتِ: اللهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ، وَالْعَزِيمَةَ عَلَى الرُّشْدِ، وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ، وَأَسْأَلُكَ حُسْنَ عِبَادَتِكَ، وَأَسْأَلُكَ قَلْبًا سَلِيمًا، وَأَسْأَلُكَ لِسَانًا صَادِقًا، وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ، إِنَّكَ أَنْتَ عَلَّامُ الْغُيُوبِ.\\n(مسند احمد ١٧١١٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/indecisive/"},{"title":"Asking for Good & Protection From Evil","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ ، وَأَعُوْذُ بِكَ مِنَ الشَّرِّ كُلِّهِ عَاجِلِهِ وَآجِلِهِ ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ عَبْدُكَ وَنَبِيُّكَ ، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا عَاذَ مِنْهُ عَبْدُكَ وَنَبِيُّكَ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْجَنَّةَ ، وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ ، وَأَعُوْذُ بِكَ مِنَ النَّارِ ، وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ ، وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ قَضَيْتَهُ لِيْ خَيْرًا","transliteration":"Allāhumma innī as’aluka mina-l-khayri kullihī ʿājilihī wa ājilih, mā ʿalimtu minhu wa mā lam aʿlam, wa aʿūdhu bika mina-sh-sharri kullih ʿājilihī wa ājilih, mā ʿalimtu minhu wa mā lam aʿlam, Allāhumma innī as’aluka min khayri mā sa’alaka ʿabduka wa Nabiyyuk, wa aʿūdhu bika min sharri mā ʿādha minhu ʿabduka wa Nabiyyuk, Allāhumma innī as’aluka-l-Jannah, wa mā qarraba ilayhā min qawlin aw ʿamal, wa aʿūdhu bika mina-n-nār, wa mā qarraba ilayhā min qawlin aw ʿamal, wa as’aluka an tajʿala kulla qaḍā’in qaḍaytahū lī khayrā.","translation":"O Allah, I beg You for all good: the immediate and the delayed, what I know of and what I do not know. I seek Your protection from all evil: the immediate and the delayed, what I know of and what I do not know. O Allah, I beg You for the good which Your slave and Prophet ﷺ asked from You, and I seek Your protection from the evil which Your slave and Prophet ﷺ sought protection for from You. O Allah, I beg You for Paradise, and whatever words or actions lead to it. I seek Your protection from Hell-fire, and whatever words or actions lead to it. I ask You to decree good for me in everything You foreordain for me.","description":null,"benefit":null,"virtue":null,"hadith":"‘Āishah narrates that the Messenger of Allah ﷺ taught her [the above]. (Ahmad 25019)","reference":"عَنْ عَائِشَةَ أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم عَلَّمَهَا هَذَا الدُّعَاءَ: اللهُمَّ إِنِّي أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، وَأَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ، وَمَا لَمْ أَعْلَمْ، اللهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ عَبْدُكَ وَنَبِيُّكَ مُحَمَّدٌ صلى الله عليه وسلم، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا عَاذَ مِنْهُ عَبْدُكَ وَنَبِيُّكَ، اللهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَعُوذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ تَقْضِيهِ لِي خَيْرًا.\\n(مسند احمد ٢٥٠١٩)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/indecisive/"},{"title":"Guidance & Steadfastness","arabic":"اَللّٰهُمَّ اهْدِنِيْ وَسَدِّدْنِيْ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْهُدَىٰ وَالسَّدَادَ.","transliteration":"Allāhumma-hdinī wa saddidnī, Allāhumma innī as’aluka-l-hudā wa-s-sadād.","translation":"O Allah, guide me and grant me firmness. O Allah, I beg You for guidance and firmness (on the straight path).","description":null,"benefit":null,"virtue":null,"hadith":"Ali (raḍiy Allāhu ‘anhu) reported that the Messenger of Allah ﷺ said to him: “Say: [the above] and when you make a mention of guidance, keep in mind the (Straight) Path and when you consider the Straight (Path), keep in mind the straightness of the arrow.” (Muslim 2725)","reference":"عَنْ عَلِيٍّ قَالَ:قَالَ لِي رَسُولُ اللهِ صلى الله عليه وسلم: قُلِ: اللَّهُمَّ اهْدِنِي، وَسَدِّدْنِي، وَاذْكُرْ بِالْهُدَى هِدَايَتَكَ الطَّرِيقَ وَالسَّدَادِ سَدَادَ السَّهْمِ. (صحيح مسلم ٢٧٢٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/indecisive/"},{"title":"Guidance & Protection from Evil","arabic":"اَللّٰهُمَّ أَلْهِمْنِيْ رُشْدِيْ ، وَأَعِذْنِيْ مِنْ شَرِّ نَفْسِيْ.","transliteration":"Allāhumma alhimnī rushdī, wa aʿidhnī min sharri nafsī.","translation":"O Allah, inspire me with sound guidance and protect me from the evil of my self.","description":null,"benefit":null,"virtue":"ʿImrān b. Husayn (raḍiy Allāhu ‘anhu) narrated: “The Prophet ﷺ said to my father: ‘O Husayn, how many deities do you worship now?‘ He said: ‘Seven. Six in the earth, and one above the heavens.’ He ﷺ said: ‘So which of them do you take for your ardent requests and fears?’ He said: ‘The one above the heavens.’ He ﷺ said: ‘O Husayn, if you accept Islam, I would teach you two phrases that would benefit you.’” He (the narrator) said: “So when Husayn accepted Islam, he said: ‘O Messenger of Allah, teach me the two phrases you promised me.’ So he ﷺ said: [the above].” (Tirmidhī 3483)","hadith":null,"reference":"عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، قَالَ: قَالَ النَّبِيُّ صلى الله عليه وسلم لِأَبِي:يَا حُصَيْنُ كَمْ تَعْبُدُ اليَوْمَ إِلَهًا؟ قَالَ أَبِي: سَبْعَةً سِتَّةً فِي الأَرْضِ وَوَاحِدًا فِي السَّمَاءِ. قَالَ فَأَيُّهُمْ تَعُدُّ لِرَغْبَتِكَ وَرَهْبَتِكَ؟ قَالَ: الَّذِي فِي السَّمَاءِ. قَالَ:يَا حُصَيْنُ أَمَا إِنَّكَ لَوْ أَسْلَمْتَ عَلَّمْتُكَ كَلِمَتَيْنِ تَنْفَعَانِكَ. قَالَ: فَلَمَّا أَسْلَمَ حُصَيْنٌ قَالَ: يَا رَسُولَ اللَّهِ عَلِّمْنِيَ الكَلِمَتَيْنِ اللَّتَيْنِ وَعَدْتَنِي، فَقَالَ:” قُلْ: اللَّهُمَّ أَلْهِمْنِي رُشْدِي، وَأَعِذْنِي مِنْ شَرِّ نَفْسِي.\\n(سنن الترمذي ٣٤٨٣)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"He said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/indecisive/"}]},{"feeling":"Hypocritical","slug":"hypocritical","url":"https://allahuakbarofficial.com/hypocritical/","items_count":5,"duas":[{"title":"For Firmness of the Heart","arabic":"يَا مُقَلِّبَ الْقُلُوْبِ ثَبِّتْ قَلْبِيْ عَلَىٰ دِيْنِكَ","transliteration":"Yā Muqalliba-l-qulūbi thabbit qalbī ʿalā dīnik.","translation":"O Changer of the hearts, make my heart firm upon Your religion.","description":null,"benefit":null,"virtue":null,"hadith":"Anas (raḍiy Allāhu ʿanhu) said: “The Messenger of Allah ﷺ would often say [the above]. So I asked: ‘O Messenger of Allah, we believe in you and what you have come with, but do you fear for us?’ He replied: ‘Yes. Indeed the hearts are in between the two Fingers of Allah’s Fingers. He changes them as He wills.’”","reference":"(Tirmidhī 3522)\\nعَنْ أَبِي كَعْبٍ صَاحِبِ الحَرِيرِ قَالَ: حَدَّثَنِي شَهْرُ بْنُ حَوْشَبٍ، قَالَ: قُلْتُ لِأُمِّ سَلَمَةَ: يَا أُمَّ المُؤْمِنِينَ مَا كَانَ أَكْثَرُ دُعَاءِ رَسُولِ اللَّهِ صلى الله عليه وسلم إِذَا كَانَ عِنْدَكِ؟ قَالَتْ: كَانَ أَكْثَرُ دُعَائِهِ: يَا مُقَلِّبَ القُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِك قَالَتْ: فَقُلْتُ: يَا رَسُولَ اللَّهِ مَا لِأَكْثَرِ دُعَائِكَ يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ؟ قَالَ: يَا أُمَّ سَلَمَةَ إِنَّهُ لَيْسَ آدَمِيٌّ إِلَّا وَقَلْبُهُ بَيْنَ أُصْبُعَيْنِ مِنْ أَصَابِعِ اللَّهِ، فَمَنْ شَاءَ أَقَامَ، وَمَنْ شَاءَ أَزَاغَ. فَتَلَا مُعَاذٌ رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا. (سنن الترمذي ٣٥٢٢)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hypocritical/"},{"title":"When One Experiences Doubt in Faith #1","arabic":"آمَنْتُ بِاللهِ وَرُسُلِهِ","transliteration":"Āmantu bi-llāhi wa rusulih.","translation":"I believe in Allah and His Messengers.","description":null,"benefit":null,"virtue":"The Messenger of Allāh ﷺ said: “Men will continue to question one another till this is propounded: ‘Allāh created all things but who created Allāh?’  He who found himself confronted with such a situation should say: [the above].” (Muslim 134)","hadith":null,"reference":"عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: « لَا يَزَالُ النَّاسُ ‌يَتَسَاءَلُونَ حَتَّى يُقَالَ هَذَا: خَلَقَ اللهُ الْخَلْقَ، فَمَنْ خَلَقَ اللهَ؟ فَمَنْ وَجَدَ مِنْ ذَلِكَ شَيْئًا، فَلْيَقُلْ: آمَنْتُ بِاللهِ.\\n(صحيح مسلم ١٣٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hypocritical/"},{"title":"When One Experiences Doubt in Faith #2","arabic":"هُوَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ ، وَهُوَ بِكُلِّ شَيْءٍ عَلِيْمٌ","transliteration":"Huwa-l-Awwalu wa-l-Ākhiru wa-ẓ-Ẓāhiru wa-l-Bāṭin, wa Huwa bi-kulli shay’in ‘Alīm.","translation":"He is the First and the Last, the Most High and the Most Near. And He is All-Knowing about everything.","description":null,"benefit":null,"virtue":null,"hadith":"Abū Zumayl reported: “I asked Ibn ʿAbbās (raḍiy Allāhū ʿanhumā): ‘What is this that I am experiencing in my heart?’ He answered: ‘What is it?’ I said: ‘By Allah, I cannot talk about it.’ He asked me: ‘Is it something to do with doubt?’ [When answered it was], he smiled and said: ‘No-one was safe from it until Allah revealed:","reference":"*If you are in doubt concerning what We revealed unto you [O Prophet], ask those who read the Scripture from before your time. The truth has indeed come to you from your Lord, so do not be of those in doubt (10:94).*’ | So he (Ibn ʿAbbās) told me: ‘If you experience any [doubt] within yourself, say: [the above].’” (Abū Dāwūd 5110)\\nحَدَّثَنَا عَبَّاسُ بْنُ عَبْدِ الْعَظِيمِ، نَا النَّضْرُ بْنُ مُحَمَّدٍ ، نَا عِكْرِمَةُ يَعْنِي ابْنَ عَمَّارٍ قَالَ: وَنَا أَبُو زُمَيْلٍ قَالَ: سَأَلْتُ ابْنَ عَبَّاسٍ فَقُلْتُ: مَا شَيْءٌ أَجِدُهُ فِي صَدْرِي قَالَ: مَا هُوَ؟ قُلْتُ: وَاللهِ مَا أَتَكَلَّمُ بِهِ. قَالَ: فَقَالَ لِي: أَشَيْءٌ مِنْ شَكٍّ؟ قَالَ وَضَحِكَ قَالَ: مَا نَجَا أَحَدٌ مِنْ ذَلِكَ، حَتَّى أَنْزَلَ اللهُ تَعَالَى {فَإِنْ كُنْتَ فِي شَكٍّ مِمَّا أَنْزَلْنَا إِلَيْكَ فَاسْأَلِ الَّذِينَ يَقْرَءُونَ الْكِتَابَ} الْآيَةَ، قَالَ: فَقَالَ لِي: إِذَا وَجَدْتَ فِي نَفْسِكَ شَيْئًا فَقُلْ {هُوَ الأَوَّلُ وَالآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ. (سنن ابي داود ٥١١٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"I said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hypocritical/"},{"title":"When One Fears Shirk & Showing off","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ","transliteration":"Allāhumma innī aʿūdhu bika an ushrika bika wa-ana aʿlam, wa astaghfiruka limā lā aʿlam.","translation":"O Allah, I seek Your protection from knowingly committing shirk, and I seek Your forgiveness for unknowingly (committing it).","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “O people, beware of this shirk, for it is more subtle than the footsteps of an ant.” The one whom Allah willed should speak asked him: “How can we beware of it when it is more subtle than the footsteps of an ant, O Messenger of Allah?” He replied: “Say [the above].” (Ahmad 19606)","hadith":null,"reference":"حَدَّثَنَا عَبَّاسٌ النَّرْسِيُّ قَالَ: حَدَّثَنَا عَبْدُ الْوَاحِدِ قَالَ: حَدَّثَنَا لَيْثٌ قَالَ: أَخْبَرَنِي رَجُلٌ مِنْ أَهْلِ الْبَصْرَةِ قَالَ: سَمِعْتُ مَعْقِلَ بْنَ يَسَارٍ يَقُولُ: انْطَلَقْتُ مَعَ أَبِي بَكْرٍ الصِّدِّيقِ رضي الله عنه إِلَى النَّبِيِّ صلى الله عليه وسلم، فَقَالَ:يَا أَبَا بَكْرٍ، لَلشِّرْكُ فِيكُمْ أَخْفَى مِنْ دَبِيبِ النَّمْلِ، فَقَالَ أَبُو بَكْرٍ: وَهَلِ الشِّرْكُ إِلَّا مَنْ جَعَلَ مَعَ اللَّهِ إِلَهًا آخَرَ؟ فَقَالَ النَّبِيُّ صلى الله عليه وسلم:وَالَّذِي نَفْسِي بِيَدِهِ، لَلشِّرْكُ أَخْفَى مِنْ دَبِيبِ النَّمْلِ، أَلَا أَدُلُّكَ عَلَى شَيْءٍ إِذَا قُلْتَهُ ذَهَبَ عَنْكَ قَلِيلُهُ وَكَثِيرُهُ؟  قَالَ:قُلِ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ. (الأدب المفرد ٧١٦)\\nعَنْ أَبِي عَلِيٍّ رَجُلٍ مِنْ بَنِي كَاهِلٍ، قَالَ: خَطَبَنَا أَبُو مُوسَى الْأَشْعَرِيُّ، فَقَالَ: يَا أَيُّهَا النَّاسُ، اتَّقُوا هَذَا الشِّرْكَ، فَإِنَّهُ أَخْفَى مِنْ دَبِيبِ النَّمْلِ، فَقَامَ إِلَيْهِ عَبْدُ اللهِ بْنُ حَزْنٍ وَقَيْسُ بْنُ المُضَارِبِ، فَقَالَا: وَاللهِ لَتَخْرُجَنَّ مِمَّا قُلْتَ، أَوْ لَنَأْتِيَنَّ عُمَرَ، مَأْذُونٌ لَنَا أَوْ غَيْرُ مَأْذُونٍ. قَالَ: بَلْ أَخْرُجُ مِمَّا قُلْتُ: خَطَبَنَا رَسُولُ اللهِ صلى الله عليه وسلم ذَاتَ يَوْمٍ، فَقَالَ: ” أَيُّهَا النَّاسُ، اتَّقُوا هَذَا الشِّرْكَ، فَإِنَّهُ أَخْفَى مِنْ دَبِيبِ النَّمْلِ  فَقَالَ لَهُ مَنْ شَاءَ اللهُ أَنْ يَقُولَ: وَكَيْفَ نَتَّقِيهِ وَهُوَ أَخْفَى مِنْ دَبِيبِ النَّمْلِ يَا رَسُولَ اللهِ؟ قَالَ:  قُولُوا: اللهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ أَنْ نُشْرِكَ بِكَ شَيْئًا نَعْلَمُهُ، وَنَسْتَغْفِرُكَ لِمَا لَا نَعْلَمُ. (احمد ١٩٦٠٦)\\nعَنْ حُذَيْفَةَ، عَنْ أَبِي رضي الله عنهما، أَمَا أَخْبَرَ ذَلِكَ حُذَيْفَةُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ، وَأَمَا أَخْبَرَهُ أَبُو بَكْرٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ قَالَ: الشِّرْكُ أَخْفَى فِيكُمْ مِنْ دَبِيبِ ‌النَّمْلِ، قَالَ: قُلْنَا: يَا رَسُولَ اللَّهِ، وَهَلِ الشِّرْكُ إِلَّا مَا عُبِدَ مِنْ دُونِ اللَّهِ عز وجل، أَوْ مَا دُعِيَ مَعَ اللَّهِ، شَكَّ عَبْدُ الْمَلِكِ بْنُ جُرَيْجٍ، فَقَالَ:ثَكِلَتْكَ أُمُّكَ يَا صِدِّيقُ، الشِّرْكُ أَخْفَى فِيكُمْ مِنْ دَبِيبِ ‌النَّمْلِ، أَلَا أُخْبِرُكَ بِقَوْلٍ يُذْهِبُ صِغَارَهُ وَكِبَارَهُ، أَوْ صَغِيرَهُ وَكَبِيرَهُ؟قَالَ: قُلْتُ: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: ” تَقُولُ كُلَّ يَوْمٍ ثَلَاثَ مَرَّاتٍ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ، وَالشِّرْكُ أَنْ يَقُولَ أَعْطَانِي اللَّهُ وَفُلَانٌ، وَالنِّدُّ أَنْ يَقُولَ الْإِنْسَانُ: لَوْلَا فُلَانٌ لَقَتَلَنِي فُلَانٌ.\\n(عمل اليوم والليلة لابن السني ٢٨٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hypocritical/"},{"title":"Protection From Dajjal, Trials & Tribulations","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ ، وَمِنْ عَذَابِ الْقَبْرِ ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيْحِ الدَّجَّالِ","transliteration":"Allāhumma innī aʿūdhu bika min ʿadhābi jahannam, wa min ʿadhābi-l-qabr, wa min fitnati-l-maḥyā wa-l-mamāt, wa min sharri fitnati-l-masīḥi-d-dajjāl.","translation":"O Allah, I seek Your protection from the punishment of the Hell-fire, from the punishment of the grave, from the trials of life and death, and from the evil of the tribulation of al-Masīḥ al-Dajjāl.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “When one of you utters tashahhud (in ṣalāh), he should then seek Allah’s protection from four things by saying [the above].” (Muslim 588)","hadith":null,"reference":"He ﷺ also said: “Whoever memorises the first ten verses of Sūrah al-Kahf, he will be protected from Dajjāl.” (Muslim 809)\\nعن أبي هريرة؛ قال قال رسول الله صلى الله عليه وسلم إِذَا تَشَهَّدَ أَحَدُكُمْ فَلْيَسْتَعِذْ بِاللَّهِ مِنْ أَرْبَعٍ. يَقُولُ: اللَّهُمَّ! إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ. وَمِنْ عَذَابِ القبر. ومن فتنة المحيا والممات. ومن شر فتنة المسيح الدجال. (صحيح مسلم ٥٨٨)\\nعَنْ أَبِي الدَّرْدَاءِ؛ أَنّ النَّبِيَّ صلى الله عليه وسلم قَالَ: مَنْ حَفِظَ عَشْرَ آيَاتٍ مِنْ أَوَّلِ سُورَةِ الْكَهْف، عُصِمَ من الدجال. (صحيح مسلم ٨٠٩)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/hypocritical/"}]},{"feeling":"Jealous","slug":"jealous","url":"https://allahuakbarofficial.com/jealous/","items_count":5,"duas":[{"title":"Three Quls: To Suffice You in All Your Matters","arabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيْمِ.\\nقُلْ هُوَ اللّٰهُ أَحَدٌ ، اَللّٰهُ الصَّمَدُ ، لَمْ يَلِدْ وَلَمْ يُوْلَدْ ، وَلَمْ يَكُنْ لَّهُ كُفُوًا أَحَدٌ.\\nقُلْ أَعُوْذُ بِرَبِّ الْفَلَقِ ، مِنْ شَرِّ مَا خَلَقَ ، وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ، وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ، وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ.\\nقُلْ أَعُوْذُ بِرَبِّ النَّاسِ ، مَلِكِ النَّاسِ ، إِلٰهِ النَّاسِ ، مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ، اَلَّذِيْ يُوَسْوِسُ فِيْ صُدُوْرِ النَّاسِ ، مِنَ الْجِنَّةِ وَالنَّاسِ","transliteration":"Bismi-llāhi-r-Raḥmāni-r-Raḥīm. Qul Huwa-llāhu Aḥad. Allāhu-ṣ-Ṣamad. Lam yalid wa lam yūlad. Wa lam yakul-lahū kufuwan aḥad.","translation":"Repeat. x3","description":null,"benefit":null,"virtue":"Muʿādh b. ʿAbdullāh b. Khubayb, narrated from his father (raḍiy Allāhu ʿanhu), who said: “We went out on a rainy and extremely dark night, looking for the Messenger of Allah ﷺ, so that he could lead us in ṣalāh.” He said: “So I met him and he ﷺ said: ‘Say’ but I did not say anything. Then he ﷺ said: ‘Say.’ But I did not say anything. He ﷺ said: ‘Say.’ So I said: ‘What should I say?’ He ﷺ said: “Recite Sūrah al-Ikhlāṣ and al-Muʿawwidhatayn (Sūrah al-Falaq and Sūrah al-Nās) three times in the morning and the evening: It will suffice you in all respects.” (Tirmidhī 3575)","hadith":null,"reference":"Say, He is Allah, the One, the Self-Sufficient Master, Who has not given birth and was not born, and to Whom no one is equal.(112) | Say, I seek protection of the Lord of the daybreak, from the evil of what He has created, and from the evil of the darkening night when it settles, and from the evil of the blowers in knots, and from the evil of the envier when he envies. (113) | Say, I seek protection of the Lord of mankind, the King of mankind, the God of mankind, from the evil of the whisperer who withdraws, who whispers in the hearts of mankind, whether they be Jinn or people. (114)\\nعَنْ مُعَاذِ بْنِ عَبْدِ اللَّهِ بْنِ خُبَيْبٍ، عَنْ أَبِيهِ، قَالَ: خَرَجْنَا فِي لَيْلَةٍ مَطِيرَةٍ وَظُلْمَةٍ شَدِيدَةٍ نَطْلُبُ رَسُولَ اللَّهِ صلى الله عليه وسلم يُصَلِّي لَنَا، قَالَ: فَأَدْرَكْتُهُ، فَقَالَ: قُلْ  فَلَمْ أَقُلْ شَيْئًا، ثُمَّ قَالَ: قُلْ، فَلَمْ أَقُلْ شَيْئًا، قَالَ: قُلْ، فَقُلْتُ، مَا أَقُولُ؟ قَالَ: ” قُلْ: قُلْ هُوَ اللَّهُ أَحَدٌ، وَالمُعَوِّذَتَيْنِ حِينَ تُمْسِي وَتُصْبِحُ ثَلَاثَ مَرَّاتٍ تَكْفِيكَ مِنْ\\nكُلِّ شَيْءٍ.” (سنن الترمذي ٣٥٧٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"He said","repeat_count":3,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/jealous/"},{"title":"Entrust All Your Matters to Allah","arabic":"يَا حَيُّ يَا قَيُّوْمُ ، بِرَحْمَتِكَ أَسْتَغِيْثُ ، أَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ ، وَلَا تَكِلْنِيْ إِلَىٰ نَفْسِيْ طَرْفَةَ عَيْنٍ.\\nأخبرنَا عبد الرَّحْمَن بن مُحَمَّد بن سَلام حَدثنَا زيد بن الْحباب أَخْبرنِي عُثْمَان بن موهب الْهَاشِمِي سَمِعت أنس بن مَالك يَقُول قَالَ النَّبِي صلى الله عليه وسلم لفاطمة مَا يمنعك أَن سَمْعِي مَا أوصيك بِهِ أَو تقولي إِذا أَصبَحت وَإِذا أمسيت يَا حَيّ يَا قيوم بِرَحْمَتك أستغيث أصلح لي شأني كلَّه وَلَا تَكِلنِي إِلَى نَفسِي طرفَة عين.","transliteration":"Yā Ḥayyu yā Qayyūm, bi-raḥmatika astaghīth, aṣliḥ lī sha’nī kullah, wa lā takilnī ilā nafsī ṭarfata ʿayn.","translation":"O The Ever Living, The Sustainer of all. ; I seek assistance through Your mercy. Rectify all of my affairs and do not entrust me to myself for the blink of an eye.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ʿanhu) narrates that the Prophet ﷺ said to Fāṭimah (raḍiy Allāhu ʿanhā), “What is preventing you from (doing) what I am advising you; that you say [the above] in the morning and evening?” (Nasā’ī in ʿAmal al-Yawm wa-l-Laylah 570)","reference":"(عمل اليوم والليلة للنسائي ٥٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/jealous/"},{"title":"Duʿa for Seeking Protection from Shaytan","arabic":"رَبِّ أَعُوْذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِيْنِ ، وَأَعُوذُ بِكَ رَبِّ أَنْ يَّحْضُرُوْنِ.","transliteration":"Rabbi aʿūdhu bika min hamazāti-sh-shayāṭīn. Wa aʿūdhu bika Rabbi ay-yaḥḍurūn.","translation":"My Lord, I seek protection with You from the promptings of the devils; and I seek protection in You, my Lord, from their coming near me. (23:97-98)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/jealous/"},{"title":"Becoming A Godly Person","arabic":"رَبِّ أَعِنِّيْ وَلَا تُعِنْ عَلَيَّ ، وَانْصُرْنِيْ وَلَا تَنْصُرْ عَلَيَّ ، وَامْكُرْ لِيْ وَلَا تَمْكُرْ عَلَيَّ ، وَاهْدِنِيْ وَيَسِّرِ الْهُدَىٰ لِيْ ، وَانْصُرْنِيْ عَلَىٰ مَنْ بَغَىٰ عَلَيَّ ، رَبِّ اجْعَلْنِيْ لَكَ شَكَّارًا ، لَكَ ذَكَّارًا ، لَكَ رَهَّابًا ، لَكَ مِطْوَاعًا ، لَكَ مُخْبِتًا ، إِلَيْكَ أَوَّاهًا مُّنِيْبًا ، رَبِّ تَقَبَّلْ تَوْبَتِيْ ، وَاغْسِلْ حَوْبَتِيْ ، وَأَجِبْ دَعْوَتِيْ ، وَثَبِّتْ حُجَّتِيْ ، وَسَدِّدْ لِسَانِيْ ، وَاهْدِ قَلْبِيْ ، وَاسْلُلْ سَخِيْمَةَ صَدْرِيْ","transliteration":"Rabbi aʿinnī wa lā tuʿin ʿalayya, wan-ṣurnī wa lā tanṣur ʿalayya, wa-mkur lī wa lā tamkur ʿalayya, wa-hdinī wa yas-siri-l-hudā lī, wan-ṣurnī ʿalā ma-m-baghā ʿalayya, Rabbi-j-ʿalnī laka shakkārā, laka dhak- kārā, laka rahhābā, laka miṭwāʿā, laka mukhbitā, ilayka aw-wāha-m-munībā, Rabbi taqabbal tawbatī, wa-ghsil ḥawbatī, wa ajib daʿwatī, wa thab-bit ḥujjatī, wa saddid lisānī, wahdi qalbī, waslul sakhīmata ṣadrī.","translation":"My Lord, help me and do not help others against me. Grant me victory and do not grant victory to others over me. Plan in my favour and do not plan for others against me. Guide me and ease guidance for me. Help me against those who oppress me. My Lord, make me one who is extremely grateful to You, who remembers you always, who perpetually fears You, who is fully obedient to You, who is humble before You, who constantly cries and pleads with You, and who repeatedly turns to You in repentance. My Lord, accept my repentance, wash away my sins, accept my supplications, strengthen my case, rectify my speech, guide my heart, and remove the malice from my heart.","description":null,"benefit":null,"virtue":null,"hadith":"Ibn ʿAbbās (raḍiy Allāhu ‘anhu) narrates that the Messenger of Allah ﷺ would supplicate with [the above]. (Tirmidhī 3551)","reference":"عَنْ ابْنِ عَبَّاسٍ، قَالَ: كَانَ النَّبِيُّ صلى الله عليه وسلم يَدْعُو يَقُولُ: رَبِّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ، وَانْصُرْنِي وَلَا تَنْصُرْ عَلَيَّ، وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ، وَاهْدِنِي وَيَسِّرِ الهُدَى لِي، وَانْصُرْنِي عَلَى مَنْ بَغَى عَلَيَّ، رَبِّ اجْعَلْنِي لَكَ شَكَّارًا، لَكَ ذَكَّارًا، لَكَ رَهَّابًا، لَكَ مِطْوَاعًا، لَكَ مُخْبِتًا، إِلَيْكَ أَوَّاهًا مُنِيبًا، رَبِّ تَقَبَّلْ تَوْبَتِي، وَاغْسِلْ حَوْبَتِي، وَأَجِبْ دَعْوَتِي، وَثَبِّتْ حُجَّتِي، وَسَدِّدْ لِسَانِي، وَاهْدِ قَلْبِي، وَاسْلُلْ سَخِيمَةَ صَدْرِي. (سنن الترمذي ٣٥٥١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/jealous/"},{"title":"Contentment & Allah’s Protection","arabic":"اَللّٰهُمَّ قَنِّعْنِيْ بِمَا رَزَقْتَنِيْ ، وَبَارِكْ لِيْ فِيْهِ ، وَاخْلُفْ عَلَيٰ كُلِّ غَائِبَةٍ لِّيْ بِخَيْرٍ","transliteration":"Allāhumma qanniʿnī bimā razaqtanī, wa bārik lī fīhī, wa-khluf ʿalā kulli ghā’ibati-l-lī bi-khayr.","translation":"O Allah, make me content with what You have granted me, bless me in it and be a protector for me in that which is absent from me (i.e. family and wealth).","description":null,"benefit":null,"virtue":null,"hadith":"Ibn ʿAbbās (radiy Allāhū ‘anhumā) narrates that the Prophet ﷺ would supplicate with [the above]. (Hākim 1878)","reference":"عَنِ ابْنِ عَبَّاسٍ، رضي الله عنهما، قَالَ: كَانَ النَّبِيُّ صلى الله عليه وسلم يَدْعُو يَقُولُ: اللَّهُمَّ ‌قَنِّعْنِي بِمَا رَزَقْتَنِي، وَبَارِكْ لِي فِيهِ، وَاخْلُفْ عَلَى كُلِّ غَائِبَةٍ لِي بِخَيْرٍ. (المستدرك على الصحيحين للحاكم ١٨٧٨)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/jealous/"}]},{"feeling":"Lazy","slug":"lazy","url":"https://allahuakbarofficial.com/lazy/","items_count":4,"duas":[{"title":"Protect Yourself From Anxiety, Laziness & Debt","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ ، وَأَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ ، وَأَعُوْذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.","transliteration":"Allāhumma innī aʿūdhu bika min-l-hammi wa-l-ḥazan, wa aʿūdhu bika min-l-ʿajzi wa-l-kasal, wa aʿūdhu bika min-l-jubni wa-l-bukhl, wa aʿūdhu bika min ghalabati-d-dayni wa qahri-r-rijāl.","translation":"O Allah, I seek Your protection from anxiety and grief. I seek Your protection from inability and laziness. I seek Your protection from cowardice and miserliness, and I seek Your protection from being overcome by debt and being overpowered by men.","description":null,"benefit":null,"virtue":"Abū Saʿīd al-Khudrī (raḍiy Allāhu ʿanhu) narrated that one day, the Messenger of Allah ﷺ entered the masjid. He saw a man from the Anṣār called Abū Umāmah (raḍiy Allāhu ʿanhu). He ﷺ asked, “What is the matter? Why are you sitting in the masjid when it is not the time for prayer?” He replied, “Never-ending worries and debts, O Messenger of Allah.” The Messenger of Allah ﷺ then asked, “Shall I not teach you words by which, when you say them, Allah will remove your worries, and settle your debts?” He replied, “Yes of course, O Messenger of Allah.” He ﷺ said, “Say in the morning and evening [the above].” Abū Umāmah (raḍiy Allāhu ʿanhu) said, “Then I did that, and Allah removed my worries and settled my debts.” (Abū Dāwūd 1555)","hadith":null,"reference":"عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: دَخَلَ رَسُولُ صَلَّى عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ مِنَ الْأَنْصَارِ، يُقَالُ لَهُ: أَبُو أُمَامَةَ، فَقَالَ: «يَا أُمَامَةَ، مَا لِي أَرَاكَ جَالِسًا فِي الْمَسْجِدِ فِي غَيْرِ وَقْتِ الصَّلَاةِ؟»، قَالَ: هُمُومٌ لَزِمَتْنِي، وَدُيُونٌ يَا رَسُولَ اللَّهِ، قَالَ: أَفَلَا أُعَلِّمُكَ كَلَامًا إِذَا أَنْتَ قُلْتَهُ أَذْهَبَ عز وجل هَمَّكَ، وَقَضَى عَنْكَ دَيْنَكَ؟، قَالَ: قُلْتُ: بَلَى، يَا رَسُولَ، قَالَ: ” قُلْ إِذَا أَصْبَحْتَ، وَإِذَا أَمْسَيْتَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَقَهْرِ الرِّجَالِ “، قَالَ: فَفَعَلْتُ ذَلِكَ، فَأَذْهَبَ اللَّهُ عز وجل هَمِّي، وَقَضَى عَنِّي دَيْنِي.\\n(سنن أبي داود ١٥٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lazy/"},{"title":"Ask Allah for Good Health and Protection","arabic":"اَللّٰهُمَّ عَافِنِيْ فِيْ بَدَنِيْ ، اَللّٰهُمَّ عَافِنِيْ فِيْ سَمْعِيْ ، اَللّٰهُمَّ عَافِنِيْ فِيْ بَصَرِيْ ، لَا إِلٰهَ إِلَّا أَنْتَ ، اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، وأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلٰهَ إِلَّا أَنْتَ.\\nعن جعفر بنِ ميمون ، حدَّثني عبدُ الرحمن بنُ أبي بكرَة، أنه قال لأبيه: يا أبةِ إني أَسمَعُكَ تَدْعُو كلَّ غَدَاةٍ: اللَّهُمَّ عافِني في بَدَني، اللهم عافِنِي في سَمْعِي، اللَّهُمَّ عافني في بَصَري، لا إلهَ إلا أنت، تُعيدها ثلاثاً حينَ تُصْبِحُ، وثلاثاً حينَ تُمسي، فقال: إني سمعتُ رسولَ الله صلى الله عليه وسلم -يدعو بهنَّ فانا أُحِبُّ أن أستَنَّ بسُنَّتِه، وقال عليٌّ وعباسٌ فيه: ويقول: اللهُمَّ إني أعوذُ بِكَ من الكُفر والفَقرِ، اللَّهُمَ إني أعُوذُ بِكَ مِن عذابِ القبر، لا إلهَ إلا أنتَ، يُعيدها ثلاثاً حِين يُصبحُ، وثلاثاً حين يُمسي، فيَدعُو بهِنَّ، فاُحِبُّ أن أستَنَّ بسُنتَّه.\\nحَدَّثَنَا أَبُو عَامِرٍ، حَدَّثَنَا عَبْدُ الْجَلِيلِ، حَدَّثَنِي جَعْفَرُ بْنُ مَيْمُونٍ، حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكَرَةَ أَنَّهُ قَالَ لِأَبِيهِ:","transliteration":"Allāhumma ʿāfinī fī badanī, Allāhumma ʿāfinī fī samʿī, Allāhumma ʿāfinī fī baṣarī, lā ilāha illā Ant, Allāhumma innī aʿūdhu bika mina-l-kufri wa-l-faqr, wa aʿūdhu bika min ʿadhābi-l-qabr, lā ilāha illā Ant.","translation":"Repeat. x3","description":null,"benefit":null,"virtue":null,"hadith":"‘Abd al-Raḥmān b. Abī Bakrah (raḍiy Allāhu ʿanhu) narrates that he said to his father, “O my father! I hear you supplicating with [the above] every morning. You repeat them three times in the morning and three times in the evening.” He said, “Indeed I heard the Messenger of Allah ﷺ supplicating with these (words) and I love to follow his practice.” (Abū Dāwūd 5090, Aḥmad 20430)","reference":"(سنن أبي داود ٥٠٩٠)\\nيَا أَبَهْ، إِنِّي أَسْمَعُك تَدْعُو كُلَّ غَدَاةٍ: ” اللهُمَّ عَافِنِي فِي بَدَنِي، اللهُمَّ عَافِنِي فِي سَمْعِي، اللهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ ” تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي. وَتَقُولُ: ” اللهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، اللهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ ” تُعِيدُهَا حِينَ تُصْبِحُ ثَلَاثًا، وَثَلَاثًا حِينَ تُمْسِي. قَالَ: نَعَمْ يَا بُنَيَّ، إِنِّي سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَدْعُو بِهِنَّ، فَأُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ. (مسند أحمد ٢٠٤٣٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"He said","repeat_count":3,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lazy/"},{"title":"Entrust All Your Matters to Allah","arabic":"يَا حَيُّ يَا قَيُّوْمُ ، بِرَحْمَتِكَ أَسْتَغِيْثُ ، أَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ ، وَلَا تَكِلْنِيْ إِلَىٰ نَفْسِيْ طَرْفَةَ عَيْنٍ.\\nأخبرنَا عبد الرَّحْمَن بن مُحَمَّد بن سَلام حَدثنَا زيد بن الْحباب أَخْبرنِي عُثْمَان بن موهب الْهَاشِمِي سَمِعت أنس بن مَالك يَقُول قَالَ النَّبِي صلى الله عليه وسلم لفاطمة مَا يمنعك أَن سَمْعِي مَا أوصيك بِهِ أَو تقولي إِذا أَصبَحت وَإِذا أمسيت يَا حَيّ يَا قيوم بِرَحْمَتك أستغيث أصلح لي شأني كلَّه وَلَا تَكِلنِي إِلَى نَفسِي طرفَة عين.","transliteration":"Yā Ḥayyu yā Qayyūm, bi-raḥmatika astaghīth, aṣliḥ lī sha’nī kullah, wa lā takilnī ilā nafsī ṭarfata ʿayn.","translation":"O The Ever Living, The Sustainer of all. ; I seek assistance through Your mercy. Rectify all of my affairs and do not entrust me to myself for the blink of an eye.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ʿanhu) narrates that the Prophet ﷺ said to Fāṭimah (raḍiy Allāhu ʿanhā), “What is preventing you from (doing) what I am advising you; that you say [the above] in the morning and evening?” (Nasā’ī in ʿAmal al-Yawm wa-l-Laylah 570)","reference":"(عمل اليوم والليلة للنسائي ٥٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lazy/"},{"title":"Protection from Evil Traits & Endings","arabic":"اَللّٰهُمَّ إِنّيْ أَعُوْذُ بِكَ مِنَ الْبُخْلِ ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ ، وَأَعُوْذُ بِكَ أَنْ أُرَدَّ إِلَىٰ أَرْذَلِ الْعُمُرِ ، وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا ، وَأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ.","transliteration":"Allāhumma innī aʿūdhu bika mina-l-bukhl, wa aʿūdhu bika mina-l-jubn, wa aʿūdhu bika an uradda ilā ardhali-l-ʿumur, wa aʿūdhu bika min fitnati-d-dunyā, wa aʿūdhu bika min ʿadhābi-l-qabr.","translation":"O Allah, I seek Your protection from miserliness and I seek Your protection from cowardice. I seek Your protection from being returned to the worst part of life (old age), I seek Your protection from the trials of the world, and I seek Your protection from the punishment of the grave.","description":null,"benefit":null,"virtue":null,"hadith":"Saʿd b. Abī Waqqās (radiy Allāhū ‘anhu) would instruct (to seek refuge) about five things [the above] and he would narrate it from the Messenger of Allah ﷺ . (Bukhārī 6370)","reference":"عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رضي الله عنه كَانَ يَأْمُرُ بِهَؤُلَاءِ الْخَمْسِ وَيُحَدِّثُهُنَّ عَنِ النَّبِيِّ صلى الله عليه وسلم: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبُخْلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ. (صحيح البخاري ٦٣٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lazy/"}]},{"feeling":"Lost","slug":"lost","url":"https://allahuakbarofficial.com/lost/","items_count":7,"duas":[{"title":"Surah al-Fatihah: The Greatest Duʿa","arabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيْمِ ،\\nاَلْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِيْنَ ، الرَّحْمٰنِ الرَّحِيْمِ ، مٰلِكِ يَوْمِ الدِّيْنِ ، إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِيْنُ ، اِهْدِنَا الصِّرَاطَ الْمُسْتَقِيْمَ ، صِرَاطَ الَّذِيْنَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوْبِ عَلَيْهِمْ وَلَا الضَّآلِّيْنَ.","transliteration":"Bismi-llāhi-r-Raḥmāni-r-Raḥīm. Alḥamdu-lillāhi Rabbi-l-ʿālamīn, ar-Raḥmāni-r-Raḥīm, Māliki yawmi-d-dīn, iyyāka naʿbudu wa iyyāka nastaʿīn, ihdina-ṣ-Ṣirāṭa-l-Mustaqīm, ṣirāṭa-lladhīna anʿamta ʿalayhim ghayri-l-maghḍūbi ʿālayhim wa la-ḍ-ḍāllīn.","translation":"In the name of Allah, the All-Merciful, the Very Merciful. All praises and thanks are for Allah, the Lord of all the worlds, The All-Merciful, The Very Merciful, Master of the Day of Judgement. You Alone we worship, You Alone we ask for help. Guide us on the Straight Path, the path of those whom You have favoured, not of those who incur (Your) anger nor of those who have gone astray. (1:1-7)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lost/"},{"title":"Protection From The Anguish of the World & Hereafter","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنْ ضِيْقِ الدُّنْيَا وَضِيْقِ يَوْمِ الْقِيَامَةِ.","transliteration":"Allāhumma innī aʿūdhu bika min ḍīqi-d-dunyā wa ḍīqi yawmi-l-qiyāmah.","translation":"O Allah, I seek Your protection from the anguish of the world and the anguish of the Day of Judgement.","description":null,"benefit":null,"virtue":null,"hadith":"Sharīq al-Hawzānī (raḥimahullāh) narrates that I entered upon Aisha (raḍiy Allāhu ‘anhā) and I asked her: “With which supplication did the Messenger of Allah ﷺ begin his Salāh when he woke up at night?” She replied: “You have asked me regarding something which no one has asked me before.” When he woke up at night, he uttered: Allāhu Akbar (Allah is the Greatest) ten times, and uttered Alḥamdullillāh (All praise be to Allah) ten times, and said Subḥāna-llāhi wa bi ḥamdih. (Allah is free from imperfection, and all praise is due to Him.) ten times, and said: Subḥānal Malik al-Quddūs (How perfect is the Sovereign, the Most Holy) ten times, and asked Allah’s forgiveness ten times, and said: “There is no god but Allah” ten times, and then said: [the above] ten times. He then began the Salāh. (Abū Dāwūd 5085)","reference":"عَنْ عُمَرَ بْنِ جُعْثُمٍ قَالَ: نَا الْأَزْهَرُ بْنُ عَبْدِ اللهِ الْحَرَازِيُّ قَالَ: حَدَّثَنِي شَرِيقٌ الْهَوْزَنِيُّ قَالَ: «دَخَلْتُ عَلَى عَائِشَةَ فَسَأَلْتُهَا بِمَ كَانَ رَسُولُ اللهِ صلى الله عليه وسلم يَفْتَتِحُ إِذَا هَبَّ مِنَ اللَّيْلِ، فَقَالَتْ: لَقَدْ سَأَلْتَنِي عَنْ شَيْءٍ مَا سَأَلَنِي عَنْهُ أَحَدٌ قَبْلَكَ، كَانَ إِذَا هَبَّ مِنَ اللَّيْلِ كَبَّرَ عَشْرًا وَحَمِدَ عَشْرًا وَقَالَ: سُبْحَانَ اللهِ وَبِحَمْدِهِ عَشْرًا وَقَالَ: سُبْحَانَ الْمَلِكِ الْقُدُّوسِ عَشْرًا وَاسْتَغْفَرَ عَشْرًا، وَهَلَّلَ عَشْرًا، ثُمَّ قَالَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ضِيقِ الدُّنْيَا، وَضِيقِ يَوْمِ الْقِيَامَةِ عَشْرًا ثُمَّ يَفْتَتِحُ الصَّلَاةَ.\\n(سنن ابي دادد ٥٠٨٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lost/"},{"title":"Allah Will Suffice You in Everything","arabic":"حَسْبِيَ اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ ، عَلَيْهِ تَوَكَّلْتُ ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ.","transliteration":"Ḥasbiya-Allāhu lā ilāha illā Huwa, ʿalayhi tawakkalt, wa Huwa Rabbu-l-ʿArshi-l-ʿaẓīm.","translation":"Repeat. x7","description":null,"benefit":null,"virtue":"Abū al-Dardā’ (raḍiy Allāhu ʿanhu) narrates from the Messenger of Allah ﷺ that he said: “Whoever recites [the above] seven times in the morning and in the evening, Allah will suffice him in everything that concerns him in matters of this world and the next.” (Ibn al-Sunnī 71)","hadith":null,"reference":"عَنْ أَبِي الدَّرْدَاءِ، رضي الله عنه، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ: مَنْ قَالَ فِي كُلِّ يَوْمٍ حِينَ يُصْبِحُ وَحِينَ يُمْسِي: حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ، سَبْعَ مَرَّاتٍ، كَفَاهُ اللَّهُ عز وجل هَمَّهُ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ. (عمل اليوم والليلة لابن السني ٧١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":7,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lost/"},{"title":"Duʿa of Prophet Musa ﷺ Expressing His Dire Need","arabic":"رَبِّ إِنِّيْ لِمَآ أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيْرٌ.","transliteration":"Rabbi innī limā anzalta illayya min khayrin faqīr.","translation":"My Lord, truly I am in dire need of any good which You may send me. (28:24)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lost/"},{"title":"Entrust All Your Matters to Allah","arabic":"يَا حَيُّ يَا قَيُّوْمُ ، بِرَحْمَتِكَ أَسْتَغِيْثُ ، أَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ ، وَلَا تَكِلْنِيْ إِلَىٰ نَفْسِيْ طَرْفَةَ عَيْنٍ.\\nأخبرنَا عبد الرَّحْمَن بن مُحَمَّد بن سَلام حَدثنَا زيد بن الْحباب أَخْبرنِي عُثْمَان بن موهب الْهَاشِمِي سَمِعت أنس بن مَالك يَقُول قَالَ النَّبِي صلى الله عليه وسلم لفاطمة مَا يمنعك أَن سَمْعِي مَا أوصيك بِهِ أَو تقولي إِذا أَصبَحت وَإِذا أمسيت يَا حَيّ يَا قيوم بِرَحْمَتك أستغيث أصلح لي شأني كلَّه وَلَا تَكِلنِي إِلَى نَفسِي طرفَة عين.","transliteration":"Yā Ḥayyu yā Qayyūm, bi-raḥmatika astaghīth, aṣliḥ lī sha’nī kullah, wa lā takilnī ilā nafsī ṭarfata ʿayn.","translation":"O The Ever Living, The Sustainer of all. ; I seek assistance through Your mercy. Rectify all of my affairs and do not entrust me to myself for the blink of an eye.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ʿanhu) narrates that the Prophet ﷺ said to Fāṭimah (raḍiy Allāhu ʿanhā), “What is preventing you from (doing) what I am advising you; that you say [the above] in the morning and evening?” (Nasā’ī in ʿAmal al-Yawm wa-l-Laylah 570)","reference":"(عمل اليوم والليلة للنسائي ٥٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lost/"},{"title":"Asking for Good & Protection From Evil","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ ، وَأَعُوْذُ بِكَ مِنَ الشَّرِّ كُلِّهِ عَاجِلِهِ وَآجِلِهِ ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ عَبْدُكَ وَنَبِيُّكَ ، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا عَاذَ مِنْهُ عَبْدُكَ وَنَبِيُّكَ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْجَنَّةَ ، وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ ، وَأَعُوْذُ بِكَ مِنَ النَّارِ ، وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ ، وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ قَضَيْتَهُ لِيْ خَيْرًا","transliteration":"Allāhumma innī as’aluka mina-l-khayri kullihī ʿājilihī wa ājilih, mā ʿalimtu minhu wa mā lam aʿlam, wa aʿūdhu bika mina-sh-sharri kullih ʿājilihī wa ājilih, mā ʿalimtu minhu wa mā lam aʿlam, Allāhumma innī as’aluka min khayri mā sa’alaka ʿabduka wa Nabiyyuk, wa aʿūdhu bika min sharri mā ʿādha minhu ʿabduka wa Nabiyyuk, Allāhumma innī as’aluka-l-Jannah, wa mā qarraba ilayhā min qawlin aw ʿamal, wa aʿūdhu bika mina-n-nār, wa mā qarraba ilayhā min qawlin aw ʿamal, wa as’aluka an tajʿala kulla qaḍā’in qaḍaytahū lī khayrā.","translation":"O Allah, I beg You for all good: the immediate and the delayed, what I know of and what I do not know. I seek Your protection from all evil: the immediate and the delayed, what I know of and what I do not know. O Allah, I beg You for the good which Your slave and Prophet ﷺ asked from You, and I seek Your protection from the evil which Your slave and Prophet ﷺ sought protection for from You. O Allah, I beg You for Paradise, and whatever words or actions lead to it. I seek Your protection from Hell-fire, and whatever words or actions lead to it. I ask You to decree good for me in everything You foreordain for me.","description":null,"benefit":null,"virtue":null,"hadith":"‘Āishah narrates that the Messenger of Allah ﷺ taught her [the above]. (Ahmad 25019)","reference":"عَنْ عَائِشَةَ أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم عَلَّمَهَا هَذَا الدُّعَاءَ: اللهُمَّ إِنِّي أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، وَأَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ، وَمَا لَمْ أَعْلَمْ، اللهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ عَبْدُكَ وَنَبِيُّكَ مُحَمَّدٌ صلى الله عليه وسلم، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا عَاذَ مِنْهُ عَبْدُكَ وَنَبِيُّكَ، اللهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَعُوذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ تَقْضِيهِ لِي خَيْرًا.\\n(مسند احمد ٢٥٠١٩)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lost/"},{"title":"Goodness in Din, Dunya & the Hereafter","arabic":"اَللّٰهُمَّ أَصْلِحْ لِيْ دِيْنِيَ الَّذِيْ هُوَ عِصْمَةُ أَمْرِيْ ، وَأَصْلِحْ لِيْ دُنْيَايَ الَّتِيْ فِيْهَا مَعَاشِيْ ، وَأَصْلِحْ لِيْ آخِرَتِيَ الَّتِيْ فِيْهَا مَعَادِيْ ، وَاجْعَلِ الْحَيَاةَ زِيَادَةً لِّيْ فِيْ كُلِّ خَيْرٍ ، وَاجْعَلِ الْمَوْتَ رَاحَةً لِّيْ مِنْ كُلِّ شَرٍّ","transliteration":"Allāhumma aṣliḥ lī dīniya-l-ladhī huwa ʿiṣmatu amrī, wa aṣliḥ lī dunyāya-l-latī fīhā maʿāshī, wa aṣliḥ lī ākhiratiya-l-latī fīhā maʿādī, wa-jʿali-l-ḥayāta ziyādata-l-lī fī kulli khayr, wa-jʿali-l-mawta rāḥata-l-lī min kulli sharr.","translation":"O Allah, rectify my religion for me which is the protection of my affairs. Rectify my world for me wherein is my livelihood. Rectify my hereafter for me, to which is my return. Make my life a means of increase for me in every good, and make death a respite for me from every evil.","description":null,"benefit":null,"virtue":null,"hadith":"Abū Hurayrah (raḍiy Allāhu ‘anhu) mentions that the Messenger of Allah ﷺ would say (supplicate): [the above]. (Muslim 2720)","reference":"عَنْ أَبِي هُرَيْرَةَ. قال كان رسول الله صلى الله عليه وسلم يقول “اللهم! أصلح لي ديني الذي هو عصمة أمري. وأصلح لي دنياي التي فيها معاشي. وأصلح لي آخرتي التي فيها معادي. واجعل الحياة زيادة لي في كل خير. واجعل الموت راحة لي من كل شر. (صحيح مسلم ٢٧٢٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lost/"}]},{"feeling":"Lonely","slug":"lonely","url":"https://allahuakbarofficial.com/lonely/","items_count":9,"duas":[{"title":"Protect Yourself From Anxiety, Laziness & Debt","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ ، وَأَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ ، وَأَعُوْذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.","transliteration":"Allāhumma innī aʿūdhu bika min-l-hammi wa-l-ḥazan, wa aʿūdhu bika min-l-ʿajzi wa-l-kasal, wa aʿūdhu bika min-l-jubni wa-l-bukhl, wa aʿūdhu bika min ghalabati-d-dayni wa qahri-r-rijāl.","translation":"O Allah, I seek Your protection from anxiety and grief. I seek Your protection from inability and laziness. I seek Your protection from cowardice and miserliness, and I seek Your protection from being overcome by debt and being overpowered by men.","description":null,"benefit":null,"virtue":"Abū Saʿīd al-Khudrī (raḍiy Allāhu ʿanhu) narrated that one day, the Messenger of Allah ﷺ entered the masjid. He saw a man from the Anṣār called Abū Umāmah (raḍiy Allāhu ʿanhu). He ﷺ asked, “What is the matter? Why are you sitting in the masjid when it is not the time for prayer?” He replied, “Never-ending worries and debts, O Messenger of Allah.” The Messenger of Allah ﷺ then asked, “Shall I not teach you words by which, when you say them, Allah will remove your worries, and settle your debts?” He replied, “Yes of course, O Messenger of Allah.” He ﷺ said, “Say in the morning and evening [the above].” Abū Umāmah (raḍiy Allāhu ʿanhu) said, “Then I did that, and Allah removed my worries and settled my debts.” (Abū Dāwūd 1555)","hadith":null,"reference":"عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: دَخَلَ رَسُولُ صَلَّى عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ مِنَ الْأَنْصَارِ، يُقَالُ لَهُ: أَبُو أُمَامَةَ، فَقَالَ: «يَا أُمَامَةَ، مَا لِي أَرَاكَ جَالِسًا فِي الْمَسْجِدِ فِي غَيْرِ وَقْتِ الصَّلَاةِ؟»، قَالَ: هُمُومٌ لَزِمَتْنِي، وَدُيُونٌ يَا رَسُولَ اللَّهِ، قَالَ: أَفَلَا أُعَلِّمُكَ كَلَامًا إِذَا أَنْتَ قُلْتَهُ أَذْهَبَ عز وجل هَمَّكَ، وَقَضَى عَنْكَ دَيْنَكَ؟، قَالَ: قُلْتُ: بَلَى، يَا رَسُولَ، قَالَ: ” قُلْ إِذَا أَصْبَحْتَ، وَإِذَا أَمْسَيْتَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَقَهْرِ الرِّجَالِ “، قَالَ: فَفَعَلْتُ ذَلِكَ، فَأَذْهَبَ اللَّهُ عز وجل هَمِّي، وَقَضَى عَنِّي دَيْنِي.(سنن أبي داود ١٥٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lonely/"},{"title":"Grief & Anxiety #1","arabic":"اَللّٰهُمَّ إِنِّيْ عَبْدُكَ ، وَابْنُ عَبْدِكَ ، وَابْنُ أَمَتِكَ ، نَاصِيَتِيْ بِيَدِكَ ، مَاضٍ فِيَّ حُكْمُكَ ، عَدْلٌ فِيَّ قَضَاؤُكَ ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ ، سَمَّيْتَ بِهِ نَفْسَكَ ، أَوْ عَلَّمْتَهُ أَحَدًا مِّنْ خَلْقِكَ ، أَوْ أَنْزَلْتَهُ فِيْ كِتَابِكَ ، أَوِ اسْتَأْثَرْتَ بِهِ فِيْ عِلْمِ الْغَيْبِ عِنْدَكَ ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيْعَ قَلْبِيْ ، وَنُوْرَ صَدْرِيْ ، وَجَلَاءَ حُزْنِيْ ، وَذَهَابَ هَمِّيْ","transliteration":"Allāhumma innī ʿabduk, wa-bnu ʿabdik, wa-bnu amatik, nāṣiyatī bi-yadik, māḍin fiyya ḥukmuk, ʿadlun fiyya qaḍā’uk, as’aluka bi-kulli-smin huwa lak, sammayta bihī nafsak, aw ʿallamtahū aḥadam-min khalqik, aw anzaltahū fī kitābik, awi-sta’tharta bihī fī ʿilmi-l-ghaybi ʿindak, an tajʿala-l-Qur’āna rabīʿa qalbī, wa nūra ṣadrī, wa jalā’a ḥuznī, wa dha-hāba hammī.","translation":"O Allah, I am Your servant and the son of Your male servant and the son of Your female servant. My forehead is in Your Hand (i.e. you have control over me). I am subject to Your judgement and Your decree concerning me is just. I ask You – by every name that is Yours, by which You have named Yourself, or taught any one of Your creation, or revealed in Your Book, or kept unto Yourself in the knowledge of the unseen that is with You – to make the Qur’ān the spring of my heart, the light of my chest, the banisher of my grief and the reliever of my anxiety.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “There is no one who is stricken with grief and anxiety, and then says [the above] — except that Allah will remove his grief and anxiety, and will give him joy instead.” The Companions asked, ‘O Messenger of Allah, should we not learn these words?’ He ﷺ replied, ‘Certainly! The one who hears them should learn them.’” (Ahmad 3712)","hadith":null,"reference":"عَنْ عَبْدِ اللهِ، قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: مَا أَصَابَ أَحَدًا قَطُّ هَمٌّ وَلَا حَزَنٌ، فَقَالَ: اللهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجِلَاءَ حُزْنِي، وَذَهَابَ هَمِّي، إِلَّا أَذْهَبَ اللهُ هَمَّهُ وَحُزْنَهُ، وَأَبْدَلَهُ مَكَانَهُ فَرَحًا، قَالَ: فَقِيلَ: يَا رَسُولَ اللهِ، أَلَا نَتَعَلَّمُهَا؟ فَقَالَ: بَلَى، يَنْبَغِي لِمَنْ سَمِعَهَا أَنْ يَتَعَلَّمَهَا. (مسند أحمد ٣٧١٢)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lonely/"},{"title":"Grief & Anxiety #2","arabic":"لَا إِلٰهَ إِلَّا اللّٰهُ الْعَظِيْمُ الْحَلِيْمُ ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ الْعَرْشِ الْعَظِيْمِ ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ السَّمٰـوٰتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيْمِ\\nعَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ:كَانَ النَّبِيُّ صلى الله عليه وسلم يَدْعُو عِنْدَ الْكَرْبِ: لَا إِلَهَ إِلَّا اللهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللهُ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ رَبُّ الْعَرْشِ الْعَظِيمِ.","transliteration":"Lā ilāha illā-llāhu-l-ʿĀẓīmu-l-Ḥalīm, lā ilāha illā-llāhu Rabbu-l-ʿĀrshi-l-ʿAẓīm, lā ilāha illā-llāhu Rabbu-s-samāwāti wa Rabbu-l-arḍi wa Rabbu-l-ʿĀrshi-l-karīm.","translation":"There is no god worthy of worship except Allah — the Supreme, the Forbearing. There is no god worthy of worship except Allah — Lord of the Magnificent Throne. There is no god worthy of worship except Allah — Lord of the heavens, Lord of the earth, and Lord of the Noble Throne.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ used to supplicate with [the above] in times of distress. (Bukhārī 6345, Muslim 2730)","reference":"(صحيح البخاري ٦٣٤٥)\\nعَنِ ابْنِ عَبَّاسٍ؛ أَنَّ نبي الله صلى الله عليه وسلم كان يقول عند الكرب “لا إله إلا الله العظيم الحليم. لا إله إلا الله رب العرش العظيم. لا إله إلا الله رب السماوات ورب الأرض ورب العرش الكريم. (صحيح مسلم ٢٧٣٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lonely/"},{"title":"When One Is Afraid of People #2","arabic":"حَسْبُنَا اللّٰهُ وَنِعْمَ الْوَكِيْلُ","transliteration":"Ḥasbunallāhu wa niʿmal Wakīl.","translation":"Allah is enough for us and He is the Best Protector.","description":null,"benefit":null,"virtue":null,"hadith":"Ibn ʿAbbās (radiy Allāhū ʿanhumā) narrated: “[The above] was said by Ibrāhīm (ʿalayhis-salām) when he was thrown into the fire; and it was said by Muḥammad ﷺ when (the hypocrites) said, ‘Your enemies have mobilised their forces against you, so fear them,’ — but this only increased them in faith and they replied: ‘Allah is enough for us and He is the Best Protector (3:173).’” (Bukhārī 4563)","reference":"عَنِ ابْنِ عَبَّاسٍ : حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ} قَالَهَا إِبْرَاهِيمُ عليه السلام حِينَ أُلْقِيَ فِي النَّارِ، وَقَالَهَا مُحَمَّدٌ صلى الله عليه وسلم حِينَ قَالُوا: إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ. (صحيح البخاري ٤٥٦٣)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lonely/"},{"title":"Protection From The Anguish of the World & Hereafter","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنْ ضِيْقِ الدُّنْيَا وَضِيْقِ يَوْمِ الْقِيَامَةِ.","transliteration":"Allāhumma innī aʿūdhu bika min ḍīqi-d-dunyā wa ḍīqi yawmi-l-qiyāmah.","translation":"O Allah, I seek Your protection from the anguish of the world and the anguish of the Day of Judgement.","description":null,"benefit":null,"virtue":null,"hadith":"Sharīq al-Hawzānī (raḥimahullāh) narrates that I entered upon Aisha (raḍiy Allāhu ‘anhā) and I asked her: “With which supplication did the Messenger of Allah ﷺ begin his Salāh when he woke up at night?” She replied: “You have asked me regarding something which no one has asked me before.” When he woke up at night, he uttered: Allāhu Akbar (Allah is the Greatest) ten times, and uttered Alḥamdullillāh (All praise be to Allah) ten times, and said Subḥāna-llāhi wa bi ḥamdih. (Allah is free from imperfection, and all praise is due to Him.) ten times, and said: Subḥānal Malik al-Quddūs (How perfect is the Sovereign, the Most Holy) ten times, and asked Allah’s forgiveness ten times, and said: “There is no god but Allah” ten times, and then said: [the above] ten times. He then began the Salāh. (Abū Dāwūd 5085)","reference":"عَنْ عُمَرَ بْنِ جُعْثُمٍ قَالَ: نَا الْأَزْهَرُ بْنُ عَبْدِ اللهِ الْحَرَازِيُّ قَالَ: حَدَّثَنِي شَرِيقٌ الْهَوْزَنِيُّ قَالَ: «دَخَلْتُ عَلَى عَائِشَةَ فَسَأَلْتُهَا بِمَ كَانَ رَسُولُ اللهِ صلى الله عليه وسلم يَفْتَتِحُ إِذَا هَبَّ مِنَ اللَّيْلِ، فَقَالَتْ: لَقَدْ سَأَلْتَنِي عَنْ شَيْءٍ مَا سَأَلَنِي عَنْهُ أَحَدٌ قَبْلَكَ، كَانَ إِذَا هَبَّ مِنَ اللَّيْلِ كَبَّرَ عَشْرًا وَحَمِدَ عَشْرًا وَقَالَ: سُبْحَانَ اللهِ وَبِحَمْدِهِ عَشْرًا وَقَالَ: سُبْحَانَ الْمَلِكِ الْقُدُّوسِ عَشْرًا وَاسْتَغْفَرَ عَشْرًا، وَهَلَّلَ عَشْرًا، ثُمَّ قَالَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ضِيقِ الدُّنْيَا، وَضِيقِ يَوْمِ الْقِيَامَةِ عَشْرًا ثُمَّ يَفْتَتِحُ الصَّلَاةَ.\\n(سنن ابي دادد ٥٠٨٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lonely/"},{"title":"Allah Will Suffice You in Everything","arabic":"حَسْبِيَ اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ ، عَلَيْهِ تَوَكَّلْتُ ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ.","transliteration":"Ḥasbiya-Allāhu lā ilāha illā Huwa, ʿalayhi tawakkalt, wa Huwa Rabbu-l-ʿArshi-l-ʿaẓīm.","translation":"Allah is sufficient for me. There is no god worthy of worship except Him. I have placed my trust in Him only and He is the Lord of the Magnificent Throne.","description":null,"benefit":null,"virtue":"Abū al-Dardā’ (raḍiy Allāhu ʿanhu) narrates from the Messenger of Allah ﷺ that he said: “Whoever recites [the above] seven times in the morning and in the evening, Allah will suffice him in everything that concerns him in matters of this world and the next.” (Ibn al-Sunnī 71)","hadith":null,"reference":"عَنْ أَبِي الدَّرْدَاءِ، رضي الله عنه، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ: مَنْ قَالَ فِي كُلِّ يَوْمٍ حِينَ يُصْبِحُ وَحِينَ يُمْسِي: حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ، سَبْعَ مَرَّاتٍ، كَفَاهُ اللَّهُ عز وجل هَمَّهُ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ. (عمل اليوم والليلة لابن السني ٧١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lonely/"},{"title":"Duʿa of Prophet Musa ﷺ Expressing His Dire Need","arabic":"رَبِّ إِنِّيْ لِمَآ أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيْرٌ.","transliteration":"Rabbi innī limā anzalta illayya min khayrin faqīr.","translation":"My Lord, truly I am in dire need of any good which You may send me. (28:24)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lonely/"},{"title":"Entrust All Your Matters to Allah","arabic":"يَا حَيُّ يَا قَيُّوْمُ ، بِرَحْمَتِكَ أَسْتَغِيْثُ ، أَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ ، وَلَا تَكِلْنِيْ إِلَىٰ نَفْسِيْ طَرْفَةَ عَيْنٍ.\\nأخبرنَا عبد الرَّحْمَن بن مُحَمَّد بن سَلام حَدثنَا زيد بن الْحباب أَخْبرنِي عُثْمَان بن موهب الْهَاشِمِي سَمِعت أنس بن مَالك يَقُول قَالَ النَّبِي صلى الله عليه وسلم لفاطمة مَا يمنعك أَن سَمْعِي مَا أوصيك بِهِ أَو تقولي إِذا أَصبَحت وَإِذا أمسيت يَا حَيّ يَا قيوم بِرَحْمَتك أستغيث أصلح لي شأني كلَّه وَلَا تَكِلنِي إِلَى نَفسِي طرفَة عين.","transliteration":"Yā Ḥayyu yā Qayyūm, bi-raḥmatika astaghīth, aṣliḥ lī sha’nī kullah, wa lā takilnī ilā nafsī ṭarfata ʿayn.","translation":"O The Ever Living, The Sustainer of all. ; I seek assistance through Your mercy. Rectify all of my affairs and do not entrust me to myself for the blink of an eye.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ʿanhu) narrates that the Prophet ﷺ said to Fāṭimah (raḍiy Allāhu ʿanhā), “What is preventing you from (doing) what I am advising you; that you say [the above] in the morning and evening?” (Nasā’ī in ʿAmal al-Yawm wa-l-Laylah 570)","reference":"(عمل اليوم والليلة للنسائي ٥٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lonely/"},{"title":"Protection from Evil Traits & Endings","arabic":"اَللّٰهُمَّ إِنّيْ أَعُوْذُ بِكَ مِنَ الْبُخْلِ ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ ، وَأَعُوْذُ بِكَ أَنْ أُرَدَّ إِلَىٰ أَرْذَلِ الْعُمُرِ ، وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا ، وَأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ.","transliteration":"Allāhumma innī aʿūdhu bika mina-l-bukhl, wa aʿūdhu bika mina-l-jubn, wa aʿūdhu bika an uradda ilā ardhali-l-ʿumur, wa aʿūdhu bika min fitnati-d-dunyā, wa aʿūdhu bika min ʿadhābi-l-qabr.","translation":"O Allah, I seek Your protection from miserliness and I seek Your protection from cowardice. I seek Your protection from being returned to the worst part of life (old age), I seek Your protection from the trials of the world, and I seek Your protection from the punishment of the grave.","description":null,"benefit":null,"virtue":null,"hadith":"Saʿd b. Abī Waqqās (radiy Allāhū ‘anhu) would instruct (to seek refuge) about five things [the above] and he would narrate it from the Messenger of Allah ﷺ . (Bukhārī 6370)","reference":"عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رضي الله عنه كَانَ يَأْمُرُ بِهَؤُلَاءِ الْخَمْسِ وَيُحَدِّثُهُنَّ عَنِ النَّبِيِّ صلى الله عليه وسلم: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبُخْلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ. (صحيح البخاري ٦٣٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/lonely/"}]},{"feeling":"Nervous","slug":"nervous","url":"https://allahuakbarofficial.com/nervous/","items_count":7,"duas":[{"title":"Protect Yourself From Anxiety, Laziness & Debt","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ ، وَأَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ ، وَأَعُوْذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.","transliteration":"Allāhumma innī aʿūdhu bika min-l-hammi wa-l-ḥazan, wa aʿūdhu bika min-l-ʿajzi wa-l-kasal, wa aʿūdhu bika min-l-jubni wa-l-bukhl, wa aʿūdhu bika min ghalabati-d-dayni wa qahri-r-rijāl.","translation":"O Allah, I seek Your protection from anxiety and grief. I seek Your protection from inability and laziness. I seek Your protection from cowardice and miserliness, and I seek Your protection from being overcome by debt and being overpowered by men.","description":null,"benefit":null,"virtue":"Abū Saʿīd al-Khudrī (raḍiy Allāhu ʿanhu) narrated that one day, the Messenger of Allah ﷺ entered the masjid. He saw a man from the Anṣār called Abū Umāmah (raḍiy Allāhu ʿanhu). He ﷺ asked, “What is the matter? Why are you sitting in the masjid when it is not the time for prayer?” He replied, “Never-ending worries and debts, O Messenger of Allah.” The Messenger of Allah ﷺ then asked, “Shall I not teach you words by which, when you say them, Allah will remove your worries, and settle your debts?” He replied, “Yes of course, O Messenger of Allah.” He ﷺ said, “Say in the morning and evening [the above].” Abū Umāmah (raḍiy Allāhu ʿanhu) said, “Then I did that, and Allah removed my worries and settled my debts.” (Abū Dāwūd 1555)","hadith":null,"reference":"عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: دَخَلَ رَسُولُ صَلَّى عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ مِنَ الْأَنْصَارِ، يُقَالُ لَهُ: أَبُو أُمَامَةَ، فَقَالَ: «يَا أُمَامَةَ، مَا لِي أَرَاكَ جَالِسًا فِي الْمَسْجِدِ فِي غَيْرِ وَقْتِ الصَّلَاةِ؟»، قَالَ: هُمُومٌ لَزِمَتْنِي، وَدُيُونٌ يَا رَسُولَ اللَّهِ، قَالَ: أَفَلَا أُعَلِّمُكَ كَلَامًا إِذَا أَنْتَ قُلْتَهُ أَذْهَبَ عز وجل هَمَّكَ، وَقَضَى عَنْكَ دَيْنَكَ؟، قَالَ: قُلْتُ: بَلَى، يَا رَسُولَ، قَالَ: ” قُلْ إِذَا أَصْبَحْتَ، وَإِذَا أَمْسَيْتَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَقَهْرِ الرِّجَالِ “، قَالَ: فَفَعَلْتُ ذَلِكَ، فَأَذْهَبَ اللَّهُ عز وجل هَمِّي، وَقَضَى عَنِّي دَيْنِي.(سنن أبي داود ١٥٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/nervous/"},{"title":"Attain Well-being in This World and the Hereafter","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِيْ دِيْنِيْ وَدُنْيَايَ وَأَهْلِيْ وَمَالِيْ ، اَللّٰهُمَّ اسْتُرْ عَوْرَاتِيْ وَآمِنْ رَّوْعَاتِيْ ، اَللّٰهُمَّ احْفَظْنِيْ مِنْ بَيْنِ يَدَيَّ ، وَمِنْ خَلْفِيْ ، وَعَنْ يَّمِيْنِيْ ، وَعَنْ شِمَالِيْ ، وَمِنْ فَوْقِيْ ، وَأَعُوْذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِيْ.","transliteration":"Allāhumma innī as’aluka-l-ʿāfiyata fi-d-dunyā wa-l-ākhirah. Allāhumma innī as’aluka-l-ʿafwa wa-l-ʿāfiyata fī dīnī wa dunyāya wa ahlī wa mālī, Allāhumma-stur ʿawrātī wa āmi-r-rawʿātī. Allāhumma-ḥfaẓnī mim bayni yadayya wa min khalfī, wa ʿay-yamīnī wa ʿan shimālī wa min fawqī, wa aʿūdhu bi-ʿaẓamatika an ughtāla min taḥtī.","translation":"O Allah, I ask You for well-being in this world and the next. O Allah, I ask You for forgiveness and well-being in my religion, in my worldly affairs, in my family and in my wealth. O Allah, conceal my faults and calm my fears. O Allah, guard me from in front of me and behind me, from my right, and from my left, and from above me. I seek protection in Your Greatness from being unexpectedly destroyed from beneath me.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “Ask Allah for forgiveness and well-being (‘āfiyah). Indeed, after conviction (yaqīn), no one has been granted anything better than well-being.” (Tirmidhī)","hadith":"ʿAbdullāh b. ʿUmar (raḍiy Allāhu ʿanhumā) narrated: “The Messenger of Allah ﷺ never failed to say these words in the morning and in the evening.” (Abū Dāwūd 5074)","reference":"عَنْ جُبَيْرِ بْنِ أَبِي سُلَيْمَانَ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ، قَالَ: سَمِعْتُ ابْنَ عُمَرَ، يَقُولُ: لَمْ يَكُنْ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَعُ هَؤُلَاءِ الدَّعَوَاتِ، حِينَ يُمْسِي، وَحِينَ يُصْبِحُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَتِي، وَقَالَ عُثْمَانُ: عَوْرَاتِي وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي.(سنن أبي داود ٥٠٧٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/nervous/"},{"title":"Allah Will Suffice You in Everything","arabic":"حَسْبِيَ اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ ، عَلَيْهِ تَوَكَّلْتُ ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ.","transliteration":"Ḥasbiya-Allāhu lā ilāha illā Huwa, ʿalayhi tawakkalt, wa Huwa Rabbu-l-ʿArshi-l-ʿaẓīm.","translation":"Repeat. x7","description":null,"benefit":null,"virtue":"Abū al-Dardā’ (raḍiy Allāhu ʿanhu) narrates from the Messenger of Allah ﷺ that he said: “Whoever recites [the above] seven times in the morning and in the evening, Allah will suffice him in everything that concerns him in matters of this world and the next.” (Ibn al-Sunnī 71)","hadith":null,"reference":"عَنْ أَبِي الدَّرْدَاءِ، رضي الله عنه، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ: مَنْ قَالَ فِي كُلِّ يَوْمٍ حِينَ يُصْبِحُ وَحِينَ يُمْسِي: حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ، سَبْعَ مَرَّاتٍ، كَفَاهُ اللَّهُ عز وجل هَمَّهُ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ. (عمل اليوم والليلة لابن السني ٧١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":7,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/nervous/"},{"title":"When One Is Distressed","arabic":"اَللّٰهُمَّ رَحْمَتَكَ أَرْجُوْ فَلَا تَكِلْنِيْ إِلٰى نَفْسِيْ طَرْفَةَ عَيْنٍ ، وَأَصْلِحْ لِي شَأْنِيْ كُلَّهُ ، لَا إِلٰهَ إِلَّا أَنْتَ","transliteration":"Allāhumma raḥmataka arjū fa-lā takilnī ilā nafsī ṭarfata ʿayn, wa aṣliḥ lī sha’nī kullah, lā ilāha illā Ant.","translation":"O Allah! It is certainly Your Mercy what I hope for, so do not entrust me to myself for the blink of an eye; and rectify all of my affairs. There is no god worthy of worship except You.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ said: “The supplications of the distressed person are [the above].” (Abū Dāwūd 5090)","reference":"عَنْ جَعْفَرِ بْنِ مَيْمُونٍ قَالَ: حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ «أَنَّهُ قَالَ لِأَبِيهِ : يَا أَبَتِ إِنِّي أَسْمَعُكَ تَدْعُو كُلَّ غَدَاةٍ: اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَدْعُو بِهِنَّ، فَأَنَا أُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ قَالَ عَبَّاسٌ فِيهِ: وَتَقُولُ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَتَدْعُو بِهِنَّ، فَأُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ. قَالَ: وَقَالَ رَسُولُ اللهِ صلى الله عليه وسلم: دَعَوَاتُ الْمَكْرُوبِ اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا ‌تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ. (سنن ابي داود ٥٠٩٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/nervous/"},{"title":"Duʿa of Prophet Musa ﷺ for Inner Peace & Strength","arabic":"رَبِّ اشْرَحْ لِيْ صَدْرِيْ ، وَيَسِّرْ لِيْٓٓ أَمْرِيْْ.","transliteration":"Rabbi-sh-shraḥ lī ṣadrī. Wa yassir lī amrī.","translation":"My Lord, put my heart at peace for me, and make my task easy for me. (20:25-26)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/nervous/"},{"title":"Entrust All Your Matters to Allah","arabic":"يَا حَيُّ يَا قَيُّوْمُ ، بِرَحْمَتِكَ أَسْتَغِيْثُ ، أَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ ، وَلَا تَكِلْنِيْ إِلَىٰ نَفْسِيْ طَرْفَةَ عَيْنٍ.\\nأخبرنَا عبد الرَّحْمَن بن مُحَمَّد بن سَلام حَدثنَا زيد بن الْحباب أَخْبرنِي عُثْمَان بن موهب الْهَاشِمِي سَمِعت أنس بن مَالك يَقُول قَالَ النَّبِي صلى الله عليه وسلم لفاطمة مَا يمنعك أَن سَمْعِي مَا أوصيك بِهِ أَو تقولي إِذا أَصبَحت وَإِذا أمسيت يَا حَيّ يَا قيوم بِرَحْمَتك أستغيث أصلح لي شأني كلَّه وَلَا تَكِلنِي إِلَى نَفسِي طرفَة عين.","transliteration":"Yā Ḥayyu yā Qayyūm, bi-raḥmatika astaghīth, aṣliḥ lī sha’nī kullah, wa lā takilnī ilā nafsī ṭarfata ʿayn.","translation":"O The Ever Living, The Sustainer of all. ; I seek assistance through Your mercy. Rectify all of my affairs and do not entrust me to myself for the blink of an eye.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ʿanhu) narrates that the Prophet ﷺ said to Fāṭimah (raḍiy Allāhu ʿanhā), “What is preventing you from (doing) what I am advising you; that you say [the above] in the morning and evening?” (Nasā’ī in ʿAmal al-Yawm wa-l-Laylah 570)","reference":"(عمل اليوم والليلة للنسائي ٥٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/nervous/"},{"title":"Duʿa of Prophet Ayyub ﷺ for Times of Distress","arabic":"-رَبِّ- أَنِّيْ مَسَّنِيَ الضُّرُّ وَأَنْتَ أَرْحَمُ الرّٰحِمِيْن.","transliteration":"(Rabbi) Annī massaniya-ḍ-ḍurru wa Anta Arḥamu-r-raḥimīn.","translation":"(My Lord), indeed adversity has touched me, and you are the Most Merciful of the merciful. (21:83)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/nervous/"}]},{"feeling":"Regret","slug":"regret","url":"https://allahuakbarofficial.com/regret/","items_count":8,"duas":[{"title":"Duʿa of the Grief-stricken Prophet Yunus ﷺ","arabic":"لَآ إِلٰهَ إِلَّآ أَنْتَ سُبْحَانَكَ إِنِّيْ كُنْتُ مِنَ الظَّالِمِيْنَ","transliteration":"Lā ilāha illā Anta subḥānaka innī kuntu mina-ẓ-ẓālimīn.","translation":"There is no god worthy of worship except You; You are free from all imperfection. Indeed, I have been of the wrongdoers. (21:87)","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “The supplication of Dhun-Nūn (Prophet Yūnus) when he supplicated, while in the belly of the whale was: [the above]. ”No Muslim man ever supplicates with [the above] except that Allah answers his supplication.” (Tirmidhī 3505)","hadith":null,"reference":"He ﷺ also said that [the above] removes difficulties and calamities. (Nasā’i 10416)\\nعَنْ إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ سَعْدٍ، عَنْ أَبِيهِ ، عَنْ سَعْدٍ قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: دَعْوَةُ ذِي النُّونِ إِذْ دَعَا وَهُوَ فِي بَطْنِ الْحُوتِ: لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ؛ فَإِنَّهُ لَمْ يَدْعُ بِهَا رَجُلٌ مُسْلِمٌ فِي شَيْءٍ قَطُّ إِلَّا اسْتَجَابَ اللهُ لَهُ. (سنن الترمذي ٣٥٠٥)\\nأَخْبَرَنَا الْقَاسِمُ بْنُ زَكَرِيَّا، قَالَ: حَدَّثَنَا عُبَيْدُ بْنُ مُحَمَّدٍ، قَالَ: حَدَّثَنَا مُحَمَّدُ بْنُ مُهَاجِرٍ، قَالَ: حَدَّثَنِي إِبْرَاهِيمُ بْنُ مُحَمَّدِ بْنِ سَعْدٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ: كُنَّا جُلُوسًا عِنْدَ رَسُولِ اللهِ صلى الله عليه وسلم قَالَ: أَلَا أُخْبِرُكُمْ، أَوْ أُحَدِّثُكُمْ، بِشَيْءٍ إِذَا نَزَلَ بِرَجُلٍ مِنْكُمْ كَرْبٌ أَوْ بَلَاءٌ مِنَ بَلَاءِ الدُّنْيَا دَعَا بِهِ فُرِّجَ عَنْهُ؟ فَقِيلَ لَهُ: بَلَى، قَالَ: ” دُعَاءُ ذِي النُّونِ: ‌لَا ‌إِلَهَ ‌إِلَّا ‌أَنْتَ ‌سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ.\\n(السنن الكبرى للنسائي ١٠٤١٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/regret/"},{"title":"Duʿa of Prophet Musa ﷺ for Forgiveness","arabic":"رَبِّ إِنِّيْ ظَلَمْتُ نَفْسِيْ فَاغْفِرْ لِيْ.","transliteration":"Rabbi innī ẓalamtu nafsī fa-ghfirlī.","translation":"My Lord, I have certainly wronged myself, so forgive me. (28:16)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/regret/"},{"title":"Protect Yourself From Anxiety, Laziness & Debt","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ ، وَأَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ ، وَأَعُوْذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.","transliteration":"Allāhumma innī aʿūdhu bika min-l-hammi wa-l-ḥazan, wa aʿūdhu bika min-l-ʿajzi wa-l-kasal, wa aʿūdhu bika min-l-jubni wa-l-bukhl, wa aʿūdhu bika min ghalabati-d-dayni wa qahri-r-rijāl.","translation":"O Allah, I seek Your protection from anxiety and grief. I seek Your protection from inability and laziness. I seek Your protection from cowardice and miserliness, and I seek Your protection from being overcome by debt and being overpowered by men.","description":null,"benefit":null,"virtue":"Abū Saʿīd al-Khudrī (raḍiy Allāhu ʿanhu) narrated that one day, the Messenger of Allah ﷺ entered the masjid. He saw a man from the Anṣār called Abū Umāmah (raḍiy Allāhu ʿanhu). He ﷺ asked, “What is the matter? Why are you sitting in the masjid when it is not the time for prayer?” He replied, “Never-ending worries and debts, O Messenger of Allah.” The Messenger of Allah ﷺ then asked, “Shall I not teach you words by which, when you say them, Allah will remove your worries, and settle your debts?” He replied, “Yes of course, O Messenger of Allah.” He ﷺ said, “Say in the morning and evening [the above].” Abū Umāmah (raḍiy Allāhu ʿanhu) said, “Then I did that, and Allah removed my worries and settled my debts.” (Abū Dāwūd 1555)","hadith":null,"reference":"عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: دَخَلَ رَسُولُ صَلَّى عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ مِنَ الْأَنْصَارِ، يُقَالُ لَهُ: أَبُو أُمَامَةَ، فَقَالَ: «يَا أُمَامَةَ، مَا لِي أَرَاكَ جَالِسًا فِي الْمَسْجِدِ فِي غَيْرِ وَقْتِ الصَّلَاةِ؟»، قَالَ: هُمُومٌ لَزِمَتْنِي، وَدُيُونٌ يَا رَسُولَ اللَّهِ، قَالَ: أَفَلَا أُعَلِّمُكَ كَلَامًا إِذَا أَنْتَ قُلْتَهُ أَذْهَبَ عز وجل هَمَّكَ، وَقَضَى عَنْكَ دَيْنَكَ؟، قَالَ: قُلْتُ: بَلَى، يَا رَسُولَ، قَالَ: ” قُلْ إِذَا أَصْبَحْتَ، وَإِذَا أَمْسَيْتَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَقَهْرِ الرِّجَالِ “، قَالَ: فَفَعَلْتُ ذَلِكَ، فَأَذْهَبَ اللَّهُ عز وجل هَمِّي، وَقَضَى عَنِّي دَيْنِي.(سنن أبي داود ١٥٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/regret/"},{"title":"Duʿa of Prophet Adam ﷺ and Hawwa for Forgiveness","arabic":"رَبَّنَا ظَلَمْنَآ أَنْفُسَنَا وَإِنْ لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُوْنَنَّ مِنَ الْخٰسِرِيْنَ.","transliteration":"Rabbanā ẓalamnā anfusanā wa il-lam taghfir lanā wa tarḥamnā la-nakūnanna minal-khāsīrīn.","translation":"Our Lord, we have wronged ourselves. If You do not forgive us and have mercy upon us, we will surely be amongst the losers. (7:23)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/regret/"},{"title":"Duʿa of Prophet Musa ﷺ for Forgiveness","arabic":"أَنْتَ وَلِيُّنَا فَاغْفِرْ لَنَا وَارْحَمْنَا ۖ وَأَنْتَ خَيْرُ الْغَافِرِيْنَ.","transliteration":"Anta Walliyyunā fa-ghfir lanā war-ḥamnā wa Anta khayrul-ghāfirīn.","translation":"You are our Protector, so forgive us and have mercy upon us. You are the best of those who forgive. (7:155)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/regret/"},{"title":"Duʿa of the Pious for Forgiveness & Protection From the Hell-fire","arabic":"رَبَّنَآ إِنَّنَآ اٰمَنَّا فَاغْفِرْ لَنَا ذُنُوْبَنَا وَقِنَا عَذَابَ النَّارِ.","transliteration":"Rabbanā in-nanā āmannā fa-ghfir lanā dhunūbanā wa qinā ʿadhāba-n-nār.","translation":"Our Lord, indeed we have believed, so forgive us our sins and protect us from the punishment of the Fire. (3:16)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/regret/"},{"title":"Duʿa of the Slaves of Allah for Forgiveness & Mercy","arabic":"رَبَّنَآ اٰمَنَّا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنْتَ خَيْرُ الرّٰحِمِيْنَ.","transliteration":"Rabbanā āmannā fa-ghfir lanā war-ḥamnā wa Anta khayru-r-rāḥimīn.","translation":"Our Lord, we have believed, so forgive us and have mercy upon us: You are the Best of those who are merciful. (23:109)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/regret/"},{"title":"Duʿa for Forgiveness & Mercy","arabic":"رَبِّ اغْفِرْ وَارْحَمْ وَأَنْتَ خَيْرُ الرّٰحِمِيْنَ.","transliteration":"Rabbi-ghfir wa-rḥam wa Anta khayru-r-rāḥimīn.","translation":"My Lord, forgive and have mercy. You are the Best of those who are merciful. (23:118)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/regret/"}]},{"feeling":"Overwhelmed","slug":"overwhelmed","url":"https://allahuakbarofficial.com/overwhelmed/","items_count":21,"duas":[{"title":"Surah al-Fatihah: The Greatest Duʿa","arabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيْمِ ،\\nاَلْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِيْنَ ، الرَّحْمٰنِ الرَّحِيْمِ ، مٰلِكِ يَوْمِ الدِّيْنِ ، إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِيْنُ ، اِهْدِنَا الصِّرَاطَ الْمُسْتَقِيْمَ ، صِرَاطَ الَّذِيْنَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوْبِ عَلَيْهِمْ وَلَا الضَّآلِّيْنَ.","transliteration":"Bismi-llāhi-r-Raḥmāni-r-Raḥīm. Alḥamdu-lillāhi Rabbi-l-ʿālamīn, ar-Raḥmāni-r-Raḥīm, Māliki yawmi-d-dīn, iyyāka naʿbudu wa iyyāka nastaʿīn, ihdina-ṣ-Ṣirāṭa-l-Mustaqīm, ṣirāṭa-lladhīna anʿamta ʿalayhim ghayri-l-maghḍūbi ʿālayhim wa la-ḍ-ḍāllīn.","translation":"In the name of Allah, the All-Merciful, the Very Merciful. All praises and thanks are for Allah, the Lord of all the worlds, The All-Merciful, The Very Merciful, Master of the Day of Judgement. You Alone we worship, You Alone we ask for help. Guide us on the Straight Path, the path of those whom You have favoured, not of those who incur (Your) anger nor of those who have gone astray. (1:1-7)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"When Difficulties Make You Yearn for Death","arabic":"اَللّٰهُمَّ أَحْيِنِيْ مَا كَانَتِ الْحَيَاةُ خَيْرًا لِّيْ ، وَتَوَفَّنِيْ إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِّيْ","transliteration":"Allāhumma aḥyinī mā kānati-l-ḥayātu khayral-lī, wa tawaffanī idhā kānati-l-wafātu khayral-lī.","translation":"O Allah, let me live as long as life is better for me; and give me death when death is better for me.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ said: “None of you should wish for death because of a difficulty that befalls him. Rather he should say [the above].” (Bukhārī 5671, Muslim 2680)","reference":"عَنْ أَنَسِ بْنِ مَالِكٍ رضي الله عنه، قَالَ النَّبِيُّ صلى الله عليه وسلم: «لَا يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ مِنْ ضُرٍّ أَصَابَهُ، فَإِنْ كَانَ لَا بُدَّ فَاعِلًا فَلْيَقُلِ: اللَّهُمَّ أَحْيِنِي مَا كَانَتِ الْحَيَاةُ خَيْرًا لِي، وَتَوَفَّنِي إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِي. (صحيح البخاري ٥٦٧١)\\nعَنْ أَنَسٍ، قَالَ قَالَ رسول الله صلى الله عليه وسلم لا يتمنين أحدكم الموت لضر نزل به. فإن كان لابد متمنيا فليقل: اللهم! أحيني ما كانت الحياة خيرا لي، وتوفني إذا كانت الوفاة خيرا لي. (صحيح مسلم ٢٦٨٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"When Something You Dislike Happens #2","arabic":"قَدَّرَ اللّٰهُ وَمَا شَاءَ فَعَلَ","transliteration":"Qaddara-llāhu wa mā shā’a faʿal.","translation":"Allah has decreed and He does whatever He wills.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ said: “A strong believer is better and more beloved to Allah than a weak believer, and there is good in everyone. Be keen on what benefits you, seek help from Allah, and do not give up. If anything afflicts you, do not say: ‘If I had done (something else), such and such would have happened.’ But say [the above], for (the utterance) ‘if’ provides an opening for the deeds of the devil.” (Muslim 2664)","reference":"عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ الله صلى الله عليه وسلم المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف. وفي كل خير. احرص على ما ينفعك واستعن بالله. ولا تعجز. وإن أصابك شيء فلا تقل: لو أني فعلت كان كذا وكذا. ولكن قل: قدر الله. وما شاء فعل. فإن لو تفتح عمل الشيطان.\\n(صحيح مسلم ٢٦٦٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"When One Is in a Difficult Situation","arabic":"اَللّٰهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا ، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا","transliteration":"Allāhumma lā sahla illā mā jaʿaltahū sahlā, wa anta tajʿalu-l-ḥazna idhā shi’ta sahlā.","translation":"O Allah, there is no ease except in that which You have made easy; and You make the difficulty easy when You wish.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Malik (raḍiy Allāhu ʿanhu) ﷺ narrates that the Messenger of Allah said [the above]. (Ibn Ḥibbān 6737, Ibn al-Sunnī 351)","reference":"عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم، قَالَ: اللهُمَّ ‌لَا ‌سَهْلَ إِلَاّ مَا جَعَلْتَهُ سَهْلاً، وَأَنْتَ تَجْعَلُ الْحَزْنَ سَهْلاً إِذَا شِئْتَ. (صحيح ابن حبان ٦٧٣٧)\\nعَنْ أَنَسِ بْنِ مَالِكٍ، رضي الله عنه أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ: اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا، وَأَنْتَ تَجْعَلُ الْحَزَنَ إِذَا شِئْتَ سَهْلًا.\\n(عمل اليوم والليلة لابن السني ٣٥١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Allah said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"Protect Yourself From Anxiety, Laziness & Debt","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ ، وَأَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ ، وَأَعُوْذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.","transliteration":"Allāhumma innī aʿūdhu bika min-l-hammi wa-l-ḥazan, wa aʿūdhu bika min-l-ʿajzi wa-l-kasal, wa aʿūdhu bika min-l-jubni wa-l-bukhl, wa aʿūdhu bika min ghalabati-d-dayni wa qahri-r-rijāl.","translation":"O Allah, I seek Your protection from anxiety and grief. I seek Your protection from inability and laziness. I seek Your protection from cowardice and miserliness, and I seek Your protection from being overcome by debt and being overpowered by men.","description":null,"benefit":null,"virtue":"Abū Saʿīd al-Khudrī (raḍiy Allāhu ʿanhu) narrated that one day, the Messenger of Allah ﷺ entered the masjid. He saw a man from the Anṣār called Abū Umāmah (raḍiy Allāhu ʿanhu). He ﷺ asked, “What is the matter? Why are you sitting in the masjid when it is not the time for prayer?” He replied, “Never-ending worries and debts, O Messenger of Allah.” The Messenger of Allah ﷺ then asked, “Shall I not teach you words by which, when you say them, Allah will remove your worries, and settle your debts?” He replied, “Yes of course, O Messenger of Allah.” He ﷺ said, “Say in the morning and evening [the above].” Abū Umāmah (raḍiy Allāhu ʿanhu) said, “Then I did that, and Allah removed my worries and settled my debts.” (Abū Dāwūd 1555)","hadith":null,"reference":"عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: دَخَلَ رَسُولُ صَلَّى عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ مِنَ الْأَنْصَارِ، يُقَالُ لَهُ: أَبُو أُمَامَةَ، فَقَالَ: «يَا أُمَامَةَ، مَا لِي أَرَاكَ جَالِسًا فِي الْمَسْجِدِ فِي غَيْرِ وَقْتِ الصَّلَاةِ؟»، قَالَ: هُمُومٌ لَزِمَتْنِي، وَدُيُونٌ يَا رَسُولَ اللَّهِ، قَالَ: أَفَلَا أُعَلِّمُكَ كَلَامًا إِذَا أَنْتَ قُلْتَهُ أَذْهَبَ عز وجل هَمَّكَ، وَقَضَى عَنْكَ دَيْنَكَ؟، قَالَ: قُلْتُ: بَلَى، يَا رَسُولَ، قَالَ: ” قُلْ إِذَا أَصْبَحْتَ، وَإِذَا أَمْسَيْتَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَقَهْرِ الرِّجَالِ “، قَالَ: فَفَعَلْتُ ذَلِكَ، فَأَذْهَبَ اللَّهُ عز وجل هَمِّي، وَقَضَى عَنِّي دَيْنِي.(سنن أبي داود ١٥٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"When Struck by a Calamity","arabic":"إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ رَاجِعُوْنَ ، اَللّٰهُمَّ اْجُرْنِيْ فِيْ مُصِيْبَتِيْ ، وَأَخْلِفْ لِيْ خَيْرًا مِّنْهَا","transliteration":"Innā lillāhi wa innā ilayhi rājiʿūn, Allāhumma-‘jurnī fī muṣībatī, wa akhlif lī khayram-minhā.","translation":"Indeed, to Allah we belong and to Him we will return. O Allah, recompense me for my affliction and replace it for me with something better.","description":null,"benefit":null,"virtue":"Umm Salamah (raḍiy Allāhu ʿanhā) said: I heard the Messenger of Allah ﷺ say, “There is no Muslim who is afflicted with a calamity, and then says what Allah has commanded him [the above duʿā’], except that Allah will recompense him with something better than it.” She says: “When Abū Salamah (her first husband) passed away, I said, ‘Which Muslim is better than Abū Salamah – the first household to migrate to the Messenger of Allah?’ I then said [the above], and Allah recompensed me (by marrying me to) the Messenger of Allah ﷺ.” (Muslim 918)","hadith":null,"reference":"وحدثنا أبو بكر بن أبي شيبة. حدثنا أَبُو أُسَامَةَ عَنْ سَعْدِ بْنِ سَعِيدٍ. قَالَ: أَخْبَرَنِي عُمَرُ بْنُ كَثِيرِ بْنِ أَفْلَحَ. قَالَ: سَمِعْتُ ابْنَ سَفِينَةَ يُحَدِّثُ؛ أَنَّهُ سَمِعَ أُمِّ سَلَمَةَ ، أَنَّهَا قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَقُولُ: مَا مِنْ مُسْلِمٍ تُصِيبُهُ مُصِيبَةٌ فَيَقُولُ مَا أَمَرَهُ اللهُ: إِنَّا لِلهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرًا مِنْهَا، إِلَّا أَخْلَفَ اللهُ لَهُ خَيْرًا مِنْهَا، قَالَتْ: فَلَمَّا مَاتَ أَبُو سَلَمَةَ قُلْتُ: أَيُّ الْمُسْلِمِينَ خَيْرٌ مِنْ أَبِي سَلَمَةَ؟ أَوَّلُ بَيْتٍ هَاجَرَ إِلَى رَسُولِ اللهِ صلى الله عليه وسلم، ثُمَّ إِنِّي قُلْتُهَا، فَأَخْلَفَ اللهُ لِي رَسُولَ اللهِ صلى الله عليه وسلم، قَالَتْ: أَرْسَلَ إِلَيَّ رَسُولُ اللهِ صلى الله عليه وسلم حَاطِبَ بْنَ أَبِي بَلْتَعَةَ يَخْطُبُنِي لَهُ، فَقُلْتُ: إِنَّ لِي بِنْتًا وَأَنَا غَيُورٌ، فَقَالَ: أَمَّا ابْنَتُهَا فَنَدْعُو اللهَ أَنْ يُغْنِيَهَا عَنْهَا، وَأَدْعُو اللهَ أَنْ يُذْهِبَ بِالْغَيْرَةِ. (صحيح مسلم ٩١٨)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"I said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"Attain Well-being in This World and the Hereafter","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِيْ دِيْنِيْ وَدُنْيَايَ وَأَهْلِيْ وَمَالِيْ ، اَللّٰهُمَّ اسْتُرْ عَوْرَاتِيْ وَآمِنْ رَّوْعَاتِيْ ، اَللّٰهُمَّ احْفَظْنِيْ مِنْ بَيْنِ يَدَيَّ ، وَمِنْ خَلْفِيْ ، وَعَنْ يَّمِيْنِيْ ، وَعَنْ شِمَالِيْ ، وَمِنْ فَوْقِيْ ، وَأَعُوْذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِيْ.","transliteration":"Allāhumma innī as’aluka-l-ʿāfiyata fi-d-dunyā wa-l-ākhirah. Allāhumma innī as’aluka-l-ʿafwa wa-l-ʿāfiyata fī dīnī wa dunyāya wa ahlī wa mālī, Allāhumma-stur ʿawrātī wa āmi-r-rawʿātī. Allāhumma-ḥfaẓnī mim bayni yadayya wa min khalfī, wa ʿay-yamīnī wa ʿan shimālī wa min fawqī, wa aʿūdhu bi-ʿaẓamatika an ughtāla min taḥtī.","translation":"O Allah, I ask You for well-being in this world and the next. O Allah, I ask You for forgiveness and well-being in my religion, in my worldly affairs, in my family and in my wealth. O Allah, conceal my faults and calm my fears. O Allah, guard me from in front of me and behind me, from my right, and from my left, and from above me. I seek protection in Your Greatness from being unexpectedly destroyed from beneath me.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “Ask Allah for forgiveness and well-being (‘āfiyah). Indeed, after conviction (yaqīn), no one has been granted anything better than well-being.” (Tirmidhī)","hadith":"ʿAbdullāh b. ʿUmar (raḍiy Allāhu ʿanhumā) narrated: “The Messenger of Allah ﷺ never failed to say these words in the morning and in the evening.” (Abū Dāwūd 5074)","reference":"عَنْ جُبَيْرِ بْنِ أَبِي سُلَيْمَانَ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ، قَالَ: سَمِعْتُ ابْنَ عُمَرَ، يَقُولُ: لَمْ يَكُنْ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَعُ هَؤُلَاءِ الدَّعَوَاتِ، حِينَ يُمْسِي، وَحِينَ يُصْبِحُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَتِي، وَقَالَ عُثْمَانُ: عَوْرَاتِي وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي.(سنن أبي داود ٥٠٧٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"Grief & Anxiety #1","arabic":"اَللّٰهُمَّ إِنِّيْ عَبْدُكَ ، وَابْنُ عَبْدِكَ ، وَابْنُ أَمَتِكَ ، نَاصِيَتِيْ بِيَدِكَ ، مَاضٍ فِيَّ حُكْمُكَ ، عَدْلٌ فِيَّ قَضَاؤُكَ ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ ، سَمَّيْتَ بِهِ نَفْسَكَ ، أَوْ عَلَّمْتَهُ أَحَدًا مِّنْ خَلْقِكَ ، أَوْ أَنْزَلْتَهُ فِيْ كِتَابِكَ ، أَوِ اسْتَأْثَرْتَ بِهِ فِيْ عِلْمِ الْغَيْبِ عِنْدَكَ ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيْعَ قَلْبِيْ ، وَنُوْرَ صَدْرِيْ ، وَجَلَاءَ حُزْنِيْ ، وَذَهَابَ هَمِّيْ","transliteration":"Allāhumma innī ʿabduk, wa-bnu ʿabdik, wa-bnu amatik, nāṣiyatī bi-yadik, māḍin fiyya ḥukmuk, ʿadlun fiyya qaḍā’uk, as’aluka bi-kulli-smin huwa lak, sammayta bihī nafsak, aw ʿallamtahū aḥadam-min khalqik, aw anzaltahū fī kitābik, awi-sta’tharta bihī fī ʿilmi-l-ghaybi ʿindak, an tajʿala-l-Qur’āna rabīʿa qalbī, wa nūra ṣadrī, wa jalā’a ḥuznī, wa dha-hāba hammī.","translation":"O Allah, I am Your servant and the son of Your male servant and the son of Your female servant. My forehead is in Your Hand (i.e. you have control over me). I am subject to Your judgement and Your decree concerning me is just. I ask You – by every name that is Yours, by which You have named Yourself, or taught any one of Your creation, or revealed in Your Book, or kept unto Yourself in the knowledge of the unseen that is with You – to make the Qur’ān the spring of my heart, the light of my chest, the banisher of my grief and the reliever of my anxiety.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “There is no one who is stricken with grief and anxiety, and then says [the above] — except that Allah will remove his grief and anxiety, and will give him joy instead.” The Companions asked, ‘O Messenger of Allah, should we not learn these words?’ He ﷺ replied, ‘Certainly! The one who hears them should learn them.’” (Ahmad 3712)","hadith":null,"reference":"عَنْ عَبْدِ اللهِ، قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: مَا أَصَابَ أَحَدًا قَطُّ هَمٌّ وَلَا حَزَنٌ، فَقَالَ: اللهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجِلَاءَ حُزْنِي، وَذَهَابَ هَمِّي، إِلَّا أَذْهَبَ اللهُ هَمَّهُ وَحُزْنَهُ، وَأَبْدَلَهُ مَكَانَهُ فَرَحًا، قَالَ: فَقِيلَ: يَا رَسُولَ اللهِ، أَلَا نَتَعَلَّمُهَا؟ فَقَالَ: بَلَى، يَنْبَغِي لِمَنْ سَمِعَهَا أَنْ يَتَعَلَّمَهَا. (مسند أحمد ٣٧١٢)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"Grief & Anxiety #2","arabic":"لَا إِلٰهَ إِلَّا اللّٰهُ الْعَظِيْمُ الْحَلِيْمُ ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ الْعَرْشِ الْعَظِيْمِ ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ السَّمٰـوٰتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيْمِ","transliteration":"Lā ilāha illā-llāhu-l-ʿĀẓīmu-l-Ḥalīm, lā ilāha illā-llāhu Rabbu-l-ʿĀrshi-l-ʿAẓīm, lā ilāha illā-llāhu Rabbu-s-samāwāti wa Rabbu-l-arḍi wa Rabbu-l-ʿĀrshi-l-karīm.","translation":"There is no god worthy of worship except Allah — the Supreme, the Forbearing. There is no god worthy of worship except Allah — Lord of the Magnificent Throne. There is no god worthy of worship except Allah — Lord of the heavens, Lord of the earth, and Lord of the Noble Throne.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ used to supplicate with [the above] in times of distress. (Bukhārī 6345, Muslim 2730)","reference":"عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ:كَانَ النَّبِيُّ صلى الله عليه وسلم يَدْعُو عِنْدَ الْكَرْبِ: لَا إِلَهَ إِلَّا اللهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللهُ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ رَبُّ الْعَرْشِ الْعَظِيمِ. (صحيح البخاري ٦٣٤٥)\\nعَنِ ابْنِ عَبَّاسٍ؛ أَنَّ نبي الله صلى الله عليه وسلم كان يقول عند الكرب “لا إله إلا الله العظيم الحليم. لا إله إلا الله رب العرش العظيم. لا إله إلا الله رب السماوات ورب الأرض ورب العرش الكريم. (صحيح مسلم ٢٧٣٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"When One Is Afraid of People #2","arabic":"حَسْبُنَا اللّٰهُ وَنِعْمَ الْوَكِيْلُ","transliteration":"Ḥasbunallāhu wa niʿmal Wakīl.","translation":"Allah is enough for us and He is the Best Protector.","description":null,"benefit":null,"virtue":null,"hadith":"Ibn ʿAbbās (radiy Allāhū ʿanhumā) narrated: “[The above] was said by Ibrāhīm (ʿalayhis-salām) when he was thrown into the fire; and it was said by Muḥammad ﷺ when (the hypocrites) said, ‘Your enemies have mobilised their forces against you, so fear them,’ — but this only increased them in faith and they replied: ‘Allah is enough for us and He is the Best Protector (3:173).’” (Bukhārī 4563)","reference":"Muslim 3005\\nعَنِ ابْنِ عَبَّاسٍ : حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ} قَالَهَا إِبْرَاهِيمُ عليه السلام حِينَ أُلْقِيَ فِي النَّارِ، وَقَالَهَا مُحَمَّدٌ صلى الله عليه وسلم حِينَ قَالُوا: إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ. (صحيح البخاري ٤٥٦٣)\\n(صحيح مسلم ٣٠٠٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"When One Is Afraid of People #6","arabic":"اَللّٰهُمَّ اسْتُرْ عَوْرَاتِنَا وَاٰمِنْ رَوْعَاتِنَا","transliteration":"Allāhumma-stur ‘awrātinā wa āmin raw‘ātinā.","translation":"O Allah, conceal our faults and calm our fears.","description":null,"benefit":null,"virtue":null,"hadith":"Abū Sa‘īd al-Khuḍrī (raḍiy Allāhu ‘anhu) narrates: “We (the Companions) said on the Day of Khandaq (Trenches): ‘O Messenger of Allah, is there anything we can say? For the hearts have reached the throats (out of fear).’ He ﷺ replied: ‘Yes! (Say) [the above].’ Abū Sa‘īd al-Khuḍrī says: ‘Allah, Mighty and Majestic destroyed the faces of the enemy with wind and Allah made them face defeat through wind.’” (Ahmad 10996)","reference":"حَدَّثَنَا أَبُو عَامِرٍ، حَدَّثَنَا الزُّبَيْرُ بْنُ عَبْدِ اللهِ، حَدَّثَنِي رُبَيْحُ بْنُ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنْ أَبِيهِ قَالَ: قُلْنَا يَوْمَ الْخَنْدَقِ: يَا رَسُولَ اللهِ، هَلْ مِنْ شَيْءٍ نَقُولُهُ فَقَدْ بَلَغَتِ الْقُلُوبُ الْحَنَاجِرَ؟ قَالَ نَعَمْ، اللهُمَّ اسْتُرْ ‌عَوْرَاتِنَا، وَآمِنْ رَوْعَاتِنَا قَالَ: فَضَرَبَ اللهُ عز وجل وُجُوهَ أَعْدَائِهِ بِالرِّيحِ، فَهَزَمَهُمُ اللهُ عز وجل بِالرِّيحِ. (مسند احمد ١٠٩٩٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"When One Feels Frightened","arabic":"لَا إِلٰهَ إِلَّا اللّٰهُ","transliteration":"Lā ilāha illā-llāh.","translation":"There is no god worthy of worship except Allah.","description":null,"benefit":null,"virtue":null,"hadith":"Zaynab b. Jaḥsh (raḍiy Allāhu ʿanhā) said that the Messenger of Allah ﷺ once entered her house in a state of fear and said, “[The above]. Woe to the Arabs from a danger that is imminent. An opening has been made today in the wall of Ya‘jūj and Ma‘jūj like this” and he made a circle with his thumb and index finger. Zaynab b. Jaḥsh said, “O Messenger of Allah ﷺ! Will we be destroyed even though there are pious people amongst us?” He ﷺ said, “Yes, when evil becomes widespread.” (Bukhārī 3346)","reference":"عَنْ أُمِّ حَبِيبَةَ بِنْتِ أَبِي سُفْيَانَ عَنْ زَيْنَبَ ابْنَةِ جَحْشٍ رضي الله عنهن أَنَّ النَّبِيَّ صلى الله عليه وسلم دَخَلَ عَلَيْهَا فَزِعًا يَقُولُ لَا إِلَهَ إِلَّا اللهُ وَيْلٌ لِلْعَرَبِ مِنْ شَرٍّ قَدِ اقْتَرَبَ فُتِحَ الْيَوْمَ مِنْ رَدْمِ يَاجُوجُ وَمَاجُوجُ مِثْلُ هَذِهِ وَحَلَّقَ بِإِصْبَعِهِ الْإِبْهَامِ وَالَّتِي تَلِيهَا قَالَتْ زَيْنَبُ ابْنَةُ جَحْشٍ: فَقُلْتُ: يَا رَسُولَ اللهِ أَنَهْلِكُ وَفِينَا الصَّالِحُونَ قَالَ نَعَمْ إِذَا كَثُرَ الْخَبَثُ. (صحيح البخاري ٣٣٤٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Jaḥsh said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"Protection From The Anguish of the World & Hereafter","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنْ ضِيْقِ الدُّنْيَا وَضِيْقِ يَوْمِ الْقِيَامَةِ.","transliteration":"Allāhumma innī aʿūdhu bika min ḍīqi-d-dunyā wa ḍīqi yawmi-l-qiyāmah.","translation":"O Allah, I seek Your protection from the anguish of the world and the anguish of the Day of Judgement.","description":null,"benefit":null,"virtue":null,"hadith":"Sharīq al-Hawzānī (raḥimahullāh) narrates that I entered upon Aisha (raḍiy Allāhu ‘anhā) and I asked her: “With which supplication did the Messenger of Allah ﷺ begin his Salāh when he woke up at night?” She replied: “You have asked me regarding something which no one has asked me before.” When he woke up at night, he uttered: Allāhu Akbar (Allah is the Greatest) ten times, and uttered Alḥamdullillāh (All praise be to Allah) ten times, and said Subḥāna-llāhi wa bi ḥamdih. (Allah is free from imperfection, and all praise is due to Him.) ten times, and said: Subḥānal Malik al-Quddūs (How perfect is the Sovereign, the Most Holy) ten times, and asked Allah’s forgiveness ten times, and said: “There is no god but Allah” ten times, and then said: [the above] ten times. He then began the Salāh. (Abū Dāwūd 5085)","reference":"عَنْ عُمَرَ بْنِ جُعْثُمٍ قَالَ: نَا الْأَزْهَرُ بْنُ عَبْدِ اللهِ الْحَرَازِيُّ قَالَ: حَدَّثَنِي شَرِيقٌ الْهَوْزَنِيُّ قَالَ: «دَخَلْتُ عَلَى عَائِشَةَ فَسَأَلْتُهَا بِمَ كَانَ رَسُولُ اللهِ صلى الله عليه وسلم يَفْتَتِحُ إِذَا هَبَّ مِنَ اللَّيْلِ، فَقَالَتْ: لَقَدْ سَأَلْتَنِي عَنْ شَيْءٍ مَا سَأَلَنِي عَنْهُ أَحَدٌ قَبْلَكَ، كَانَ إِذَا هَبَّ مِنَ اللَّيْلِ كَبَّرَ عَشْرًا وَحَمِدَ عَشْرًا وَقَالَ: سُبْحَانَ اللهِ وَبِحَمْدِهِ عَشْرًا وَقَالَ: سُبْحَانَ الْمَلِكِ الْقُدُّوسِ عَشْرًا وَاسْتَغْفَرَ عَشْرًا، وَهَلَّلَ عَشْرًا، ثُمَّ قَالَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ضِيقِ الدُّنْيَا، وَضِيقِ يَوْمِ الْقِيَامَةِ عَشْرًا ثُمَّ يَفْتَتِحُ الصَّلَاةَ.\\n(سنن ابي دادد ٥٠٨٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"Allah Will Suffice You in Everything","arabic":"حَسْبِيَ اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ ، عَلَيْهِ تَوَكَّلْتُ ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ.","transliteration":"Ḥasbiya-Allāhu lā ilāha illā Huwa, ʿalayhi tawakkalt, wa Huwa Rabbu-l-ʿArshi-l-ʿaẓīm.","translation":"Repeat. x7","description":null,"benefit":null,"virtue":"Abū al-Dardā’ (raḍiy Allāhu ʿanhu) narrates from the Messenger of Allah ﷺ that he said: “Whoever recites [the above] seven times in the morning and in the evening, Allah will suffice him in everything that concerns him in matters of this world and the next.” (Ibn al-Sunnī 71)","hadith":null,"reference":"عَنْ أَبِي الدَّرْدَاءِ، رضي الله عنه، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ: مَنْ قَالَ فِي كُلِّ يَوْمٍ حِينَ يُصْبِحُ وَحِينَ يُمْسِي: حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ، سَبْعَ مَرَّاتٍ، كَفَاهُ اللَّهُ عز وجل هَمَّهُ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ. (عمل اليوم والليلة لابن السني ٧١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":7,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"Duʿa of Prophet Musa ﷺ Expressing His Dire Need","arabic":"رَبِّ إِنِّيْ لِمَآ أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيْرٌ.","transliteration":"Rabbi innī limā anzalta illayya min khayrin faqīr.","translation":"My Lord, truly I am in dire need of any good which You may send me. (28:24)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"When Overwhelmed With Difficulties","arabic":"حَسْبِيَ اللّٰهُ وَنِعْمَ الْوَكِيْلُ","transliteration":"Ḥasbiyallāhu wa niʿmal Wakīl.","translation":"Allah is enough for me and He is the Best Protector.","description":null,"benefit":null,"virtue":null,"hadith":"Ibn ʿAbbās (radiy Allāhu ʿanhumā) said: “The last utterance of Ibrāhīm ﷺ  when he was thrown into the fire was [the above].” (Bukhārī 4564)","reference":"عَنِ ابْنِ عَبَّاسٍ قَالَ: كَانَ آخِرَ قَوْلِ إِبْرَاهِيمَ حِينَ أُلْقِيَ فِي النَّارِ: حَسْبِيَ اللهُ وَنِعْمَ الْوَكِيلُ. (صحيح البخاري ٤٥٦٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"For Difficult Times: All Your Prayers Answered","arabic":"لَآ إِلٰهَ إِلَّآ أَنْتَ سُبْحَانَكَ إِنِّيْ كُنْتُ مِنَ الظَّالِمِيْنَ","transliteration":"Lā ilāha illā Anta subḥānaka innī kuntu mina-ẓ-ẓālimīn.","translation":"There is no god worthy of worship except You; You are free from all imperfection. Indeed, I have been of the wrongdoers. (21:87)","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “The supplication of Dhun-Nūn (Prophet Yūnus) when he supplicated in the belly of the whale was: [the above]. No Muslim man ever supplicates with [the above] except that Allah answers his supplications.” (Tirmidhī 3505)","hadith":null,"reference":"Saʿd b. Abī Waqqāṣ said: We were sat in the company of the Messenger of Allah ﷺ. He ﷺ said, “Shall I not inform you of a supplication which will remove the calamity or a worldy trial which befalls a person from amongst you?” It was said, “Of course.” He said, “The supplication of Dhun-Nūn: [the above].”  (See Nasā‘ī in ʿAmal al-Yawm wa al-Laylah 655)\\nعَنْ سَعْدٍ قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: دَعْوَةُ ذِي النُّونِ إِذْ دَعَا وَهُوَ فِي بَطْنِ الْحُوتِ: لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ؛ فَإِنَّهُ لَمْ يَدْعُ بِهَا رَجُلٌ مُسْلِمٌ فِي شَيْءٍ قَطُّ إِلَّا اسْتَجَابَ اللهُ لَهُ. (سنن الترمذي ٣٥٠٥)\\nأخبرنَا الْقَاسِم بن زَكَرِيَّا قَالَ حَدثنَا عبيد بن مُحَمَّد قَالَ حَدثنَا مُحَمَّد بن مهَاجر قَالَ حَدثنِي إِبْرَاهِيم بن مُحَمَّد بن سعد عَن أَبِيه عَن جده قَالَ كُنَّا جُلُوسًا عِنْد رَسُول الله صلى الله عليه وسلم قَالَ أَلا أخْبركُم أَو أحدثكُم بِشَيْء إِذا نزل بِرَجُل مِنْكُم كرب أَو بلَاء من بلَاء الدُّنْيَا دَعَا بِهِ فرج عَنهُ فَقيل لَهُ بلَى قَالَ دُعَاء ذِي النُّون لَا إِلَه إِلَّا أَنْت سُبْحَانَكَ إِنِّي كنت من الظَّالِمين. (عمل اليوم والليلة للنسائي ٦٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Waqqāṣ said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"When One Is Distressed","arabic":"اَللّٰهُمَّ رَحْمَتَكَ أَرْجُوْ فَلَا تَكِلْنِيْ إِلٰى نَفْسِيْ طَرْفَةَ عَيْنٍ ، وَأَصْلِحْ لِي شَأْنِيْ كُلَّهُ ، لَا إِلٰهَ إِلَّا أَنْتَ","transliteration":"Allāhumma raḥmataka arjū fa-lā takilnī ilā nafsī ṭarfata ʿayn, wa aṣliḥ lī sha’nī kullah, lā ilāha illā Ant.","translation":"O Allah! It is certainly Your Mercy what I hope for, so do not entrust me to myself for the blink of an eye; and rectify all of my affairs. There is no god worthy of worship except You.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ said: “The supplications of the distressed person are [the above].” (Abū Dāwūd 5090)","reference":"عَنْ جَعْفَرِ بْنِ مَيْمُونٍ قَالَ: حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ «أَنَّهُ قَالَ لِأَبِيهِ : يَا أَبَتِ إِنِّي أَسْمَعُكَ تَدْعُو كُلَّ غَدَاةٍ: اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَدْعُو بِهِنَّ، فَأَنَا أُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ قَالَ عَبَّاسٌ فِيهِ: وَتَقُولُ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَتَدْعُو بِهِنَّ، فَأُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ. قَالَ: وَقَالَ رَسُولُ اللهِ صلى الله عليه وسلم: دَعَوَاتُ الْمَكْرُوبِ اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا ‌تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ. (سنن ابي داود ٥٠٩٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"Entrust All Your Matters to Allah","arabic":"يَا حَيُّ يَا قَيُّوْمُ ، بِرَحْمَتِكَ أَسْتَغِيْثُ ، أَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ ، وَلَا تَكِلْنِيْ إِلَىٰ نَفْسِيْ طَرْفَةَ عَيْنٍ.\\nأخبرنَا عبد الرَّحْمَن بن مُحَمَّد بن سَلام حَدثنَا زيد بن الْحباب أَخْبرنِي عُثْمَان بن موهب الْهَاشِمِي سَمِعت أنس بن مَالك يَقُول قَالَ النَّبِي صلى الله عليه وسلم لفاطمة مَا يمنعك أَن سَمْعِي مَا أوصيك بِهِ أَو تقولي إِذا أَصبَحت وَإِذا أمسيت يَا حَيّ يَا قيوم بِرَحْمَتك أستغيث أصلح لي شأني كلَّه وَلَا تَكِلنِي إِلَى نَفسِي طرفَة عين.","transliteration":"Yā Ḥayyu yā Qayyūm, bi-raḥmatika astaghīth, aṣliḥ lī sha’nī kullah, wa lā takilnī ilā nafsī ṭarfata ʿayn.","translation":"O The Ever Living, The Sustainer of all. ; I seek assistance through Your mercy. Rectify all of my affairs and do not entrust me to myself for the blink of an eye.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ʿanhu) narrates that the Prophet ﷺ said to Fāṭimah (raḍiy Allāhu ʿanhā), “What is preventing you from (doing) what I am advising you; that you say [the above] in the morning and evening?” (Nasā’ī in ʿAmal al-Yawm wa-l-Laylah 570)","reference":"(عمل اليوم والليلة للنسائي ٥٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"Du\'a of Prophet Nūh ﷺ for when feeling overpowered","arabic":"رَبِّ- اَنِّيْ مَغْلُوْبٌ فَانْتَصِرْ-","transliteration":"(Rabbi) Innī maghlūbun fantaṣir","translation":"(My Lord), indeed i am overpowered so defend (me). (54:10)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"},{"title":"Protection from Trials, Wretchedness, Bad Fate & the Gloating of Enemies","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنْ جَهْدِ الْبَلَاءِ ، وَدَرَكِ الشَّقَاءِ ، وَسُوْءِ الْقَضَاءِ ، وَشَمَاتَةِ الْأَعْدَاءِ.","transliteration":"Allāhumma innī aʿūdhu bika min jahdi-l-balā’, wa daraki-sh-shaqā’, wa sūi’-l-qaḍā’, wa shamātati-l-aʿdā’.","translation":"O Allah, I seek Your protection from severe trials, wretchedness, bad fate and that my enemies rejoice in my misery.","description":null,"benefit":null,"virtue":null,"hadith":"Abū Hurayrah (raḍiy Allāhu ‘anhu) narrates that the Messenger of Allah ﷺ used to seek refuge with Allah from [the above]. (Bukhārī 6347)","reference":"عَنْ أَبِي هُرَيْرَةَ كَانَ رَسُولُ اللهِ صلى الله عليه وسلم يَتَعَوَّذُ مِنْ جَهْدِ الْبَلَاءِ وَدَرَكِ الشَّقَاءِ وَسُوءِ الْقَضَاءِ وَشَمَاتَةِ الْأَعْدَاءِ. (صحيح البخاري ٦٣٤٧)\\n(عمل اليوم والليلة للنسائي ٥٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/overwhelmed/"}]},{"feeling":"Sad","slug":"sad","url":"https://allahuakbarofficial.com/sad/","items_count":20,"duas":[{"title":"Surah al-Fatihah: The Greatest Duʿa","arabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيْمِ ،\\nاَلْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِيْنَ ، الرَّحْمٰنِ الرَّحِيْمِ ، مٰلِكِ يَوْمِ الدِّيْنِ ، إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِيْنُ ، اِهْدِنَا الصِّرَاطَ الْمُسْتَقِيْمَ ، صِرَاطَ الَّذِيْنَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوْبِ عَلَيْهِمْ وَلَا الضَّآلِّيْنَ.","transliteration":"Bismi-llāhi-r-Raḥmāni-r-Raḥīm. Alḥamdu-lillāhi Rabbi-l-ʿālamīn, ar-Raḥmāni-r-Raḥīm, Māliki yawmi-d-dīn, iyyāka naʿbudu wa iyyāka nastaʿīn, ihdina-ṣ-Ṣirāṭa-l-Mustaqīm, ṣirāṭa-lladhīna anʿamta ʿalayhim ghayri-l-maghḍūbi ʿālayhim wa la-ḍ-ḍāllīn.","translation":"In the name of Allah, the All-Merciful, the Very Merciful. All praises and thanks are for Allah, the Lord of all the worlds, The All-Merciful, The Very Merciful, Master of the Day of Judgement. You Alone we worship, You Alone we ask for help. Guide us on the Straight Path, the path of those whom You have favoured, not of those who incur (Your) anger nor of those who have gone astray. (1:1-7)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"When Something You Dislike Happens #1","arabic":"اَلْحَمْدُ لِلّٰهِ عَلَىٰ كُلِّ حَالٍ","transliteration":"Al-ḥamdu li-llāhi ʿalā kulli ḥāl.","translation":"All praise is for Allah in every situation.","description":null,"benefit":null,"virtue":null,"hadith":"When the Messenger of Allah ﷺ saw something that he disliked, he used to say [the above]. (Ibn Mājah 3803, Ibn al-Sunnī 378)","reference":"عَنْ عَائِشَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِذَا رَأَى مَا يُحِبُّ قَالَ: الْحَمْدُ لِلَّهِ الَّذِي بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ، وَإِذَا رَأَى مَا يَكْرَهُ قَالَ: الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ. (سنن ابن ماجه ٣٨٠٣)\\nعَنْ عَائِشَةَ، رضي الله عنها قَالَتْ: كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِذَا رَأَى مَا يُحِبُّ قَالَ: الْحَمْدُ لِلَّهِ الَّذِي بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ، وَإِذَا رَأَى مَا يَكْرَهُ قَالَ: الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ. (عمل اليوم والليلة لابن السني ٣٧٨)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"When Difficulties Make You Yearn for Death","arabic":"اَللّٰهُمَّ أَحْيِنِيْ مَا كَانَتِ الْحَيَاةُ خَيْرًا لِّيْ ، وَتَوَفَّنِيْ إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِّيْ","transliteration":"Allāhumma aḥyinī mā kānati-l-ḥayātu khayral-lī, wa tawaffanī idhā kānati-l-wafātu khayral-lī.","translation":"O Allah, let me live as long as life is better for me; and give me death when death is better for me.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ said: “None of you should wish for death because of a difficulty that befalls him. Rather he should say [the above].” (Bukhārī 5671, Muslim 2680)","reference":"عَنْ أَنَسِ بْنِ مَالِكٍ رضي الله عنه، قَالَ النَّبِيُّ صلى الله عليه وسلم: «لَا يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ مِنْ ضُرٍّ أَصَابَهُ، فَإِنْ كَانَ لَا بُدَّ فَاعِلًا فَلْيَقُلِ: اللَّهُمَّ أَحْيِنِي مَا كَانَتِ الْحَيَاةُ خَيْرًا لِي، وَتَوَفَّنِي إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِي. (صحيح البخاري ٥٦٧١)\\nعَنْ أَنَسٍ، قَالَ قَالَ رسول الله صلى الله عليه وسلم لا يتمنين أحدكم الموت لضر نزل به. فإن كان لابد متمنيا فليقل: اللهم! أحيني ما كانت الحياة خيرا لي، وتوفني إذا كانت الوفاة خيرا لي. (صحيح مسلم ٢٦٨٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"When Something You Dislike Happens #2","arabic":"قَدَّرَ اللّٰهُ وَمَا شَاءَ فَعَلَ","transliteration":"Qaddara-llāhu wa mā shā’a faʿal.","translation":"Allah has decreed and He does whatever He wills.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ said: “A strong believer is better and more beloved to Allah than a weak believer, and there is good in everyone. Be keen on what benefits you, seek help from Allah, and do not give up. If anything afflicts you, do not say: ‘If I had done (something else), such and such would have happened.’ But say [the above], for (the utterance) ‘if’ provides an opening for the deeds of the devil.” (Muslim 2664)","reference":"عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ الله صلى الله عليه وسلم المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف. وفي كل خير. احرص على ما ينفعك واستعن بالله. ولا تعجز. وإن أصابك شيء فلا تقل: لو أني فعلت كان كذا وكذا. ولكن قل: قدر الله. وما شاء فعل. فإن لو تفتح عمل الشيطان.\\n(صحيح مسلم ٢٦٦٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"When One Is in a Difficult Situation","arabic":"اَللّٰهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا ، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا","transliteration":"Allāhumma lā sahla illā mā jaʿaltahū sahlā, wa anta tajʿalu-l-ḥazna idhā shi’ta sahlā.","translation":"O Allah, there is no ease except in that which You have made easy; and You make the difficulty easy when You wish.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Malik (raḍiy Allāhu ʿanhu) ﷺ narrates that the Messenger of Allah said [the above]. (Ibn Ḥibbān 6737, Ibn al-Sunnī 351)","reference":"عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم، قَالَ: اللهُمَّ ‌لَا ‌سَهْلَ إِلَاّ مَا جَعَلْتَهُ سَهْلاً، وَأَنْتَ تَجْعَلُ الْحَزْنَ سَهْلاً إِذَا شِئْتَ. (صحيح ابن حبان ٦٧٣٧)\\nعَنْ أَنَسِ بْنِ مَالِكٍ، رضي الله عنه أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ: اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا، وَأَنْتَ تَجْعَلُ الْحَزَنَ إِذَا شِئْتَ سَهْلًا.\\n(عمل اليوم والليلة لابن السني ٣٥١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Allah said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"Protect Yourself From Anxiety, Laziness & Debt","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ ، وَأَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ ، وَأَعُوْذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.","transliteration":"Allāhumma innī aʿūdhu bika min-l-hammi wa-l-ḥazan, wa aʿūdhu bika min-l-ʿajzi wa-l-kasal, wa aʿūdhu bika min-l-jubni wa-l-bukhl, wa aʿūdhu bika min ghalabati-d-dayni wa qahri-r-rijāl.","translation":"O Allah, I seek Your protection from anxiety and grief. I seek Your protection from inability and laziness. I seek Your protection from cowardice and miserliness, and I seek Your protection from being overcome by debt and being overpowered by men.","description":null,"benefit":null,"virtue":"Abū Saʿīd al-Khudrī (raḍiy Allāhu ʿanhu) narrated that one day, the Messenger of Allah ﷺ entered the masjid. He saw a man from the Anṣār called Abū Umāmah (raḍiy Allāhu ʿanhu). He ﷺ asked, “What is the matter? Why are you sitting in the masjid when it is not the time for prayer?” He replied, “Never-ending worries and debts, O Messenger of Allah.” The Messenger of Allah ﷺ then asked, “Shall I not teach you words by which, when you say them, Allah will remove your worries, and settle your debts?” He replied, “Yes of course, O Messenger of Allah.” He ﷺ said, “Say in the morning and evening [the above].” Abū Umāmah (raḍiy Allāhu ʿanhu) said, “Then I did that, and Allah removed my worries and settled my debts.” (Abū Dāwūd 1555)","hadith":null,"reference":"عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: دَخَلَ رَسُولُ صَلَّى عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ مِنَ الْأَنْصَارِ، يُقَالُ لَهُ: أَبُو أُمَامَةَ، فَقَالَ: «يَا أُمَامَةَ، مَا لِي أَرَاكَ جَالِسًا فِي الْمَسْجِدِ فِي غَيْرِ وَقْتِ الصَّلَاةِ؟»، قَالَ: هُمُومٌ لَزِمَتْنِي، وَدُيُونٌ يَا رَسُولَ اللَّهِ، قَالَ: أَفَلَا أُعَلِّمُكَ كَلَامًا إِذَا أَنْتَ قُلْتَهُ أَذْهَبَ عز وجل هَمَّكَ، وَقَضَى عَنْكَ دَيْنَكَ؟، قَالَ: قُلْتُ: بَلَى، يَا رَسُولَ، قَالَ: ” قُلْ إِذَا أَصْبَحْتَ، وَإِذَا أَمْسَيْتَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَقَهْرِ الرِّجَالِ “، قَالَ: فَفَعَلْتُ ذَلِكَ، فَأَذْهَبَ اللَّهُ عز وجل هَمِّي، وَقَضَى عَنِّي دَيْنِي.(سنن أبي داود ١٥٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"When Struck by a Calamity","arabic":"إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ رَاجِعُوْنَ ، اَللّٰهُمَّ اْجُرْنِيْ فِيْ مُصِيْبَتِيْ ، وَأَخْلِفْ لِيْ خَيْرًا مِّنْهَا","transliteration":"Innā lillāhi wa innā ilayhi rājiʿūn, Allāhumma-‘jurnī fī muṣībatī, wa akhlif lī khayram-minhā.","translation":"Indeed, to Allah we belong and to Him we will return. O Allah, recompense me for my affliction and replace it for me with something better.","description":null,"benefit":null,"virtue":"Umm Salamah (raḍiy Allāhu ʿanhā) said: I heard the Messenger of Allah ﷺ say, “There is no Muslim who is afflicted with a calamity, and then says what Allah has commanded him [the above duʿā’], except that Allah will recompense him with something better than it.” She says: “When Abū Salamah (her first husband) passed away, I said, ‘Which Muslim is better than Abū Salamah – the first household to migrate to the Messenger of Allah?’ I then said [the above], and Allah recompensed me (by marrying me to) the Messenger of Allah ﷺ.” (Muslim 918)","hadith":null,"reference":"وحدثنا أبو بكر بن أبي شيبة. حدثنا أَبُو أُسَامَةَ عَنْ سَعْدِ بْنِ سَعِيدٍ. قَالَ: أَخْبَرَنِي عُمَرُ بْنُ كَثِيرِ بْنِ أَفْلَحَ. قَالَ: سَمِعْتُ ابْنَ سَفِينَةَ يُحَدِّثُ؛ أَنَّهُ سَمِعَ أُمِّ سَلَمَةَ ، أَنَّهَا قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَقُولُ: مَا مِنْ مُسْلِمٍ تُصِيبُهُ مُصِيبَةٌ فَيَقُولُ مَا أَمَرَهُ اللهُ: إِنَّا لِلهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرًا مِنْهَا، إِلَّا أَخْلَفَ اللهُ لَهُ خَيْرًا مِنْهَا، قَالَتْ: فَلَمَّا مَاتَ أَبُو سَلَمَةَ قُلْتُ: أَيُّ الْمُسْلِمِينَ خَيْرٌ مِنْ أَبِي سَلَمَةَ؟ أَوَّلُ بَيْتٍ هَاجَرَ إِلَى رَسُولِ اللهِ صلى الله عليه وسلم، ثُمَّ إِنِّي قُلْتُهَا، فَأَخْلَفَ اللهُ لِي رَسُولَ اللهِ صلى الله عليه وسلم، قَالَتْ: أَرْسَلَ إِلَيَّ رَسُولُ اللهِ صلى الله عليه وسلم حَاطِبَ بْنَ أَبِي بَلْتَعَةَ يَخْطُبُنِي لَهُ، فَقُلْتُ: إِنَّ لِي بِنْتًا وَأَنَا غَيُورٌ، فَقَالَ: أَمَّا ابْنَتُهَا فَنَدْعُو اللهَ أَنْ يُغْنِيَهَا عَنْهَا، وَأَدْعُو اللهَ أَنْ يُذْهِبَ بِالْغَيْرَةِ. (صحيح مسلم ٩١٨)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"I said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"Attain Well-being in This World and the Hereafter","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِيْ دِيْنِيْ وَدُنْيَايَ وَأَهْلِيْ وَمَالِيْ ، اَللّٰهُمَّ اسْتُرْ عَوْرَاتِيْ وَآمِنْ رَّوْعَاتِيْ ، اَللّٰهُمَّ احْفَظْنِيْ مِنْ بَيْنِ يَدَيَّ ، وَمِنْ خَلْفِيْ ، وَعَنْ يَّمِيْنِيْ ، وَعَنْ شِمَالِيْ ، وَمِنْ فَوْقِيْ ، وَأَعُوْذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِيْ.","transliteration":"Allāhumma innī as’aluka-l-ʿāfiyata fi-d-dunyā wa-l-ākhirah. Allāhumma innī as’aluka-l-ʿafwa wa-l-ʿāfiyata fī dīnī wa dunyāya wa ahlī wa mālī, Allāhumma-stur ʿawrātī wa āmi-r-rawʿātī. Allāhumma-ḥfaẓnī mim bayni yadayya wa min khalfī, wa ʿay-yamīnī wa ʿan shimālī wa min fawqī, wa aʿūdhu bi-ʿaẓamatika an ughtāla min taḥtī.","translation":"O Allah, I ask You for well-being in this world and the next. O Allah, I ask You for forgiveness and well-being in my religion, in my worldly affairs, in my family and in my wealth. O Allah, conceal my faults and calm my fears. O Allah, guard me from in front of me and behind me, from my right, and from my left, and from above me. I seek protection in Your Greatness from being unexpectedly destroyed from beneath me.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “Ask Allah for forgiveness and well-being (‘āfiyah). Indeed, after conviction (yaqīn), no one has been granted anything better than well-being.” (Tirmidhī)","hadith":"ʿAbdullāh b. ʿUmar (raḍiy Allāhu ʿanhumā) narrated: “The Messenger of Allah ﷺ never failed to say these words in the morning and in the evening.” (Abū Dāwūd 5074)","reference":"عَنْ جُبَيْرِ بْنِ أَبِي سُلَيْمَانَ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ، قَالَ: سَمِعْتُ ابْنَ عُمَرَ، يَقُولُ: لَمْ يَكُنْ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَعُ هَؤُلَاءِ الدَّعَوَاتِ، حِينَ يُمْسِي، وَحِينَ يُصْبِحُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَتِي، وَقَالَ عُثْمَانُ: عَوْرَاتِي وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي.(سنن أبي داود ٥٠٧٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"Grief & Anxiety #1","arabic":"اَللّٰهُمَّ إِنِّيْ عَبْدُكَ ، وَابْنُ عَبْدِكَ ، وَابْنُ أَمَتِكَ ، نَاصِيَتِيْ بِيَدِكَ ، مَاضٍ فِيَّ حُكْمُكَ ، عَدْلٌ فِيَّ قَضَاؤُكَ ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ ، سَمَّيْتَ بِهِ نَفْسَكَ ، أَوْ عَلَّمْتَهُ أَحَدًا مِّنْ خَلْقِكَ ، أَوْ أَنْزَلْتَهُ فِيْ كِتَابِكَ ، أَوِ اسْتَأْثَرْتَ بِهِ فِيْ عِلْمِ الْغَيْبِ عِنْدَكَ ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيْعَ قَلْبِيْ ، وَنُوْرَ صَدْرِيْ ، وَجَلَاءَ حُزْنِيْ ، وَذَهَابَ هَمِّيْ","transliteration":"Allāhumma innī ʿabduk, wa-bnu ʿabdik, wa-bnu amatik, nāṣiyatī bi-yadik, māḍin fiyya ḥukmuk, ʿadlun fiyya qaḍā’uk, as’aluka bi-kulli-smin huwa lak, sammayta bihī nafsak, aw ʿallamtahū aḥadam-min khalqik, aw anzaltahū fī kitābik, awi-sta’tharta bihī fī ʿilmi-l-ghaybi ʿindak, an tajʿala-l-Qur’āna rabīʿa qalbī, wa nūra ṣadrī, wa jalā’a ḥuznī, wa dha-hāba hammī.","translation":"O Allah, I am Your servant and the son of Your male servant and the son of Your female servant. My forehead is in Your Hand (i.e. you have control over me). I am subject to Your judgement and Your decree concerning me is just. I ask You – by every name that is Yours, by which You have named Yourself, or taught any one of Your creation, or revealed in Your Book, or kept unto Yourself in the knowledge of the unseen that is with You – to make the Qur’ān the spring of my heart, the light of my chest, the banisher of my grief and the reliever of my anxiety.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “There is no one who is stricken with grief and anxiety, and then says [the above] — except that Allah will remove his grief and anxiety, and will give him joy instead.” The Companions asked, ‘O Messenger of Allah, should we not learn these words?’ He ﷺ replied, ‘Certainly! The one who hears them should learn them.’” (Ahmad 3712)","hadith":null,"reference":"عَنْ عَبْدِ اللهِ، قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: مَا أَصَابَ أَحَدًا قَطُّ هَمٌّ وَلَا حَزَنٌ، فَقَالَ: اللهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجِلَاءَ حُزْنِي، وَذَهَابَ هَمِّي، إِلَّا أَذْهَبَ اللهُ هَمَّهُ وَحُزْنَهُ، وَأَبْدَلَهُ مَكَانَهُ فَرَحًا، قَالَ: فَقِيلَ: يَا رَسُولَ اللهِ، أَلَا نَتَعَلَّمُهَا؟ فَقَالَ: بَلَى، يَنْبَغِي لِمَنْ سَمِعَهَا أَنْ يَتَعَلَّمَهَا. (مسند أحمد ٣٧١٢)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"Grief & Anxiety #2","arabic":"لَا إِلٰهَ إِلَّا اللّٰهُ الْعَظِيْمُ الْحَلِيْمُ ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ الْعَرْشِ الْعَظِيْمِ ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ السَّمٰـوٰتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيْمِ","transliteration":"Lā ilāha illā-llāhu-l-ʿĀẓīmu-l-Ḥalīm, lā ilāha illā-llāhu Rabbu-l-ʿĀrshi-l-ʿAẓīm, lā ilāha illā-llāhu Rabbu-s-samāwāti wa Rabbu-l-arḍi wa Rabbu-l-ʿĀrshi-l-karīm.","translation":"There is no god worthy of worship except Allah — the Supreme, the Forbearing. There is no god worthy of worship except Allah — Lord of the Magnificent Throne. There is no god worthy of worship except Allah — Lord of the heavens, Lord of the earth, and Lord of the Noble Throne.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ used to supplicate with [the above] in times of distress. (Bukhārī 6345, Muslim 2730)","reference":"عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ:كَانَ النَّبِيُّ صلى الله عليه وسلم يَدْعُو عِنْدَ الْكَرْبِ: لَا إِلَهَ إِلَّا اللهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللهُ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ رَبُّ الْعَرْشِ الْعَظِيمِ. (صحيح البخاري ٦٣٤٥)\\nعَنِ ابْنِ عَبَّاسٍ؛ أَنَّ نبي الله صلى الله عليه وسلم كان يقول عند الكرب “لا إله إلا الله العظيم الحليم. لا إله إلا الله رب العرش العظيم. لا إله إلا الله رب السماوات ورب الأرض ورب العرش الكريم. (صحيح مسلم ٢٧٣٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"When One Is Afraid of People #2","arabic":"حَسْبُنَا اللّٰهُ وَنِعْمَ الْوَكِيْلُ","transliteration":"Ḥasbunallāhu wa niʿmal Wakīl.","translation":"Allah is enough for us and He is the Best Protector.","description":null,"benefit":null,"virtue":null,"hadith":"Ibn ʿAbbās (radiy Allāhū ʿanhumā) narrated: “[The above] was said by Ibrāhīm (ʿalayhis-salām) when he was thrown into the fire; and it was said by Muḥammad ﷺ when (the hypocrites) said, ‘Your enemies have mobilised their forces against you, so fear them,’ — but this only increased them in faith and they replied: ‘Allah is enough for us and He is the Best Protector (3:173).’” (Bukhārī 4563)","reference":"Muslim 3005\\nعَنِ ابْنِ عَبَّاسٍ : حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ} قَالَهَا إِبْرَاهِيمُ عليه السلام حِينَ أُلْقِيَ فِي النَّارِ، وَقَالَهَا مُحَمَّدٌ صلى الله عليه وسلم حِينَ قَالُوا: إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ. (صحيح البخاري ٤٥٦٣)\\n(صحيح مسلم ٣٠٠٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"When One Feels Frightened","arabic":"لَا إِلٰهَ إِلَّا اللّٰهُ","transliteration":"Lā ilāha illā-llāh.","translation":"There is no god worthy of worship except Allah.","description":null,"benefit":null,"virtue":null,"hadith":"Zaynab b. Jaḥsh (raḍiy Allāhu ʿanhā) said that the Messenger of Allah ﷺ once entered her house in a state of fear and said, “[The above]. Woe to the Arabs from a danger that is imminent. An opening has been made today in the wall of Ya‘jūj and Ma‘jūj like this” and he made a circle with his thumb and index finger. Zaynab b. Jaḥsh said, “O Messenger of Allah ﷺ! Will we be destroyed even though there are pious people amongst us?” He ﷺ said, “Yes, when evil becomes widespread.” (Bukhārī 3346)","reference":"عَنْ أُمِّ حَبِيبَةَ بِنْتِ أَبِي سُفْيَانَ عَنْ زَيْنَبَ ابْنَةِ جَحْشٍ رضي الله عنهن أَنَّ النَّبِيَّ صلى الله عليه وسلم دَخَلَ عَلَيْهَا فَزِعًا يَقُولُ لَا إِلَهَ إِلَّا اللهُ وَيْلٌ لِلْعَرَبِ مِنْ شَرٍّ قَدِ اقْتَرَبَ فُتِحَ الْيَوْمَ مِنْ رَدْمِ يَاجُوجُ وَمَاجُوجُ مِثْلُ هَذِهِ وَحَلَّقَ بِإِصْبَعِهِ الْإِبْهَامِ وَالَّتِي تَلِيهَا قَالَتْ زَيْنَبُ ابْنَةُ جَحْشٍ: فَقُلْتُ: يَا رَسُولَ اللهِ أَنَهْلِكُ وَفِينَا الصَّالِحُونَ قَالَ نَعَمْ إِذَا كَثُرَ الْخَبَثُ. (صحيح البخاري ٣٣٤٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Jaḥsh said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"Protection From The Anguish of the World & Hereafter","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنْ ضِيْقِ الدُّنْيَا وَضِيْقِ يَوْمِ الْقِيَامَةِ.","transliteration":"Allāhumma innī aʿūdhu bika min ḍīqi-d-dunyā wa ḍīqi yawmi-l-qiyāmah.","translation":"O Allah, I seek Your protection from the anguish of the world and the anguish of the Day of Judgement.","description":null,"benefit":null,"virtue":null,"hadith":"Sharīq al-Hawzānī (raḥimahullāh) narrates that I entered upon Aisha (raḍiy Allāhu ‘anhā) and I asked her: “With which supplication did the Messenger of Allah ﷺ begin his Salāh when he woke up at night?” She replied: “You have asked me regarding something which no one has asked me before.” When he woke up at night, he uttered: Allāhu Akbar (Allah is the Greatest) ten times, and uttered Alḥamdullillāh (All praise be to Allah) ten times, and said Subḥāna-llāhi wa bi ḥamdih. (Allah is free from imperfection, and all praise is due to Him.) ten times, and said: Subḥānal Malik al-Quddūs (How perfect is the Sovereign, the Most Holy) ten times, and asked Allah’s forgiveness ten times, and said: “There is no god but Allah” ten times, and then said: [the above] ten times. He then began the Salāh. (Abū Dāwūd 5085)","reference":"عَنْ عُمَرَ بْنِ جُعْثُمٍ قَالَ: نَا الْأَزْهَرُ بْنُ عَبْدِ اللهِ الْحَرَازِيُّ قَالَ: حَدَّثَنِي شَرِيقٌ الْهَوْزَنِيُّ قَالَ: «دَخَلْتُ عَلَى عَائِشَةَ فَسَأَلْتُهَا بِمَ كَانَ رَسُولُ اللهِ صلى الله عليه وسلم يَفْتَتِحُ إِذَا هَبَّ مِنَ اللَّيْلِ، فَقَالَتْ: لَقَدْ سَأَلْتَنِي عَنْ شَيْءٍ مَا سَأَلَنِي عَنْهُ أَحَدٌ قَبْلَكَ، كَانَ إِذَا هَبَّ مِنَ اللَّيْلِ كَبَّرَ عَشْرًا وَحَمِدَ عَشْرًا وَقَالَ: سُبْحَانَ اللهِ وَبِحَمْدِهِ عَشْرًا وَقَالَ: سُبْحَانَ الْمَلِكِ الْقُدُّوسِ عَشْرًا وَاسْتَغْفَرَ عَشْرًا، وَهَلَّلَ عَشْرًا، ثُمَّ قَالَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ ضِيقِ الدُّنْيَا، وَضِيقِ يَوْمِ الْقِيَامَةِ عَشْرًا ثُمَّ يَفْتَتِحُ الصَّلَاةَ.\\n(سنن ابي دادد ٥٠٨٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"Allah Will Suffice You in Everything","arabic":"حَسْبِيَ اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ ، عَلَيْهِ تَوَكَّلْتُ ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ.","transliteration":"Ḥasbiya-Allāhu lā ilāha illā Huwa, ʿalayhi tawakkalt, wa Huwa Rabbu-l-ʿArshi-l-ʿaẓīm.","translation":"Repeat. x7","description":null,"benefit":null,"virtue":"Abū al-Dardā’ (raḍiy Allāhu ʿanhu) narrates from the Messenger of Allah ﷺ that he said: “Whoever recites [the above] seven times in the morning and in the evening, Allah will suffice him in everything that concerns him in matters of this world and the next.” (Ibn al-Sunnī 71)","hadith":null,"reference":"عَنْ أَبِي الدَّرْدَاءِ، رضي الله عنه، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ: مَنْ قَالَ فِي كُلِّ يَوْمٍ حِينَ يُصْبِحُ وَحِينَ يُمْسِي: حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ، سَبْعَ مَرَّاتٍ، كَفَاهُ اللَّهُ عز وجل هَمَّهُ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ. (عمل اليوم والليلة لابن السني ٧١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":7,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"Duʿa of Prophet Musa ﷺ Expressing His Dire Need","arabic":"رَبِّ إِنِّيْ لِمَآ أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيْرٌ.","transliteration":"Rabbi innī limā anzalta illayya min khayrin faqīr.","translation":"My Lord, truly I am in dire need of any good which You may send me. (28:24)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"For Difficult Times: All Your Prayers Answered","arabic":"لَآ إِلٰهَ إِلَّآ أَنْتَ سُبْحَانَكَ إِنِّيْ كُنْتُ مِنَ الظَّالِمِيْنَ","transliteration":"Lā ilāha illā Anta subḥānaka innī kuntu mina-ẓ-ẓālimīn.","translation":"There is no god worthy of worship except You; You are free from all imperfection. Indeed, I have been of the wrongdoers. (21:87)","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “The supplication of Dhun-Nūn (Prophet Yūnus) when he supplicated in the belly of the whale was: [the above]. No Muslim man ever supplicates with [the above] except that Allah answers his supplications.” (Tirmidhī 3505)","hadith":null,"reference":"Saʿd b. Abī Waqqāṣ said: We were sat in the company of the Messenger of Allah ﷺ. He ﷺ said, “Shall I not inform you of a supplication which will remove the calamity or a worldy trial which befalls a person from amongst you?” It was said, “Of course.” He said, “The supplication of Dhun-Nūn: [the above].”  (See Nasā‘ī in ʿAmal al-Yawm wa al-Laylah 655)\\nعَنْ سَعْدٍ قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: دَعْوَةُ ذِي النُّونِ إِذْ دَعَا وَهُوَ فِي بَطْنِ الْحُوتِ: لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ؛ فَإِنَّهُ لَمْ يَدْعُ بِهَا رَجُلٌ مُسْلِمٌ فِي شَيْءٍ قَطُّ إِلَّا اسْتَجَابَ اللهُ لَهُ. (سنن الترمذي ٣٥٠٥)\\nأخبرنَا الْقَاسِم بن زَكَرِيَّا قَالَ حَدثنَا عبيد بن مُحَمَّد قَالَ حَدثنَا مُحَمَّد بن مهَاجر قَالَ حَدثنِي إِبْرَاهِيم بن مُحَمَّد بن سعد عَن أَبِيه عَن جده قَالَ كُنَّا جُلُوسًا عِنْد رَسُول الله صلى الله عليه وسلم قَالَ أَلا أخْبركُم أَو أحدثكُم بِشَيْء إِذا نزل بِرَجُل مِنْكُم كرب أَو بلَاء من بلَاء الدُّنْيَا دَعَا بِهِ فرج عَنهُ فَقيل لَهُ بلَى قَالَ دُعَاء ذِي النُّون لَا إِلَه إِلَّا أَنْت سُبْحَانَكَ إِنِّي كنت من الظَّالِمين. (عمل اليوم والليلة للنسائي ٦٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Waqqāṣ said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"When One Is Distressed","arabic":"اَللّٰهُمَّ رَحْمَتَكَ أَرْجُوْ فَلَا تَكِلْنِيْ إِلٰى نَفْسِيْ طَرْفَةَ عَيْنٍ ، وَأَصْلِحْ لِي شَأْنِيْ كُلَّهُ ، لَا إِلٰهَ إِلَّا أَنْتَ","transliteration":"Allāhumma raḥmataka arjū fa-lā takilnī ilā nafsī ṭarfata ʿayn, wa aṣliḥ lī sha’nī kullah, lā ilāha illā Ant.","translation":"O Allah! It is certainly Your Mercy what I hope for, so do not entrust me to myself for the blink of an eye; and rectify all of my affairs. There is no god worthy of worship except You.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ said: “The supplications of the distressed person are [the above].” (Abū Dāwūd 5090)","reference":"عَنْ جَعْفَرِ بْنِ مَيْمُونٍ قَالَ: حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ «أَنَّهُ قَالَ لِأَبِيهِ : يَا أَبَتِ إِنِّي أَسْمَعُكَ تَدْعُو كُلَّ غَدَاةٍ: اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَدْعُو بِهِنَّ، فَأَنَا أُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ قَالَ عَبَّاسٌ فِيهِ: وَتَقُولُ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَتَدْعُو بِهِنَّ، فَأُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ. قَالَ: وَقَالَ رَسُولُ اللهِ صلى الله عليه وسلم: دَعَوَاتُ الْمَكْرُوبِ اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا ‌تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ. (سنن ابي داود ٥٠٩٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"Entrust All Your Matters to Allah","arabic":"يَا حَيُّ يَا قَيُّوْمُ ، بِرَحْمَتِكَ أَسْتَغِيْثُ ، أَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ ، وَلَا تَكِلْنِيْ إِلَىٰ نَفْسِيْ طَرْفَةَ عَيْنٍ.\\nأخبرنَا عبد الرَّحْمَن بن مُحَمَّد بن سَلام حَدثنَا زيد بن الْحباب أَخْبرنِي عُثْمَان بن موهب الْهَاشِمِي سَمِعت أنس بن مَالك يَقُول قَالَ النَّبِي صلى الله عليه وسلم لفاطمة مَا يمنعك أَن سَمْعِي مَا أوصيك بِهِ أَو تقولي إِذا أَصبَحت وَإِذا أمسيت يَا حَيّ يَا قيوم بِرَحْمَتك أستغيث أصلح لي شأني كلَّه وَلَا تَكِلنِي إِلَى نَفسِي طرفَة عين.","transliteration":"Yā Ḥayyu yā Qayyūm, bi-raḥmatika astaghīth, aṣliḥ lī sha’nī kullah, wa lā takilnī ilā nafsī ṭarfata ʿayn.","translation":"O The Ever Living, The Sustainer of all. ; I seek assistance through Your mercy. Rectify all of my affairs and do not entrust me to myself for the blink of an eye.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ʿanhu) narrates that the Prophet ﷺ said to Fāṭimah (raḍiy Allāhu ʿanhā), “What is preventing you from (doing) what I am advising you; that you say [the above] in the morning and evening?” (Nasā’ī in ʿAmal al-Yawm wa-l-Laylah 570)","reference":"(عمل اليوم والليلة للنسائي ٥٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"Duʿa for Seeking Protection from Shaytan","arabic":"رَبِّ أَعُوْذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِيْنِ ، وَأَعُوذُ بِكَ رَبِّ أَنْ يَّحْضُرُوْنِ.","transliteration":"Rabbi aʿūdhu bika min hamazāti-sh-shayāṭīn. Wa aʿūdhu bika Rabbi ay-yaḥḍurūn.","translation":"My Lord, I seek protection with You from the promptings of the devils; and I seek protection in You, my Lord, from their coming near me. (23:97-98)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"},{"title":"Protection from Evil Traits & Endings","arabic":"اَللّٰهُمَّ إِنّيْ أَعُوْذُ بِكَ مِنَ الْبُخْلِ ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ ، وَأَعُوْذُ بِكَ أَنْ أُرَدَّ إِلَىٰ أَرْذَلِ الْعُمُرِ ، وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا ، وَأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ.","transliteration":"Allāhumma innī aʿūdhu bika mina-l-bukhl, wa aʿūdhu bika mina-l-jubn, wa aʿūdhu bika an uradda ilā ardhali-l-ʿumur, wa aʿūdhu bika min fitnati-d-dunyā, wa aʿūdhu bika min ʿadhābi-l-qabr.","translation":"O Allah, I seek Your protection from miserliness and I seek Your protection from cowardice. I seek Your protection from being returned to the worst part of life (old age), I seek Your protection from the trials of the world, and I seek Your protection from the punishment of the grave.","description":null,"benefit":null,"virtue":null,"hadith":"Saʿd b. Abī Waqqās (radiy Allāhū ‘anhu) would instruct (to seek refuge) about five things [the above] and he would narrate it from the Messenger of Allah ﷺ . (Bukhārī 6370)","reference":"عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رضي الله عنه كَانَ يَأْمُرُ بِهَؤُلَاءِ الْخَمْسِ وَيُحَدِّثُهُنَّ عَنِ النَّبِيِّ صلى الله عليه وسلم: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبُخْلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ. (صحيح البخاري ٦٣٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/sad/"}]},{"feeling":"Scared","slug":"scared","url":"https://allahuakbarofficial.com/scared/","items_count":10,"duas":[{"title":"After a Nightmare","arabic":"أَعُوْذُ بِكَلِمَاتِ اللّٰهِ التَّامَّاتِ مِنْ غَضَبِهِ وَعِقَابِهِ ، وَشَرِّ عِبَادِهِ ، وَمِنْ هَمَزَاتِ الشَّيَاطِيْنِ وَأَنْ يَّحْضُرُوْنِ.","transliteration":"Aʿūdhu bi kalimāt-i-llāhi-t-tāmmāti min ghaḍabihī wa ʿiqābih, wa sharri ʿibādih, wa min hamazāti-sh-shayaṭīni wa ay-yaḥḍurūn.","translation":"I seek protection in the perfect words of Allah from His anger and punishment, from the evil of His servants, from the evil suggestions of the devils and from them appearing to me.","description":null,"benefit":null,"virtue":null,"hadith":"ʿAmr b. Shuʿayb narrated from his father, who narrated from his grandfather, that the Messenger of Allah ﷺ said: “When one of you becomes frightened during sleep, then let him say: [the above]. Indeed they shall not harm him.” He said: “So ʿAbdullah b. ʿAmr (raḍiy Allāhu ‘anhu) used to teach it to those of his children who attained maturity; and those of them who had not reached maturity, he would write it on a sheet and then hang it around their neck.” (Tirmidhī 3528)","reference":"The Messenger of Allah ﷺ said: “A good dream is from Allah, and a bad dream is from Shayṭān. When anyone has a bad dream, he should seek Allah’s protection and spit on his left — indeed (the dream) will not harm him.” (Bukhārī 6986)\\nعَنْ أَبِيهِ ، عَنْ جَدِّهِ أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم قَالَ:إِذَا فَزِعَ أَحَدُكُمْ فِي النَّوْمِ، فَلْيَقُلْ: أَعُوذُ بِكَلِمَاتِ اللهِ التَّامَّةِ مِنْ غَضَبِهِ وَعِقَابِهِ وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونِ، فَإِنَّهَا لَنْ تَضُرَّهُ. فَكَانَ عَبْدُ اللهِ بْنُ عُمَرَ يُلَقِّنُهَا مَنْ بَلَغَ مِنْ وَلَدِهِ، وَمَنْ لَمْ يَبْلُغْ مِنْهُمْ كَتَبَهَا فِي صَكٍّ، ثُمَّ عَلَّقَهَا فِي عُنُقِهِ.\\n(سنن الترمذي ٣٥٢٨)\\nعَنْ أَبِي قَتَادَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ: «الرُّؤْيَا الصَّالِحَةُ مِنَ اللهِ، وَالْحُلُمُ مِنَ الشَّيْطَانِ، فَإِذَا حَلَمَ فَلْيَتَعَوَّذْ مِنْهُ، وَلْيَبْصُقْ عَنْ شِمَالِهِ، فَإِنَّهَا لَا تَضُرُّهُ. (صحيح البخاري ٦٩٨٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"He said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/scared/"},{"title":"When One Is Afraid of People #1","arabic":"اَللّٰهُمَّ اكْفِنِيْهِمْ بِمَا شِئْتَ\\nعن صهيب؛ إن رسول الله صلى الله عليه وسلم قال كان ملك فيمن كان قبلكم. وكان له ساحر. فلما كبر قال للملك: إني قد كبرت. فابعث إلي غلاما أعلمه السحر. فبعث إليه غلاما يعلمه. فكان في طريقه، إذا سلك، راهب. فقعد إليه وسمع كلامه. فأعجبه. فكان إذا أتى الساحر مر بالراهب وقعد إليه. فإذا أتى الساحر ضربه. فشكا ذلك إلى الراهب. فقال: إذا خشيت الساحر فقل: حبسني أهلي. وإذا خشيت أهلك فقل: حبسني الساحر. فبينما هو كذلك إذ أتى على دابة عظيمة قد حبست الناس. فقال: اليوم أعلم آلساحر أفضل أم الراهب أفضل؟ فأخذ حجرا فقال: اللهم! إن كان أمر الراهب أحب إليك من أمر الساحر فاقتل هذه الدابة. حتى يمضي الناس. فرماها فقتلها. ومضى الناس. فأتى الراهب فأخبره. فقال له الراهب: أي بني! أنت، اليوم، أفضل مني. قد بلغ من أمرك ما أرى. وإنك ستبتلى. فإن ابتليت فلا تدل علي. وكان الغلام يبرئ الأكمه والأبرص ويداوي الناس من سائر الأدواء. فسمع جليس للملك كان قد عمي. فأتاه بهدايا كثيرة. فقال: ما ههنا لك أجمع، إن أنت شفيتني. فقال: إني لا أشفي أحدا. إنما يشفي الله. فإن أنت آمنت بالله دعوت الله فشفاك. فآمن بالله. فشفاه الله. فأتى الملك فجلس إليه كما كان يجلس. فقال له الملك: من رد عليك بصرك؟ قال: ربي. قال: ولك رب غيري؟ قال: ربي وربك الله. فأخذه فلم يزل يعذبه حتى دل على الغلام. فجئ بالغلام. فقال له الملك: أي بني! قد بلغ من سحرك ما تبرئ الأكمه والأبرص وتفعل وتفعل. فقال: إني لا أشفي أحدا. إنما يشفي الله. فأخذه فلم يزل يعذبه حتى دل على الراهب. فجئ بالراهب. فقيل له: ارجع عن دينك. فأبى. فدعا بالمئشار. فوضع المئشار على مفرق رأسه. فشقه حتى وقع شقاه. ثم جئ بجليس الملك فقيل له: ارجع عن دينك. فأبى. فوضع المئشار في مفرق رأسه. فشقه به حتى وقع شقاه. ثم جئ بالغلام فقيل له: ارجع عن دينك. فأبى. فدفعه إلى نفر من أصحابه فقال: اذهبوا به إلى جبل كذا وكذا. فاصعدوا به الجبل. فإذا بلغتم ذروته، فإن رجع عن دينه، وإلا فاطرحوه. فذهبوا به فصعدوا به الجبل. فقال: اللهم! اكفنيهم بما شئت.","transliteration":"Allāhumma-k-finīhim bimā shi’t.","translation":"O Allah, suffice me from them, with what You choose.","description":null,"benefit":null,"virtue":null,"hadith":"Suhaib (radiy Allāhū ʿanhu) reported that Allah’s Messenger ﷺ said: “There lived a king before you and he had a (court) magician. As he (the magician) grew old, he said to the king: I have grown old, send some young boy to me so that I should teach him magic. He (the king) sent to him a young man so that he should train him (in magic). And on his way (to the magician) he (the young man) found a monk sitting there. He (the young man) listened to his (the monk’s) talk and was impressed by it. It became his habit that on his way to the magician he met the monk and set there and he came to the magician (late). He (the magician) beat him because of delay. He made a complaint of that to the monk and he said to him: When you feel afraid of the magician, say: Members of my family had detained me. And when you feel afraid of your family you should say: The magician had detained me. It so happened that there came a huge beast (of prey) and it blocked the way of the people, and he (the young boy) said: I will come to know today whether the magician is superior or the monk is superior. He picked up a stone and said: O Allah, if the affair of the monk is dearer to Thee than the affair of the magician, cause death to this animal so that the people should be able to move about freely. He threw that stone towards it and killed it and the people began to move about (on the path freely). He (the young man) then came to that monk and Informed him and the monk said: Sonny, today you are superior to me. Your affair has come to a stage where I find that you would be soon put to a trial, and in case you are put to a trial don’t give my clue. That young man began to treat the blind and those suffering from leprosy and he in fact began to cure people from (all kinds) of illness. When a companion of the king who had gone blind heard about him, he came to him with numerous gifts and said: If you cure me all these things collected together here would be yours. Be said: I myself do not cure anyone. It is Allah Who cures and if you affirm faith in Allah, I shall also supplicate Allah to cure you. He affirmed his faith in Allah and Allah cured him and he came to the king and sat by his side as he used to sit before. The king said to him: Who restored your eyesight? He said: My Lord. Thereupon he said: It means that your Lord is One besides me. He said: My Lord and your Lord is Allah, so he (the king) took hold of him and tormented him till he gave a clue of that boy. The young man was thus summoned and the king said to him: O boy, it has been conveyed to me that you have become so much proficient in your magic that you cure the blind and those suffering from leprosy and you do such and such things. Thereupon he said: I do not cure anyone; it is Allah Who cures, and he (the king) took hold of him and began to torment him. So he gave a clue of the monk. The monk was thus summoned and it was said to him: You should turn back from your religion. He, however, refused to do so. He (ordered) for a saw to be brought (and when it was done) he (the king) placed it in the middle of his head and tore it into parts till a part fell down. Then the courtier of the king was brought and it was said to him: Turn back from your religion. Arid he refused to do so, and the saw was placed in the midst of his head and it was torn till a part fell down. Then that young boy was brought and it was said to him: Turn back from your religion. He refused to do so and he was handed over to a group of his courtiers. And he ‘said to them: Take him to such and such mountain; make him climb up that mountain and when you reach its top (ask him to renounce his faith) but if he refuses to do so, then throw him (down the mountain). So they took him and made him climb up the mountain and he said: O Allah, save me from them (in any way) Thou likest and the mountain began to quake and they all fell down and that person came walking to the king. The king said to him: What has happened to your companions? He said: Allah has saved me from them. He again handed him to some of his courtiers and said: Take him and carry him in a small boat and when you reach the middle of the ocean (ask him to renounce) his religion, but if he does not renounce his religion throw him (into the water). So they took him and he said: O Allah, save me from them and what they want to do. It was quite soon that the boat turned over and they were drowned and he came walking to the king, and the king said to him: What has happened to your companions? He said: Allah has saved me from them, and he said to the king: You cannot kill me until you do what I ask you to do. And he said: What is that? He said: You should gather people in a plain and hang me by the trunk (of a tree). Then take hold of an arrow from the quiver and say: In the name of Allah, the Lord of the young boy; then shoot an arrow and if you do that then you would be able to kill me. So he (the king) called the people in an open plain and tied him (the boy) to the trunk of a tree, then he took hold of an arrow from his quiver and then placed the arrow in the bow and then said: In the name of Allah, the Lord of the young boy; he then shot an arrow and it bit his temple. He (the boy) placed his hands upon the temple where the arrow had bit him and he died and the people said: We affirm our faith in the Lord of this young man, we affirm our faith in the Lord of this young man, we affirm our faith in the Lord of this young man. The courtiers came to the king and it was said to him: Do you see that Allah has actually done what you aimed at averting. They (the people) have affirmed their faith in the Lord. He (the king) commanded ditches to be dug at important points in the path. When these ditches were dug, and the fire was lit in them it was said (to the people): He who would not turn back from his (boy’s) religion would be thrown in the fire or it would be said to them to jump in that. (The people courted death but did not renounce religion) till a woman came with her child and she felt hesitant in jumping into the fire and the child said to her: 0 mother, endure (this ordeal) for it is the Truth.’’","reference":"(صحيح مسلم ٣٠٠٥) | Muslim 3005","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"He made a complaint of that to the monk and he said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/scared/"},{"title":"When One Is Afraid of People #2","arabic":"حَسْبُنَا اللّٰهُ وَنِعْمَ الْوَكِيْلُ","transliteration":"Ḥasbunallāhu wa niʿmal Wakīl.","translation":"Allah is enough for us and He is the Best Protector.","description":null,"benefit":null,"virtue":null,"hadith":"Ibn ʿAbbās (radiy Allāhū ʿanhumā) narrated: “[The above] was said by Ibrāhīm (ʿalayhis-salām) when he was thrown into the fire; and it was said by Muḥammad ﷺ when (the hypocrites) said, ‘Your enemies have mobilised their forces against you, so fear them,’ — but this only increased them in faith and they replied: ‘Allah is enough for us and He is the Best Protector (3:173).’” (Bukhārī 4563)","reference":"Muslim 3005\\nعَنِ ابْنِ عَبَّاسٍ : حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ} قَالَهَا إِبْرَاهِيمُ عليه السلام حِينَ أُلْقِيَ فِي النَّارِ، وَقَالَهَا مُحَمَّدٌ صلى الله عليه وسلم حِينَ قَالُوا: إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ. (صحيح البخاري ٤٥٦٣)\\n(صحيح مسلم ٣٠٠٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/scared/"},{"title":"When One Is Afraid of People #3","arabic":"اَللّٰهُمَّ إِنَّا نَجْعَلُكَ فِيْ نُحُوْرِهِمْ ، وَنَعُوْذُ بِكَ مِنْ شُرُوْرِهِمْ","transliteration":"Allāhumma innā najʿaluka fī nuḥūrihim, wa naʿūdhu bika min shurūrihim.","translation":"O Allah, we make You our shield against them and we seek refuge in You from their evil.","description":null,"benefit":null,"virtue":null,"hadith":"When the Messenger of Allah ﷺ was apprehensive of [a group] of people, he would say: [the above]. (Abū Dāwūd 1537)","reference":"عَنْ أَبِي بُرْدَةَ بْنِ عَبْدِ اللهِ : أَنَّ أَبَاهُ حَدَّثَهُ، أَنَّ النَّبِيَّ صلى الله عليه وسلم كَانَ إِذَا خَافَ قَوْمًا قَالَ: اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ، وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ.\\n(سنن ابي داود ١٥٣٧)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/scared/"},{"title":"When One Is Afraid of People #4","arabic":"اَللّٰهُمَّ أنْتَ عَضُدِيْ وَأَنْتَ نَصِيْرِيْ ، بِكَ أَحُوْلُ ، وبِكَ أصُوْلُ ، وَبِكَ أُقَاتِلُ","transliteration":"Allāhumma Anta Aḍudī wa Anta Naṣīrī, Bika aḥūlu, wa bika aṣūlu, wa bika uqātil.","translation":"O Allah, You are my aid and helper; by You I move, by You I attack, and by You I fight.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ‘anhu) narrated that when the Messenger of Allah ﷺ went on an expedition, he said [the above].” (Abū Dāwūd 2632)","reference":"عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ:كَانَ رَسُولُ اللهِ صلى الله عليه وسلم إِذَا غَزَا قَالَ: اللَّهُمَّ أَنْتَ عَضُدِي وَنَصِيرِي، بِكَ أَحُولُ وَبِكَ أَصُولُ، وَبِكَ أُقَاتِلُ. (سنن ابي داود ٢٦٣٢)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/scared/"},{"title":"When One Is Afraid of People #5","arabic":"اَللّٰهُمَّ اسْتُرْ عَوْرَاتِنَا وَاٰمِنْ رَوْعَاتِنَا","transliteration":"Allāhumma-stur ‘awrātinā wa āmin raw‘ātinā.","translation":"O Allah, conceal our faults and calm our fears.","description":null,"benefit":null,"virtue":null,"hadith":"Abū Sa‘īd al-Khuḍrī (raḍiy Allāhu ‘anhu) narrates: “We (the Companions) said on the Day of Khandaq (Trenches): ‘O Messenger of Allah, is there anything we can say? For the hearts have reached the throats (out of fear).’ He ﷺ replied: ‘Yes! (Say) [the above].’ Abū Sa‘īd al-Khuḍrī says: ‘Allah, Mighty and Majestic destroyed the faces of the enemy with wind and Allah made them face defeat through wind.’” (Ahmad 10996)","reference":"حَدَّثَنَا أَبُو عَامِرٍ، حَدَّثَنَا الزُّبَيْرُ بْنُ عَبْدِ اللهِ، حَدَّثَنِي رُبَيْحُ بْنُ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنْ أَبِيهِ قَالَ: قُلْنَا يَوْمَ الْخَنْدَقِ: يَا رَسُولَ اللهِ، هَلْ مِنْ شَيْءٍ نَقُولُهُ فَقَدْ بَلَغَتِ الْقُلُوبُ الْحَنَاجِرَ؟ قَالَ نَعَمْ، اللهُمَّ اسْتُرْ ‌عَوْرَاتِنَا، وَآمِنْ رَوْعَاتِنَا قَالَ: فَضَرَبَ اللهُ عز وجل وُجُوهَ أَعْدَائِهِ بِالرِّيحِ، فَهَزَمَهُمُ اللهُ عز وجل بِالرِّيحِ. (مسند احمد ١٠٩٩٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/scared/"},{"title":"When Meeting the Enemy","arabic":"اَللّٰهُمَّ مُنْزِلَ الْكِتَابِ ، ومُجْرِيَ السَّحَابِ ، وهَازِمَ الْأحْزَابِ ، اهْزِمْهُمْ وانْصُرْنَا عَلَيْهِمْ","transliteration":"Allāhumma munzila-l-kitāb, wa mujriya-s-saḥāb, wa hāzima-l-aḥzāb, ihzimhum wa-n-ṣurnā ʿalayhim.","translation":"O Allah, Revealer of the Book, Mover of the clouds, Defeater of the tribes, defeat them and grant us victory over them.","description":null,"benefit":null,"virtue":null,"hadith":"ʿAbdullāh b. Abī Awfā (raḍiy Allāhu ‘anhu) reported that the Messenger of Allah ﷺ, on one of the days that he encountered the enemy, waited until the sun rose, then stood among the people and said: “O people, do not look forward to meeting the enemy, but ask Allah for well-being. When you encounter them, be steadfast. And know that Paradise is under the shade of swords.” Then he said [the above]. (Bukhārī 2965)","reference":"عَنْ سَالِمٍ أَبِي النَّضْرِ مَوْلَى عُمَرَ بْنِ عُبَيْدِ اللهِ وَكَانَ كَاتِبًا لَهُ قَالَ: كَتَبَ إِلَيْهِ عَبْدُ اللهِ بْنُ أَبِي أَوْفَى رضي الله عنهما فَقَرَأْتُهُ: أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم فِي بَعْضِ أَيَّامِهِ الَّتِي لَقِيَ فِيهَا انْتَظَرَ حَتَّى مَالَتِ الشَّمْسُ ثُمَّ قَامَ فِي النَّاسِ قَالَ: أَيُّهَا النَّاسُ لَا تَتَمَنَّوْا لِقَاءَ الْعَدُوِّ وَسَلُوا اللهَ الْعَافِيَةَ فَإِذَا لَقِيتُمُوهُمْ فَاصْبِرُوا وَاعْلَمُوا أَنَّ الْجَنَّةَ تَحْتَ ظِلَالِ السُّيُوفِ. ثُمَّ قَالَ: اللَّهُمَّ مُنْزِلَ الْكِتَابِ وَمُجْرِيَ السَّحَابِ وَهَازِمَ الْأَحْزَابِ اهْزِمْهُمْ وَانْصُرْنَا عَلَيْهِمْ. (صحيح البخاري ٢٩٦٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Then he said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/scared/"},{"title":"When One Feels Frightened","arabic":"لَا إِلٰهَ إِلَّا اللّٰهُ","transliteration":"Lā ilāha illā-llāh.","translation":"There is no god worthy of worship except Allah.","description":null,"benefit":null,"virtue":null,"hadith":"Zaynab b. Jaḥsh (raḍiy Allāhu ʿanhā) said that the Messenger of Allah ﷺ once entered her house in a state of fear and said, “[The above]. Woe to the Arabs from a danger that is imminent. An opening has been made today in the wall of Ya‘jūj and Ma‘jūj like this” and he made a circle with his thumb and index finger. Zaynab b. Jaḥsh said, “O Messenger of Allah ﷺ! Will we be destroyed even though there are pious people amongst us?” He ﷺ said, “Yes, when evil becomes widespread.” (Bukhārī 3346)","reference":"عَنْ أُمِّ حَبِيبَةَ بِنْتِ أَبِي سُفْيَانَ عَنْ زَيْنَبَ ابْنَةِ جَحْشٍ رضي الله عنهن أَنَّ النَّبِيَّ صلى الله عليه وسلم دَخَلَ عَلَيْهَا فَزِعًا يَقُولُ لَا إِلَهَ إِلَّا اللهُ وَيْلٌ لِلْعَرَبِ مِنْ شَرٍّ قَدِ اقْتَرَبَ فُتِحَ الْيَوْمَ مِنْ رَدْمِ يَاجُوجُ وَمَاجُوجُ مِثْلُ هَذِهِ وَحَلَّقَ بِإِصْبَعِهِ الْإِبْهَامِ وَالَّتِي تَلِيهَا قَالَتْ زَيْنَبُ ابْنَةُ جَحْشٍ: فَقُلْتُ: يَا رَسُولَ اللهِ أَنَهْلِكُ وَفِينَا الصَّالِحُونَ قَالَ نَعَمْ إِذَا كَثُرَ الْخَبَثُ. (صحيح البخاري ٣٣٤٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Jaḥsh said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/scared/"},{"title":"When One Fears a Ruler","arabic":"اَللّٰهُمَّ رَبَّ السَّمٰـوٰتِ السَّبْعِ ، وَرَبَّ العَرْشِ العَظِيْمِ ، كُنْ لِيْ جَارًا مِنْ فُلَانِ بْنِ فُلَانٍ ، وَأَحْزَابِهِ مِنْ خَلَائِقِكَ ؛ أنْ يَّفْرُطَ عَلَىَّ أحَدٌ مِنهُمْ أوْ يَطْغٰى ، عَزَّ جَارُكَ ، وَجَلَّ ثَنَاؤُكَ ، وَلَا إِلٰهَ إِلَّا أَنْتَ","transliteration":"Allāhumma Rabb-as-samāwāti-s-sabiʿ, wa Rabba-l-ʿArshi-l-ʿaẓīm, kun lī jāran min fulāni-bni-fulān, wa aḥzābihi min khalāiqiqa; ay-yafruṭa ʿalayya aḥadun minhum aw yaṭgā, ʿazza jāruk, wa jalla thanā’uk, wa lā ilāha illā Ant.","translation":"O Allah, Lord of the seven heavens, Lord of the Magnificent Throne, be for me a support against [such and such a person] and his helpers from among your creatures, lest any of them abuse me or do me wrong. Mighty is Your patronage, and glorious are Your praises. There is none worthy of worship but You.","description":null,"benefit":null,"virtue":null,"hadith":"ʿAbdullāh b. Masʿūd (raḍiy Allāhu ‘anhu) said: “If a leader is appointed over you from whom you fear injustice, let him say: [the above].” (Al Adab Al Mufrad 707)","reference":"عَنِ الْأَعْمَشِ قَالَ: حَدَّثَنَا ثُمَامَةُ بْنُ عُقْبَةَ قَالَ: سَمِعْتُ الْحَارِثَ بْنَ سُوَيْدٍ يَقُولُ: قَالَ عَبْدُ اللَّهِ بْنُ مَسْعُودٍ: إِذَا كَانَ عَلَى أَحَدِكُمْ إِمَامٌ يَخَافُ تَغَطْرُسَهُ أَوْ ظُلْمَهُ، فَلْيَقُلِ: اللَّهُمَّ رَبَّ السَّمَاوَاتِ السَّبْعِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، كُنْ لِي جَارًا مِنْ فُلَانِ بْنِ فُلَانٍ وَأَحْزَابِهِ مِنْ خَلَائِقِكَ، أَنْ يَفْرُطَ عَلَيَّ أَحَدٌ مِنْهُمْ أَوْ يَطْغَى، عَزَّ جَارُكَ، وَجَلَّ ثَنَاؤُكَ، وَلَا إِلَهَ إِلَّا أَنْتَ. (الادب المفرد ٧٠٧)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/scared/"},{"title":"When One Is Distressed","arabic":"اَللّٰهُمَّ رَحْمَتَكَ أَرْجُوْ فَلَا تَكِلْنِيْ إِلٰى نَفْسِيْ طَرْفَةَ عَيْنٍ ، وَأَصْلِحْ لِي شَأْنِيْ كُلَّهُ ، لَا إِلٰهَ إِلَّا أَنْتَ","transliteration":"Allāhumma raḥmataka arjū fa-lā takilnī ilā nafsī ṭarfata ʿayn, wa aṣliḥ lī sha’nī kullah, lā ilāha illā Ant.","translation":"O Allah! It is certainly Your Mercy what I hope for, so do not entrust me to myself for the blink of an eye; and rectify all of my affairs. There is no god worthy of worship except You.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ said: “The supplications of the distressed person are [the above].” (Abū Dāwūd 5090)","reference":"عَنْ جَعْفَرِ بْنِ مَيْمُونٍ قَالَ: حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ «أَنَّهُ قَالَ لِأَبِيهِ : يَا أَبَتِ إِنِّي أَسْمَعُكَ تَدْعُو كُلَّ غَدَاةٍ: اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَدْعُو بِهِنَّ، فَأَنَا أُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ قَالَ عَبَّاسٌ فِيهِ: وَتَقُولُ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَتَدْعُو بِهِنَّ، فَأُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ. قَالَ: وَقَالَ رَسُولُ اللهِ صلى الله عليه وسلم: دَعَوَاتُ الْمَكْرُوبِ اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا ‌تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ. (سنن ابي داود ٥٠٩٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/scared/"}]},{"feeling":"Tired","slug":"tired","url":"https://allahuakbarofficial.com/tired/","items_count":5,"duas":[{"title":"Protect Yourself From Anxiety, Laziness & Debt","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ ، وَأَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ ، وَأَعُوْذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.","transliteration":"Allāhumma innī aʿūdhu bika min-l-hammi wa-l-ḥazan, wa aʿūdhu bika min-l-ʿajzi wa-l-kasal, wa aʿūdhu bika min-l-jubni wa-l-bukhl, wa aʿūdhu bika min ghalabati-d-dayni wa qahri-r-rijāl.","translation":"O Allah, I seek Your protection from anxiety and grief. I seek Your protection from inability and laziness. I seek Your protection from cowardice and miserliness, and I seek Your protection from being overcome by debt and being overpowered by men.","description":null,"benefit":null,"virtue":"Abū Saʿīd al-Khudrī (raḍiy Allāhu ʿanhu) narrated that one day, the Messenger of Allah ﷺ entered the masjid. He saw a man from the Anṣār called Abū Umāmah (raḍiy Allāhu ʿanhu). He ﷺ asked, “What is the matter? Why are you sitting in the masjid when it is not the time for prayer?” He replied, “Never-ending worries and debts, O Messenger of Allah.” The Messenger of Allah ﷺ then asked, “Shall I not teach you words by which, when you say them, Allah will remove your worries, and settle your debts?” He replied, “Yes of course, O Messenger of Allah.” He ﷺ said, “Say in the morning and evening [the above].” Abū Umāmah (raḍiy Allāhu ʿanhu) said, “Then I did that, and Allah removed my worries and settled my debts.” (Abū Dāwūd 1555)","hadith":null,"reference":"عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: دَخَلَ رَسُولُ صَلَّى عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ مِنَ الْأَنْصَارِ، يُقَالُ لَهُ: أَبُو أُمَامَةَ، فَقَالَ: «يَا أُمَامَةَ، مَا لِي أَرَاكَ جَالِسًا فِي الْمَسْجِدِ فِي غَيْرِ وَقْتِ الصَّلَاةِ؟»، قَالَ: هُمُومٌ لَزِمَتْنِي، وَدُيُونٌ يَا رَسُولَ اللَّهِ، قَالَ: أَفَلَا أُعَلِّمُكَ كَلَامًا إِذَا أَنْتَ قُلْتَهُ أَذْهَبَ عز وجل هَمَّكَ، وَقَضَى عَنْكَ دَيْنَكَ؟، قَالَ: قُلْتُ: بَلَى، يَا رَسُولَ، قَالَ: ” قُلْ إِذَا أَصْبَحْتَ، وَإِذَا أَمْسَيْتَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَقَهْرِ الرِّجَالِ “، قَالَ: فَفَعَلْتُ ذَلِكَ، فَأَذْهَبَ اللَّهُ عز وجل هَمِّي، وَقَضَى عَنِّي دَيْنِي.(سنن أبي داود ١٥٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/tired/"},{"title":"Ask Allah for Good Health and Protection","arabic":"اَللّٰهُمَّ عَافِنِيْ فِيْ بَدَنِيْ ، اَللّٰهُمَّ عَافِنِيْ فِيْ سَمْعِيْ ، اَللّٰهُمَّ عَافِنِيْ فِيْ بَصَرِيْ ، لَا إِلٰهَ إِلَّا أَنْتَ ، اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، وأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلٰهَ إِلَّا أَنْتَ.\\nعن جعفر بنِ ميمون ، حدَّثني عبدُ الرحمن بنُ أبي بكرَة، أنه قال لأبيه: يا أبةِ إني أَسمَعُكَ تَدْعُو كلَّ غَدَاةٍ: اللَّهُمَّ عافِني في بَدَني، اللهم عافِنِي في سَمْعِي، اللَّهُمَّ عافني في بَصَري، لا إلهَ إلا أنت، تُعيدها ثلاثاً حينَ تُصْبِحُ، وثلاثاً حينَ تُمسي، فقال: إني سمعتُ رسولَ الله صلى الله عليه وسلم -يدعو بهنَّ فانا أُحِبُّ أن أستَنَّ بسُنَّتِه، وقال عليٌّ وعباسٌ فيه: ويقول: اللهُمَّ إني أعوذُ بِكَ من الكُفر والفَقرِ، اللَّهُمَ إني أعُوذُ بِكَ مِن عذابِ القبر، لا إلهَ إلا أنتَ، يُعيدها ثلاثاً حِين يُصبحُ، وثلاثاً حين يُمسي، فيَدعُو بهِنَّ، فاُحِبُّ أن أستَنَّ بسُنتَّه.\\nحَدَّثَنَا أَبُو عَامِرٍ، حَدَّثَنَا عَبْدُ الْجَلِيلِ، حَدَّثَنِي جَعْفَرُ بْنُ مَيْمُونٍ، حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكَرَةَ أَنَّهُ قَالَ لِأَبِيهِ:","transliteration":"Allāhumma ʿāfinī fī badanī, Allāhumma ʿāfinī fī samʿī, Allāhumma ʿāfinī fī baṣarī, lā ilāha illā Ant, Allāhumma innī aʿūdhu bika mina-l-kufri wa-l-faqr, wa aʿūdhu bika min ʿadhābi-l-qabr, lā ilāha illā Ant.","translation":"Repeat.   x3","description":null,"benefit":null,"virtue":null,"hadith":"‘Abd al-Raḥmān b. Abī Bakrah (raḍiy Allāhu ʿanhu) narrates that he said to his father, “O my father! I hear you supplicating with [the above] every morning. You repeat them three times in the morning and three times in the evening.” He said, “Indeed I heard the Messenger of Allah ﷺ supplicating with these (words) and I love to follow his practice.” (Abū Dāwūd 5090, Aḥmad 20430)","reference":"(سنن أبي داود ٥٠٩٠)\\nيَا أَبَهْ، إِنِّي أَسْمَعُك تَدْعُو كُلَّ غَدَاةٍ: ” اللهُمَّ عَافِنِي فِي بَدَنِي، اللهُمَّ عَافِنِي فِي سَمْعِي، اللهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ ” تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي. وَتَقُولُ: ” اللهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، اللهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ ” تُعِيدُهَا حِينَ تُصْبِحُ ثَلَاثًا، وَثَلَاثًا حِينَ تُمْسِي. قَالَ: نَعَمْ يَا بُنَيَّ، إِنِّي سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَدْعُو بِهِنَّ، فَأُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ. (مسند أحمد ٢٠٤٣٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"He said","repeat_count":3,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/tired/"},{"title":"Allah Will Suffice You in Everything","arabic":"حَسْبِيَ اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ ، عَلَيْهِ تَوَكَّلْتُ ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ.","transliteration":"Ḥasbiya-Allāhu lā ilāha illā Huwa, ʿalayhi tawakkalt, wa Huwa Rabbu-l-ʿArshi-l-ʿaẓīm.","translation":"Repeat.  x7","description":null,"benefit":null,"virtue":"Abū al-Dardā’ (raḍiy Allāhu ʿanhu) narrates from the Messenger of Allah ﷺ that he said: “Whoever recites [the above] seven times in the morning and in the evening, Allah will suffice him in everything that concerns him in matters of this world and the next.” (Ibn al-Sunnī 71)","hadith":null,"reference":"عَنْ أَبِي الدَّرْدَاءِ، رضي الله عنه، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ: مَنْ قَالَ فِي كُلِّ يَوْمٍ حِينَ يُصْبِحُ وَحِينَ يُمْسِي: حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ، سَبْعَ مَرَّاتٍ، كَفَاهُ اللَّهُ عز وجل هَمَّهُ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ. (عمل اليوم والليلة لابن السني ٧١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":7,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/tired/"},{"title":"Duʿa of Prophet Musa ﷺ Expressing His Dire Need","arabic":"رَبِّ إِنِّيْ لِمَآ أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيْرٌ.","transliteration":"Rabbi innī limā anzalta illayya min khayrin faqīr.","translation":"My Lord, truly I am in dire need of any good which You may send me. (28:24)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/tired/"},{"title":"Entrust All Your Matters to Allah","arabic":"يَا حَيُّ يَا قَيُّوْمُ ، بِرَحْمَتِكَ أَسْتَغِيْثُ ، أَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ ، وَلَا تَكِلْنِيْ إِلَىٰ نَفْسِيْ طَرْفَةَ عَيْنٍ.\\nأخبرنَا عبد الرَّحْمَن بن مُحَمَّد بن سَلام حَدثنَا زيد بن الْحباب أَخْبرنِي عُثْمَان بن موهب الْهَاشِمِي سَمِعت أنس بن مَالك يَقُول قَالَ النَّبِي صلى الله عليه وسلم لفاطمة مَا يمنعك أَن سَمْعِي مَا أوصيك بِهِ أَو تقولي إِذا أَصبَحت وَإِذا أمسيت يَا حَيّ يَا قيوم بِرَحْمَتك أستغيث أصلح لي شأني كلَّه وَلَا تَكِلنِي إِلَى نَفسِي طرفَة عين.","transliteration":"Yā Ḥayyu yā Qayyūm, bi-raḥmatika astaghīth, aṣliḥ lī sha’nī kullah, wa lā takilnī ilā nafsī ṭarfata ʿayn.","translation":"O The Ever Living, The Sustainer of all. ; I seek assistance through Your mercy. Rectify all of my affairs and do not entrust me to myself for the blink of an eye.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ʿanhu) narrates that the Prophet ﷺ said to Fāṭimah (raḍiy Allāhu ʿanhā), “What is preventing you from (doing) what I am advising you; that you say [the above] in the morning and evening?” (Nasā’ī in ʿAmal al-Yawm wa-l-Laylah 570)","reference":"(عمل اليوم والليلة للنسائي ٥٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/tired/"}]},{"feeling":"Suicidal","slug":"suicidal","url":"https://allahuakbarofficial.com/suicidal/","items_count":14,"duas":[{"title":"Surah al-Fatihah: The Greatest Duʿa","arabic":"بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيْمِ ،\\nاَلْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِيْنَ ، الرَّحْمٰنِ الرَّحِيْمِ ، مٰلِكِ يَوْمِ الدِّيْنِ ، إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِيْنُ ، اِهْدِنَا الصِّرَاطَ الْمُسْتَقِيْمَ ، صِرَاطَ الَّذِيْنَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوْبِ عَلَيْهِمْ وَلَا الضَّآلِّيْنَ.","transliteration":"Bismi-llāhi-r-Raḥmāni-r-Raḥīm. Alḥamdu-lillāhi Rabbi-l-ʿālamīn, ar-Raḥmāni-r-Raḥīm, Māliki yawmi-d-dīn, iyyāka naʿbudu wa iyyāka nastaʿīn, ihdina-ṣ-Ṣirāṭa-l-Mustaqīm, ṣirāṭa-lladhīna anʿamta ʿalayhim ghayri-l-maghḍūbi ʿālayhim wa la-ḍ-ḍāllīn.","translation":"In the name of Allah, the All-Merciful, the Very Merciful. All praises and thanks are for Allah, the Lord of all the worlds, The All-Merciful, The Very Merciful, Master of the Day of Judgement. You Alone we worship, You Alone we ask for help. Guide us on the Straight Path, the path of those whom You have favoured, not of those who incur (Your) anger nor of those who have gone astray. (1:1-7)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/suicidal/"},{"title":"When Difficulties Make You Yearn for Death","arabic":"اَللّٰهُمَّ أَحْيِنِيْ مَا كَانَتِ الْحَيَاةُ خَيْرًا لِّيْ ، وَتَوَفَّنِيْ إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِّيْ","transliteration":"Allāhumma aḥyinī mā kānati-l-ḥayātu khayral-lī, wa tawaffanī idhā kānati-l-wafātu khayral-lī.","translation":"O Allah, let me live as long as life is better for me; and give me death when death is better for me.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ said: “None of you should wish for death because of a difficulty that befalls him. Rather he should say [the above].” (Bukhārī 5671, Muslim 2680)","reference":"عَنْ أَنَسِ بْنِ مَالِكٍ رضي الله عنه، قَالَ النَّبِيُّ صلى الله عليه وسلم: «لَا يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ مِنْ ضُرٍّ أَصَابَهُ، فَإِنْ كَانَ لَا بُدَّ فَاعِلًا فَلْيَقُلِ: اللَّهُمَّ أَحْيِنِي مَا كَانَتِ الْحَيَاةُ خَيْرًا لِي، وَتَوَفَّنِي إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِي. (صحيح البخاري ٥٦٧١)\\nعَنْ أَنَسٍ، قَالَ قَالَ رسول الله صلى الله عليه وسلم لا يتمنين أحدكم الموت لضر نزل به. فإن كان لابد متمنيا فليقل: اللهم! أحيني ما كانت الحياة خيرا لي، وتوفني إذا كانت الوفاة خيرا لي. (صحيح مسلم ٢٦٨٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/suicidal/"},{"title":"Protect Yourself From Anxiety, Laziness & Debt","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ ، وَأَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ ، وَأَعُوْذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.","transliteration":"Allāhumma innī aʿūdhu bika min-l-hammi wa-l-ḥazan, wa aʿūdhu bika min-l-ʿajzi wa-l-kasal, wa aʿūdhu bika min-l-jubni wa-l-bukhl, wa aʿūdhu bika min ghalabati-d-dayni wa qahri-r-rijāl.","translation":"O Allah, I seek Your protection from anxiety and grief. I seek Your protection from inability and laziness. I seek Your protection from cowardice and miserliness, and I seek Your protection from being overcome by debt and being overpowered by men.","description":null,"benefit":null,"virtue":"Abū Saʿīd al-Khudrī (raḍiy Allāhu ʿanhu) narrated that one day, the Messenger of Allah ﷺ entered the masjid. He saw a man from the Anṣār called Abū Umāmah (raḍiy Allāhu ʿanhu). He ﷺ asked, “What is the matter? Why are you sitting in the masjid when it is not the time for prayer?” He replied, “Never-ending worries and debts, O Messenger of Allah.” The Messenger of Allah ﷺ then asked, “Shall I not teach you words by which, when you say them, Allah will remove your worries, and settle your debts?” He replied, “Yes of course, O Messenger of Allah.” He ﷺ said, “Say in the morning and evening [the above].” Abū Umāmah (raḍiy Allāhu ʿanhu) said, “Then I did that, and Allah removed my worries and settled my debts.” (Abū Dāwūd 1555)","hadith":null,"reference":"عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: دَخَلَ رَسُولُ صَلَّى عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ مِنَ الْأَنْصَارِ، يُقَالُ لَهُ: أَبُو أُمَامَةَ، فَقَالَ: «يَا أُمَامَةَ، مَا لِي أَرَاكَ جَالِسًا فِي الْمَسْجِدِ فِي غَيْرِ وَقْتِ الصَّلَاةِ؟»، قَالَ: هُمُومٌ لَزِمَتْنِي، وَدُيُونٌ يَا رَسُولَ اللَّهِ، قَالَ: أَفَلَا أُعَلِّمُكَ كَلَامًا إِذَا أَنْتَ قُلْتَهُ أَذْهَبَ عز وجل هَمَّكَ، وَقَضَى عَنْكَ دَيْنَكَ؟، قَالَ: قُلْتُ: بَلَى، يَا رَسُولَ، قَالَ: ” قُلْ إِذَا أَصْبَحْتَ، وَإِذَا أَمْسَيْتَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَقَهْرِ الرِّجَالِ “، قَالَ: فَفَعَلْتُ ذَلِكَ، فَأَذْهَبَ اللَّهُ عز وجل هَمِّي، وَقَضَى عَنِّي دَيْنِي.(سنن أبي داود ١٥٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/suicidal/"},{"title":"Attain Well-being in This World and the Hereafter","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِيْ دِيْنِيْ وَدُنْيَايَ وَأَهْلِيْ وَمَالِيْ ، اَللّٰهُمَّ اسْتُرْ عَوْرَاتِيْ وَآمِنْ رَّوْعَاتِيْ ، اَللّٰهُمَّ احْفَظْنِيْ مِنْ بَيْنِ يَدَيَّ ، وَمِنْ خَلْفِيْ ، وَعَنْ يَّمِيْنِيْ ، وَعَنْ شِمَالِيْ ، وَمِنْ فَوْقِيْ ، وَأَعُوْذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِيْ.","transliteration":"Allāhumma innī as’aluka-l-ʿāfiyata fi-d-dunyā wa-l-ākhirah. Allāhumma innī as’aluka-l-ʿafwa wa-l-ʿāfiyata fī dīnī wa dunyāya wa ahlī wa mālī, Allāhumma-stur ʿawrātī wa āmi-r-rawʿātī. Allāhumma-ḥfaẓnī mim bayni yadayya wa min khalfī, wa ʿay-yamīnī wa ʿan shimālī wa min fawqī, wa aʿūdhu bi-ʿaẓamatika an ughtāla min taḥtī.","translation":"O Allah, I ask You for well-being in this world and the next. O Allah, I ask You for forgiveness and well-being in my religion, in my worldly affairs, in my family and in my wealth. O Allah, conceal my faults and calm my fears. O Allah, guard me from in front of me and behind me, from my right, and from my left, and from above me. I seek protection in Your Greatness from being unexpectedly destroyed from beneath me.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “Ask Allah for forgiveness and well-being (‘āfiyah). Indeed, after conviction (yaqīn), no one has been granted anything better than well-being.” (Tirmidhī)","hadith":"ʿAbdullāh b. ʿUmar (raḍiy Allāhu ʿanhumā) narrated: “The Messenger of Allah ﷺ never failed to say these words in the morning and in the evening.” (Abū Dāwūd 5074)","reference":"عَنْ جُبَيْرِ بْنِ أَبِي سُلَيْمَانَ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ، قَالَ: سَمِعْتُ ابْنَ عُمَرَ، يَقُولُ: لَمْ يَكُنْ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَعُ هَؤُلَاءِ الدَّعَوَاتِ، حِينَ يُمْسِي، وَحِينَ يُصْبِحُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَتِي، وَقَالَ عُثْمَانُ: عَوْرَاتِي وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي.(سنن أبي داود ٥٠٧٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/suicidal/"},{"title":"Grief & Anxiety #1","arabic":"اَللّٰهُمَّ إِنِّيْ عَبْدُكَ ، وَابْنُ عَبْدِكَ ، وَابْنُ أَمَتِكَ ، نَاصِيَتِيْ بِيَدِكَ ، مَاضٍ فِيَّ حُكْمُكَ ، عَدْلٌ فِيَّ قَضَاؤُكَ ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ ، سَمَّيْتَ بِهِ نَفْسَكَ ، أَوْ عَلَّمْتَهُ أَحَدًا مِّنْ خَلْقِكَ ، أَوْ أَنْزَلْتَهُ فِيْ كِتَابِكَ ، أَوِ اسْتَأْثَرْتَ بِهِ فِيْ عِلْمِ الْغَيْبِ عِنْدَكَ ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيْعَ قَلْبِيْ ، وَنُوْرَ صَدْرِيْ ، وَجَلَاءَ حُزْنِيْ ، وَذَهَابَ هَمِّيْ","transliteration":"Allāhumma innī ʿabduk, wa-bnu ʿabdik, wa-bnu amatik, nāṣiyatī bi-yadik, māḍin fiyya ḥukmuk, ʿadlun fiyya qaḍā’uk, as’aluka bi-kulli-smin huwa lak, sammayta bihī nafsak, aw ʿallamtahū aḥadam-min khalqik, aw anzaltahū fī kitābik, awi-sta’tharta bihī fī ʿilmi-l-ghaybi ʿindak, an tajʿala-l-Qur’āna rabīʿa qalbī, wa nūra ṣadrī, wa jalā’a ḥuznī, wa dha-hāba hammī.","translation":"O Allah, I am Your servant and the son of Your male servant and the son of Your female servant. My forehead is in Your Hand (i.e. you have control over me). I am subject to Your judgement and Your decree concerning me is just. I ask You – by every name that is Yours, by which You have named Yourself, or taught any one of Your creation, or revealed in Your Book, or kept unto Yourself in the knowledge of the unseen that is with You – to make the Qur’ān the spring of my heart, the light of my chest, the banisher of my grief and the reliever of my anxiety.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “There is no one who is stricken with grief and anxiety, and then says [the above] — except that Allah will remove his grief and anxiety, and will give him joy instead.” The Companions asked, ‘O Messenger of Allah, should we not learn these words?’ He ﷺ replied, ‘Certainly! The one who hears them should learn them.’” (Ahmad 3712)","hadith":null,"reference":"عَنْ عَبْدِ اللهِ، قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: مَا أَصَابَ أَحَدًا قَطُّ هَمٌّ وَلَا حَزَنٌ، فَقَالَ: اللهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجِلَاءَ حُزْنِي، وَذَهَابَ هَمِّي، إِلَّا أَذْهَبَ اللهُ هَمَّهُ وَحُزْنَهُ، وَأَبْدَلَهُ مَكَانَهُ فَرَحًا، قَالَ: فَقِيلَ: يَا رَسُولَ اللهِ، أَلَا نَتَعَلَّمُهَا؟ فَقَالَ: بَلَى، يَنْبَغِي لِمَنْ سَمِعَهَا أَنْ يَتَعَلَّمَهَا. (مسند أحمد ٣٧١٢)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/suicidal/"},{"title":"Grief & Anxiety #2","arabic":"لَا إِلٰهَ إِلَّا اللّٰهُ الْعَظِيْمُ الْحَلِيْمُ ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ الْعَرْشِ الْعَظِيْمِ ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ السَّمٰـوٰتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيْمِ","transliteration":"Lā ilāha illā-llāhu-l-ʿĀẓīmu-l-Ḥalīm, lā ilāha illā-llāhu Rabbu-l-ʿĀrshi-l-ʿAẓīm, lā ilāha illā-llāhu Rabbu-s-samāwāti wa Rabbu-l-arḍi wa Rabbu-l-ʿĀrshi-l-karīm.","translation":"There is no god worthy of worship except Allah — the Supreme, the Forbearing. There is no god worthy of worship except Allah — Lord of the Magnificent Throne. There is no god worthy of worship except Allah — Lord of the heavens, Lord of the earth, and Lord of the Noble Throne.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ used to supplicate with [the above] in times of distress. (Bukhārī 6345, Muslim 2730)","reference":"عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ:كَانَ النَّبِيُّ صلى الله عليه وسلم يَدْعُو عِنْدَ الْكَرْبِ: لَا إِلَهَ إِلَّا اللهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللهُ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ رَبُّ الْعَرْشِ الْعَظِيمِ. (صحيح البخاري ٦٣٤٥)\\nعَنِ ابْنِ عَبَّاسٍ؛ أَنَّ نبي الله صلى الله عليه وسلم كان يقول عند الكرب “لا إله إلا الله العظيم الحليم. لا إله إلا الله رب العرش العظيم. لا إله إلا الله رب السماوات ورب الأرض ورب العرش الكريم. (صحيح مسلم ٢٧٣٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/suicidal/"},{"title":"Allah Will Suffice You in Everything","arabic":"حَسْبِيَ اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ ، عَلَيْهِ تَوَكَّلْتُ ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ.","transliteration":"Ḥasbiya-Allāhu lā ilāha illā Huwa, ʿalayhi tawakkalt, wa Huwa Rabbu-l-ʿArshi-l-ʿaẓīm.","translation":"Repeat. x7","description":null,"benefit":null,"virtue":"Abū al-Dardā’ (raḍiy Allāhu ʿanhu) narrates from the Messenger of Allah ﷺ that he said: “Whoever recites [the above] seven times in the morning and in the evening, Allah will suffice him in everything that concerns him in matters of this world and the next.” (Ibn al-Sunnī 71)","hadith":null,"reference":"عَنْ أَبِي الدَّرْدَاءِ، رضي الله عنه، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ: مَنْ قَالَ فِي كُلِّ يَوْمٍ حِينَ يُصْبِحُ وَحِينَ يُمْسِي: حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ، سَبْعَ مَرَّاتٍ، كَفَاهُ اللَّهُ عز وجل هَمَّهُ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ. (عمل اليوم والليلة لابن السني ٧١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":7,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/suicidal/"},{"title":"For Difficult Times: All Your Prayers Answered","arabic":"لَآ إِلٰهَ إِلَّآ أَنْتَ سُبْحَانَكَ إِنِّيْ كُنْتُ مِنَ الظَّالِمِيْنَ","transliteration":"Lā ilāha illā Anta subḥānaka innī kuntu mina-ẓ-ẓālimīn.","translation":"There is no god worthy of worship except You; You are free from all imperfection. Indeed, I have been of the wrongdoers. (21:87)","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “The supplication of Dhun-Nūn (Prophet Yūnus) when he supplicated in the belly of the whale was: [the above]. No Muslim man ever supplicates with [the above] except that Allah answers his supplications.” (Tirmidhī 3505)","hadith":null,"reference":"Saʿd b. Abī Waqqāṣ said: We were sat in the company of the Messenger of Allah ﷺ. He ﷺ said, “Shall I not inform you of a supplication which will remove the calamity or a worldy trial which befalls a person from amongst you?” It was said, “Of course.” He said, “The supplication of Dhun-Nūn: [the above].”  (See Nasā‘ī in ʿAmal al-Yawm wa al-Laylah 655)\\nعَنْ سَعْدٍ قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: دَعْوَةُ ذِي النُّونِ إِذْ دَعَا وَهُوَ فِي بَطْنِ الْحُوتِ: لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ؛ فَإِنَّهُ لَمْ يَدْعُ بِهَا رَجُلٌ مُسْلِمٌ فِي شَيْءٍ قَطُّ إِلَّا اسْتَجَابَ اللهُ لَهُ. (سنن الترمذي ٣٥٠٥)\\nأخبرنَا الْقَاسِم بن زَكَرِيَّا قَالَ حَدثنَا عبيد بن مُحَمَّد قَالَ حَدثنَا مُحَمَّد بن مهَاجر قَالَ حَدثنِي إِبْرَاهِيم بن مُحَمَّد بن سعد عَن أَبِيه عَن جده قَالَ كُنَّا جُلُوسًا عِنْد رَسُول الله صلى الله عليه وسلم قَالَ أَلا أخْبركُم أَو أحدثكُم بِشَيْء إِذا نزل بِرَجُل مِنْكُم كرب أَو بلَاء من بلَاء الدُّنْيَا دَعَا بِهِ فرج عَنهُ فَقيل لَهُ بلَى قَالَ دُعَاء ذِي النُّون لَا إِلَه إِلَّا أَنْت سُبْحَانَكَ إِنِّي كنت من الظَّالِمين. (عمل اليوم والليلة للنسائي ٦٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Waqqāṣ said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/suicidal/"},{"title":"When One Is Distressed","arabic":"اَللّٰهُمَّ رَحْمَتَكَ أَرْجُوْ فَلَا تَكِلْنِيْ إِلٰى نَفْسِيْ طَرْفَةَ عَيْنٍ ، وَأَصْلِحْ لِي شَأْنِيْ كُلَّهُ ، لَا إِلٰهَ إِلَّا أَنْتَ","transliteration":"Allāhumma raḥmataka arjū fa-lā takilnī ilā nafsī ṭarfata ʿayn, wa aṣliḥ lī sha’nī kullah, lā ilāha illā Ant.","translation":"O Allah! It is certainly Your Mercy what I hope for, so do not entrust me to myself for the blink of an eye; and rectify all of my affairs. There is no god worthy of worship except You.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ said: “The supplications of the distressed person are [the above].” (Abū Dāwūd 5090)","reference":"عَنْ جَعْفَرِ بْنِ مَيْمُونٍ قَالَ: حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ «أَنَّهُ قَالَ لِأَبِيهِ : يَا أَبَتِ إِنِّي أَسْمَعُكَ تَدْعُو كُلَّ غَدَاةٍ: اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَدْعُو بِهِنَّ، فَأَنَا أُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ قَالَ عَبَّاسٌ فِيهِ: وَتَقُولُ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَتَدْعُو بِهِنَّ، فَأُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ. قَالَ: وَقَالَ رَسُولُ اللهِ صلى الله عليه وسلم: دَعَوَاتُ الْمَكْرُوبِ اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا ‌تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ. (سنن ابي داود ٥٠٩٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/suicidal/"},{"title":"Entrust All Your Matters to Allah","arabic":"يَا حَيُّ يَا قَيُّوْمُ ، بِرَحْمَتِكَ أَسْتَغِيْثُ ، أَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ ، وَلَا تَكِلْنِيْ إِلَىٰ نَفْسِيْ طَرْفَةَ عَيْنٍ.\\nأخبرنَا عبد الرَّحْمَن بن مُحَمَّد بن سَلام حَدثنَا زيد بن الْحباب أَخْبرنِي عُثْمَان بن موهب الْهَاشِمِي سَمِعت أنس بن مَالك يَقُول قَالَ النَّبِي صلى الله عليه وسلم لفاطمة مَا يمنعك أَن سَمْعِي مَا أوصيك بِهِ أَو تقولي إِذا أَصبَحت وَإِذا أمسيت يَا حَيّ يَا قيوم بِرَحْمَتك أستغيث أصلح لي شأني كلَّه وَلَا تَكِلنِي إِلَى نَفسِي طرفَة عين.","transliteration":"Yā Ḥayyu yā Qayyūm, bi-raḥmatika astaghīth, aṣliḥ lī sha’nī kullah, wa lā takilnī ilā nafsī ṭarfata ʿayn.","translation":"O The Ever Living, The Sustainer of all. ; I seek assistance through Your mercy. Rectify all of my affairs and do not entrust me to myself for the blink of an eye.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ʿanhu) narrates that the Prophet ﷺ said to Fāṭimah (raḍiy Allāhu ʿanhā), “What is preventing you from (doing) what I am advising you; that you say [the above] in the morning and evening?” (Nasā’ī in ʿAmal al-Yawm wa-l-Laylah 570)","reference":"(عمل اليوم والليلة للنسائي ٥٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/suicidal/"},{"title":"Duʿa for Seeking Protection from Shaytan","arabic":"رَبِّ أَعُوْذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِيْنِ ، وَأَعُوذُ بِكَ رَبِّ أَنْ يَّحْضُرُوْنِ.","transliteration":"Rabbi aʿūdhu bika min hamazāti-sh-shayāṭīn. Wa aʿūdhu bika Rabbi ay-yaḥḍurūn.","translation":"My Lord, I seek protection with You from the promptings of the devils; and I seek protection in You, my Lord, from their coming near me. (23:97-98)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/suicidal/"},{"title":"The Ultimate Duʿa","arabic":"اَللّٰهُمَّ بِعِلْمِكَ الْغَيْبَ ، وَقُدْرَتِكَ عَلَى الْخَلْقِ ، أَحْيِنِيْ مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِّيْ ، وَتَوَفَّنِيْ إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِّيْ ، اَللّٰهُمَّ وَأَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ ، وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ ، وَأَسْأَلُكَ الْقَصْدَ فِي الْفَقْرِ وَالْغِنَىٰ ، وَأَسْأَلُكَ نَعِيْمًا لَّا يَنْفَدُ ، وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لَّا تَنْقَطِعُ ، وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ ، وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَىٰ وَجْهِكَ ، وَالشَّوْقَ إِلَىٰ لِقَائِكَ ، فِيْ غَيْرِ ضَرَّاءَ مُضِرَّةٍ ، وَلَا فِتْنَةٍ مُّضِلَّةٍ ، اَللّٰهُمَّ زَيِّنَّا بِزِيْنَةِ الْإِيْمَانِ ، وَاجْعَلْنَا هُدَاةً مُّهْتَدِيْنَ","transliteration":"Allāhumma bi-ʿilmika-l-ghayb, wa qudratika ʿala-l-khalq, aḥyinī mā ʿalimta-l-ḥayāta khayra-l-lī, wa tawaffanī idhā ʿalimta-l-wafāta khayra-l-lī, Allāhumma wa as’aluka khashyataka fi-l-ghaybi wa-sh-shahādah, wa as’aluka kalimata-l-ḥaqqi fi-r-riḍā wa-l-ghaḍab, wa as’aluka-l-qaṣda fi-l-faqr wa-l-ghinā, wa as’aluka naʿīma-l-lā yanfad, wa as’aluka qurrata ʿayni-l-lā tanqaṭiʿ, wa as’aluka-r-riḍā baʿda-l-qaḍā, wa as’aluka barda-l-ʿayshi baʿda-l-mawt, wa as’aluka ladh-dhata-n-naẓari ilā wajhik, wa-sh-shawqa ilā liqā’ik, fī ghayri ḍarrā’a muḍirrah, wa lā fitnati-m-muḍillah, Allāhumma zayyinnā bi-zīnati-l-īmān, wa-jʿalnā hudāta-m-muhtadīn.","translation":"O Allah, with Your knowledge of the unseen and Your absolute power over the creation, let me live in this world as long as You know my living is good for me; and give me death when You know death is better for me. O Allah, I ask You for Your fear in private and in public, and for the word of truth in times of joy and anger. I ask You for moderation in poverty and in wealth. I ask You for endless blessings and perpetual delights. I ask You to make me pleased with destiny; for a cool and comfortable life after death; for the pleasure of seeing Your Face; and for the longing to meet You, without any painful ordeals and tribulations that misguide. O Allah, adorn us with the beauty of faith, and make us those who guide others and are guided themselves.","description":null,"benefit":null,"virtue":null,"hadith":"ʿAtā b. As-Sā’ib narrated that his father said: “ʿAmmār b. Yāsir (raḍiy Allāhu ‘anhu) led us in prayer and he made it brief. Some of the people said to him: ‘You made the prayer short (or brief).’ He said: ‘Nevertheless I still recited supplications that I heard from the Messenger of Allah ﷺ.’ When he got up and left, a man- he was my father but he did not name himself- followed him and asked him about that supplication, then he came and told the people [the above].” (Nasā’ī 1305)","reference":"أَخْبَرَنَا يَحْيَى بْنُ حَبِيبِ بْنِ عَرَبِيٍّ، قَالَ: حَدَّثَنَا حَمَّادٌ، قَالَ: حَدَّثَنَا عَطَاءُ بْنُ السَّائِبِ ، عَنْ أَبِيهِ قَالَ:صَلَّى بِنَا عَمَّارُ بْنُ يَاسِرٍ صَلَاةً، فَأَوْجَزَ فِيهَا، فَقَالَ لَهُ بَعْضُ الْقَوْمِ: لَقَدْ خَفَّفْتَ، أَوْ أَوْجَزْتَ الصَّلَاةَ، فَقَالَ: أَمَّا عَلَى ذَلِكَ، فَقَدْ دَعَوْتُ فِيهَا بِدَعَوَاتٍ سَمِعْتُهُنَّ مِنْ رَسُولِ اللهِ صلى الله عليه وسلم، فَلَمَّا قَامَ تَبِعَهُ رَجُلٌ مِنَ الْقَوْمِ هُوَ أَبِي غَيْرَ أَنَّهُ كَنَّى عَنْ نَفْسِهِ، فَسَأَلَهُ عَنِ الدُّعَاءِ، ثُمَّ جَاءَ فَأَخْبَرَ بِهِ الْقَوْمَ: اللَّهُمَّ بِعِلْمِكَ الْغَيْبَ، وَقُدْرَتِكَ عَلَى الْخَلْقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِي، وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي، اللَّهُمَّ وَأَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ، وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ، وَأَسْأَلُكَ الْقَصْدَ فِي الْفَقْرِ وَالْغِنَى، وَأَسْأَلُكَ نَعِيمًا لَا يَنْفَدُ، وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لَا تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَاءَ بَعْدَ الْقَضَاءِ، وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ، وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ، وَالشَّوْقَ إِلَى لِقَائِكَ فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ، وَلَا فِتْنَةٍ مُضِلَّةٍ، اللَّهُمَّ زَيِّنَّا بِزِينَةِ الْإِيمَانِ، وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ.\\n(سنن النسائي ١٣٠٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Some of the people said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/suicidal/"},{"title":"Duʿa of Prophet Ayyub ﷺ for Times of Distress","arabic":"-رَبِّ- أَنِّيْ مَسَّنِيَ الضُّرُّ وَأَنْتَ أَرْحَمُ الرّٰحِمِيْن.","transliteration":"(Rabbi) Annī massaniya-ḍ-ḍurru wa Anta Arḥamu-r-raḥimīn.","translation":"(My Lord), indeed adversity has touched me, and you are the Most Merciful of the merciful. (21:83)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/suicidal/"},{"title":"Protection from Evil Traits & Endings","arabic":"اَللّٰهُمَّ إِنّيْ أَعُوْذُ بِكَ مِنَ الْبُخْلِ ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ ، وَأَعُوْذُ بِكَ أَنْ أُرَدَّ إِلَىٰ أَرْذَلِ الْعُمُرِ ، وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا ، وَأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ.","transliteration":"Allāhumma innī aʿūdhu bika mina-l-bukhl, wa aʿūdhu bika mina-l-jubn, wa aʿūdhu bika an uradda ilā ardhali-l-ʿumur, wa aʿūdhu bika min fitnati-d-dunyā, wa aʿūdhu bika min ʿadhābi-l-qabr.","translation":"O Allah, I seek Your protection from miserliness and I seek Your protection from cowardice. I seek Your protection from being returned to the worst part of life (old age), I seek Your protection from the trials of the world, and I seek Your protection from the punishment of the grave.","description":null,"benefit":null,"virtue":null,"hadith":"Saʿd b. Abī Waqqās (radiy Allāhū ‘anhu) would instruct (to seek refuge) about five things [the above] and he would narrate it from the Messenger of Allah ﷺ . (Bukhārī 6370)","reference":"عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رضي الله عنه كَانَ يَأْمُرُ بِهَؤُلَاءِ الْخَمْسِ وَيُحَدِّثُهُنَّ عَنِ النَّبِيِّ صلى الله عليه وسلم: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبُخْلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوذُ بِكَ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ. (صحيح البخاري ٦٣٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/suicidal/"}]},{"feeling":"Unloved","slug":"unloved","url":"https://allahuakbarofficial.com/unloved/","items_count":6,"duas":[{"title":"Attain Well-being in This World and the Hereafter","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِيْ دِيْنِيْ وَدُنْيَايَ وَأَهْلِيْ وَمَالِيْ ، اَللّٰهُمَّ اسْتُرْ عَوْرَاتِيْ وَآمِنْ رَّوْعَاتِيْ ، اَللّٰهُمَّ احْفَظْنِيْ مِنْ بَيْنِ يَدَيَّ ، وَمِنْ خَلْفِيْ ، وَعَنْ يَّمِيْنِيْ ، وَعَنْ شِمَالِيْ ، وَمِنْ فَوْقِيْ ، وَأَعُوْذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِيْ.","transliteration":"Allāhumma innī as’aluka-l-ʿāfiyata fi-d-dunyā wa-l-ākhirah. Allāhumma innī as’aluka-l-ʿafwa wa-l-ʿāfiyata fī dīnī wa dunyāya wa ahlī wa mālī, Allāhumma-stur ʿawrātī wa āmi-r-rawʿātī. Allāhumma-ḥfaẓnī mim bayni yadayya wa min khalfī, wa ʿay-yamīnī wa ʿan shimālī wa min fawqī, wa aʿūdhu bi-ʿaẓamatika an ughtāla min taḥtī.","translation":"O Allah, I ask You for well-being in this world and the next. O Allah, I ask You for forgiveness and well-being in my religion, in my worldly affairs, in my family and in my wealth. O Allah, conceal my faults and calm my fears. O Allah, guard me from in front of me and behind me, from my right, and from my left, and from above me. I seek protection in Your Greatness from being unexpectedly destroyed from beneath me.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “Ask Allah for forgiveness and well-being (‘āfiyah). Indeed, after conviction (yaqīn), no one has been granted anything better than well-being.” (Tirmidhī)","hadith":"ʿAbdullāh b. ʿUmar (raḍiy Allāhu ʿanhumā) narrated: “The Messenger of Allah ﷺ never failed to say these words in the morning and in the evening.” (Abū Dāwūd 5074)","reference":"عَنْ جُبَيْرِ بْنِ أَبِي سُلَيْمَانَ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ، قَالَ: سَمِعْتُ ابْنَ عُمَرَ، يَقُولُ: لَمْ يَكُنْ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَعُ هَؤُلَاءِ الدَّعَوَاتِ، حِينَ يُمْسِي، وَحِينَ يُصْبِحُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَتِي، وَقَالَ عُثْمَانُ: عَوْرَاتِي وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي.(سنن أبي داود ٥٠٧٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/unloved/"},{"title":"When One Is Afraid of People #2","arabic":"حَسْبُنَا اللّٰهُ وَنِعْمَ الْوَكِيْلُ","transliteration":"Ḥasbunallāhu wa niʿmal Wakīl.","translation":"Allah is enough for us and He is the Best Protector.","description":null,"benefit":null,"virtue":null,"hadith":"Ibn ʿAbbās (radiy Allāhū ʿanhumā) narrated: “[The above] was said by Ibrāhīm (ʿalayhis-salām) when he was thrown into the fire; and it was said by Muḥammad ﷺ when (the hypocrites) said, ‘Your enemies have mobilised their forces against you, so fear them,’ — but this only increased them in faith and they replied: ‘Allah is enough for us and He is the Best Protector (3:173).’” (Bukhārī 4563)","reference":"عَنِ ابْنِ عَبَّاسٍ : حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ} قَالَهَا إِبْرَاهِيمُ عليه السلام حِينَ أُلْقِيَ فِي النَّارِ، وَقَالَهَا مُحَمَّدٌ صلى الله عليه وسلم حِينَ قَالُوا: إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ. (صحيح البخاري ٤٥٦٣)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/unloved/"},{"title":"Allah Will Suffice You in Everything","arabic":"حَسْبِيَ اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ ، عَلَيْهِ تَوَكَّلْتُ ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ.","transliteration":"Ḥasbiya-Allāhu lā ilāha illā Huwa, ʿalayhi tawakkalt, wa Huwa Rabbu-l-ʿArshi-l-ʿaẓīm.","translation":"Allah is sufficient for me. There is no god worthy of worship except Him. I have placed my trust in Him only and He is the Lord of the Magnificent Throne.","description":null,"benefit":null,"virtue":null,"hadith":"Abū al-Dardā’ (raḍiy Allāhu ʿanhu) narrates from the Messenger of Allah ﷺ that he said: “Whoever recites [the above] seven times in the morning and in the evening, Allah will suffice him in everything that concerns him in matters of this world and the next.” (Ibn al-Sunnī 71)","reference":"عَنْ أَبِي الدَّرْدَاءِ، رضي الله عنه، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ: مَنْ قَالَ فِي كُلِّ يَوْمٍ حِينَ يُصْبِحُ وَحِينَ يُمْسِي: حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ، سَبْعَ مَرَّاتٍ، كَفَاهُ اللَّهُ عز وجل هَمَّهُ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ. (عمل اليوم والليلة لابن السني ٧١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/unloved/"},{"title":"Duʿa of Prophet Musa ﷺ Expressing His Dire Need","arabic":"رَبِّ إِنِّيْ لِمَآ أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيْرٌ.","transliteration":"Rabbi innī limā anzalta illayya min khayrin faqīr.","translation":"My Lord, truly I am in dire need of any good which You may send me. (28:24)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/unloved/"},{"title":"Entrust All Your Matters to Allah","arabic":"يَا حَيُّ يَا قَيُّوْمُ ، بِرَحْمَتِكَ أَسْتَغِيْثُ ، أَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ ، وَلَا تَكِلْنِيْ إِلَىٰ نَفْسِيْ طَرْفَةَ عَيْنٍ.\\nأخبرنَا عبد الرَّحْمَن بن مُحَمَّد بن سَلام حَدثنَا زيد بن الْحباب أَخْبرنِي عُثْمَان بن موهب الْهَاشِمِي سَمِعت أنس بن مَالك يَقُول قَالَ النَّبِي صلى الله عليه وسلم لفاطمة مَا يمنعك أَن سَمْعِي مَا أوصيك بِهِ أَو تقولي إِذا أَصبَحت وَإِذا أمسيت يَا حَيّ يَا قيوم بِرَحْمَتك أستغيث أصلح لي شأني كلَّه وَلَا تَكِلنِي إِلَى نَفسِي طرفَة عين.","transliteration":"Yā Ḥayyu yā Qayyūm, bi-raḥmatika astaghīth, aṣliḥ lī sha’nī kullah, wa lā takilnī ilā nafsī ṭarfata ʿayn.","translation":"O The Ever Living, The Sustainer of all. ; I seek assistance through Your mercy. Rectify all of my affairs and do not entrust me to myself for the blink of an eye.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ʿanhu) narrates that the Prophet ﷺ said to Fāṭimah (raḍiy Allāhu ʿanhā), “What is preventing you from (doing) what I am advising you; that you say [the above] in the morning and evening?” (Nasā’ī in ʿAmal al-Yawm wa-l-Laylah 570)","reference":"(عمل اليوم والليلة للنسائي ٥٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/unloved/"},{"title":"Loving Allah & What He Loves","arabic":"اَللّٰهُمَّ ارْزُقْـنِيْ حُبَّكَ ، وَحُبَّ مَنْ يَّنْفَعُنِيْ حُبُّهُ عِنْدَكَ ، اَللّٰهُمَّ مَا رَزَقْتَنِيْ مِمَّا أُحِبُّ فَاجْعَلْهُ قُوَّةً لِّيْ فِيْمَا تُحِبُّ ، اَللّٰهُمَّ مَا زَوَيْتَ عَنِّيْ مِمَّا أُحِبُّ فَاجْعَلْهُ فَرَاغًا لِّيْ فِيْمَا تُحِبُّ","transliteration":"Allāhumma-r-zuqnī ḥubbak, wa ḥubba ma-y-yanfaʿunī ḥubbuhu ʿindak, Allāhumma mā razaqtanī mim-mā uḥibbu fa-jʿalhu quwwata-l-lī fīmā tuḥibb, Allāhumma mā zawayta ʿannī mim-mā uḥibbu fa-jʿalhu farāgha-l-lī fīmā tuḥibb.","translation":"O Allah, grant me Your love and the love of those whose love will benefit me with You. O Allah, whatever You have provided me of the things that I love, make them a source of strength for me in pursuing what You love. O Allah, whatever you have withheld from me from what I love, make its absence a means for me to pursue what You love.","description":null,"benefit":null,"virtue":null,"hadith":"ʿAbdullāh b. Yazīd Al-Khatmī Al-Ansarī (raḍiy Allāhu ‘anhu) narrated that the Messenger of Allah used to say [the above] in his supplication. (Tirmidhī 3491)","reference":"عَنْ عَبْدِ اللَّهِ بْنِ يَزِيدَ الخَطْمِيِّ الأَنْصَارِيِّ، عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم أَنَّهُ كَانَ يَقُولُ فِي دُعَائِهِ: اللَّهُمَّ ارْزُقْنِي حُبَّكَ وَحُبَّ مَنْ يَنْفَعُنِي حُبُّهُ عِنْدَكَ، اللَّهُمَّ مَا رَزَقْتَنِي مِمَّا أُحِبُّ فَاجْعَلْهُ قُوَّةً لِي فِيمَا تُحِبُّ، اللَّهُمَّ وَمَا زَوَيْتَ عَنِّي مِمَّا أُحِبُّ فَاجْعَلْهُ فَرَاغًا لِي فِيمَا تُحِبُّ. (سنن الترمذي ٣٤٩١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/unloved/"}]},{"feeling":"Weak","slug":"weak","url":"https://allahuakbarofficial.com/weak/","items_count":19,"duas":[{"title":"When Something You Dislike Happens #2","arabic":"قَدَّرَ اللّٰهُ وَمَا شَاءَ فَعَلَ","transliteration":"Qaddara-llāhu wa mā shā’a faʿal.","translation":"Allah has decreed and He does whatever He wills.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ said: “A strong believer is better and more beloved to Allah than a weak believer, and there is good in everyone. Be keen on what benefits you, seek help from Allah, and do not give up. If anything afflicts you, do not say: ‘If I had done (something else), such and such would have happened.’ But say [the above], for (the utterance) ‘if’ provides an opening for the deeds of the devil.” (Muslim 2664)","reference":"عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ الله صلى الله عليه وسلم المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف. وفي كل خير. احرص على ما ينفعك واستعن بالله. ولا تعجز. وإن أصابك شيء فلا تقل: لو أني فعلت كان كذا وكذا. ولكن قل: قدر الله. وما شاء فعل. فإن لو تفتح عمل الشيطان.\\n(صحيح مسلم ٢٦٦٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"When One Is in a Difficult Situation","arabic":"اَللّٰهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا ، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا","transliteration":"Allāhumma lā sahla illā mā jaʿaltahū sahlā, wa anta tajʿalu-l-ḥazna idhā shi’ta sahlā.","translation":"O Allah, there is no ease except in that which You have made easy; and You make the difficulty easy when You wish.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Malik (raḍiy Allāhu ʿanhu) ﷺ narrates that the Messenger of Allah said [the above]. (Ibn Ḥibbān 6737, Ibn al-Sunnī 351)","reference":"عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم، قَالَ: اللهُمَّ ‌لَا ‌سَهْلَ إِلَاّ مَا جَعَلْتَهُ سَهْلاً، وَأَنْتَ تَجْعَلُ الْحَزْنَ سَهْلاً إِذَا شِئْتَ. (صحيح ابن حبان ٦٧٣٧)\\nعَنْ أَنَسِ بْنِ مَالِكٍ، رضي الله عنه أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ: اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا، وَأَنْتَ تَجْعَلُ الْحَزَنَ إِذَا شِئْتَ سَهْلًا.\\n(عمل اليوم والليلة لابن السني ٣٥١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Allah said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"Protect Yourself From Anxiety, Laziness & Debt","arabic":"اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ ، وَأَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ ، وَأَعُوْذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ.","transliteration":"Allāhumma innī aʿūdhu bika min-l-hammi wa-l-ḥazan, wa aʿūdhu bika min-l-ʿajzi wa-l-kasal, wa aʿūdhu bika min-l-jubni wa-l-bukhl, wa aʿūdhu bika min ghalabati-d-dayni wa qahri-r-rijāl.","translation":"O Allah, I seek Your protection from anxiety and grief. I seek Your protection from inability and laziness. I seek Your protection from cowardice and miserliness, and I seek Your protection from being overcome by debt and being overpowered by men.","description":null,"benefit":null,"virtue":"Abū Saʿīd al-Khudrī (raḍiy Allāhu ʿanhu) narrated that one day, the Messenger of Allah ﷺ entered the masjid. He saw a man from the Anṣār called Abū Umāmah (raḍiy Allāhu ʿanhu). He ﷺ asked, “What is the matter? Why are you sitting in the masjid when it is not the time for prayer?” He replied, “Never-ending worries and debts, O Messenger of Allah.” The Messenger of Allah ﷺ then asked, “Shall I not teach you words by which, when you say them, Allah will remove your worries, and settle your debts?” He replied, “Yes of course, O Messenger of Allah.” He ﷺ said, “Say in the morning and evening [the above].” Abū Umāmah (raḍiy Allāhu ʿanhu) said, “Then I did that, and Allah removed my worries and settled my debts.” (Abū Dāwūd 1555)","hadith":null,"reference":"عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: دَخَلَ رَسُولُ صَلَّى عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ مِنَ الْأَنْصَارِ، يُقَالُ لَهُ: أَبُو أُمَامَةَ، فَقَالَ: «يَا أُمَامَةَ، مَا لِي أَرَاكَ جَالِسًا فِي الْمَسْجِدِ فِي غَيْرِ وَقْتِ الصَّلَاةِ؟»، قَالَ: هُمُومٌ لَزِمَتْنِي، وَدُيُونٌ يَا رَسُولَ اللَّهِ، قَالَ: أَفَلَا أُعَلِّمُكَ كَلَامًا إِذَا أَنْتَ قُلْتَهُ أَذْهَبَ عز وجل هَمَّكَ، وَقَضَى عَنْكَ دَيْنَكَ؟، قَالَ: قُلْتُ: بَلَى، يَا رَسُولَ، قَالَ: ” قُلْ إِذَا أَصْبَحْتَ، وَإِذَا أَمْسَيْتَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ، وَقَهْرِ الرِّجَالِ “، قَالَ: فَفَعَلْتُ ذَلِكَ، فَأَذْهَبَ اللَّهُ عز وجل هَمِّي، وَقَضَى عَنِّي دَيْنِي.(سنن أبي داود ١٥٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"Attain Well-being in This World and the Hereafter","arabic":"اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ ، اَللّٰهُمَّ إِنِّيْ أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِيْ دِيْنِيْ وَدُنْيَايَ وَأَهْلِيْ وَمَالِيْ ، اَللّٰهُمَّ اسْتُرْ عَوْرَاتِيْ وَآمِنْ رَّوْعَاتِيْ ، اَللّٰهُمَّ احْفَظْنِيْ مِنْ بَيْنِ يَدَيَّ ، وَمِنْ خَلْفِيْ ، وَعَنْ يَّمِيْنِيْ ، وَعَنْ شِمَالِيْ ، وَمِنْ فَوْقِيْ ، وَأَعُوْذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِيْ.","transliteration":"Allāhumma innī as’aluka-l-ʿāfiyata fi-d-dunyā wa-l-ākhirah. Allāhumma innī as’aluka-l-ʿafwa wa-l-ʿāfiyata fī dīnī wa dunyāya wa ahlī wa mālī, Allāhumma-stur ʿawrātī wa āmi-r-rawʿātī. Allāhumma-ḥfaẓnī mim bayni yadayya wa min khalfī, wa ʿay-yamīnī wa ʿan shimālī wa min fawqī, wa aʿūdhu bi-ʿaẓamatika an ughtāla min taḥtī.","translation":"O Allah, I ask You for well-being in this world and the next. O Allah, I ask You for forgiveness and well-being in my religion, in my worldly affairs, in my family and in my wealth. O Allah, conceal my faults and calm my fears. O Allah, guard me from in front of me and behind me, from my right, and from my left, and from above me. I seek protection in Your Greatness from being unexpectedly destroyed from beneath me.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “Ask Allah for forgiveness and well-being (‘āfiyah). Indeed, after conviction (yaqīn), no one has been granted anything better than well-being.” (Tirmidhī)","hadith":"ʿAbdullāh b. ʿUmar (raḍiy Allāhu ʿanhumā) narrated: “The Messenger of Allah ﷺ never failed to say these words in the morning and in the evening.” (Abū Dāwūd 5074)","reference":"عَنْ جُبَيْرِ بْنِ أَبِي سُلَيْمَانَ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ، قَالَ: سَمِعْتُ ابْنَ عُمَرَ، يَقُولُ: لَمْ يَكُنْ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَعُ هَؤُلَاءِ الدَّعَوَاتِ، حِينَ يُمْسِي، وَحِينَ يُصْبِحُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَتِي، وَقَالَ عُثْمَانُ: عَوْرَاتِي وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي.(سنن أبي داود ٥٠٧٤)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"Grief & Anxiety #1","arabic":"اَللّٰهُمَّ إِنِّيْ عَبْدُكَ ، وَابْنُ عَبْدِكَ ، وَابْنُ أَمَتِكَ ، نَاصِيَتِيْ بِيَدِكَ ، مَاضٍ فِيَّ حُكْمُكَ ، عَدْلٌ فِيَّ قَضَاؤُكَ ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ ، سَمَّيْتَ بِهِ نَفْسَكَ ، أَوْ عَلَّمْتَهُ أَحَدًا مِّنْ خَلْقِكَ ، أَوْ أَنْزَلْتَهُ فِيْ كِتَابِكَ ، أَوِ اسْتَأْثَرْتَ بِهِ فِيْ عِلْمِ الْغَيْبِ عِنْدَكَ ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيْعَ قَلْبِيْ ، وَنُوْرَ صَدْرِيْ ، وَجَلَاءَ حُزْنِيْ ، وَذَهَابَ هَمِّيْ","transliteration":"Allāhumma innī ʿabduk, wa-bnu ʿabdik, wa-bnu amatik, nāṣiyatī bi-yadik, māḍin fiyya ḥukmuk, ʿadlun fiyya qaḍā’uk, as’aluka bi-kulli-smin huwa lak, sammayta bihī nafsak, aw ʿallamtahū aḥadam-min khalqik, aw anzaltahū fī kitābik, awi-sta’tharta bihī fī ʿilmi-l-ghaybi ʿindak, an tajʿala-l-Qur’āna rabīʿa qalbī, wa nūra ṣadrī, wa jalā’a ḥuznī, wa dha-hāba hammī.","translation":"O Allah, I am Your servant and the son of Your male servant and the son of Your female servant. My forehead is in Your Hand (i.e. you have control over me). I am subject to Your judgement and Your decree concerning me is just. I ask You – by every name that is Yours, by which You have named Yourself, or taught any one of Your creation, or revealed in Your Book, or kept unto Yourself in the knowledge of the unseen that is with You – to make the Qur’ān the spring of my heart, the light of my chest, the banisher of my grief and the reliever of my anxiety.","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “There is no one who is stricken with grief and anxiety, and then says [the above] — except that Allah will remove his grief and anxiety, and will give him joy instead.” The Companions asked, ‘O Messenger of Allah, should we not learn these words?’ He ﷺ replied, ‘Certainly! The one who hears them should learn them.’” (Ahmad 3712)","hadith":null,"reference":"عَنْ عَبْدِ اللهِ، قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: مَا أَصَابَ أَحَدًا قَطُّ هَمٌّ وَلَا حَزَنٌ، فَقَالَ: اللهُمَّ إِنِّي عَبْدُكَ، ابْنُ عَبْدِكَ، ابْنُ أَمَتِكَ نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجِلَاءَ حُزْنِي، وَذَهَابَ هَمِّي، إِلَّا أَذْهَبَ اللهُ هَمَّهُ وَحُزْنَهُ، وَأَبْدَلَهُ مَكَانَهُ فَرَحًا، قَالَ: فَقِيلَ: يَا رَسُولَ اللهِ، أَلَا نَتَعَلَّمُهَا؟ فَقَالَ: بَلَى، يَنْبَغِي لِمَنْ سَمِعَهَا أَنْ يَتَعَلَّمَهَا. (مسند أحمد ٣٧١٢)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"Grief & Anxiety #2","arabic":"لَا إِلٰهَ إِلَّا اللّٰهُ الْعَظِيْمُ الْحَلِيْمُ ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ الْعَرْشِ الْعَظِيْمِ ، لَا إِلٰهَ إِلَّا اللّٰهُ رَبُّ السَّمٰـوٰتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيْمِ","transliteration":"Lā ilāha illā-llāhu-l-ʿĀẓīmu-l-Ḥalīm, lā ilāha illā-llāhu Rabbu-l-ʿĀrshi-l-ʿAẓīm, lā ilāha illā-llāhu Rabbu-s-samāwāti wa Rabbu-l-arḍi wa Rabbu-l-ʿĀrshi-l-karīm.","translation":"There is no god worthy of worship except Allah — the Supreme, the Forbearing. There is no god worthy of worship except Allah — Lord of the Magnificent Throne. There is no god worthy of worship except Allah — Lord of the heavens, Lord of the earth, and Lord of the Noble Throne.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ used to supplicate with [the above] in times of distress. (Bukhārī 6345, Muslim 2730)","reference":"عَنِ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ:كَانَ النَّبِيُّ صلى الله عليه وسلم يَدْعُو عِنْدَ الْكَرْبِ: لَا إِلَهَ إِلَّا اللهُ الْعَظِيمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللهُ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ رَبُّ الْعَرْشِ الْعَظِيمِ. (صحيح البخاري ٦٣٤٥)\\nعَنِ ابْنِ عَبَّاسٍ؛ أَنَّ نبي الله صلى الله عليه وسلم كان يقول عند الكرب “لا إله إلا الله العظيم الحليم. لا إله إلا الله رب العرش العظيم. لا إله إلا الله رب السماوات ورب الأرض ورب العرش الكريم. (صحيح مسلم ٢٧٣٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"When One Is Afraid of People #1","arabic":"اَللّٰهُمَّ اكْفِنِيْهِمْ بِمَا شِئْتَ\\nعن صهيب؛ إن رسول الله صلى الله عليه وسلم قال كان ملك فيمن كان قبلكم. وكان له ساحر. فلما كبر قال للملك: إني قد كبرت. فابعث إلي غلاما أعلمه السحر. فبعث إليه غلاما يعلمه. فكان في طريقه، إذا سلك، راهب. فقعد إليه وسمع كلامه. فأعجبه. فكان إذا أتى الساحر مر بالراهب وقعد إليه. فإذا أتى الساحر ضربه. فشكا ذلك إلى الراهب. فقال: إذا خشيت الساحر فقل: حبسني أهلي. وإذا خشيت أهلك فقل: حبسني الساحر. فبينما هو كذلك إذ أتى على دابة عظيمة قد حبست الناس. فقال: اليوم أعلم آلساحر أفضل أم الراهب أفضل؟ فأخذ حجرا فقال: اللهم! إن كان أمر الراهب أحب إليك من أمر الساحر فاقتل هذه الدابة. حتى يمضي الناس. فرماها فقتلها. ومضى الناس. فأتى الراهب فأخبره. فقال له الراهب: أي بني! أنت، اليوم، أفضل مني. قد بلغ من أمرك ما أرى. وإنك ستبتلى. فإن ابتليت فلا تدل علي. وكان الغلام يبرئ الأكمه والأبرص ويداوي الناس من سائر الأدواء. فسمع جليس للملك كان قد عمي. فأتاه بهدايا كثيرة. فقال: ما ههنا لك أجمع، إن أنت شفيتني. فقال: إني لا أشفي أحدا. إنما يشفي الله. فإن أنت آمنت بالله دعوت الله فشفاك. فآمن بالله. فشفاه الله. فأتى الملك فجلس إليه كما كان يجلس. فقال له الملك: من رد عليك بصرك؟ قال: ربي. قال: ولك رب غيري؟ قال: ربي وربك الله. فأخذه فلم يزل يعذبه حتى دل على الغلام. فجئ بالغلام. فقال له الملك: أي بني! قد بلغ من سحرك ما تبرئ الأكمه والأبرص وتفعل وتفعل. فقال: إني لا أشفي أحدا. إنما يشفي الله. فأخذه فلم يزل يعذبه حتى دل على الراهب. فجئ بالراهب. فقيل له: ارجع عن دينك. فأبى. فدعا بالمئشار. فوضع المئشار على مفرق رأسه. فشقه حتى وقع شقاه. ثم جئ بجليس الملك فقيل له: ارجع عن دينك. فأبى. فوضع المئشار في مفرق رأسه. فشقه به حتى وقع شقاه. ثم جئ بالغلام فقيل له: ارجع عن دينك. فأبى. فدفعه إلى نفر من أصحابه فقال: اذهبوا به إلى جبل كذا وكذا. فاصعدوا به الجبل. فإذا بلغتم ذروته، فإن رجع عن دينه، وإلا فاطرحوه. فذهبوا به فصعدوا به الجبل. فقال: اللهم! اكفنيهم بما شئت.","transliteration":"Allāhumma-k-finīhim bimā shi’t.","translation":"O Allah, suffice me from them, with what You choose.","description":null,"benefit":null,"virtue":null,"hadith":"Suhaib (radiy Allāhū ʿanhu) reported that Allah’s Messenger ﷺ said: “There lived a king before you and he had a (court) magician. As he (the magician) grew old, he said to the king: I have grown old, send some young boy to me so that I should teach him magic. He (the king) sent to him a young man so that he should train him (in magic). And on his way (to the magician) he (the young man) found a monk sitting there. He (the young man) listened to his (the monk’s) talk and was impressed by it. It became his habit that on his way to the magician he met the monk and set there and he came to the magician (late). He (the magician) beat him because of delay. He made a complaint of that to the monk and he said to him: When you feel afraid of the magician, say: Members of my family had detained me. And when you feel afraid of your family you should say: The magician had detained me. It so happened that there came a huge beast (of prey) and it blocked the way of the people, and he (the young boy) said: I will come to know today whether the magician is superior or the monk is superior. He picked up a stone and said: O Allah, if the affair of the monk is dearer to Thee than the affair of the magician, cause death to this animal so that the people should be able to move about freely. He threw that stone towards it and killed it and the people began to move about (on the path freely). He (the young man) then came to that monk and Informed him and the monk said: Sonny, today you are superior to me. Your affair has come to a stage where I find that you would be soon put to a trial, and in case you are put to a trial don’t give my clue. That young man began to treat the blind and those suffering from leprosy and he in fact began to cure people from (all kinds) of illness. When a companion of the king who had gone blind heard about him, he came to him with numerous gifts and said: If you cure me all these things collected together here would be yours. Be said: I myself do not cure anyone. It is Allah Who cures and if you affirm faith in Allah, I shall also supplicate Allah to cure you. He affirmed his faith in Allah and Allah cured him and he came to the king and sat by his side as he used to sit before. The king said to him: Who restored your eyesight? He said: My Lord. Thereupon he said: It means that your Lord is One besides me. He said: My Lord and your Lord is Allah, so he (the king) took hold of him and tormented him till he gave a clue of that boy. The young man was thus summoned and the king said to him: O boy, it has been conveyed to me that you have become so much proficient in your magic that you cure the blind and those suffering from leprosy and you do such and such things. Thereupon he said: I do not cure anyone; it is Allah Who cures, and he (the king) took hold of him and began to torment him. So he gave a clue of the monk. The monk was thus summoned and it was said to him: You should turn back from your religion. He, however, refused to do so. He (ordered) for a saw to be brought (and when it was done) he (the king) placed it in the middle of his head and tore it into parts till a part fell down. Then the courtier of the king was brought and it was said to him: Turn back from your religion. Arid he refused to do so, and the saw was placed in the midst of his head and it was torn till a part fell down. Then that young boy was brought and it was said to him: Turn back from your religion. He refused to do so and he was handed over to a group of his courtiers. And he ‘said to them: Take him to such and such mountain; make him climb up that mountain and when you reach its top (ask him to renounce his faith) but if he refuses to do so, then throw him (down the mountain). So they took him and made him climb up the mountain and he said: O Allah, save me from them (in any way) Thou likest and the mountain began to quake and they all fell down and that person came walking to the king. The king said to him: What has happened to your companions? He said: Allah has saved me from them. He again handed him to some of his courtiers and said: Take him and carry him in a small boat and when you reach the middle of the ocean (ask him to renounce) his religion, but if he does not renounce his religion throw him (into the water). So they took him and he said: O Allah, save me from them and what they want to do. It was quite soon that the boat turned over and they were drowned and he came walking to the king, and the king said to him: What has happened to your companions? He said: Allah has saved me from them, and he said to the king: You cannot kill me until you do what I ask you to do. And he said: What is that? He said: You should gather people in a plain and hang me by the trunk (of a tree). Then take hold of an arrow from the quiver and say: In the name of Allah, the Lord of the young boy; then shoot an arrow and if you do that then you would be able to kill me. So he (the king) called the people in an open plain and tied him (the boy) to the trunk of a tree, then he took hold of an arrow from his quiver and then placed the arrow in the bow and then said: In the name of Allah, the Lord of the young boy; he then shot an arrow and it bit his temple. He (the boy) placed his hands upon the temple where the arrow had bit him and he died and the people said: We affirm our faith in the Lord of this young man, we affirm our faith in the Lord of this young man, we affirm our faith in the Lord of this young man. The courtiers came to the king and it was said to him: Do you see that Allah has actually done what you aimed at averting. They (the people) have affirmed their faith in the Lord. He (the king) commanded ditches to be dug at important points in the path. When these ditches were dug, and the fire was lit in them it was said (to the people): He who would not turn back from his (boy’s) religion would be thrown in the fire or it would be said to them to jump in that. (The people courted death but did not renounce religion) till a woman came with her child and she felt hesitant in jumping into the fire and the child said to her: 0 mother, endure (this ordeal) for it is the Truth.’’","reference":"(صحيح مسلم ٣٠٠٥) | Muslim 3005","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"He made a complaint of that to the monk and he said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"When One Is Afraid of People #2","arabic":"حَسْبُنَا اللّٰهُ وَنِعْمَ الْوَكِيْلُ","transliteration":"Ḥasbunallāhu wa niʿmal Wakīl.","translation":"Allah is enough for us and He is the Best Protector.","description":null,"benefit":null,"virtue":null,"hadith":"Ibn ʿAbbās (radiy Allāhū ʿanhumā) narrated: “[The above] was said by Ibrāhīm (ʿalayhis-salām) when he was thrown into the fire; and it was said by Muḥammad ﷺ when (the hypocrites) said, ‘Your enemies have mobilised their forces against you, so fear them,’ — but this only increased them in faith and they replied: ‘Allah is enough for us and He is the Best Protector (3:173).’” (Bukhārī 4563)","reference":"Muslim 3005\\nعَنِ ابْنِ عَبَّاسٍ : حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ} قَالَهَا إِبْرَاهِيمُ عليه السلام حِينَ أُلْقِيَ فِي النَّارِ، وَقَالَهَا مُحَمَّدٌ صلى الله عليه وسلم حِينَ قَالُوا: إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا حَسْبُنَا اللهُ وَنِعْمَ الْوَكِيلُ. (صحيح البخاري ٤٥٦٣)\\n(صحيح مسلم ٣٠٠٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"When One Is Afraid of People #3","arabic":"اَللّٰهُمَّ إِنَّا نَجْعَلُكَ فِيْ نُحُوْرِهِمْ ، وَنَعُوْذُ بِكَ مِنْ شُرُوْرِهِمْ","transliteration":"Allāhumma innā najʿaluka fī nuḥūrihim, wa naʿūdhu bika min shurūrihim.","translation":"O Allah, we make You our shield against them and we seek refuge in You from their evil.","description":null,"benefit":null,"virtue":null,"hadith":"When the Messenger of Allah ﷺ was apprehensive of [a group] of people, he would say: [the above]. (Abū Dāwūd 1537)","reference":"عَنْ أَبِي بُرْدَةَ بْنِ عَبْدِ اللهِ : أَنَّ أَبَاهُ حَدَّثَهُ، أَنَّ النَّبِيَّ صلى الله عليه وسلم كَانَ إِذَا خَافَ قَوْمًا قَالَ: اللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ، وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ.\\n(سنن ابي داود ١٥٣٧)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"When One Is Afraid of People #4","arabic":"اَللّٰهُ اَللّٰهُ رَبِّيْ ، لاَ أُشْرِكُ بِهِ شَيْئًا","transliteration":"Allāhu Allāhu Rabbī, lā ushriku bihi shay’ā.","translation":"Allah, Allah is my Lord, I do not assign anything as a partner to Him.","description":null,"benefit":null,"virtue":null,"hadith":"Asmā bint ʿUmays (raḍiy Allāhu ‘anhā) narrated that the Messenger of Allah ﷺ said to her: “Shall I not teach you words for you to say in times of distress?” or “when in distress?”. He then said [the above]. (Abū Dāwūd 1525)","reference":"عَنْ أَسْمَاءَ بِنْتِ عُمَيْسٍ قَالَتْ: قَالَ لِي رَسُولُ اللهِ صلى الله عليه وسلم: أَلَا أُعَلِّمُكِ كَلِمَاتٍ تَقُولِينَهُنَّ عِنْدَ الْكَرْبِ أَوْ فِي الْكَرْبِ: اللهُ اللهُ رَبِّي لَا أُشْرِكُ بِهِ شَيْئًا.\\n(سنن ابي داود ١٥٢٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"He then said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"When Meeting the Enemy","arabic":"اَللّٰهُمَّ مُنْزِلَ الْكِتَابِ ، ومُجْرِيَ السَّحَابِ ، وهَازِمَ الْأحْزَابِ ، اهْزِمْهُمْ وانْصُرْنَا عَلَيْهِمْ","transliteration":"Allāhumma munzila-l-kitāb, wa mujriya-s-saḥāb, wa hāzima-l-aḥzāb, ihzimhum wa-n-ṣurnā ʿalayhim.","translation":"O Allah, Revealer of the Book, Mover of the clouds, Defeater of the tribes, defeat them and grant us victory over them.","description":null,"benefit":null,"virtue":null,"hadith":"ʿAbdullāh b. Abī Awfā (raḍiy Allāhu ‘anhu) reported that the Messenger of Allah ﷺ, on one of the days that he encountered the enemy, waited until the sun rose, then stood among the people and said: “O people, do not look forward to meeting the enemy, but ask Allah for well-being. When you encounter them, be steadfast. And know that Paradise is under the shade of swords.” Then he said [the above]. (Bukhārī 2965)","reference":"عَنْ سَالِمٍ أَبِي النَّضْرِ مَوْلَى عُمَرَ بْنِ عُبَيْدِ اللهِ وَكَانَ كَاتِبًا لَهُ قَالَ: كَتَبَ إِلَيْهِ عَبْدُ اللهِ بْنُ أَبِي أَوْفَى رضي الله عنهما فَقَرَأْتُهُ: أَنَّ رَسُولَ اللهِ صلى الله عليه وسلم فِي بَعْضِ أَيَّامِهِ الَّتِي لَقِيَ فِيهَا انْتَظَرَ حَتَّى مَالَتِ الشَّمْسُ ثُمَّ قَامَ فِي النَّاسِ قَالَ: أَيُّهَا النَّاسُ لَا تَتَمَنَّوْا لِقَاءَ الْعَدُوِّ وَسَلُوا اللهَ الْعَافِيَةَ فَإِذَا لَقِيتُمُوهُمْ فَاصْبِرُوا وَاعْلَمُوا أَنَّ الْجَنَّةَ تَحْتَ ظِلَالِ السُّيُوفِ. ثُمَّ قَالَ: اللَّهُمَّ مُنْزِلَ الْكِتَابِ وَمُجْرِيَ السَّحَابِ وَهَازِمَ الْأَحْزَابِ اهْزِمْهُمْ وَانْصُرْنَا عَلَيْهِمْ. (صحيح البخاري ٢٩٦٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Then he said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"When One Feels Frightened","arabic":"لَا إِلٰهَ إِلَّا اللّٰهُ","transliteration":"Lā ilāha illā-llāh.","translation":"There is no god worthy of worship except Allah.","description":null,"benefit":null,"virtue":null,"hadith":"Zaynab b. Jaḥsh (raḍiy Allāhu ʿanhā) said that the Messenger of Allah ﷺ once entered her house in a state of fear and said, “[The above]. Woe to the Arabs from a danger that is imminent. An opening has been made today in the wall of Ya‘jūj and Ma‘jūj like this” and he made a circle with his thumb and index finger. Zaynab b. Jaḥsh said, “O Messenger of Allah ﷺ! Will we be destroyed even though there are pious people amongst us?” He ﷺ said, “Yes, when evil becomes widespread.” (Bukhārī 3346)","reference":"عَنْ أُمِّ حَبِيبَةَ بِنْتِ أَبِي سُفْيَانَ عَنْ زَيْنَبَ ابْنَةِ جَحْشٍ رضي الله عنهن أَنَّ النَّبِيَّ صلى الله عليه وسلم دَخَلَ عَلَيْهَا فَزِعًا يَقُولُ لَا إِلَهَ إِلَّا اللهُ وَيْلٌ لِلْعَرَبِ مِنْ شَرٍّ قَدِ اقْتَرَبَ فُتِحَ الْيَوْمَ مِنْ رَدْمِ يَاجُوجُ وَمَاجُوجُ مِثْلُ هَذِهِ وَحَلَّقَ بِإِصْبَعِهِ الْإِبْهَامِ وَالَّتِي تَلِيهَا قَالَتْ زَيْنَبُ ابْنَةُ جَحْشٍ: فَقُلْتُ: يَا رَسُولَ اللهِ أَنَهْلِكُ وَفِينَا الصَّالِحُونَ قَالَ نَعَمْ إِذَا كَثُرَ الْخَبَثُ. (صحيح البخاري ٣٣٤٦)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Jaḥsh said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"Ask Allah for Good Health and Protection","arabic":"اَللّٰهُمَّ عَافِنِيْ فِيْ بَدَنِيْ ، اَللّٰهُمَّ عَافِنِيْ فِيْ سَمْعِيْ ، اَللّٰهُمَّ عَافِنِيْ فِيْ بَصَرِيْ ، لَا إِلٰهَ إِلَّا أَنْتَ ، اَللّٰهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، وأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلٰهَ إِلَّا أَنْتَ.\\nعن جعفر بنِ ميمون ، حدَّثني عبدُ الرحمن بنُ أبي بكرَة، أنه قال لأبيه: يا أبةِ إني أَسمَعُكَ تَدْعُو كلَّ غَدَاةٍ: اللَّهُمَّ عافِني في بَدَني، اللهم عافِنِي في سَمْعِي، اللَّهُمَّ عافني في بَصَري، لا إلهَ إلا أنت، تُعيدها ثلاثاً حينَ تُصْبِحُ، وثلاثاً حينَ تُمسي، فقال: إني سمعتُ رسولَ الله صلى الله عليه وسلم -يدعو بهنَّ فانا أُحِبُّ أن أستَنَّ بسُنَّتِه، وقال عليٌّ وعباسٌ فيه: ويقول: اللهُمَّ إني أعوذُ بِكَ من الكُفر والفَقرِ، اللَّهُمَ إني أعُوذُ بِكَ مِن عذابِ القبر، لا إلهَ إلا أنتَ، يُعيدها ثلاثاً حِين يُصبحُ، وثلاثاً حين يُمسي، فيَدعُو بهِنَّ، فاُحِبُّ أن أستَنَّ بسُنتَّه.\\nحَدَّثَنَا أَبُو عَامِرٍ، حَدَّثَنَا عَبْدُ الْجَلِيلِ، حَدَّثَنِي جَعْفَرُ بْنُ مَيْمُونٍ، حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكَرَةَ أَنَّهُ قَالَ لِأَبِيهِ:","transliteration":"Allāhumma ʿāfinī fī badanī, Allāhumma ʿāfinī fī samʿī, Allāhumma ʿāfinī fī baṣarī, lā ilāha illā Ant, Allāhumma innī aʿūdhu bika mina-l-kufri wa-l-faqr, wa aʿūdhu bika min ʿadhābi-l-qabr, lā ilāha illā Ant.","translation":"O Allah, grant me well-being in my body. O Allah, grant me well-being in my hearing. O Allah, grant me well-being in my sight. There is no god worthy of worship except You. O Allah, I seek Your protection from disbelief and poverty and I seek Your protection from the punishment of the grave. There is no god worthy of worship except You.","description":null,"benefit":null,"virtue":null,"hadith":"‘Abd al-Raḥmān b. Abī Bakrah (raḍiy Allāhu ʿanhu) narrates that he said to his father, “O my father! I hear you supplicating with [the above] every morning. You repeat them three times in the morning and three times in the evening.” He said, “Indeed I heard the Messenger of Allah ﷺ supplicating with these (words) and I love to follow his practice.” (Abū Dāwūd 5090, Aḥmad 20430)","reference":"(سنن أبي داود ٥٠٩٠)\\nيَا أَبَهْ، إِنِّي أَسْمَعُك تَدْعُو كُلَّ غَدَاةٍ: ” اللهُمَّ عَافِنِي فِي بَدَنِي، اللهُمَّ عَافِنِي فِي سَمْعِي، اللهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ ” تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي. وَتَقُولُ: ” اللهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، اللهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ ” تُعِيدُهَا حِينَ تُصْبِحُ ثَلَاثًا، وَثَلَاثًا حِينَ تُمْسِي. قَالَ: نَعَمْ يَا بُنَيَّ، إِنِّي سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَدْعُو بِهِنَّ، فَأُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ. (مسند أحمد ٢٠٤٣٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"He said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"When One Fears a Ruler","arabic":"اَللّٰهُمَّ رَبَّ السَّمٰـوٰتِ السَّبْعِ ، وَرَبَّ العَرْشِ العَظِيْمِ ، كُنْ لِيْ جَارًا مِنْ فُلَانِ بْنِ فُلَانٍ ، وَأَحْزَابِهِ مِنْ خَلَائِقِكَ ؛ أنْ يَّفْرُطَ عَلَىَّ أحَدٌ مِنهُمْ أوْ يَطْغٰى ، عَزَّ جَارُكَ ، وَجَلَّ ثَنَاؤُكَ ، وَلَا إِلٰهَ إِلَّا أَنْتَ","transliteration":"Allāhumma Rabb-as-samāwāti-s-sabiʿ, wa Rabba-l-ʿArshi-l-ʿaẓīm, kun lī jāran min fulāni-bni-fulān, wa aḥzābihi min khalāiqiqa; ay-yafruṭa ʿalayya aḥadun minhum aw yaṭgā, ʿazza jāruk, wa jalla thanā’uk, wa lā ilāha illā Ant.","translation":"O Allah, Lord of the seven heavens, Lord of the Magnificent Throne, be for me a support against [such and such a person] and his helpers from among your creatures, lest any of them abuse me or do me wrong. Mighty is Your patronage, and glorious are Your praises. There is none worthy of worship but You.","description":null,"benefit":null,"virtue":null,"hadith":"ʿAbdullāh b. Masʿūd (raḍiy Allāhu ‘anhu) said: “If a leader is appointed over you from whom you fear injustice, let him say: [the above].” (Al Adab Al Mufrad 707)","reference":"عَنِ الْأَعْمَشِ قَالَ: حَدَّثَنَا ثُمَامَةُ بْنُ عُقْبَةَ قَالَ: سَمِعْتُ الْحَارِثَ بْنَ سُوَيْدٍ يَقُولُ: قَالَ عَبْدُ اللَّهِ بْنُ مَسْعُودٍ: إِذَا كَانَ عَلَى أَحَدِكُمْ إِمَامٌ يَخَافُ تَغَطْرُسَهُ أَوْ ظُلْمَهُ، فَلْيَقُلِ: اللَّهُمَّ رَبَّ السَّمَاوَاتِ السَّبْعِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، كُنْ لِي جَارًا مِنْ فُلَانِ بْنِ فُلَانٍ وَأَحْزَابِهِ مِنْ خَلَائِقِكَ، أَنْ يَفْرُطَ عَلَيَّ أَحَدٌ مِنْهُمْ أَوْ يَطْغَى، عَزَّ جَارُكَ، وَجَلَّ ثَنَاؤُكَ، وَلَا إِلَهَ إِلَّا أَنْتَ. (الادب المفرد ٧٠٧)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"Allah Will Suffice You in Everything","arabic":"حَسْبِيَ اللّٰهُ لَا إِلٰهَ إِلَّا هُوَ ، عَلَيْهِ تَوَكَّلْتُ ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ.","transliteration":"Ḥasbiya-Allāhu lā ilāha illā Huwa, ʿalayhi tawakkalt, wa Huwa Rabbu-l-ʿArshi-l-ʿaẓīm.","translation":"Allah is sufficient for me. There is no god worthy of worship except Him. I have placed my trust in Him only and He is the Lord of the Magnificent Throne.","description":null,"benefit":null,"virtue":"Abū al-Dardā’ (raḍiy Allāhu ʿanhu) narrates from the Messenger of Allah ﷺ that he said: “Whoever recites [the above] seven times in the morning and in the evening, Allah will suffice him in everything that concerns him in matters of this world and the next.” (Ibn al-Sunnī 71)","hadith":null,"reference":"عَنْ أَبِي الدَّرْدَاءِ، رضي الله عنه، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ: مَنْ قَالَ فِي كُلِّ يَوْمٍ حِينَ يُصْبِحُ وَحِينَ يُمْسِي: حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ، عَلَيْهِ تَوَكَّلْتُ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ، سَبْعَ مَرَّاتٍ، كَفَاهُ اللَّهُ عز وجل هَمَّهُ مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ. (عمل اليوم والليلة لابن السني ٧١)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"Duʿa of Prophet Musa ﷺ Expressing His Dire Need","arabic":"رَبِّ إِنِّيْ لِمَآ أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيْرٌ.","transliteration":"Rabbi innī limā anzalta illayya min khayrin faqīr.","translation":"My Lord, truly I am in dire need of any good which You may send me. (28:24)","description":null,"benefit":null,"virtue":null,"hadith":null,"reference":null,"source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"For Difficult Times: All Your Prayers Answered","arabic":"لَآ إِلٰهَ إِلَّآ أَنْتَ سُبْحَانَكَ إِنِّيْ كُنْتُ مِنَ الظَّالِمِيْنَ","transliteration":"Lā ilāha illā Anta subḥānaka innī kuntu mina-ẓ-ẓālimīn.","translation":"There is no god worthy of worship except You; You are free from all imperfection. Indeed, I have been of the wrongdoers. (21:87)","description":null,"benefit":null,"virtue":"The Messenger of Allah ﷺ said: “The supplication of Dhun-Nūn (Prophet Yūnus) when he supplicated in the belly of the whale was: [the above]. No Muslim man ever supplicates with [the above] except that Allah answers his supplications.” (Tirmidhī 3505)","hadith":null,"reference":"Saʿd b. Abī Waqqāṣ said: We were sat in the company of the Messenger of Allah ﷺ. He ﷺ said, “Shall I not inform you of a supplication which will remove the calamity or a worldy trial which befalls a person from amongst you?” It was said, “Of course.” He said, “The supplication of Dhun-Nūn: [the above].”  (See Nasā‘ī in ʿAmal al-Yawm wa al-Laylah 655)\\nعَنْ سَعْدٍ قَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: دَعْوَةُ ذِي النُّونِ إِذْ دَعَا وَهُوَ فِي بَطْنِ الْحُوتِ: لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ؛ فَإِنَّهُ لَمْ يَدْعُ بِهَا رَجُلٌ مُسْلِمٌ فِي شَيْءٍ قَطُّ إِلَّا اسْتَجَابَ اللهُ لَهُ. (سنن الترمذي ٣٥٠٥)\\nأخبرنَا الْقَاسِم بن زَكَرِيَّا قَالَ حَدثنَا عبيد بن مُحَمَّد قَالَ حَدثنَا مُحَمَّد بن مهَاجر قَالَ حَدثنِي إِبْرَاهِيم بن مُحَمَّد بن سعد عَن أَبِيه عَن جده قَالَ كُنَّا جُلُوسًا عِنْد رَسُول الله صلى الله عليه وسلم قَالَ أَلا أخْبركُم أَو أحدثكُم بِشَيْء إِذا نزل بِرَجُل مِنْكُم كرب أَو بلَاء من بلَاء الدُّنْيَا دَعَا بِهِ فرج عَنهُ فَقيل لَهُ بلَى قَالَ دُعَاء ذِي النُّون لَا إِلَه إِلَّا أَنْت سُبْحَانَكَ إِنِّي كنت من الظَّالِمين. (عمل اليوم والليلة للنسائي ٦٥٥)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":"Waqqāṣ said","repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"When One Is Distressed","arabic":"اَللّٰهُمَّ رَحْمَتَكَ أَرْجُوْ فَلَا تَكِلْنِيْ إِلٰى نَفْسِيْ طَرْفَةَ عَيْنٍ ، وَأَصْلِحْ لِي شَأْنِيْ كُلَّهُ ، لَا إِلٰهَ إِلَّا أَنْتَ","transliteration":"Allāhumma raḥmataka arjū fa-lā takilnī ilā nafsī ṭarfata ʿayn, wa aṣliḥ lī sha’nī kullah, lā ilāha illā Ant.","translation":"O Allah! It is certainly Your Mercy what I hope for, so do not entrust me to myself for the blink of an eye; and rectify all of my affairs. There is no god worthy of worship except You.","description":null,"benefit":null,"virtue":null,"hadith":"The Messenger of Allah ﷺ said: “The supplications of the distressed person are [the above].” (Abū Dāwūd 5090)","reference":"عَنْ جَعْفَرِ بْنِ مَيْمُونٍ قَالَ: حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ «أَنَّهُ قَالَ لِأَبِيهِ : يَا أَبَتِ إِنِّي أَسْمَعُكَ تَدْعُو كُلَّ غَدَاةٍ: اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَدْعُو بِهِنَّ، فَأَنَا أُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ قَالَ عَبَّاسٌ فِيهِ: وَتَقُولُ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ، تُعِيدُهَا ثَلَاثًا حِينَ تُصْبِحُ، وَثَلَاثًا حِينَ تُمْسِي، فَتَدْعُو بِهِنَّ، فَأُحِبُّ أَنْ أَسْتَنَّ بِسُنَّتِهِ. قَالَ: وَقَالَ رَسُولُ اللهِ صلى الله عليه وسلم: دَعَوَاتُ الْمَكْرُوبِ اللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا ‌تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ. (سنن ابي داود ٥٠٩٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"},{"title":"Entrust All Your Matters to Allah","arabic":"يَا حَيُّ يَا قَيُّوْمُ ، بِرَحْمَتِكَ أَسْتَغِيْثُ ، أَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ ، وَلَا تَكِلْنِيْ إِلَىٰ نَفْسِيْ طَرْفَةَ عَيْنٍ.\\nأخبرنَا عبد الرَّحْمَن بن مُحَمَّد بن سَلام حَدثنَا زيد بن الْحباب أَخْبرنِي عُثْمَان بن موهب الْهَاشِمِي سَمِعت أنس بن مَالك يَقُول قَالَ النَّبِي صلى الله عليه وسلم لفاطمة مَا يمنعك أَن سَمْعِي مَا أوصيك بِهِ أَو تقولي إِذا أَصبَحت وَإِذا أمسيت يَا حَيّ يَا قيوم بِرَحْمَتك أستغيث أصلح لي شأني كلَّه وَلَا تَكِلنِي إِلَى نَفسِي طرفَة عين.","transliteration":"Yā Ḥayyu yā Qayyūm, bi-raḥmatika astaghīth, aṣliḥ lī sha’nī kullah, wa lā takilnī ilā nafsī ṭarfata ʿayn.","translation":"O The Ever Living, The Sustainer of all. ; I seek assistance through Your mercy. Rectify all of my affairs and do not entrust me to myself for the blink of an eye.","description":null,"benefit":null,"virtue":null,"hadith":"Anas b. Mālik (raḍiy Allāhu ʿanhu) narrates that the Prophet ﷺ said to Fāṭimah (raḍiy Allāhu ʿanhā), “What is preventing you from (doing) what I am advising you; that you say [the above] in the morning and evening?” (Nasā’ī in ʿAmal al-Yawm wa-l-Laylah 570)","reference":"(عمل اليوم والليلة للنسائي ٥٧٠)","source":"Allahu Akbar Official","quran_reference":null,"surah":null,"ayah":null,"narrator":null,"repeat_count":null,"audio_url":null,"image_url":null,"source_url":"https://allahuakbarofficial.com/weak/"}]}]}');

